const SearchResults = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const navigate = useNavigate();
  const { searchQuery, searchResults, isSearching, performSearch, clearSearch, getHighlightedText } = useSearch();
  const [localQuery, setLocalQuery] = useState('');

  const query = searchParams.get('q') || '';

  useEffect(() => {
    if (query) {
      setLocalQuery(query);
      performSearch(query);
    }
  }, [query, performSearch]);

  const handleSearchChange = (event) => {
    setLocalQuery(event.target.value);
  };

  const handleSearchSubmit = (event) => {
    event.preventDefault();
    if (localQuery.trim()) {
      setSearchParams({ q: localQuery.trim() });
    }
  };

  const handleClearSearch = () => {
    setLocalQuery('');
    clearSearch();
    setSearchParams({});
  };

  const handleResultClick = (result) => {
    navigate(result.path);
  };

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
  };

  const itemVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0 }
  };

  const getCategoryColor = (category) => {
    const colors = {
      overview: 'primary',
      setup: 'success',
      features: 'warning',
      architecture: 'info',
      api: 'secondary',
      integration: 'error',
      devops: 'primary',
      support: 'warning'
    };
    return colors[category?.toLowerCase()] || 'default';
  };

  const getResultIcon = (category) => {
    const icons = {
      overview: <DocumentIcon />,
      setup: <TrendingIcon />,
      features: <TrendingIcon />,
      architecture: <DocumentIcon />,
      api: <DocumentIcon />,
      integration: <TrendingIcon />,
      devops: <DocumentIcon />,
      support: <DocumentIcon />
    };
    return icons[category?.toLowerCase()] || <DocumentIcon />;
  };

  const groupedResults = searchResults.reduce((acc, result) => {
    const category = result.item.category;
    if (!acc[category]) {
      acc[category] = [];
    }
    acc[category].push(result);
    return acc;
  }, {});

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <motion.div variants={containerVariants} initial="hidden" animate="visible">
        {/* Breadcrumbs */}
        <motion.div variants={itemVariants}>
          <Breadcrumbs sx={{ mb: 3 }}>
            <Link component={RouterLink} to="/" sx={{ display: 'flex', alignItems: 'center' }}>
              <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" />
              Home
            </Link>
            <Typography color="text.primary">Search Results</Typography>
          </Breadcrumbs>
        </motion.div>

        {/* Header */}
        <motion.div variants={itemVariants}>
          <Typography variant="h3" component="h1" gutterBottom sx={{ fontWeight: 700, color: 'primary.main' }}>
            🔍 Search Results
          </Typography>
          <Typography variant="h6" color="text.secondary" sx={{ mb: 4 }}>
            {query ? `Results for "${query}"` : 'Enter a search term to find documentation'}
          </Typography>
        </motion.div>

        {/* Search Bar */}
        <motion.div variants={itemVariants}>
          <Paper sx={{ p: 3, mb: 4 }}>
            <form onSubmit={handleSearchSubmit}>
              <TextField
                fullWidth
                variant="outlined"
                placeholder="Search documentation..."
                value={localQuery}
                onChange={handleSearchChange}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
