        {/* Search Stats */}
        {query && (
          <motion.div variants={itemVariants}>
            <Alert severity="info" sx={{ mb: 4 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <Typography variant="body1">
                  {isSearching ? 'Searching...' : `Found ${searchResults.length} results in ${Object.keys(groupedResults).length} categories`}
                </Typography>
                {searchResults.length > 0 && (
                  <Box sx={{ display: 'flex', gap: 1 }}>
                    {Object.keys(groupedResults).map((category) => (
                      <Chip
                        key={category}
                        label={`${category} (${groupedResults[category].length})`}
                        size="small"
                        color={getCategoryColor(category)}
                        variant="outlined"
                      />
                    ))}
                  </Box>
                )}
              </Box>
            </Alert>
          </motion.div>
        )}

        {/* Results */}
        {query && (
          <motion.div variants={itemVariants}>
            {searchResults.length > 0 ? (
              <AnimatePresence>
                {Object.entries(groupedResults).map(([category, results]) => (
                  <motion.div
                    key={category}
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -20 }}
                    style={{ marginBottom: '2rem' }}
                  >
                    <Typography variant="h4" sx={{ mb: 3, color: 'primary.main', fontWeight: 600 }}>
                      {category} ({results.length} results)
                    </Typography>
                    <Grid container spacing={3} sx={{ mb: 4 }}>
                      {results.map((result, index) => (
                        <Grid item xs={12} md={6} key={result.item.id}>
                          <Card
                            sx={{
                              height: '100%',
                              cursor: 'pointer',
                              transition: 'all 0.2s',
                              '&:hover': {
                                transform: 'translateY(-4px)',
                                boxShadow: 6
                              }
                            }}
                            onClick={() => handleResultClick(result.item)}
                          >
                            <CardContent>
                              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                                <Box sx={{ mr: 2, color: 'primary.main' }}>
                                  {getResultIcon(result.item.category)}
                                </Box>
                                <Typography
                                  variant="h6"
                                  sx={{ flexGrow: 1, fontWeight: 600 }}
                                  dangerouslySetInnerHTML={{
                                    __html: getHighlightedText(
                                      result.item.title,
                                      result.matches?.find(m => m.key === 'title')?.indices
                                    )
                                  }}
                                />
                                <ArrowIcon color="action" />
                              </Box>
                              <Typography
                                variant="body2"
                                color="text.secondary"
                                sx={{ mb: 2 }}
                                dangerouslySetInnerHTML={{
                                  __html: getHighlightedText(
                                    result.item.description,
                                    result.matches?.find(m => m.key === 'description')?.indices
                                  )
                                }}
                              />
                              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Chip
                                  label={result.item.category}
                                  size="small"
                                  color={getCategoryColor(result.item.category)}
                                  variant="outlined"
                                />
                                <Typography variant="caption" color="primary.main" fontWeight={600}>
                                  {Math.round((1 - result.score) * 100)}% match
                                </Typography>
                              </Box>
                            </CardContent>
                          </Card>
                        </Grid>
                      ))}
                    </Grid>
                    <Divider sx={{ mb: 4 }} />
                  </motion.div>
                ))}
              </AnimatePresence>
            ) : !isSearching ? (
              <Box sx={{ textAlign: 'center', py: 8 }}>
                <SearchIcon sx={{ fontSize: 80, color: 'text.disabled', mb: 2 }} />
                <Typography variant="h5" color="text.secondary" gutterBottom>
                  No results found
                </Typography>
                <Typography variant="body1" color="text.disabled">
                  Try different keywords or check your spelling
                </Typography>
              </Box>
            ) : null}
          </motion.div>
        )}

        {/* Empty State */}
        {!query && (
          <motion.div variants={itemVariants}>
            <Box sx={{ textAlign: 'center', py: 8 }}>
              <SearchIcon sx={{ fontSize: 80, color: 'text.disabled', mb: 2 }} />
