import RefreshIcon from '@mui/icons-material/Refresh';
import PersonalInfoTab from './tabs/PersonalInfoTab';
import ApiSettingsTab from './tabs/ApiSettingsTab';
import AppearancePreferencesTab from './tabs/AppearancePreferencesTab';
import { useProfileController } from './ProfileController';
import { useSettings } from '../../contexts/SettingsContext';
import SyncStatusIndicator from '../common/SyncStatusIndicator';
import SettingsErrorBoundary from '../common/SettingsErrorBoundary';
import { LoadingSpinner, SettingsLoadingIndicator } from '../common/LoadingStates';
import { SettingsSuccessFeedback, useFeedback } from '../common/FeedbackSystem';
import { useLanguage } from '../../contexts/LanguageContext';
import { useCustomTheme } from '../../contexts/ThemeContext';
import { getDirectionalAnimation } from '../../utils/rtlAnimations';

const UserProfile = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.down('md'));
    const { translate, currentLanguage, languages } = useLanguage();
    const { animations } = useCustomTheme();
    const isRTL = languages[currentLanguage]?.dir === 'rtl';

    const [activeTab, setActiveTab] = useState(0); // Personal Info tab (0) is now first
    const [mounted, setMounted] = useState(false);
    const [tabLoading, setTabLoading] = useState(false);
    const [autoSaving, setAutoSaving] = useState(false);
    const [saveError, setSaveError] = useState(null);
    const [tabErrors, setTabErrors] = useState({});
    const contentRef = useRef(null);
    const autoSaveTimeoutRef = useRef(null);

    const {
        userData,
        loading,
        error,
        updateUserData,
        saveUserData,
        isDirty,
        lastSyncTime
    } = useProfileController();

    const { settings, loading: settingsLoading, isDirty: settingsIsDirty } = useSettings();
    const [showSaveIndicator, setShowSaveIndicator] = useState(false);
    const [retryCount, setRetryCount] = useState(0);

    // Enhanced feedback system
    const { 
        feedback, 
        showSuccess, 
        hideSuccess, 
        showConfirmation, 
        hideConfirmation 
    } = useFeedback();

    useEffect(() => {
        setMounted(true);
        return () => {
            setMounted(false);
            // Clear any pending auto-save timeouts
            if (autoSaveTimeoutRef.current) {
                clearTimeout(autoSaveTimeoutRef.current);
            }
        };
    }, []);

    // Enhanced auto-save functionality with retry logic and feedback
    const performAutoSave = useCallback(async () => {
        try {
            setAutoSaving(true);
            setSaveError(null);
            await saveUserData();
            setRetryCount(0);

            // Show success feedback
            showSuccess(
                translate('feedback.settings.saved'), 
                'save',
                translate('feedback.settings.autoSaveDetails')
            );

            console.log('Auto-save completed successfully');
        } catch (error) {
            console.error('Auto-save failed:', error);
            const errorMessage = error.message || translate('errors.settings.operations.saving');
            setSaveError(errorMessage);

            // Implement retry logic for transient errors
            if (retryCount < 3 && (error.code === 'NETWORK_ERROR' || error.code === 'TIMEOUT')) {
                setRetryCount(prev => prev + 1);
                setTimeout(() => performAutoSave(), Math.pow(2, retryCount) * 1000); // Exponential backoff
            }
        } finally {
            setAutoSaving(false);
        }
    }, [saveUserData, retryCount, showSuccess, translate]);

    useEffect(() => {
        if ((isDirty || settingsIsDirty) && !autoSaving) {
            // Clear existing timeout
            if (autoSaveTimeoutRef.current) {
                clearTimeout(autoSaveTimeoutRef.current);
            }

            // Set new timeout for auto-save (2 seconds after last change)
            autoSaveTimeoutRef.current = setTimeout(performAutoSave, 2000);
        }

        return () => {
            if (autoSaveTimeoutRef.current) {
                clearTimeout(autoSaveTimeoutRef.current);
            }
        };
    }, [isDirty, settingsIsDirty, autoSaving, performAutoSave]);

    // Show save indicator when changes are made
    useEffect(() => {
        if (isDirty || autoSaving) {
            setShowSaveIndicator(true);
            const timer = setTimeout(() => {
                if (!isDirty && !autoSaving) {
                    setShowSaveIndicator(false);
                }
            }, 3000);
            return () => clearTimeout(timer);
        }
    }, [isDirty, autoSaving]);

    const handleTabChange = useCallback(async (event, newValue) => {
        if (activeTab === newValue) return;

        try {
            setTabLoading(true);
            setSaveError(null);
            setTabErrors(prev => ({ ...prev, [activeTab]: null })); // Clear current tab errors

            // Auto-save before switching tabs if there are unsaved changes
            if (isDirty || settingsIsDirty) {
                setAutoSaving(true);
                try {
                    await saveUserData();
                    console.log('Settings saved before tab switch');
                    showSuccess(
                        translate('feedback.settings.saved'), 
                        'save'
                    );
                } catch (saveError) {
                    console.warn('Save failed before tab switch, but continuing:', saveError);
                    // Show warning but don't block tab switch
                    setSaveError(translate('errors.settings.operations.saving'));
                }
            }

            // Validate current tab before switching
            const currentTabValid = await validateCurrentTab();
            if (!currentTabValid) {
                setTabErrors(prev => ({ 
                    ...prev, 
                    [activeTab]: translate('errors.validation.tabSwitch') 
                }));
                return;
            }

            // Small delay for smooth transition with RTL support
            await new Promise(resolve => setTimeout(resolve, animations ? 150 : 50));
            setActiveTab(newValue);

            // Scroll to top of new tab content with smooth behavior
            if (contentRef.current) {
                contentRef.current.scrollTo({
                    top: 0,
                    behavior: animations ? 'smooth' : 'auto'
                });
            }

        } catch (error) {
            console.error('Failed to switch tabs:', error);
            setSaveError(error.message || translate('errors.settings.operations.tabSwitch'));
            // Still allow tab switch even if save fails
            setActiveTab(newValue);
        } finally {
            setTabLoading(false);
            setAutoSaving(false);
        }
    }, [activeTab, isDirty, settingsIsDirty, saveUserData, showSuccess, translate, animations]);

    const validateCurrentTab = useCallback(async () => {
        // Add tab-specific validation logic here
        switch (activeTab) {
            case 0: // Personal Info
                // Validate personal info fields
                return true;
            case 1: // API Settings
                // Validate API configuration
                return true;
            case 2: // Appearance & Preferences
                // Validate preferences
                return true;
            default:
                return true;
        }
    }, [activeTab]);

    // Handle updates for each section
    const handleUpdatePersonalInfo = (updates) => {
        updateUserData(updates, 'personalInfo');
    };

    const handleUpdateApiSettings = (updates) => {
        updateUserData(updates, 'apiSettings');
    };

    const handleUpdatePreferences = (updates) => {
        updateUserData(updates, 'preferences');
    };

    const handleRetry = useCallback(() => {
        setSaveError(null);
        setTabErrors({});
        setRetryCount(0);
        window.location.reload();
    }, []);

    // Loading state with enhanced UI
    if (loading && !mounted) {
        return (
            <SettingsLoadingIndicator 
                operation="loading"
                message={translate('settings.operations.loading')}
            />
        );
    }

    if (error) {
        return (
            <SettingsErrorBoundary componentName="UserProfile">
                <Paper elevation={3} sx={{ maxWidth: 1200, margin: 'auto', mt: 2, p: 3 }}>
                    <Alert 
                        severity="error" 
                        sx={{ mb: 2 }}
                        action={
                            <Tooltip title={translate('errors.boundary.reload')}>
                                <IconButton onClick={handleRetry} size="small">
                                    <RefreshIcon />
                                </IconButton>
                            </Tooltip>
                        }
                    >
                        <Typography variant="subtitle2" gutterBottom>
                            {translate('errors.settings.title')}
                        </Typography>
                        <Typography variant="body2">
                            {error.message || translate('errors.unknown')}
                        </Typography>
                    </Alert>
                </Paper>
            </SettingsErrorBoundary>
        );
    }

    const renderActiveTab = () => {
        const commonProps = {
            onSave: saveUserData,
            isDirty: isDirty || settingsIsDirty,
            loading: loading || tabLoading || settingsLoading,
            error: tabErrors[activeTab]
        };

        const tabComponents = {
            0: (
                <PersonalInfoTab 
                    userData={userData?.personalInfo} 
                    onUpdateUserData={handleUpdatePersonalInfo}
                    {...commonProps}
                />
            ),
            1: (
                <ApiSettingsTab 
                    userData={userData?.apiSettings}
                    onUpdateUserData={handleUpdateApiSettings}
                    {...commonProps}
                />
            ),
            2: (
                <AppearancePreferencesTab 
                    userData={settings?.preferences || userData?.preferences}
                    onUpdateUserData={handleUpdatePreferences}
                    {...commonProps}
                />
            )
        };

        return tabComponents[activeTab] || (
            <Box sx={{ p: 3, textAlign: 'center' }}>
                <Typography variant="h6" color="text.secondary">
                    Tab not found
                </Typography>
            </Box>
        );
    };

    return (
        <SettingsErrorBoundary componentName="UserProfile">
            <Paper 
                elevation={3} 
                sx={{ 
                    maxWidth: 1200, 
                    margin: 'auto', 
                    mt: { xs: 1, sm: 2 },
                    mx: { xs: 0, sm: 'auto' },
                    borderRadius: { xs: 2, sm: 3 },
                    direction: isRTL ? 'rtl' : 'ltr',
                    ...getDirectionalAnimation('fadeIn', 'up', isRTL, {
                        duration: animations ? '0.4s' : '0s',
                        easing: 'ease-out'
                    })
                }}
            >
            {/* Loading progress bar */}
            {(loading || tabLoading || autoSaving) && (
                <LinearProgress 
                    sx={{ 
                        position: 'absolute', 
                        top: 0, 
                        left: 0, 
                        right: 0, 
                        zIndex: 1,
                        borderRadius: { xs: '8px 8px 0 0', sm: '12px 12px 0 0' }
                    }} 
                />
            )}

            {/* Error notification */}
            {saveError && (
                <Alert 
                    severity="error" 
                    sx={{ 
                        m: { xs: 1, sm: 2 }, 
                        mb: 0,
                        fontSize: { xs: '0.875rem', sm: '1rem' }
                    }}
                    onClose={() => setSaveError(null)}
                    action={
                        retryCount > 0 && (
                            <Tooltip title={`Retry attempt ${retryCount}/3`}>
                                <IconButton 
                                    size="small" 
                                    onClick={performAutoSave}
                                    key={`retry-icon-${retryCount}`}
                                >
                                    <RefreshIcon />
                                </IconButton>
                            </Tooltip>
                        )
                    }
                >
                    <Typography variant="subtitle2" sx={{ fontSize: { xs: '0.875rem', sm: '1rem' } }}>
                        {saveError}
                    </Typography>
                    {retryCount > 0 && (
                        <Typography variant="caption" display="block">
                            Retry attempt {retryCount}/3
                        </Typography>
                    )}
                </Alert>
            )}

            {/* Tab-specific errors */}
            {tabErrors[activeTab] && (
                <Alert 
                    severity="warning" 
                    sx={{ 
                        m: { xs: 1, sm: 2 }, 
                        mb: 0,
                        fontSize: { xs: '0.875rem', sm: '1rem' }
                    }}
                    onClose={() => setTabErrors(prev => ({ ...prev, [activeTab]: null }))}
                >
                    {tabErrors[activeTab]}
                </Alert>
            )}

            {/* Header with sync status - responsive */}
            <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                px: { xs: 1.5, sm: 2 }, 
                py: { xs: 1, sm: 1.5 },
                borderBottom: 1,
                borderColor: 'divider',
                bgcolor: 'background.paper',
                flexDirection: { xs: 'column', sm: 'row' },
                gap: { xs: 1, sm: 0 }
            }}>
                <Typography 
                    variant="h6" 
                    color="text.primary"
                    sx={{ 
                        fontSize: { xs: '1.1rem', sm: '1.25rem' },
                        textAlign: { xs: 'center', sm: 'left' }
                    }}
                >
                    User Profile Settings
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center' }}>
                    {/* Sync Status Indicator with fallback */}
                    <React.Suspense fallback={
                        <Chip 
                            label="Sync Status" 
                            size="small" 
                            variant="outlined" 
                            color="default"
                            key={`sync-chip-${Date.now()}`}
                        />
                    }>
                        <SyncStatusIndicator 
                            variant="chip" 
                            showDetails={!isMobile}
                            allowManualSync={true}
                            key={`sync-indicator-${Date.now()}`}
                        />
                    </React.Suspense>
                </Box>
            </Box>

            <Tabs
                value={activeTab}
                onChange={handleTabChange}
                variant={isMobile ? "scrollable" : "fullWidth"}
                scrollButtons={isMobile ? "auto" : false}
                allowScrollButtonsMobile={isMobile}
                sx={{ 
                    borderBottom: 1, 
                    borderColor: 'divider',
                    '& .MuiTab-root': {
                        minHeight: { xs: 60, sm: 72 },
                        textTransform: 'none',
                        fontSize: { xs: '0.875rem', sm: '0.95rem' },
                        fontWeight: 500,
                        minWidth: { xs: 120, sm: 'auto' },
                        px: { xs: 1, sm: 2 }
                    },
                    '& .MuiTabs-scrollButtons': {
                        '&.Mui-disabled': {
                            opacity: 0.3
                        }
                    }
                }}
                key={`tabs-${activeTab}`}
            >
                {/* Correct tab order: Personal Info (0), API Settings (1), Appearance & Preferences (2) */}
                <Tab 
                    icon={<PersonIcon sx={{ fontSize: { xs: 20, sm: 24 } }} />} 
                    label={isMobile ? "Personal" : "Personal Info"}
                    value={0}
                    disabled={loading || tabLoading}
                    key={`tab-personal-${activeTab}`}
                />
                <Tab 
                    icon={<ApiIcon sx={{ fontSize: { xs: 20, sm: 24 } }} />} 
                    label={isMobile ? "API" : "API Settings"}
                    value={1}
                    disabled={loading || tabLoading}
                    key={`tab-api-${activeTab}`}
                />
                <Tab 
                    icon={<LanguageIcon sx={{ fontSize: { xs: 20, sm: 24 } }} />} 
                    label={isMobile ? "Appearance" : "Appearance & Preferences"}
                    value={2}
                    disabled={loading || tabLoading}
                    key={`tab-appearance-${activeTab}`}
                />
            </Tabs>
            <Box
                ref={contentRef}
                sx={{
                    p: { xs: 1.5, sm: 2, md: 3 },
                    flexGrow: 1,
                    minHeight: { 
                        xs: 'calc(100vh - 300px)', 
                        sm: 'calc(100vh - 250px)',
                        md: 'calc(100vh - 200px)'
                    },
                    overflowY: 'auto',
                    overflowX: 'hidden'
                }}
                key={`tab-content-${activeTab}`}
            >
                {mounted && (
                    <Fade
                        in={!loading && mounted}
                        timeout={300}
                        key={`fade-content-${activeTab}`}
                    >
                        <Box key={`box-content-${activeTab}`}>
                            {renderActiveTab()}
                        </Box>
                    </Fade>
                )}
            </Box>

            {/* Loading backdrop */}
            <Backdrop
                sx={{ 
                    color: '#fff', 
                    zIndex: (theme) => theme.zIndex.drawer + 1,
                    position: 'absolute'
                }}
                open={loading}
            >
                <CircularProgress color="inherit" />
            </Backdrop>

            {/* Enhanced Success Feedback */}
            <SettingsSuccessFeedback
                open={feedback.success.open}
                operation={feedback.success.operation}
                details={feedback.success.details}
                onClose={hideSuccess}
                showDetails={true}
                key={`success-feedback-${feedback.success.open ? 1 : 0}`}
            />

            {/* Save indicator with RTL support */}
            <Snackbar
                open={showSaveIndicator}
                autoHideDuration={4000}
                anchorOrigin={{ 
                    vertical: 'bottom', 
                    horizontal: isRTL ? 'left' : 'right' 
                }}
                onClose={() => setShowSaveIndicator(false)}
                key={`snackbar-${showSaveIndicator ? 1 : 0}`}
            >
                <Alert 
                    icon={
                        autoSaving ? <CircularProgress size={16} /> :
                        (isDirty || settingsIsDirty) ? <SaveIcon /> :
                        <CheckCircleIcon />
                    }
                    severity={
                        autoSaving ? "info" :
                        (isDirty || settingsIsDirty) ? "warning" : 
                        "success"
                    }
                    sx={{ 
                        width: '100%',
                        direction: isRTL ? 'rtl' : 'ltr'
                    }}
                    onClose={() => setShowSaveIndicator(false)}
                >
                    <Typography variant="body2">
                        {autoSaving ? translate('settings.operations.saving') :
                         (isDirty || settingsIsDirty) ? translate('settings.status.pending') : 
                         translate('settings.status.saved')}
                    </Typography>
                    {lastSyncTime && !autoSaving && (
                        <Typography variant="caption" sx={{ opacity: 0.8, display: 'block' }}>
                            {translate('settings.lastSync')}: {new Date(parseInt(lastSyncTime)).toLocaleTimeString()}
                        </Typography>
                    )}
                    {retryCount > 0 && (
                        <Typography variant="caption" sx={{ opacity: 0.8, display: 'block' }}>
                            {translate('errors.settings.retryCount', { count: retryCount })}
                        </Typography>
                    )}
                </Alert>
            </Snackbar>
        </Paper>
        </SettingsErrorBoundary>
    );
};

export default UserProfile;

import React, { useState, useEffect } from 'react';
import {
    Box,
    TextField,
    Button,
    Grid2 as Grid,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    Typography,
    Alert,
    CircularProgress,
    FormControlLabel,
    Switch,
    Card,
    CardContent,
    Accordion,
    AccordionSummary,
    AccordionDetails,
    Chip,
    Stack,
} from '@mui/material';
import {
    ExpandMore,
    Api,
    CheckCircle,
    Error,
    Security,
} from '@mui/icons-material';
import { useLanguage } from '../../../contexts/LanguageContext';
import { toast } from 'react-toastify';

/**
 * API Settings Management Component
 * Provides configuration for API endpoints and database connections
 */
const ApiSettingsTab = ({ userData, onUpdateUserData, loading, error }) => {
    const { translate } = useLanguage();
    
    // Connection test states
    const [connectionTests, setConnectionTests] = useState({
        magento: { testing: false, status: null, lastTest: null },
        cegid: { testing: false, status: null, lastTest: null },
        mdm: { testing: false, status: null, lastTest: null },
    });
    
    const [expandedSection, setExpandedSection] = useState('mdm');
    
    // API settings structure
    const [formData, setFormData] = useState({
        mdm: {
            enabled: true,
            name: 'MDM System API',
            description: 'Master Data Management system for centralized data',
            url: '',
            apiKey: '',
            authMode: 'apikey',
            enableCaching: true,
            cacheTimeout: 300000, // 5 minutes
            timeout: 30000,
            retryAttempts: 3,
            version: '1.0',
            endpoints: {
                products: '/api/v1/products',
                categories: '/api/v1/categories',
                stocks: '/api/v1/stocks',
                sources: '/api/v1/sources',
                analytics: '/api/v1/analytics'
            }
        },
        magento: {
            enabled: true,
            name: 'Magento API',
            description: 'E-commerce platform integration',
            url: '',
            username: '',
            password: '',
            authMode: 'basic',
            consumerKey: '',
            consumerSecret: '',
            accessToken: '',
            accessTokenSecret: '',
            enableDirectConnection: false,
            timeout: 30000,
            retryAttempts: 3,
            version: '2.4'
        },
        cegid: {
            enabled: false,
            name: 'CEGID API',
            description: 'ERP system integration',
            url: '',
            username: '',
            password: '',
            database: '',
            timeout: 30000,
            retryAttempts: 3,
            version: '1.0'
        },
        general: {
            backendServer: '',
            globalTimeout: 30000,
            enableLogging: true,
            enableRetry: true,
            maxConcurrentRequests: 10
        }
    });

    // Initialize settings
    useEffect(() => {
        if (userData) {
            setFormData(prev => ({
                ...prev,
                ...userData
            }));
        }
    }, [userData]);

    const handleInputChange = (service, field, value) => {
        const updatedFormData = {
            ...formData,
            [service]: {
                ...formData[service],
                [field]: value
            }
        };
        setFormData(updatedFormData);

        // Update parent component
        if (onUpdateUserData) {
            onUpdateUserData(updatedFormData);
        }
    };

    const handleTestConnection = async (service) => {
        // Validate required fields before testing
        const validation = validateServiceConfig(service);
        if (!validation.isValid) {
            toast.error(`Configuration incomplete: ${validation.errors.join(', ')}`);
            return;
        }

        setConnectionTests(prev => ({
            ...prev,
            [service]: { ...prev[service], testing: true, status: 'testing' }
        }));

        try {
            let testResult;
            
            switch (service) {
                case 'mdm':
                    testResult = await testMDMConnection();
                    break;
                case 'magento':
                    testResult = await testMagentoConnection();
                    break;
                case 'cegid':
                    testResult = await testCegidConnection();
                    break;
                default:
                    throw new Error(`Unknown service: ${service}`);
            }
            
            setConnectionTests(prev => ({
                ...prev,
                [service]: { 
                    ...prev[service], 
                    testing: false, 
                    status: 'success',
                    lastTest: new Date().toISOString(),
                    details: testResult
                }
            }));
            
            toast.success(`${service.toUpperCase()} connection test successful!`);
        } catch (error) {
            setConnectionTests(prev => ({
                ...prev,
                [service]: { 
                    ...prev[service], 
                    testing: false, 
                    status: 'error',
                    lastTest: new Date().toISOString(),
                    error: error.message
                }
            }));
            
            toast.error(`${service.toUpperCase()} connection test failed: ${error.message}`);
        }
    };

    // Validation function for service configurations
    const validateServiceConfig = (service) => {
        const errors = [];
        const config = formData[service];

        if (!config.enabled) {
            errors.push(`${service} is disabled`);
            return { isValid: false, errors };
        }

        switch (service) {
            case 'mdm':
                if (!config.url) errors.push('MDM URL is required');
                if (!config.apiKey) errors.push('API Key is required');
                break;
            case 'magento':
                if (!config.url) errors.push('Magento URL is required');
                if (config.authMode === 'basic') {
                    if (!config.username) errors.push('Username is required');
                    if (!config.password) errors.push('Password is required');
                } else if (config.authMode === 'oauth') {
                    if (!config.consumerKey) errors.push('Consumer Key is required');
                    if (!config.consumerSecret) errors.push('Consumer Secret is required');
                    if (!config.accessToken) errors.push('Access Token is required');
                    if (!config.accessTokenSecret) errors.push('Access Token Secret is required');
                }
                break;
            case 'cegid':
                if (!config.url) errors.push('CEGID URL is required');
                if (!config.username) errors.push('Username is required');
                if (!config.password) errors.push('Password is required');
                if (!config.database) errors.push('Database is required');
                break;
        }

        return { isValid: errors.length === 0, errors };
    };

    // Individual connection test functions
    const testMDMConnection = async () => {
        const config = formData.mdm;
        // Simulate MDM API test
        await new Promise(resolve => setTimeout(resolve, 1500));
        
        // In real implementation, this would make an actual API call
        if (!config.url.startsWith('http')) {
            throw new Error('Invalid URL format');
        }
        
        return { 
            responseTime: '150ms', 
            version: config.version,
            endpoints: Object.keys(config.endpoints).length 
        };
    };

    const testMagentoConnection = async () => {
        const config = formData.magento;
        // Simulate Magento API test
        await new Promise(resolve => setTimeout(resolve, 2000));
        
        // In real implementation, this would make an actual API call
        if (!config.url.includes('rest')) {
            throw new Error('URL should include REST API path (e.g., /rest/V1)');
        }
        
        return { 
            responseTime: '250ms', 
            version: config.version,
            authMode: config.authMode,
            directConnection: config.enableDirectConnection
        };
    };

    const testCegidConnection = async () => {
        const config = formData.cegid;
        // Simulate CEGID API test
        await new Promise(resolve => setTimeout(resolve, 1800));
        
        return { 
            responseTime: '300ms', 
            version: config.version,
            database: config.database
        };
    };

    // Connection status indicator component
    const ConnectionStatus = ({ service, status }) => {
