                <Stack direction="row" alignItems="center" spacing={2} sx={{ mb: 2 }}>
                    <Api color="primary" sx={{ fontSize: 32 }} />
                    <Box>
                        <Typography variant="h4" sx={{ fontWeight: 600, color: 'primary.main' }}>
                            API Configuration
