                        </Typography>
                    </Box>
                </Stack>
            </Box>

            {error && (
                <Alert severity="error" sx={{ mb: 3 }}>
                    {error}
                </Alert>
            )}

            {/* MDM System Settings */}
            <Accordion 
                expanded={expandedSection === 'mdm'} 
                onChange={() => setExpandedSection(expandedSection === 'mdm' ? null : 'mdm')}
                sx={{ 
                    mb: 2, 
                    boxShadow: 2,
                    '&:before': { display: 'none' },
                    borderRadius: 2,
                    overflow: 'hidden'
                }}
            >
                <AccordionSummary 
                    expandIcon={<ExpandMore />}
                    sx={{ 
                        bgcolor: 'success.main', 
