const PersonalInfoTab = ({ userData, onUpdateUserData, loading, error }) => {
  const { translate } = useLanguage();
  const { currentUser } = useAuth();
  const [formData, setFormData] = useState({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    country: '',
    postalCode: '',
    birthDate: '',
    gender: ''
  });

  // Load data when userData changes
  useEffect(() => {
    if (userData) {
      setFormData(prev => ({
        ...prev,
        ...userData
      }));
    }
  }, [userData]);

  const handleInputChange = (field, value) => {
    const updatedFormData = {
      ...formData,
      [field]: value
    };
    setFormData(updatedFormData);

    // Update through parent component
    if (onUpdateUserData) {
      onUpdateUserData(updatedFormData);
    }
  };

  const handleSyncToFirebase = () => {
    if (onUpdateUserData) {
      onUpdateUserData(formData);
    }
  };

  return (
    <Paper elevation={0} sx={{ p: 2 }}>
      <Grid container spacing={2}>
        {/* Header with Avatar and Save Button */}
        <Grid xs={12}>
          <Stack
            direction="row"
            alignItems="center"
            justifyContent="space-between"
            spacing={2}
            sx={{ mb: 2 }}
          >
            <Stack direction="row" spacing={2} alignItems="center">
              <Box position="relative">
                {loading ? (
                  <Skeleton variant="circular" width={100} height={100} />
                ) : (
                  <StyledAvatar
                    alt={formData.firstName}
                    src={currentUser?.photoURL}
                  />
                )}
                <input
                  accept="image/*"
                  style={{ display: 'none' }}
                  id="avatar-upload"
                  type="file"
                  onChange={(event) => console.log('Avatar file:', event.target.files[0])}
                />
                <label htmlFor="avatar-upload">
                  <UploadButton
                    component="span"
                    size="small"
                    color="primary"
                    aria-label="upload picture"
                  >
                    <PhotoCamera fontSize="small" />
                  </UploadButton>
                </label>
              </Box>
              <Stack>
                <Typography variant="h6" gutterBottom>
                  {translate('profile.personalInfo.title')}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {currentUser?.email}
                </Typography>
              </Stack>
            </Stack>
            <Button
              variant="contained"
              color="primary"
              onClick={handleSyncToFirebase}
              startIcon={<SyncIcon />}
              disabled={loading}
            >
              {translate('profile.syncToCloud')}
            </Button>
          </Stack>
          <Divider sx={{ my: 2 }} />
        </Grid>

        {/* Form Fields */}
        <Grid item xs={12}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.firstName')}
                name="firstName"
                value={formData.firstName}
                onChange={(e) => handleInputChange('firstName', e.target.value)}
                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.lastName')}
                name="lastName"
                value={formData.lastName}
                onChange={(e) => handleInputChange('lastName', e.target.value)}
                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.phone')}
                name="phone"
                value={formData.phone}
                onChange={(e) => handleInputChange('phone', e.target.value)}
                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.birthDate')}
                name="birthDate"
                type="date"
                value={formData.birthDate}
                onChange={(e) => handleInputChange('birthDate', e.target.value)}
                disabled={loading}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                select
                label={translate('profile.personalInfo.gender')}
                name="gender"
                value={formData.gender}
                onChange={(e) => handleInputChange('gender', e.target.value)}
                disabled={loading}
              >
                <MenuItem value="male">{translate('profile.personalInfo.male')}</MenuItem>
                <MenuItem value="female">{translate('profile.personalInfo.female')}</MenuItem>
                <MenuItem value="other">{translate('profile.personalInfo.other')}</MenuItem>
              </StyledTextField>
            </Grid>
            <Grid item xs={12}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.address')}
                name="address"
                value={formData.address}
                onChange={(e) => handleInputChange('address', e.target.value)}
                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.city')}
                name="city"
                value={formData.city}
                onChange={(e) => handleInputChange('city', e.target.value)}
                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.country')}
                name="country"
                value={formData.country}
