                disabled={loading}
              />
            </Grid>
            <Grid item xs={12} sm={6} md={4}>
              <StyledTextField
                fullWidth
                size="small"
                label={translate('profile.personalInfo.postalCode')}
                name="postalCode"
                value={formData.postalCode}
                onChange={(e) => handleInputChange('postalCode', e.target.value)}
                disabled={loading}
              />
            </Grid>
          </Grid>
        </Grid>
      </Grid>
    </Paper>
  );
};

