));

CardSkeleton.displayName = 'CardSkeleton';

/**
 * Single Stat Card Component
 */
const StatCard = memo(({
  title,
  value,
  subtitle,
  icon: Icon,
  color = 'primary',
  trend,
  percentage,
  loading = false,
  onClick,
  sx = {}
}) => {
