InfoCard.displayName = 'InfoCard';

/**
 * Progress Card Component
 */
const ProgressCard = memo(({
  title,
  value,
  max = 100,
  color = 'primary',
  showPercentage = true,
  sx = {}
}) => {
  const cardId = useId();
  const percentage = Math.round((value / max) * 100);

  return (
    <Card id={cardId} sx={sx} elevation={1}>
      <CardContent>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
          <Typography variant="body2" color="text.secondary">
            {title}
          </Typography>
          {showPercentage && (
            <Typography variant="body2" color="text.secondary">
              {percentage}%
            </Typography>
          )}
        </Box>

        <LinearProgress
          variant="determinate"
          value={percentage}
          color={color}
          sx={{
            height: 8,
            borderRadius: 4,
            '& .MuiLinearProgress-bar': {
              borderRadius: 4
            }
          }}
        />

        <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
          {value} of {max}
        </Typography>
      </CardContent>
    </Card>
  );
});

ProgressCard.displayName = 'ProgressCard';

/**
 * BaseCard Component - Main export
 */
const BaseCard = memo(({
  // Core props
  variant = 'stats',
  type = 'info',

  // Content props
  title,
  value,
  subtitle,
  content,
  icon,

  // Stats props
  stats = {},
  config = {},

  // State props
  loading = false,

  // Style props
  color = 'primary',
  sx = {},

  // Event props
  onClick,
  onDismiss,

  // Advanced props
  trend,
  percentage,
  progress,
  actions,
  dismissible = false,

  ...props
}) => {
  // If stats object is provided, render multiple stat cards
  const renderStatsCards = useCallback(() => {
    if (!stats || Object.keys(stats).length === 0) return null;

    const defaultStatsConfig = [
      { key: 'total', title: 'Total', color: 'primary' },
      { key: 'active', title: 'Active', color: 'success' },
      { key: 'inactive', title: 'Inactive', color: 'warning' },
      { key: 'selected', title: 'Selected', color: 'info' }
    ];

    const statsToRender = config.stats || defaultStatsConfig;

    return (
      <Box sx={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 2 }}>
        {statsToRender.map(statConfig => {
          const statValue = stats[statConfig.key];
          if (statValue === undefined) return null;

          return (
            <StatCard
              key={statConfig.key}
              title={statConfig.title}
              value={statValue}
              color={statConfig.color}
              icon={statConfig.icon}
              loading={loading}
              onClick={onClick}
              trend={statConfig.trend}
              percentage={statConfig.percentage}
            />
          );
        })}
      </Box>
    );
  }, [stats, config.stats, loading, onClick]);

  // Loading state
  if (loading) {
    return <CardSkeleton variant={variant} />;
  }

  // Multiple stats cards
  if (variant === 'stats' && stats && Object.keys(stats).length > 0) {
    return renderStatsCards();
  }

  // Single card variants
  switch (variant) {
    case 'stats':
      return (
        <StatCard
          title={title}
          value={value}
          subtitle={subtitle}
          icon={icon}
          color={color}
          trend={trend}
          percentage={percentage}
          loading={loading}
          onClick={onClick}
          sx={sx}
          {...props}
        />
      );

    case 'info':
      return (
        <InfoCard
          title={title}
          content={content}
          type={type}
          icon={icon}
          actions={actions}
          dismissible={dismissible}
          onDismiss={onDismiss}
          sx={sx}
          {...props}
        />
      );

    case 'progress':
      return (
        <ProgressCard
          title={title}
          value={progress?.value || value}
          max={progress?.max || 100}
          color={color}
          showPercentage={progress?.showPercentage !== false}
          sx={sx}
          {...props}
        />
      );

    default:
      return (
        <StatCard
          title={title}
          value={value}
          subtitle={subtitle}
          icon={icon}
          color={color}
          loading={loading}
          onClick={onClick}
          sx={sx}
          {...props}
        />
      );
  }
});

BaseCard.displayName = 'BaseCard';

export default BaseCard;

/**
 * BaseDialog - Modern React 18 Base Dialog Component
