/**
 * Get configuration for a specific grid type
 */
export const getGridConfig = (gridType = 'default') => {
  return GRID_TYPE_CONFIGS[gridType] || GRID_TYPE_CONFIGS.default;
};

/**
 * Merge configurations with deep merge support
 */
export const mergeConfigs = >(
  base,
  override: Partial
) => {// const merged = { ...base } ; // Unused - commented out
  for (const [key, value] of Object.entries(override)) {
    if (value && typeof value === 'object' && !Array.isArray(value)) {
      (merged )[key] = mergeConfigs((merged )[key] || {}, value);
    } else {
      (merged )[key] = value;
    }
  }
  
  return merged;
};

/**
 * Apply preset configuration with overrides
 */
export const applyGridPreset = (
  preset,
  overrides: Partial = {}
) => {// const presetConfig = GRID_PRESETS[preset] || GRID_PRESETS.crud; // Unused - commented out
  return mergeConfigs(presetConfig, overrides);
};

/**
 * Get toolbar configuration for grid type
 */
export const getToolbarConfig = (
  gridType = 'default',
  overrides: Partial = {}
) => {// const gridConfig = getGridConfig(gridType); // Unused - commented out
  return mergeConfigs(gridConfig.toolbar, overrides);
};

/**
 * Get stats configuration for grid type
 */
export const getStatsConfig = (
  gridType = 'default',
  overrides: Partial = {}
) => {// const gridConfig = getGridConfig(gridType); // Unused - commented out
  return mergeConfigs(gridConfig.stats, overrides);
};

/**
 * Get custom actions for grid type
 */
export const getCustomActions = (gridType = 'default') => {
  return GRID_CUSTOM_ACTIONS[gridType] || [];
};

/**
 * Create complete grid configuration
 */
export const createGridConfiguration = (
  gridType,
  preset?,
  overrides = {}
) => {
  // Start with grid type configuration// const typeConfig = getGridConfig(gridType); // Unused - commented out
  // Apply preset if specified// let config = typeConfig; // Unused - commented out
  if (preset) {// const presetConfig = applyGridPreset(preset); // Unused - commented out
    config = mergeConfigs(config, presetConfig);
  }
  
  // Apply custom overrides
  config = mergeConfigs(config, overrides);
  
  // Add custom actions// const customActions = getCustomActions(gridType); // Unused - commented out
  return {
    ...config,
    customActions: [...customActions, ...(overrides.customActions || [])]
  };
};

