import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Box,
  Typography,
  Alert,
  Stepper,
  Step,
  StepLabel,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tooltip
} from '@mui/material';
import {
  BugReport as BugIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  AttachFile as AttachIcon,
  Info as InfoIcon
} from '@mui/icons-material';
import bugBountyService, { BUG_CATEGORIES } from '../../services/bugBountyService.js';

const steps = ['Bug Details', 'Steps to Reproduce', 'Environment & Contact'];

const BugReportForm = ({ open, onClose, onSubmit }) => {
  const [activeStep, setActiveStep] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    category: '',
    severity: '',
    stepsToReproduce: [''],
    expectedBehavior: '',
    actualBehavior: '',
    testerName: '',
    testerEmail: '',
    testerExperience: 'beginner',
    attachments: []
  });

  const handleInputChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const handleStepChange = (field, index, value) => {
    const newSteps = [...formData.stepsToReproduce];
    newSteps[index] = value;
    setFormData(prev => ({
      ...prev,
      stepsToReproduce: newSteps
    }));
  };

  const addStep = () => {
    setFormData(prev => ({
      ...prev,
      stepsToReproduce: [...prev.stepsToReproduce, '']
    }));
  };

  const removeStep = (index) => {
    if (formData.stepsToReproduce.length > 1) {
      const newSteps = formData.stepsToReproduce.filter((_, i) => i !== index);
      setFormData(prev => ({
        ...prev,
        stepsToReproduce: newSteps
      }));
    }
  };

  const handleNext = () => {
    setActiveStep(prev => prev + 1);
  };

  const handleBack = () => {
    setActiveStep(prev => prev - 1);
  };

  const handleSubmit = async () => {
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      // Generate tester ID
      const testerId = `tester_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

      const bugData = {
        ...formData,
        testerId,
        environment: {
          browser: navigator.userAgent,
          url: window.location.href,
          timestamp: new Date().toISOString(),
          screenResolution: `${window.screen.width}x${window.screen.height}`
        }
      };

      const result = await bugBountyService.submitBug(bugData);

      if (result.success) {
        setSuccess(`Bug report submitted successfully! Bug ID: ${result.bugId}`);
        setTimeout(() => {
          onSubmit?.(result);
          handleClose();
        }, 2000);
      } else {
        setError(result.error || 'Failed to submit bug report');
      }
    } catch (err) {
      setError('An unexpected error occurred');
      console.error('Bug submission error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setActiveStep(0);
    setFormData({
      title: '',
      description: '',
      category: '',
      severity: '',
      stepsToReproduce: [''],
      expectedBehavior: '',
      actualBehavior: '',
      testerName: '',
      testerEmail: '',
      testerExperience: 'beginner',
      attachments: []
    });
    setError('');
    setSuccess('');
    onClose();
  };

  const isStepValid = (step) => {
    switch (step) {
      case 0:
        return formData.title && formData.description && formData.category && formData.severity;
      case 1:
        return formData.stepsToReproduce.some(step => step.trim()) && 
               formData.expectedBehavior && formData.actualBehavior;
      case 2:
        return formData.testerName && formData.testerEmail;
      default:
        return false;
    }
  };

  const getRewardEstimate = () => {
    if (formData.category && formData.severity) {
      return bugBountyService.calculateReward(formData.category, formData.severity);
    }
    return 0;
  };

  const renderStepContent = (step) => {
    switch (step) {
      case 0:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Bug Title"
                value={formData.title}
                onChange={(e) => handleInputChange('title', e.target.value)}
                placeholder="Brief description of the bug"
                required
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                multiline
                rows={4}
                label="Bug Description"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                placeholder="Detailed description of what went wrong"
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth required>
                <InputLabel>Category</InputLabel>
                <Select
                  value={formData.category}
                  onChange={(e) => handleInputChange('category', e.target.value)}
                >
                  {Object.entries(BUG_CATEGORIES).map(([key, category]) => (
                    <MenuItem key={key} value={key}>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <Chip
                          size="small"
                          label={category.name}
                          sx={{ backgroundColor: category.color, color: 'white' }}
                        />
                        <Typography variant="body2">{category.description}</Typography>
                      </Box>
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth required>
                <InputLabel>Severity</InputLabel>
                <Select
                  value={formData.severity}
                  onChange={(e) => handleInputChange('severity', e.target.value)}
                >
                  <MenuItem value="critical">Critical - System unusable</MenuItem>
                  <MenuItem value="high">High - Major functionality affected</MenuItem>
                  <MenuItem value="medium">Medium - Minor functionality affected</MenuItem>
                  <MenuItem value="low">Low - Cosmetic or minor issue</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            {formData.category && formData.severity && (
              <Grid item xs={12}>
                <Alert severity="info" icon={<InfoIcon />}>
                  <Typography variant="body2">
                    <strong>Estimated Reward: ${getRewardEstimate()}</strong>
                    <br />
                    Final reward depends on bug quality and verification.
                  </Typography>
                </Alert>
              </Grid>
            )}
          </Grid>
        );

      case 1:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                Steps to Reproduce
              </Typography>
              {formData.stepsToReproduce.map((step, index) => (
                <Box key={index} sx={{ display: 'flex', gap: 1, mb: 2 }}>
                  <TextField
                    fullWidth
                    label={`Step ${index + 1}`}
                    value={step}
                    onChange={(e) => handleStepChange('stepsToReproduce', index, e.target.value)}
                    placeholder="Describe what to do in this step"
                  />
                  <IconButton
                    onClick={() => removeStep(index)}
                    disabled={formData.stepsToReproduce.length === 1}
                    color="error"
                  >
                    <DeleteIcon />
                  </IconButton>
                </Box>
              ))}
              <Button
                startIcon={<AddIcon />}
                onClick={addStep}
                variant="outlined"
                size="small"
              >
                Add Step
              </Button>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                multiline
                rows={3}
                label="Expected Behavior"
                value={formData.expectedBehavior}
                onChange={(e) => handleInputChange('expectedBehavior', e.target.value)}
                placeholder="What should happen?"
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                multiline
                rows={3}
                label="Actual Behavior"
                value={formData.actualBehavior}
                onChange={(e) => handleInputChange('actualBehavior', e.target.value)}
                placeholder="What actually happened?"
                required
              />
            </Grid>
          </Grid>
        );

      case 2:
        return (
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Your Name"
                value={formData.testerName}
                onChange={(e) => handleInputChange('testerName', e.target.value)}
                required
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                type="email"
                label="Email Address"
                value={formData.testerEmail}
                onChange={(e) => handleInputChange('testerEmail', e.target.value)}
                required
              />
            </Grid>
            <Grid item xs={12}>
              <FormControl fullWidth>
                <InputLabel>Testing Experience</InputLabel>
                <Select
                  value={formData.testerExperience}
                  onChange={(e) => handleInputChange('testerExperience', e.target.value)}
                >
                  <MenuItem value="beginner">Beginner (0-1 years)</MenuItem>
                  <MenuItem value="intermediate">Intermediate (1-3 years)</MenuItem>
                  <MenuItem value="advanced">Advanced (3-5 years)</MenuItem>
                  <MenuItem value="expert">Expert (5+ years)</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <Card variant="outlined">
                <CardContent>
                  <Typography variant="h6" gutterBottom>
                    Environment Information
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    <strong>Browser:</strong> {navigator.userAgent}
                    <br />
                    <strong>Screen Resolution:</strong> {window.screen.width}x{window.screen.height}
                    <br />
                    <strong>Current URL:</strong> {window.location.href}
                    <br />
                    <strong>Timestamp:</strong> {new Date().toLocaleString()}
                  </Typography>
                </CardContent>
              </Card>
            </Grid>
          </Grid>
        );

      default:
        return null;
    }
  };

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
      <DialogTitle>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <BugIcon color="primary" />
          <Typography variant="h6">Report a Bug</Typography>
        </Box>
      </DialogTitle>

      <DialogContent>
        <Box sx={{ mb: 3 }}>
          <Stepper activeStep={activeStep}>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
        </Box>

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        {success && (
          <Alert severity="success" sx={{ mb: 2 }}>
            {success}
          </Alert>
        )}

        {renderStepContent(activeStep)}
      </DialogContent>

      <DialogActions>
        <Button onClick={handleClose}>Cancel</Button>
        <Button
          onClick={handleBack}
          disabled={activeStep === 0}
        >
          Back
        </Button>
        {activeStep < steps.length - 1 ? (
          <Button
            onClick={handleNext}
            disabled={!isStepValid(activeStep)}
            variant="contained"
          >
            Next
          </Button>
        ) : (
          <Button
            onClick={handleSubmit}
            disabled={!isStepValid(activeStep) || loading}
            variant="contained"
            color="primary"
          >
            {loading ? 'Submitting...' : 'Submit Bug Report'}
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default BugReportForm;

import React from 'react';
import { Card, CardContent, Typography, Box } from '@mui/material';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

/**
 * Brand Distribution Chart Component
 * Shows product distribution across different brands
 */
const BrandDistributionChart = ({ data, title = "Brand Distribution" }) => {
  // Custom tooltip for better data display
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      const data = payload[0];
      return (
        <Box
          sx={{
            backgroundColor: 'rgba(255, 255, 255, 0.95)',
            border: '1px solid #ccc',
            borderRadius: 1,
            padding: 1,
            boxShadow: 2
          }}
        >
          <Typography variant="body2" fontWeight="bold">
            {label}
          </Typography>
          <Typography variant="body2" color="primary">
            Products: {data.value}
          </Typography>
          {data.payload.percentage && (
            <Typography variant="body2" color="text.secondary">
              {data.payload.percentage}% of total
            </Typography>
          )}
        </Box>
      );
    }
    return null;
  };

  if (!data || data.length === 0) {
    return (
      <Card sx={{ height: 400 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            {title}
          </Typography>
          <Box 
            sx={{ 
              display: 'flex', 
              alignItems: 'center', 
              justifyContent: 'center', 
              height: 300,
              color: 'text.secondary'
            }}
          >
            No brand data available
          </Box>
        </CardContent>
      </Card>
    );
  }

  // Calculate percentages
  const total = data.reduce((sum, item) => sum + item.value, 0);
  const dataWithPercentage = data.map(item => ({
    ...item,
    percentage: ((item.value / total) * 100).toFixed(1)
  }));

  // Sort by value descending and take top 10
  const sortedData = dataWithPercentage
    .sort((a, b) => b.value - a.value)
    .slice(0, 10);

  return (
    <Card sx={{ height: 400 }}>
      <CardContent>
        <Typography variant="h6" gutterBottom>
          {title}
        </Typography>
        <ResponsiveContainer width="100%" height={300}>
          <BarChart
            data={sortedData}
            margin={{
              top: 5,
              right: 30,
              left: 20,
              bottom: 60,
            }}
          >
            <CartesianGrid strokeDasharray="3 3" />
            <XAxis 
              dataKey="name" 
              angle={-45}
              textAnchor="end"
              height={80}
              interval={0}
              fontSize={12}
            />
            <YAxis />
            <Tooltip content={<CustomTooltip />} />
            <Bar 
              dataKey="value" 
              fill="#2196f3"
              radius={[4, 4, 0, 0]}
            />
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
};

