      onClose={onClose}
      anchorOrigin={anchorOrigin}
      TransitionComponent={animations ? TransitionComponent : undefined}
    >
      <Alert
        onClose={onClose}
        severity="success"
        variant={variant}
        icon={showIcon ? <SuccessIcon /> : false}
        action={action}
        sx={{
          minWidth: 300,
          '& .MuiAlert-message': {
            display: 'flex',
            alignItems: 'center',
