import React from 'react';
import { Alert, Box, Button, Typography, Paper } from '@mui/material';
import { ErrorOutline, Refresh } from '@mui/icons-material';

class GridErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null, 
      errorInfo: null,
      retryCount: 0
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({
      error,
      errorInfo
    });

    // Log error for debugging
    console.error(`Grid Error in ${this.props.gridName}:`, error, errorInfo);

    // Call parent error handler if provided
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      retryCount: this.state.retryCount + 1
    });

    // Call retry handler if provided
    if (this.props.onRetry) {
      this.props.onRetry();
    }
  };

  render() {
    if (this.state.hasError) {
      return (
        <Paper 
          elevation={2} 
          sx={{ 
            p: 3, 
            m: 2, 
            textAlign: 'center',
            minHeight: '200px',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          <ErrorOutline sx={{ fontSize: 48, color: 'error.main', mb: 2 }} />

          <Typography variant="h6" gutterBottom>
            Grid Error Occurred
          </Typography>

          <Typography variant="body2" color="text.secondary" paragraph>
            {this.props.gridName && `Grid: ${this.props.gridName}`}
          </Typography>

          {process.env.NODE_ENV === 'development' && (
            <Box sx={{ mt: 2, mb: 2, textAlign: 'left', width: '100%' }}>
              <Alert severity="error" sx={{ textAlign: 'left' }}>
                <Typography variant="caption" component="div">
                  <strong>Error:</strong> {this.state.error?.message}
                </Typography>
                {this.state.errorInfo?.componentStack && (
                  <Typography variant="caption" component="pre" sx={{ mt: 1, fontSize: '0.7rem' }}>
                    {this.state.errorInfo.componentStack.split('\n').slice(0, 5).join('\n')}
                  </Typography>
                )}
              </Alert>
            </Box>
          )}

          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button 
              variant="contained" 
              startIcon={<Refresh />}
              onClick={this.handleRetry}
              disabled={this.state.retryCount >= 3}
            >
              {this.state.retryCount >= 3 ? 'Max Retries Reached' : 'Retry'}
            </Button>

            {this.props.fallbackComponent && (
              <Button 
                variant="outlined" 
                onClick={() => this.setState({ hasError: false })}
              >
                Use Fallback
              </Button>
            )}
          </Box>

          {this.state.retryCount > 0 && (
            <Typography variant="caption" color="text.secondary" sx={{ mt: 1 }}>
              Retry attempts: {this.state.retryCount}/3
            </Typography>
          )}
        </Paper>
      );
    }

    // If there's a fallback component and we've exceeded retries, show it
    if (this.state.retryCount >= 3 && this.props.fallbackComponent) {
      return this.props.fallbackComponent;
    }

    return this.props.children;
  }
}

export default GridErrorBoundary;

/**
 * Grid Settings Component
 * Comprehensive grid customization and settings management
 */

import React, { useState, useEffect, useCallback } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Switch,
  FormControlLabel,
  Slider,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Chip,
  Stack,
  Divider,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  TextField,
  IconButton,
  Tooltip,
  Alert,
  Card,
  CardContent,
  Grid,
  useTheme
} from '@mui/material';
import {
  ExpandMore,
  Settings,
  Visibility,
  VisibilityOff,
  DragIndicator,
  Refresh,
  Save,
  RestoreFromTrash,
  Download,
  Upload
} from '@mui/icons-material';
import { DragDropContext, Droppable, Draggable } from 'react-beautiful-dnd';

const GridSettings = ({
  open,
  onClose,
  onSave,
  gridId,
  columns = [],
  currentSettings = {},
  onReset
}) => {
  const theme = useTheme();

  // Settings state
  const [settings, setSettings] = useState({
    // Display settings
    pageSize: 25,
    density: 'standard', // compact, standard, comfortable
    showToolbar: true,
    showFooter: true,
    showColumnHeaders: true,

    // Column settings
    columnVisibility: {},
    columnOrder: [],
    columnWidths: {},

    // Filtering and sorting
    enableFiltering: true,
    enableSorting: true,
    enableColumnReordering: true,
    enableColumnResizing: true,

    // Export settings
    enableExport: true,
    exportFormats: ['csv', 'excel', 'pdf'],

    // Performance settings
    virtualization: true,
    lazyLoading: true,
    cacheSize: 100,

    // Appearance
    theme: 'default',
    alternateRowColors: true,
    showBorders: true,
    headerHeight: 56,
    rowHeight: 52,

    // Advanced features
    enableGrouping: false,
    enableAggregation: false,
    enableSelection: true,
    selectionMode: 'multiple', // single, multiple

    ...currentSettings
  });

  // Initialize settings from props
  useEffect(() => {
    if (currentSettings) {
      setSettings(prev => ({ ...prev, ...currentSettings }));
    }

    // Initialize column visibility and order
    if (columns.length > 0) {
      const visibility = {};
      const order = [];

      columns.forEach(col => {
        visibility[col.field] = col.visible !== false;
        order.push(col.field);
      });

      setSettings(prev => ({
        ...prev,
        columnVisibility: { ...prev.columnVisibility, ...visibility },
        columnOrder: prev.columnOrder.length > 0 ? prev.columnOrder : order
      }));
    }
  }, [currentSettings, columns]);

  /**
   * Handle settings change
   */
  const handleSettingChange = (key, value) => {
    setSettings(prev => ({
      ...prev,
      [key]: value
    }));
  };

  /**
   * Handle column visibility toggle
   */
  const handleColumnVisibilityChange = (field, visible) => {
    setSettings(prev => ({
      ...prev,
      columnVisibility: {
        ...prev.columnVisibility,
        [field]: visible
      }
    }));
  };

  /**
   * Handle column reordering
   */
  const handleColumnReorder = (result) => {
    if (!result.destination) return;

    const newOrder = Array.from(settings.columnOrder);
    const [reorderedItem] = newOrder.splice(result.source.index, 1);
    newOrder.splice(result.destination.index, 0, reorderedItem);

    setSettings(prev => ({
      ...prev,
      columnOrder: newOrder
    }));
  };

  /**
   * Handle save settings
   */
  const handleSave = () => {
    // Save to localStorage
    const storageKey = `gridSettings_${gridId}`;
    localStorage.setItem(storageKey, JSON.stringify(settings));

    // Call parent save handler
    if (onSave) {
      onSave(settings);
    }

    onClose();
  };

  /**
   * Handle reset settings
   */
  const handleReset = () => {
    const defaultSettings = {
      pageSize: 25,
      density: 'standard',
      showToolbar: true,
      showFooter: true,
      showColumnHeaders: true,
      columnVisibility: {},
      columnOrder: [],
      columnWidths: {},
      enableFiltering: true,
      enableSorting: true,
      enableColumnReordering: true,
      enableColumnResizing: true,
      enableExport: true,
      exportFormats: ['csv', 'excel', 'pdf'],
      virtualization: true,
      lazyLoading: true,
      cacheSize: 100,
      theme: 'default',
      alternateRowColors: true,
      showBorders: true,
      headerHeight: 56,
      rowHeight: 52,
      enableGrouping: false,
      enableAggregation: false,
      enableSelection: true,
      selectionMode: 'multiple'
    };

    setSettings(defaultSettings);

    // Clear from localStorage
    const storageKey = `gridSettings_${gridId}`;
    localStorage.removeItem(storageKey);

    if (onReset) {
      onReset();
    }
  };

  /**
   * Export settings
   */
  const handleExportSettings = () => {
    const dataStr = JSON.stringify(settings, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);

    const exportFileDefaultName = `grid-settings-${gridId}.json`;

    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  /**
   * Import settings
   */
  const handleImportSettings = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const importedSettings = JSON.parse(e.target.result);
          setSettings(prev => ({ ...prev, ...importedSettings }));
        } catch (error) {
          console.error('Error importing settings:', error);
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 2,
          maxHeight: '90vh'
        }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 1,
        borderBottom: `1px solid ${theme.palette.divider}`
      }}>
        <Settings />
        Grid Settings - {gridId}
      </DialogTitle>

      <DialogContent sx={{ p: 0 }}>
        <Box sx={{ p: 3 }}>
          {/* Quick Actions */}
          <Stack direction="row" spacing={1} sx={{ mb: 3 }}>
            <Button
              size="small"
              startIcon={<Download />}
              onClick={handleExportSettings}
            >
              Export
            </Button>
            <Button
              size="small"
              startIcon={<Upload />}
              component="label"
            >
              Import
              <input
                type="file"
                hidden
                accept=".json"
                onChange={handleImportSettings}
              />
            </Button>
            <Button
              size="small"
              startIcon={<RestoreFromTrash />}
              onClick={handleReset}
              color="warning"
            >
              Reset
            </Button>
          </Stack>

          {/* Display Settings */}
          <Accordion defaultExpanded>
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Display Settings</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={3}>
                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth size="small">
                    <InputLabel>Page Size</InputLabel>
                    <Select
                      value={settings.pageSize}
                      label="Page Size"
                      onChange={(e) => handleSettingChange('pageSize', e.target.value)}
                    >
                      <MenuItem value={10}>10 rows</MenuItem>
                      <MenuItem value={25}>25 rows</MenuItem>
                      <MenuItem value={50}>50 rows</MenuItem>
                      <MenuItem value={100}>100 rows</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <FormControl fullWidth size="small">
                    <InputLabel>Density</InputLabel>
                    <Select
                      value={settings.density}
                      label="Density"
                      onChange={(e) => handleSettingChange('density', e.target.value)}
                    >
                      <MenuItem value="compact">Compact</MenuItem>
                      <MenuItem value="standard">Standard</MenuItem>
                      <MenuItem value="comfortable">Comfortable</MenuItem>
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <Stack spacing={1}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.showToolbar}
                          onChange={(e) => handleSettingChange('showToolbar', e.target.checked)}
                        />
                      }
                      label="Show Toolbar"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.showFooter}
                          onChange={(e) => handleSettingChange('showFooter', e.target.checked)}
                        />
                      }
                      label="Show Footer"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.alternateRowColors}
                          onChange={(e) => handleSettingChange('alternateRowColors', e.target.checked)}
                        />
                      }
                      label="Alternate Row Colors"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.showBorders}
                          onChange={(e) => handleSettingChange('showBorders', e.target.checked)}
                        />
                      }
                      label="Show Borders"
                    />
                  </Stack>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>

          {/* Column Settings */}
          <Accordion>
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Column Settings</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Typography variant="subtitle2" sx={{ mb: 2 }}>
                Drag to reorder columns, toggle visibility
              </Typography>

              <DragDropContext onDragEnd={handleColumnReorder}>
                <Droppable droppableId="columns">
                  {(provided) => (
                    <Box {...provided.droppableProps} ref={provided.innerRef}>
                      {settings.columnOrder.map((field, index) => {
                        const column = columns.find(col => col.field === field);
                        if (!column) return null;

                        return (
                          <Draggable key={field} draggableId={field} index={index}>
                            {(provided, snapshot) => (
                              <Card
                                ref={provided.innerRef}
                                {...provided.draggableProps}
                                sx={{
                                  mb: 1,
                                  backgroundColor: snapshot.isDragging 
                                    ? theme.palette.action.hover 
                                    : 'inherit'
                                }}
                              >
                                <CardContent sx={{ py: 1, '&:last-child': { pb: 1 } }}>
                                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                                    <Box {...provided.dragHandleProps}>
                                      <DragIndicator color="action" />
                                    </Box>

                                    <Typography sx={{ flexGrow: 1 }}>
                                      {column.headerName || column.field}
                                    </Typography>

                                    <IconButton
                                      size="small"
                                      onClick={() => handleColumnVisibilityChange(
                                        field, 
                                        !settings.columnVisibility[field]
                                      )}
                                    >
                                      {settings.columnVisibility[field] ? 
                                        <Visibility /> : <VisibilityOff />
                                      }
                                    </IconButton>
                                  </Box>
                                </CardContent>
                              </Card>
                            )}
                          </Draggable>
                        );
                      })}
                      {provided.placeholder}
                    </Box>
                  )}
                </Droppable>
              </DragDropContext>
            </AccordionDetails>
          </Accordion>

          {/* Feature Settings */}
          <Accordion>
            <AccordionSummary expandIcon={<ExpandMore />}>
              <Typography variant="h6">Features</Typography>
            </AccordionSummary>
            <AccordionDetails>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <Stack spacing={1}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.enableFiltering}
                          onChange={(e) => handleSettingChange('enableFiltering', e.target.checked)}
                        />
                      }
                      label="Enable Filtering"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.enableSorting}
                          onChange={(e) => handleSettingChange('enableSorting', e.target.checked)}
                        />
                      }
                      label="Enable Sorting"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.enableColumnReordering}
                          onChange={(e) => handleSettingChange('enableColumnReordering', e.target.checked)}
                        />
                      }
                      label="Column Reordering"
                    />
                  </Stack>
                </Grid>

                <Grid item xs={12} sm={6}>
                  <Stack spacing={1}>
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.enableExport}
                          onChange={(e) => handleSettingChange('enableExport', e.target.checked)}
                        />
                      }
                      label="Enable Export"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.virtualization}
                          onChange={(e) => handleSettingChange('virtualization', e.target.checked)}
                        />
                      }
                      label="Virtualization"
                    />
                    <FormControlLabel
                      control={
                        <Switch
                          checked={settings.enableSelection}
                          onChange={(e) => handleSettingChange('enableSelection', e.target.checked)}
                        />
                      }
                      label="Row Selection"
                    />
                  </Stack>
                </Grid>
              </Grid>
            </AccordionDetails>
          </Accordion>
        </Box>
      </DialogContent>

      <DialogActions sx={{ p: 3, borderTop: `1px solid ${theme.palette.divider}` }}>
        <Button onClick={onClose}>
          Cancel
        </Button>
        <Button
          variant="contained"
          onClick={handleSave}
          startIcon={<Save />}
        >
          Save Settings
        </Button>
      </DialogActions>
    </Dialog>
  );
};

/**
 * Hook to manage grid settings
 */
export const useGridSettings = (gridId, defaultSettings = {}) => {
  const [settings, setSettings] = useState(defaultSettings);
  const [settingsLoaded, setSettingsLoaded] = useState(false);

  // Load settings from localStorage on mount
  useEffect(() => {
    const storageKey = `gridSettings_${gridId}`;
    const savedSettings = localStorage.getItem(storageKey);

    if (savedSettings) {
      try {
        const parsed = JSON.parse(savedSettings);
        setSettings(prev => ({ ...prev, ...parsed }));
      } catch (error) {
        console.error('Error loading grid settings:', error);
      }
    }

    setSettingsLoaded(true);
  }, [gridId]);

  // Save settings to localStorage
  const saveSettings = useCallback((newSettings) => {
    const storageKey = `gridSettings_${gridId}`;
    const mergedSettings = { ...settings, ...newSettings };

    localStorage.setItem(storageKey, JSON.stringify(mergedSettings));
    setSettings(mergedSettings);
  }, [gridId, settings]);

  // Reset settings
  const resetSettings = useCallback(() => {
    const storageKey = `gridSettings_${gridId}`;
    localStorage.removeItem(storageKey);
    setSettings(defaultSettings);
  }, [gridId, defaultSettings]);

  return {
    settings,
    settingsLoaded,
    saveSettings,
    resetSettings,
    updateSetting: (key, value) => {
      const newSettings = { ...settings, [key]: value };
      saveSettings(newSettings);
    }
  };
};

export default GridSettings;

// GridToolbarActions - Modular Action Buttons Component
import React from 'react';
import {
  Box,
  Button
} from '@mui/material';
import TooltipWrapper from './TooltipWrapper';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  FileDownload as ExportIcon,
  FileUpload as ImportIcon,
  Sync as SyncIcon,
  Autorenew as AutorenewIcon,
  Info as InfoIcon
} from '@mui/icons-material';

/**
 * GridToolbarActions - Action buttons section of the toolbar
 * Handles all action buttons like Add, Edit, Delete, Sync, Export, etc.
 */
const GridToolbarActions = ({
  config,
  selectedCount,
  hasSelection,
  onAdd,
  onEdit,
  onDelete,
  onSync,
  onExport,
  onImport,
  customActions = [],
  loading = false,
  buttonSize = 'medium',
  spacing = 1,
  translate,
  mdmStocks,

  // Custom action handlers from CustomGridToolbar
  onSyncStocksHandler,
  onSyncAllHandler,
  canInfo,
  onInfo
}) => {
  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: spacing }}>
      {/* Add Button */}
      {config.showAdd && (
        <TooltipWrapper title={translate('add', 'Add New')} disabled={loading}>
          <Button
            startIcon={<AddIcon />}
            onClick={onAdd}
            variant="contained"
            size={buttonSize}
            disabled={loading}
          >
            {config.compact ? '' : translate('add', 'Add')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Edit Button */}
      {config.showEdit && (
        <TooltipWrapper title={translate('edit', 'Edit Selected')} disabled={!hasSelection || loading}>
          <Button
            startIcon={<EditIcon />}
            onClick={onEdit}
            variant="outlined"
            size={buttonSize}
            disabled={!hasSelection || loading}
          >
            {config.compact ? '' : translate('edit', 'Edit')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Delete Button */}
      {config.showDelete && (
        <TooltipWrapper title={translate('delete', 'Delete Selected')} disabled={!hasSelection || loading}>
          <Button
            startIcon={<DeleteIcon />}
            onClick={onDelete}
            variant="outlined"
            color="error"
            size={buttonSize}
            disabled={!hasSelection || loading}
          >
            {config.compact ? '' : translate('delete', 'Delete')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Sync Button */}
      {config.showSync && (
        <TooltipWrapper title={translate('sync', 'Sync Data')} disabled={loading}>
          <Button
            startIcon={<SyncIcon />}
            onClick={onSync}
            variant="outlined"
            color="secondary"
            size={buttonSize}
            disabled={loading}
          >
            {config.compact ? '' : translate('sync', 'Sync')}
          </Button>
        </TooltipWrapper>
      )}



      {/* Import Button */}
      {config.showImport && (
        <TooltipWrapper title={translate('import', 'Import Data')} disabled={loading}>
          <Button
            startIcon={<ImportIcon />}
            onClick={onImport}
            variant="outlined"
            size={buttonSize}
            disabled={loading}
          >
            {config.compact ? '' : translate('import', 'Import')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Info Button */}
      {canInfo && (
        <TooltipWrapper title={translate('info', 'Information')} disabled={loading}>
          <Button
            startIcon={<InfoIcon />}
            onClick={onInfo}
            variant="outlined"
            size={buttonSize}
            disabled={loading}
          >
            {config.compact ? '' : translate('info', 'Info')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Export Button */}
      {config.showExport && (
        <TooltipWrapper title={translate('export', 'Export Data')} disabled={loading}>
          <Button
            startIcon={<ExportIcon />}
            onClick={onExport}
            variant="outlined"
            size={buttonSize}
            disabled={loading}
          >
            {config.compact ? '' : translate('export', 'Export')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Sync Stocks Button - Only for MDM grids */}
      {mdmStocks && typeof onSyncStocksHandler === 'function' && (
        <TooltipWrapper title={translate('syncStocks', 'Mark changed stocks for sync')} disabled={loading}>
          <Button
            variant="outlined"
            color="warning"
            size={buttonSize}
            onClick={onSyncStocksHandler}
            startIcon={<AutorenewIcon />}
            disabled={loading}
          >
            {config.compact ? '' : translate('syncStocks', 'Mark Changed Stocks')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Sync All Handler - Only for MDM grids */}
      {mdmStocks && typeof onSyncAllHandler === 'function' && (
        <TooltipWrapper title={translate('syncAll', 'Sync all data')} disabled={loading}>
          <Button
            variant="outlined"
            color="secondary"
            size={buttonSize}
            onClick={onSyncAllHandler}
            startIcon={<SyncIcon />}
            disabled={loading}
          >
            {config.compact ? '' : translate('syncAll', 'Sync All')}
          </Button>
        </TooltipWrapper>
      )}

      {/* Custom Actions */}
      {customActions.map((action, index) => {
        // Safely render icon - ensure it's a valid React element
        const renderIcon = () => {
          if (!action.icon) return null;

          // Handle Material-UI icon components (functions)
          if (typeof action.icon === 'function') {
            const IconComponent = action.icon;
            return <IconComponent />;
          }

          // Handle React elements
          if (React.isValidElement(action.icon)) {
            return action.icon;
          }

          // Invalid icon type - return null to avoid prop type warning
          return null;
        };

        return (
          <TooltipWrapper 
            key={index} 
            title={action.tooltip || action.label}
            disabled={action.disabled || loading}
          >
            <Button
              startIcon={renderIcon()}
              onClick={action.onClick}
              variant={action.variant || 'outlined'}
              color={action.color || 'primary'}
              size={buttonSize}
              disabled={action.disabled || loading}
            >
              {config.compact ? '' : action.label}
            </Button>
          </TooltipWrapper>
        );
      })}
    </Box>
  );
};

