      </MenuItem>

      {/* Column Visibility Controls */}
      {Object.keys(columnVisibility).length > 0 && (
        <Box sx={{ maxHeight: 200, overflow: 'auto' }}>
          {Object.entries(columnVisibility).map(([field, visible]) => (
            <MenuItem key={field} dense>
              <FormControlLabel
                control={
                  <Switch
                    checked={visible}
                    onChange={(e) => {
                      onColumnVisibilityChange?.({
                        ...columnVisibility,
