 */
const StatCard = memo(({ title, value, icon, color = 'primary', active, onClick }) => {
  return (
    <BaseCard
      variant="stats"
      title={title}
      value={value}
      icon={icon}
      color={color}
      onClick={onClick}
      sx={{
        minWidth: 160,
        width: 160,
        '@media (max-width: 960px)': {
          minWidth: 140,
          width: 140,
        },
