/**
 * Enhanced Suspense wrapper with timeout and progress indication
 */
export const EnhancedSuspense = ({
  children,
  fallback,
  delay = 0,
  timeout = 10000,
  onTimeout,
  showProgress = true,
  progressVariant = 'circular'
}) => {
  const [isDelayed, setIsDelayed] = useState(delay > 0);
  const [isTimedOut, setIsTimedOut] = useState(false);
  const [isPending, startTransition] = useTransition();
  const theme = useTheme();

  // Handle delay
  useEffect(() => {
    if (delay > 0) {
      const delayTimer = setTimeout(() => {
        startTransition(() => {
          setIsDelayed(false);
        });
      }, delay);

      return () => clearTimeout(delayTimer);
    }
  }, [delay]);

  // Handle timeout
  useEffect(() => {
    if (timeout > 0) {
      const timeoutTimer = setTimeout(() => {
        setIsTimedOut(true);
        onTimeout?.();
      }, timeout);

      return () => clearTimeout(timeoutTimer);
    }
  }, [timeout, onTimeout]);

  // Default fallback based on progress variant
  const defaultFallback = useMemo(() => {
    if (!showProgress) return null;

    switch (progressVariant) {
      case 'linear':
        return <LinearLoader message="Loading component..." />;
      case 'skeleton':
        return <SkeletonLoader />;
      default:
        return <CircularLoader message="Loading..." />;
    }
  }, [showProgress, progressVariant]);

  // Don't render anything during delay period
  if (isDelayed) {
    return null;
  }

  // Show timeout message
  if (isTimedOut) {
    return (
      <Box
        display="flex"
        flexDirection="column"
        alignItems="center"
        justifyContent="center"
        p={4}
        color="error.main"
      >
        <Typography variant="h6" gutterBottom>
          Loading timeout
        </Typography>
        <Typography variant="body2" color="text.secondary">
          The component is taking longer than expected to load.
        </Typography>
      </Box>
    );
  }

  return (
    <AnimatePresence mode="wait">
      <Suspense fallback={fallback || defaultFallback}>
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{ duration: 0.3 }}
        >
          {children}
        </motion.div>
      </Suspense>
    </AnimatePresence>
  );
};

