} from '@mui/icons-material';
import { useUserSettings, useSystemPreferences } from '../../hooks/useUserSettings';
import { languages } from '../../contexts/LanguageContext';

const UserPreferencesPanel = ({ open, onClose }) => {
  const theme = useTheme();
  const {
    currentUser,
    mode,
    currentLanguage,
    fontSize,
    settings,
    loading,
    setThemeMode,
    setLanguage,
    setFontSize,
    saveCurrentPreferences,
    resetToSystemDefaults,
    applySystemDefaults
  } = useUserSettings();

  const { systemTheme, systemLanguage, systemPrefersDark } = useSystemPreferences();
  const [saving, setSaving] = useState(false);

  /**
   * Handle theme change
   */
  const handleThemeChange = (newTheme) => {
    setThemeMode(newTheme);
  };

  /**
   * Handle language change
   */
  const handleLanguageChange = (newLanguage) => {
    setLanguage(newLanguage);
  };

  /**
   * Handle font size change
   */
  const handleFontSizeChange = (newFontSize) => {
    setFontSize(newFontSize);
  };

  /**
   * Save preferences
   */
  const handleSave = async () => {
    setSaving(true);
    try {
      const result = await saveCurrentPreferences();
      if (result.success) {
        onClose();
      }
    } catch (error) {
      console.error('Error saving preferences:', error);
    } finally {
      setSaving(false);
    }
  };

  /**
   * Reset to defaults
   */
  const handleReset = () => {
    if (currentUser) {
      resetToSystemDefaults();
    } else {
      applySystemDefaults();
    }
  };

  const themeOptions = [
    { value: 'light', label: 'Light', icon: <Brightness7 /> },
    { value: 'dark', label: 'Dark', icon: <Brightness4 /> },
    { value: 'system', label: 'System', icon: <Computer /> }
  ];

  const fontSizeOptions = [
    { value: 'small', label: 'Small' },
    { value: 'medium', label: 'Medium' },
    { value: 'large', label: 'Large' }
  ];

