          background: COLORS.gradient[color] || COLORS.gradient.primary,
          color: 'white',
          cursor: onClick ? 'pointer' : 'default',
          position: 'relative',
          overflow: 'hidden',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            background: isHovered 
              ? 'rgba(255, 255, 255, 0.1)' 
              : 'transparent',
            transition: 'background 0.3s ease'
