/**
 * Professional Status Widget
 */
export const ProfessionalStatusWidget = ({
  title,
  items,
  loading = false
}) => {
  const getStatusIcon = (status) => {
    switch (status) {
      case 'success': return <CheckCircle sx={{ color: COLORS.success }} />;
      case 'warning': return <Warning sx={{ color: COLORS.warning }} />;
      case 'error': return <Error sx={{ color: COLORS.error }} />;
      default: return <Info sx={{ color: COLORS.info }} />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'success': return COLORS.success;
      case 'warning': return COLORS.warning;
      case 'error': return COLORS.error;
      default: return COLORS.info;
    }
  };

  return (
    <Card sx={{ height: '100%' }}>
      <CardContent>
        <Typography variant="h6" sx={{ fontWeight: 600, mb: 3 }}>
          {title}
        </Typography>

        {loading ? (
          <Stack spacing={2}>
            {[1, 2, 3, 4].map((i) => (
              <Box key={i} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Skeleton variant="circular" width={24} height={24} />
                <Skeleton variant="text" width="70%" />
              </Box>
            ))}
          </Stack>
        ) : (
          <Stack spacing={2}>
            {items.map((item, index) => (
              <Box key={index} sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                {getStatusIcon(item.status)}
                <Box sx={{ flexGrow: 1 }}>
                  <Typography variant="body2" sx={{ fontWeight: 500 }}>
                    {item.label}
                  </Typography>
                  {item.description && (
                    <Typography variant="caption" color="text.secondary">
                      {item.description}
                    </Typography>
                  )}
                </Box>
                {item.badge && (
                  <Chip
                    label={item.badge}
                    size="small"
                    sx={{
                      backgroundColor: alpha(getStatusColor(item.status), 0.1),
                      color: getStatusColor(item.status),
                      fontWeight: 600
                    }}
                  />
                )}
              </Box>
            ))}
          </Stack>
        )}
      </CardContent>
    </Card>
  );
};

