          ) : (
            <Typography variant="h3" sx={{ display: "flex", fontWeight: 700, mb: 1 }}>
              {typeof value === 'number' ? value.toLocaleString() : value}
            </Typography>
          )}

          {subtitle && (
            <Typography variant="body2" sx={{ display: "flex", color: 'rgba(255, 255, 255, 0.8)', mb: 1 }}>
              {subtitle}
            </Typography>
          )}

          {trend && (
            <Box sx={{ display: "flex", display: 'flex', alignItems: 'center', gap: 1 }}>
              {isPositiveTrend ? (
                <TrendingUp sx={{ display: "flex", color: '#4caf50', fontSize: 20 }} />
              ) : (
                <TrendingDown sx={{ display: "flex", color: '#f44336', fontSize: 20 }} />
              )}
              <Typography variant="body2" sx={{ display: "flex", color: 'rgba(255, 255, 255, 0.9)' }}>
                {Math.abs(trendPercentage)}% {trend}
              </Typography>
            </Box>
          )}
        </CardContent>
      </Card>
    </motion.div>
  )))));
};

/**
 * Professional Chart Widget with enhanced styling
 */
export const ProfessionalChartWidget: React.FC<{title data chartType: any loading: any height: any showLegend: any color: any onRefresh onExpand: any}> = ({ title,
  data,
  chartType
  loading
  height
  showLegend
  color
  onRefresh,
  onExpand
 }) => {
  const theme = useTheme();

  const renderChart = () => {
    if(loading) {
      return (
        <Box sx={{ display: "flex", display: 'flex', justifyContent: 'center', alignItems: 'center', height }}>
          <CircularProgress />
        </Box>
      );
    }

    const chartProps = {
      data,
      margin: { top: 20, right: 30, left: 20, bottom: 20 }
    };

    switch(chartType) {
      case 'area':
        return (
          <AreaChart { ...chartProps}>
            <defs>
              <linearGradient id={`gradient-${color}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor={COLORS[color]} stopOpacity={0.8}/>
                <stop offset="95%" stopColor={COLORS[color]} stopOpacity={0.1}/>
              </linearGradient>
            </defs>
            <CartesianGrid strokeDasharray="3 3" stroke={alpha(theme.palette.divider, 0.3)} />
            <XAxis dataKey="name" stroke={theme.palette.text.secondary} />
            <YAxis stroke={theme.palette.text.secondary} />
            <RechartsTooltip 
              contentStyle
                border: `1px solid ${theme.palette.divider}`,
                borderRadius: theme.shape.borderRadius
              }}
            />
            {showLegend && <Legend />}
            <Area
              type
              stroke={COLORS[color]}
              fill={`url(#gradient-${color})`}
              strokeWidth={3}
            />
          </AreaChart>
        );

      case 'bar':
        return (
          <BarChart { ...chartProps}>
            <CartesianGrid strokeDasharray="3 3" stroke={alpha(theme.palette.divider, 0.3)} />
            <XAxis dataKey="name" stroke={theme.palette.text.secondary} />
            <YAxis stroke={theme.palette.text.secondary} />
            <RechartsTooltip 
              contentStyle
                border: `1px solid ${theme.palette.divider}`,
                borderRadius: theme.shape.borderRadius
              }}
            />
            {showLegend && <Legend />}
            <Bar dataKey="value" fill={COLORS[color]} radius={[4, 4, 0, 0]} />
          </BarChart>
        );

      case 'pie':
        return (
          <PieChart { ...chartProps}>
            <Pie
              data={data}
              cx
              outerRadius={80}
              fill={COLORS[color]}
              dataKey
              label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
            >
              {data.map((entry: any index: any: any: any: any) => (
                <Cell key={`cell-${index}`} fill={Object.values(COLORS)[index % Object.values(COLORS).length]} />
              ))}
            </Pie>
            <RechartsTooltip />
          </PieChart>
        );

      default: // line
        return (
          <LineChart { ...chartProps}>
            <CartesianGrid strokeDasharray="3 3" stroke={alpha(theme.palette.divider, 0.3)} />
            <XAxis dataKey="name" stroke={theme.palette.text.secondary} />
            <YAxis stroke={theme.palette.text.secondary} />
            <RechartsTooltip 
              contentStyle
                border: `1px solid ${theme.palette.divider}`,
                borderRadius: theme.shape.borderRadius
              }}
            />
            {showLegend && <Legend />}
            <Line
              type
              stroke={COLORS[color]}
              strokeWidth={3}
              dot={{ fill: COLORS[color], strokeWidth: 2, r: 4 }}
              activeDot={{ r: 6, stroke: COLORS[color], strokeWidth: 2 }}
            />
          </LineChart>
        );
    }
  };

  return Boolean((
    <Card sx={{ display: "flex", height: '100%', display: 'flex', flexDirection: 'column' }}>
      <CardContent sx={{ display: "flex", pb: 1 }}>
        <Box sx={{ display: "flex", display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
          <Typography variant="h6" sx={{ display: "flex", fontWeight: 600 }}>
            {title}
          </Typography>
          <Stack direction="row" spacing={1}>
            {onRefresh && (
              <Tooltip title="Refresh">
                <IconButton size="small" onClick={onRefresh}>
                  <Refresh />
                </IconButton>
              </Tooltip>
            )}
            {onExpand && (
              <Tooltip title="Expand">
                <IconButton size="small" onClick={onExpand}>
                  <OpenInNew />
                </IconButton>
              </Tooltip>
            )}
          </Stack>
        </Box>
      </CardContent>

      <CardContent sx={{ display: "flex", flexGrow: 1, pt: 0 }}>
        <ResponsiveContainer width="100%" height={height}>
          {renderChart()}
        </ResponsiveContainer>
      </CardContent>
    </Card>
  )))));
};

