                      <Typography variant="caption" color="text.disabled" component="span">
                        {formatTimeAgo(activity.timestamp)}
                      </Typography>
                    </span>
                  }
                />
              </ListItem>
              {index < filteredActivities.slice(0, 8).length - 1 && (
