                <Typography variant="h4" color="primary" fontWeight={700}>
                  {sources.length}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Total Sources
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          {sources.length > 0 && (
            <>
              <Grid item xs={12} md={4}>
                <Card variant="outlined">
                  <CardContent sx={{ display: "flex", textAlign: 'center' }}>
                    <Typography variant="h4" color="success.main" fontWeight={700}>
                      {completedSources.length}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Completed
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>

              <Grid item xs={12} md={4}>
                <Card variant="outlined">
                  <CardContent sx={{ display: "flex", textAlign: 'center' }}>
                    <Typography variant="h4" color="error.main" fontWeight={700}>
                      {errorSources.length}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Failed
                    </Typography>
                  </CardContent>
                </Card>
              </Grid>
            </>
          )}
        </Grid>

        {/* Main Progress */}
        {(isActive || completed) && (
          <Box sx={{ display: "flex", mb: 3 }}>
            <Box sx={{ display: "flex", display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
              <Typography variant="body2" color="text.secondary">
                Overall Progress: {current} / {total} Steps
              </Typography>
              <Typography variant="body2" fontWeight={600} color="primary">
                {percentage}%
              </Typography>
            </Box>
            <LinearProgress
              variant="body2"
              value={percentage}
              sx={{
                backgroundColor: 'rgba(0,0,0,0.1)',
                '& .MuiLinearProgress-bar': {
                  borderRadius: 4,
                  background: completed 
                    ? 'linear-gradient(90deg, #4caf50 0%, #8bc34a 100%)'
                    : errorSources.length > 0
                    ? 'linear-gradient(90deg, #f44336 0%, #e57373 100%)'
                    : 'linear-gradient(90deg, #ff9800 0%, #ffb74d 100%)'
                }
              }}
            />
          </Box>
        )}

        {/* Current Step */}
        {currentStep && (
          <Box sx={{ display: "flex", mb: 2 }}>
            <Chip 
              icon={isActive ? <SyncIcon /> : completed ? <SuccessIcon /> : <ErrorIcon />}
              label={currentStep}
              color={getStatusColor()}
              variant="body2"
              sx={{ display: "flex", fontSize: '0.8rem' }}
            />
          </Box>
        )}

        {/* Sources Progress */}
        {sources.length > 0 && (isActive || completed) && (
          <Box sx={{ display: "flex", mb: 2 }}>
            <Typography variant="body2" color="text.secondary" gutterBottom>
              Sources: {completedSources.length} / {sources.length} completed
            </Typography>
