                            ))}
                          
                        
                      
                    
                  
                )}
              
            
          
        
      

      
        
          {uploadResults ? 'Close' : 'Cancel'}
        
        {activeStep > 0 && !uploadResults && (
          
            Reset
          
        )}
      
    
  );
};

export default BulkMediaUploadDialog;

import React, { useState, useCallback } from 'react';

// Type definitions
interface CSVData {
  headers: string[];
  data: any[][];
  skuColumn: string;
  imageColumn: string;
  refColumn?: string;
}

interface FileWithPreview extends File {
  preview?: string;
}

interface UploadProgress {
  current: number;
  total: number;
  sku?: string;
  fileName?: string;
  status?: string;
  stage?: string;
}

interface UploadStats {
  successful: number;
  failed: number;
  skipped: number;
  total: number;
  matched: number;
  uniqueProducts: number;
  multipleImagesProducts: number;
  averageSimilarity: number;
  matchStrategies: {
    exact: number;
    fuzzy: number;
    ref: number;
    product: number;
  };
}

interface MatchResult {
  sku: string;
  fileName: string;
  file: File;
  matchStrategy: string;
  imageIndex: number;
  totalImagesForSku: number;
  isMainImage: boolean;
  similarity: number;
}

interface MatchingResults {
  matches: MatchResult[];
  stats: UploadStats;
}

interface BulkMediaUploadDialogProps {
  open: boolean;
  onClose: () => void;
  onComplete?: (results: any[]) => void;
}
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Paper,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  LinearProgress,
  Alert,
  Chip,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tooltip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Switch,
  FormControlLabel,
  Slider,
  TextField,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  ToggleButton,
  ToggleButtonGroup,
  Divider,
  Badge
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Description as CSVIcon,
  Image as ImageIcon,
  CheckCircle as SuccessIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Close as CloseIcon,
  Settings as SettingsIcon,
  PhotoLibrary as MultiImageIcon,
  Speed as SpeedIcon,
  Tune as TuneIcon,
  Info as InfoIcon,
