          </Paper>
        )}

        {/* Main Content */}
        <Box sx={{ flexGrow: 1, p: 3, overflow: 'auto' }}>
          <Stepper activeStep={activeStep} orientation="vertical">
            {/* Step 1: CSV Upload */}
