                      : 'Drag & drop CSV file here, or click to select'
                    }
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Automatically detects column structure and enables appropriate matching strategies
                  </Typography>
                </Paper>

                {csvFile && csvData && (
                  <Alert severity="success" sx={{ mt: 2 }}>
                    <Typography variant="body2">
                      <strong>{csvFile.name}</strong> - {csvData.data.length} products loaded
                    </Typography>
                    <Typography variant="caption" display="block">
                      Columns detected: {csvData.skuColumn}, {csvData.imageColumn}
                      {csvData.refColumn && `, ${csvData.refColumn}`}
                    </Typography>
                  </Alert>
                )}
              </StepContent>
            </Step>

            {/* Step 2: Image Upload */}
            <Step>
              <StepLabel>
                <Typography variant="h6">Upload Images</Typography>
              </StepLabel>
              <StepContent>
                <Paper
                  {...imageDropzone.getRootProps()}
                  sx={{
                    p: 4,
                    border: '2px dashed',
                    borderColor: imageDropzone.isDragActive ? 'success.main' : 'grey.300',
                    bgcolor: imageDropzone.isDragActive ? 'success.light' : 'background.default',
                    cursor: 'pointer',
                    textAlign: 'center',
                    transition: 'all 0.2s ease'
                  }}
                >
                  <input {...imageDropzone.getInputProps()} />
                  <MultiImageIcon sx={{ fontSize: 64, color: 'success.main', mb: 2 }} />
                  <Typography variant="h6" gutterBottom>
                    {imageDropzone.isDragActive
                      ? 'Drop images here...'
                      : 'Drag & drop images here, or click to select multiple'
                    }
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Supports: image.jpg, image_1.jpg, image_2.jpg patterns | Max: 10MB per file
                  </Typography>
                </Paper>

                {imageFiles.length > 0 && (
                  <Box sx={{ mt: 3 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                      <Typography variant="subtitle1">
                        Selected Images ({imageFiles.length})
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        Total Size: {(imageFiles.reduce((sum, f) => sum + f.size, 0) / 1024 / 1024).toFixed(2)}MB
                      </Typography>
                    </Box>

                    <Box sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid', borderColor: 'divider', borderRadius: 1, p: 1 }}>
                      <Grid container spacing={1}>
                        {imageFiles.map((file, index) => (
                          <Grid item key={index}>
                            <Chip
                              label={file.name}
                              onDelete={() => removeImage(index)}
                              size="small"
                              color="primary"
                              variant="outlined"
                            />
                          </Grid>
                        ))}
                      </Grid>
                    </Box>

                    <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                      <Button
                        variant="contained"
                        onClick={handleMatching}
                        disabled={!csvData || imageFiles.length === 0 || loading}
                        startIcon={loading ? <SuccessIcon className="spin" /> : <SearchIcon />}
                        color="success"
                      >
                        {loading ? 'Processing...' : 'Start Advanced Matching'}
                      </Button>
                      <Button
                        variant="outlined"
                        onClick={() => setImageFiles([])}
                        disabled={imageFiles.length === 0}
                      >
                        Clear All Images
                      </Button>
                    </Box>
                  </Box>
                )}
              </StepContent>
            </Step>

            {/* Step 3: Review Matches */}
            <Step>
              <StepLabel>
                <Typography variant="h6">Review Advanced Matches</Typography>
              </StepLabel>
              <StepContent>
                {matchingResults && (
                  <Box>
                    {/* Enhanced Statistics Cards */}
                    <Grid container spacing={2} sx={{ mb: 3 }}>
                      <Grid item xs={6} sm={3}>
                        <Card sx={{ textAlign: 'center', bgcolor: 'success.light' }}>
                          <CardContent sx={{ py: 2 }}>
                            <SuccessIcon sx={{ fontSize: 32, color: 'success.main' }} />
                            <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                              {matchingResults.stats.matched}
                            </Typography>
                            <Typography variant="caption">Total Matches</Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                      <Grid item xs={6} sm={3}>
                        <Card sx={{ textAlign: 'center', bgcolor: 'info.light' }}>
                          <CardContent sx={{ py: 2 }}>
                            <MultiImageIcon sx={{ fontSize: 32, color: 'info.main' }} />
                            <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                              {matchingResults.stats.uniqueProducts}
                            </Typography>
                            <Typography variant="caption">Products</Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                      <Grid item xs={6} sm={3}>
                        <Card sx={{ textAlign: 'center', bgcolor: 'warning.light' }}>
                          <CardContent sx={{ py: 2 }}>
                            <WarningIcon sx={{ fontSize: 32, color: 'warning.main' }} />
                            <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                              {matchingResults.stats.multipleImagesProducts || 0}
                            </Typography>
                            <Typography variant="caption">Multi-Image</Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                      <Grid item xs={6} sm={3}>
                        <Card sx={{ textAlign: 'center', bgcolor: 'secondary.light' }}>
                          <CardContent sx={{ py: 2 }}>
                            <AIIcon sx={{ fontSize: 32, color: 'secondary.main' }} />
                            <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                              {matchingResults.stats.averageSimilarity || 0}
                            </Typography>
                            <Typography variant="caption">Avg Similarity</Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                    </Grid>

                    {/* Strategy Breakdown */}
                    <Alert severity="success" sx={{ mb: 3 }}>
                      <Typography variant="body2">
                        <strong>Advanced Matching Complete:</strong> Found {matchingResults.stats.matched} matches 
                        using {Object.values(matchingResults.stats.matchStrategies).filter(v => v > 0).length} strategies.
                      </Typography>
                      <Box sx={{ mt: 1, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                        {matchingResults.stats.matchStrategies.ref > 0 && (
                          <Chip label={`REF: ${matchingResults.stats.matchStrategies.ref}`} color="warning" size="small" />
                        )}
                        {matchingResults.stats.matchStrategies.exact > 0 && (
                          <Chip label={`Exact: ${matchingResults.stats.matchStrategies.exact}`} color="primary" size="small" />
                        )}
                        {matchingResults.stats.matchStrategies.fuzzy > 0 && (
                          <Chip label={`Fuzzy: ${matchingResults.stats.matchStrategies.fuzzy}`} color="success" size="small" />
                        )}
                        {matchingResults.stats.matchStrategies.product > 0 && (
                          <Chip label={`Product: ${matchingResults.stats.matchStrategies.product}`} color="info" size="small" />
                        )}
                      </Box>
                    </Alert>

                    {/* Matches Table */}
                    {matchingResults.matches.length > 0 && (
                      <Box sx={{ mb: 3 }}>
                        <Typography variant="subtitle1" gutterBottom>
                          Matches to Upload ({matchingResults.matches.length})
                        </Typography>
                        <TableContainer component={Paper} sx={{ maxHeight: 300 }}>
                          <Table size="small" stickyHeader>
                            <TableHead>
                              <TableRow>
                                <TableCell>SKU</TableCell>
                                <TableCell>Image File</TableCell>
                                <TableCell>Strategy</TableCell>
                                <TableCell>Position</TableCell>
                                <TableCell>Similarity</TableCell>
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {matchingResults.matches.slice(0, 15).map((match, index) => (
                                <TableRow key={index}>
                                  <TableCell>{match.sku}</TableCell>
                                  <TableCell>{match.file.name}</TableCell>
                                  <TableCell>
                                    <Chip 
                                      label={match.matchStrategy} 
                                      size="small" 
                                      color={
                                        match.matchStrategy === 'ref' ? 'warning' :
                                        match.matchStrategy === 'exact' ? 'primary' :
                                        match.matchStrategy === 'fuzzy' ? 'success' : 'info'
                                      }
                                    />
                                  </TableCell>
                                  <TableCell>
                                    {match.imageIndex + 1}/{match.totalImagesForSku}
                                    {match.isMainImage && (
                                      <Chip label="Main" size="small" color="primary" sx={{ ml: 1 }} />
                                    )}
                                  </TableCell>
                                  <TableCell>{(match.similarity * 100).toFixed(0)}%</TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </TableContainer>
                        {matchingResults.matches.length > 15 && (
                          <Typography variant="caption" sx={{ p: 2, display: 'block', textAlign: 'center' }}>
                            ... and {matchingResults.matches.length - 15} more matches
                          </Typography>
                        )}
                      </Box>
                    )}

                    <Button
                      variant="contained"
                      size="large"
                      onClick={handleStartUpload}
                      disabled={matchingResults.matches.length === 0}
                      startIcon={<UploadIcon />}
                      color="primary"
                    >
                      Start Optimized Upload ({matchingResults.matches.length} images)
                    </Button>
                  </Box>
                )}
              </StepContent>
            </Step>

            {/* Step 4: Upload Process */}
            <Step>
              <StepLabel>
                <Typography variant="h6">Optimized Upload Process</Typography>
              </StepLabel>
              <StepContent>
                {uploadProgress && (
                  <Box sx={{ mb: 3 }}>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                      <Typography variant="body2">
                        Progress: {uploadProgress.current} of {uploadProgress.total}
                      </Typography>
                      <Typography variant="body2">
                        {((uploadProgress.current / uploadProgress.total) * 100).toFixed(1)}%
                      </Typography>
                    </Box>
                    <LinearProgress
                      variant="determinate"
                      value={(uploadProgress.current / uploadProgress.total) * 100}
                      sx={{ mb: 2, height: 8, borderRadius: 4 }}
                    />
                    {uploadProgress.sku && (
                      <Box>
                        <Typography variant="body2" color="primary">
                          Current: SKU {uploadProgress.sku} - {uploadProgress.fileName}
                        </Typography>
                        <Typography variant="caption" color="text.secondary">
                          Status: {uploadProgress.status} | Stage: {uploadProgress.stage}
                        </Typography>
                      </Box>
                    )}
                  </Box>
                )}

                {uploadResults && (
                  <Box>
                    <Alert severity="success" sx={{ mb: 3 }}>
                      <Typography variant="body1" gutterBottom>
                        Optimized upload completed successfully!
                      </Typography>
                      <Typography variant="body2">
                        {uploadResults.filter((r: any) => r.status === 'success').length} successful, {uploadResults.filter((r: any) => r.status === 'error').length} failed
                      </Typography>
                    </Alert>

                    <Box sx={{ maxHeight: 400, overflow: 'auto' }}>
                      <TableContainer component={Paper}>
                        <Table size="small">
                          <TableHead>
                            <TableRow>
                              <TableCell>Status</TableCell>
                              <TableCell>SKU</TableCell>
                              <TableCell>File</TableCell>
                              <TableCell>Strategy</TableCell>
                              <TableCell>Message</TableCell>
                            </TableRow>
                          </TableHead>
                          <TableBody>
                            {uploadResults.map((result: any, index: number) => (
                              <TableRow key={index}>
                                <TableCell>
                                  {result.status === 'success' ? (
                                    <SuccessIcon color="success" fontSize="small" />
                                  ) : (
                                    <ErrorIcon color="error" fontSize="small" />
                                  )}
                                </TableCell>
                                <TableCell>{result.sku}</TableCell>
                                <TableCell>{result.file.name}</TableCell>
                                <TableCell>
                                  <Chip 
                                    label={result.matchStrategy} 
                                    size="small"
                                    color={
                                      result.matchStrategy === 'ref' ? 'warning' :
                                      result.matchStrategy === 'exact' ? 'primary' :
                                      result.matchStrategy === 'fuzzy' ? 'success' : 'info'
                                    }
                                  />
                                </TableCell>
                                <TableCell>
                                  <Typography variant="caption">
                                    {result.result.message}
                                  </Typography>
                                </TableCell>
                              </TableRow>
                            ))}
                          </TableBody>
                        </Table>
                      </TableContainer>
                    </Box>
                  </Box>
                )}
              </StepContent>
            </Step>
          </Stepper>
        </Box>
      </DialogContent>

      <DialogActions sx={{ p: 2, bgcolor: 'background.paper' }}>
        <Button onClick={onClose} disabled={loading}>
          {uploadResults ? 'Close' : 'Cancel'}
        </Button>
        {activeStep > 0 && !uploadResults && (
          <Button onClick={handleReset} color="secondary" disabled={loading}>
            Reset
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default BulkMediaUploadDialog;

import React, { useState, useCallback } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    Alert,
    LinearProgress,
    Stepper,
    Step,
    StepLabel,
    Card,
    CardContent,
    Chip,
    List,
    ListItem,
    ListItemText,
    Divider,
    FormControlLabel,
    Switch
} from '@mui/material';
import {
    CloudUpload as UploadIcon,
    CheckCircle as CheckIcon,
    Error as ErrorIcon,
    Warning as WarningIcon,
    Info as InfoIcon
} from '@mui/icons-material';
import { toast } from 'react-toastify';
import { 
    parseCSVContent, 
    validateMagentoCSV, 
    autoFixCSVIssues, 
    separateProductTypes,
    generateImportSummary 
} from '../../utils/csvImportUtils';
import ProductService from '../../services/ProductService';

const CSVImportDialog = ({ open, onClose, onImportComplete }) => {
    const [activeStep, setActiveStep] = useState(0);
    const [csvFile, setCsvFile] = useState(null);
    const [csvData, setCsvData] = useState([]);
    const [validationResult, setValidationResult] = useState(null);
    const [separatedProducts, setSeparatedProducts] = useState(null);
    const [importSummary, setImportSummary] = useState(null);
    const [importing, setImporting] = useState(false);
    const [importProgress, setImportProgress] = useState({ current: 0, total: 0 });
    const [importResults, setImportResults] = useState(null);
    const [autoFix, setAutoFix] = useState(true);

    const steps = ['Upload CSV', 'Validate Data', 'Review & Import', 'Import Results'];

    const handleFileUpload = useCallback((event) => {
        const file = event.target.files[0];
        if (!file) return;

        if (!file.name.toLowerCase().endsWith('.csv')) {
            toast.error('Please select a CSV file');
            return;
        }

        setCsvFile(file);
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const content = e.target.result;
                const products = parseCSVContent(content);
                setCsvData(products);
                setActiveStep(1);
                toast.success(`Loaded ${products.length} products from CSV`);
            } catch (error) {
                toast.error(`Error parsing CSV: ${error.message}`);
            }
        };

        reader.readAsText(file);
    }, []);

    const handleValidation = useCallback(() => {
        if (csvData.length === 0) return;

        try {
            // Auto-fix common issues if enabled
            const dataToValidate = autoFix ? autoFixCSVIssues(csvData) : csvData;

            // Validate the data
            const validation = validateMagentoCSV(dataToValidate);
            setValidationResult(validation);

            // Separate product types
            const separated = separateProductTypes(validation.validProducts);
            setSeparatedProducts(separated);

            // Generate summary
            const summary = generateImportSummary(validation, separated);
            setImportSummary(summary);

            setActiveStep(2);

            if (validation.isValid) {
                toast.success('CSV validation passed successfully');
            } else {
                toast.warning(`Validation completed with ${validation.errors.length} errors`);
            }
        } catch (error) {
            toast.error(`Validation error: ${error.message}`);
        }
    }, [csvData, autoFix]);

    const handleImport = useCallback(async () => {
        if (!separatedProducts || !validationResult.isValid) return;

        setImporting(true);
        setActiveStep(3);

        try {
            const results = {
                simple: { successful: 0, failed: 0, errors: [] },
                configurable: { successful: 0, failed: 0, errors: [] },
                total: { successful: 0, failed: 0, errors: [] }
            };

            const totalProducts = separatedProducts.simpleProducts.length + 
                                separatedProducts.configurableProducts.length;
            let processedCount = 0;

            // Import simple products first
            if (separatedProducts.simpleProducts.length > 0) {
                const simpleResults = await ProductService.processBulkProducts(
                    separatedProducts.simpleProducts.map(p => ProductService.transformToMagentoFormat(p)),
                    (progress) => {
                        setImportProgress({
                            current: processedCount + progress.current,
                            total: totalProducts,
                            phase: 'Simple Products',
                            ...progress
                        });
                    }
                );

                results.simple = simpleResults;
                processedCount += separatedProducts.simpleProducts.length;
            }

            // Import configurable products
            if (separatedProducts.configurableProducts.length > 0) {
                for (const configurableProduct of separatedProducts.configurableProducts) {
                    try {
                        const result = await ProductService.processConfigurableProduct(configurableProduct);
                        if (result.success) {
                            results.configurable.successful++;
                        } else {
                            results.configurable.failed++;
                            results.configurable.errors.push({
                                sku: configurableProduct.sku,
                                error: result.error
                            });
                        }
                    } catch (error) {
                        results.configurable.failed++;
                        results.configurable.errors.push({
                            sku: configurableProduct.sku,
                            error: error.message
                        });
                    }

                    processedCount++;
                    setImportProgress({
                        current: processedCount,
                        total: totalProducts,
                        phase: 'Configurable Products'
                    });
                }
            }

            // Calculate totals
            results.total.successful = results.simple.successful + results.configurable.successful;
            results.total.failed = results.simple.failed + results.configurable.failed;
            results.total.errors = [...results.simple.errors, ...results.configurable.errors];

            setImportResults(results);

            if (results.total.successful > 0) {
                toast.success(`Successfully imported ${results.total.successful} products`);
                if (onImportComplete) {
                    onImportComplete(results);
                }
            }

            if (results.total.failed > 0) {
                toast.warning(`${results.total.failed} products failed to import`);
            }

        } catch (error) {
            toast.error(`Import failed: ${error.message}`);
        } finally {
            setImporting(false);
        }
    }, [separatedProducts, validationResult, onImportComplete]);

    const handleClose = () => {
        if (!importing) {
            // Reset state
            setActiveStep(0);
            setCsvFile(null);
            setCsvData([]);
            setValidationResult(null);
            setSeparatedProducts(null);
            setImportSummary(null);
            setImportResults(null);
            setImportProgress({ current: 0, total: 0 });
            onClose();
        }
    };

    const renderStepContent = () => {
        switch (activeStep) {
            case 0:
                return (
                    <Box sx={{ textAlign: 'center', py: 4 }}>
                        <input
                            accept=".csv"
                            style={{ display: 'none' }}
                            id="csv-upload"
                            type="file"
                            onChange={handleFileUpload}
                        />
                        <label htmlFor="csv-upload">
                            <Button
                                variant="contained"
                                component="span"
                                startIcon={<UploadIcon />}
                                size="large"
                                sx={{ mb: 2 }}
                            >
                                Select CSV File
                            </Button>
                        </label>
                        <Typography variant="body2" color="text.secondary">
                            Upload a CSV file with product data for Magento import
                        </Typography>
                        {csvFile && (
                            <Alert severity="info" sx={{ mt: 2 }}>
                                Selected: {csvFile.name} ({csvData.length} products)
                            </Alert>
                        )}
                    </Box>
                );

            case 1:
                return (
                    <Box sx={{ py: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={autoFix}
                                        onChange={(e) => setAutoFix(e.target.checked)}
                                    />
                                }
                                label="Auto-fix common issues"
                            />
                        </Box>

                        <Alert severity="info" sx={{ mb: 2 }}>
                            Ready to validate {csvData.length} products from {csvFile?.name}
                        </Alert>

                        <Typography variant="body2" color="text.secondary">
                            Validation will check for required fields, valid product types, and other Magento requirements.
                        </Typography>
                    </Box>
                );

            case 2:
                return validationResult && importSummary ? (
                    <Box sx={{ py: 2 }}>
                        {/* Validation Summary */}
                        <Card sx={{ mb: 2 }}>
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Validation Summary
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                    <Chip 
                                        icon={<CheckIcon />} 
                                        label={`${importSummary.validation.validProducts} Valid`} 
                                        color="success" 
                                        size="small" 
                                    />
                                    {importSummary.validation.errorProducts > 0 && (
                                        <Chip 
                                            icon={<ErrorIcon />} 
                                            label={`${importSummary.validation.errorProducts} Errors`} 
                                            color="error" 
                                            size="small" 
                                        />
                                    )}
                                    {importSummary.validation.warnings > 0 && (
                                        <Chip 
                                            icon={<WarningIcon />} 
                                            label={`${importSummary.validation.warnings} Warnings`} 
                                            color="warning" 
                                            size="small" 
                                        />
                                    )}
                                </Box>

                                {/* Product Types */}
                                <Typography variant="subtitle2" gutterBottom>
                                    Product Types:
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                    <Chip label={`${importSummary.productTypes.simple} Simple`} variant="outlined" size="small" />
                                    <Chip label={`${importSummary.productTypes.configurable} Configurable`} variant="outlined" size="small" />
                                    <Chip label={`${importSummary.productTypes.variations} Variations`} variant="outlined" size="small" />
                                </Box>
                            </CardContent>
                        </Card>

                        {/* Errors and Warnings */}
                        {(validationResult.errors.length > 0 || validationResult.warnings.length > 0) && (
                            <Card sx={{ mb: 2 }}>
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Issues Found
                                    </Typography>
                                    <List dense>
                                        {validationResult.errors.slice(0, 10).map((error, index) => (
                                            <ListItem key={index}>
                                                <ErrorIcon color="error" sx={{ mr: 1 }} />
                                                <ListItemText primary={error} />
                                            </ListItem>
                                        ))}
                                        {validationResult.warnings.slice(0, 5).map((warning, index) => (
                                            <ListItem key={index}>
                                                <WarningIcon color="warning" sx={{ mr: 1 }} />
                                                <ListItemText primary={warning} />
                                            </ListItem>
                                        ))}
                                    </List>
                                </CardContent>
                            </Card>
                        )}

                        {/* Recommendations */}
                        {importSummary.recommendations.length > 0 && (
                            <Card>
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Recommendations
                                    </Typography>
                                    <List dense>
                                        {importSummary.recommendations.map((rec, index) => (
                                            <ListItem key={index}>
                                                <InfoIcon color="info" sx={{ mr: 1 }} />
                                                <ListItemText primary={rec.message} />
                                            </ListItem>
                                        ))}
                                    </List>
                                </CardContent>
                            </Card>
                        )}
                    </Box>
                ) : null;

            case 3:
                return (
                    <Box sx={{ py: 2 }}>
                        {importing ? (
                            <Box>
                                <Typography variant="h6" gutterBottom>
                                    Importing Products...
                                </Typography>
                                <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                                    {importProgress.phase}: {importProgress.current} / {importProgress.total}
                                </Typography>
                                <LinearProgress 
                                    variant="determinate" 
                                    value={(importProgress.current / importProgress.total) * 100} 
                                    sx={{ mb: 2 }}
                                />
                            </Box>
                        ) : importResults ? (
                            <Box>
                                <Typography variant="h6" gutterBottom>
                                    Import Complete
                                </Typography>
                                <Card>
                                    <CardContent>
                                        <Box sx={{ display: 'flex', gap: 1, mb: 2 }}>
                                            <Chip 
                                                icon={<CheckIcon />} 
                                                label={`${importResults.total.successful} Successful`} 
                                                color="success" 
                                            />
                                            {importResults.total.failed > 0 && (
                                                <Chip 
                                                    icon={<ErrorIcon />} 
                                                    label={`${importResults.total.failed} Failed`} 
                                                    color="error" 
                                                />
                                            )}
                                        </Box>

                                        {importResults.total.errors.length > 0 && (
                                            <Box>
                                                <Typography variant="subtitle2" gutterBottom>
                                                    Failed Products:
                                                </Typography>
                                                <List dense>
                                                    {importResults.total.errors.slice(0, 10).map((error, index) => (
                                                        <ListItem key={index}>
                                                            <ListItemText 
                                                                primary={error.sku} 
                                                                secondary={error.error} 
                                                            />
                                                        </ListItem>
                                                    ))}
                                                </List>
                                            </Box>
                                        )}
                                    </CardContent>
                                </Card>
                            </Box>
                        ) : null}
                    </Box>
                );

            default:
                return null;
        }
    };

    return (
        <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
            <DialogTitle>
                CSV Product Import
            </DialogTitle>

            <DialogContent>
                <Stepper activeStep={activeStep} sx={{ mb: 3 }}>
                    {steps.map((label) => (
                        <Step key={label}>
                            <StepLabel>{label}</StepLabel>
                        </Step>
                    ))}
                </Stepper>

                {renderStepContent()}
            </DialogContent>

            <DialogActions>
                <Button onClick={handleClose} disabled={importing}>
                    {importResults ? 'Close' : 'Cancel'}
                </Button>

                {activeStep === 1 && (
                    <Button 
                        onClick={handleValidation} 
                        variant="contained"
                        disabled={csvData.length === 0}
                    >
                        Validate Data
                    </Button>
                )}

                {activeStep === 2 && validationResult?.isValid && (
                    <Button 
                        onClick={handleImport} 
                        variant="contained"
                        color="primary"
                    >
                        Start Import
                    </Button>
                )}
            </DialogActions>
        </Dialog>
    );
};

export default CSVImportDialog;

import React, { useState, useCallback } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    Alert,
    LinearProgress,
    Stepper,
    Step,
    StepLabel,
    Card,
    CardContent,
    Chip,
    List,
    ListItem,
    ListItemText,
    Divider,
    FormControlLabel,
    Switch
} from '@mui/material';
import {
    CloudUpload as UploadIcon,
    CheckCircle as CheckIcon,
    Error as ErrorIcon,
    Warning as WarningIcon,
    Info as InfoIcon
} from '@mui/icons-material';
import { toast } from 'react-toastify';
import { 
    parseCSVContent, 
    validateMagentoCSV, 
    autoFixCSVIssues, 
    separateProductTypes,
    generateImportSummary 
} from '../../utils/csvImportUtils';
import ProductService from '../../services/ProductService';

const CSVImportDialog: React.FC<any> = ({ open, onClose, onImportComplete }) => {
    const [activeStep, setActiveStep] = useState(0);
    const [csvFile, setCsvFile] = useState(null);
    const [csvData, setCsvData] = useState([]);
    const [validationResult, setValidationResult] = useState(null);
    const [separatedProducts, setSeparatedProducts] = useState(null);
    const [importSummary, setImportSummary] = useState(null);
    const [importing, setImporting] = useState(false);
    const [importProgress, setImportProgress] = useState({ current: 0, total: 0 });
    const [importResults, setImportResults] = useState(null);
    const [autoFix, setAutoFix] = useState(true);

    const steps = ['Upload CSV', 'Validate Data', 'Review & Import', 'Import Results'];

    const handleFileUpload = useCallback((event) => {
        const file = event.target.files[0];
        if (!file) return;

        if (!file.name.toLowerCase().endsWith('.csv')) {
            toast.error('Please select a CSV file');
            return;
        setCsvFile(file);
        const reader = new FileReader();

        reader.onload = (e) => {
            try {
                const content = e.target.result;
                const products = parseCSVContent(content);
                setCsvData(products);
                setActiveStep(1);
                toast.success(`Loaded ${products.length} products from CSV`);
            } catch(error: any) {
                toast.error(`Error parsing CSV: ${error.message}`);
        };

        reader.readAsText(file);
    }, []);

    const handleValidation = useCallback(() => {
        if (csvData.length ===0) return;

        try {
            // Auto-fix common issues if enabled
            const dataToValidate = autoFix ? autoFixCSVIssues(csvData) : csvData;

            // Validate the data
            const validation = validateMagentoCSV(dataToValidate);
            setValidationResult(validation);

            // Separate product types
            const separated = separateProductTypes(validation.validProducts);
            setSeparatedProducts(separated);

            // Generate summary
            const summary = generateImportSummary(validation, separated);
            setImportSummary(summary);

            setActiveStep(2);

            if(validation.isValid) {
                toast.success('CSV validation passed successfully');
            } else {
                toast.warning(`Validation completed with ${validation.errors.length} errors`);
        } catch(error: any) {
            toast.error(`Validation error: ${error.message}`);
    }, [csvData, autoFix]);

    const handleImport = useCallback(async () => {
        if (!separatedProducts || !validationResult.isValid) return;

        setImporting(true);
        setActiveStep(3);

        try {
            const results = {
                simple: { successful: 0, failed: 0, errors: [] },
                configurable: { successful: 0, failed: 0, errors: [] },
                total: { successful: 0, failed: 0, errors: [] }
            };

            const totalProducts = separatedProducts?.simpleProducts.length + 
                                separatedProducts.configurableProducts.length;
            let processedCount = 0;

            // Import simple products first
            if(separatedProducts?.simpleProducts.length > 0) {
                const simpleResults = await ProductService.processBulkProducts(separatedProducts?.simpleProducts.map((p: any) => ProductService.transformToMagentoFormat(p)),
                    (progress) => {
                        setImportProgress({
                            current: processedCount + progress.current,
                            total: totalProducts,
                            phase: 'Simple Products',
                            ...progress
                        });
                );

                results.simple = simpleResults;
                processedCount += separatedProducts?.simpleProducts.length;
            // Import configurable products
            if(separatedProducts.configurableProducts.length > 0) {
                for (const configurableProduct of separatedProducts.configurableProducts) {
                    try {
                        const result = await ProductService.processConfigurableProduct(configurableProduct);
                        if(result.success) {
                            results.configurable.successful++;
                        } else {
                            results.configurable.failed++;
                            results.configurable.errors.push({
                                sku: configurableProduct.sku,
                                error: result.error
                            });
                    } catch(error: any) {
                        results.configurable.failed++;
                        results.configurable.errors.push({
                            sku: configurableProduct.sku,
                            error: error.message
                        });
                    processedCount++;
                    setImportProgress({
                        current: processedCount,
                        total: totalProducts,
                        phase: 'Configurable Products'
                    });
            // Calculate totals
            results.total.successful = results.simple.successful + results.configurable.successful;
            results.total.failed = results.simple.failed + results.configurable.failed;
            results.total.errors = [...results.simple.errors, ...results.configurable.errors];

            setImportResults(results);

            if(results.total.successful > 0) {
                toast.success(`Successfully imported ${results.total.successful} products`);
                if(onImportComplete) {
                    onImportComplete(results);
            if(results.total.failed > 0) {
                toast.warning(`${results.total.failed} products failed to import`);
        } catch(error: any) {
            toast.error(`Import failed: ${error.message}`);
        } finally {
            setImporting(false);
    }, [separatedProducts, validationResult, onImportComplete]);

    const handleClose = () => {
        if(!importing) {
            // Reset state
            setActiveStep(0);
            setCsvFile(null);
            setCsvData([]);
            setValidationResult(null);
            setSeparatedProducts(null);
            setImportSummary(null);
            setImportResults(null);
            setImportProgress({ current: 0, total: 0 });
            onClose();
    };

    const renderStepContent = () => {
        switch(activeStep) {
            case 0:
                return(<Box sx={{ display: "flex", textAlign: 'center', py: 4 } as any}>
                        <input
                            accept
                            style={{ display: 'none' }}
                            id
                            onChange={(e) => handleFileUpload}
                        />
                        <label htmlFor="csv-upload">
                            <Button
                                variant="outlined"
                                startIcon={<UploadIcon />}
                                size="small"
                                sx={{ display: "flex", mb: 2 } as any}
                            >
                                Select CSV File
                            </Button>
                        </label>
                        <Typography variant="outlined" color="text.secondary">
                            Upload a CSV file with product data for Magento import
                        </Typography>
                        {csvFile && (
                            <Alert severity="info" sx={{ display: "flex", mt: 2 } as any}>
                                Selected: {csvFile.name} ({csvData.length} products)
                            </Alert>
                        )}
                    </Box>
                );

            case 1:
                return(<Box sx={{ display: "flex", py: 2 } as any}></
                        <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 } as any}>
                            <FormControlLabel control
                                        checked={autoFix}
                                        onChange={(e) => setAutoFix(e.target.checked)}
                                    />
                                label
                        <Alert severity="info" sx={{ display: "flex", mb: 2 } as any}>
                            Ready to validate {csvData.length} products from {csvFile.name}
                        </Alert>

                        <Typography variant="outlined" color="text.secondary">
                            Validation will check for required fields, valid product types, and other Magento requirements.
                        </Typography>
                    </Box>
                );

            case 2:
                return (validationResult && importSummary ? (
                    <Box sx={{ display: "flex", py: 2 } as any}>
                        {/* Validation Summary */}
                        <Card sx={{ display: "flex", mb: 2 } as any}></
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Validation Summary
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 1, mb: 2 } as any}></
                                    <Chip 
                                        icon={<CheckIcon />} 
                                        label={`${importSummary.validation.validProducts} Valid`} 
                                        color
                                            icon={<ErrorIcon />} 
                                            label={`${importSummary.validation.errorProducts} Errors`} 
                                            color
                                    )}
                                    {importSummary.validation.warnings > 0 && (
                                        <Chip 
                                            icon={<WarningIcon />} 
                                            label={`${importSummary.validation.warnings} Warnings`} 
                                            color
                                    )}
                                </Box>

                                {/* Product Types */}
                                <Typography variant="subtitle2" gutterBottom>
                                    Product Types:
                                </Typography>
                                <Box sx={{ display: 'flex', gap: 1, mb: 2 } as any}></
                                    <Chip label={`${importSummary.productTypes.simple} Simple`} variant="outlined" size="small" />
                                    <Chip label={`${importSummary.productTypes.configurable} Configurable`} variant="outlined" size="small" /></
                                    <Chip label={`${importSummary.productTypes.variations} Variations`} variant="outlined" size="small" /></Chip>
                            </CardContent>
                        </Card>

                        {/* Errors and Warnings */}
                        {(validationResult.errors.length > 0 || validationResult.warnings.length > 0) && (
                            <Card sx={{ display: "flex", mb: 2 } as any}></
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Issues Found
                                    </Typography>
                                    <List dense>
                                        {validationResult.errors.slice(0, 10).map((error: any index: any) => (
                                            <ListItem key={index}></
                                                <ErrorIcon color="error" sx={{ display: "flex", mr: 1 } as any} />
                                                <ListItemText primary={error} /></ListItemText>
                                        ))}
                                        {validationResult.warnings.slice(0, 5).map((warning: any index: any) => (
                                            <ListItem key={index}></
                                                <WarningIcon color="warning" sx={{ display: "flex", mr: 1 } as any} />
                                                <ListItemText primary={warning} /></ListItemText>
                                        ))}
                                    </List>
                                </CardContent>
                            </Card>
                        )}

                        {/* Recommendations */}
                        {importSummary.recommendations.length > 0 && (
                            <Card></
                                <CardContent>
                                    <Typography variant="h6" gutterBottom>
                                        Recommendations
                                    </Typography>
                                    <List dense>
                                        {importSummary.recommendations.map((rec: any index: any) => (
                                            <ListItem key={index}></
                                                <InfoIcon color="info" sx={{ display: "flex", mr: 1 } as any} />
                                                <ListItemText primary={rec.message} /></ListItemText>
                                        ))}
                                    </List>
                                </CardContent>
                            </Card>
                        )}
                    </Box>
                ) : null);

            case 3:
                return (
                    <Box sx={{ display: "flex", py: 2 } as any}>
                        {importing ? (
                            <Box></
                                <Typography variant="h6" gutterBottom>
                                    Importing Products...
                                </Typography>
                                <Typography variant="outlined" color="text.secondary" sx={{ display: "flex", mb: 2 } as any}>
                                    {importProgress.phase}: {importProgress.current} / {importProgress.total}
                                </Typography>
                                <LinearProgress variant="outlined"
                                    value={(importProgress.current / importProgress.total) * 100} 
                                    sx={{ display: "flex", mb: 2 } as any}
                                /></LinearProgress>
                        ) : importResults ? (
                            <Box></
                                <Typography variant="h6" gutterBottom>
                                    Import Complete
                                </Typography>
                                <Card></
                                    <CardContent>
                                        <Box sx={{ display: 'flex', gap: 1, mb: 2 } as any}></
                                            <Chip 
                                                icon={<CheckIcon />} 
                                                label={`${importResults.total.successful} Successful`} 
                                                color
                                                    icon={<ErrorIcon />} 
                                                    label={`${importResults.total.failed} Failed`} 
                                                    color
                                            )}
                                        </Box>

                                        {importResults.total.errors.length > 0 && (
                                            <Box></
                                                <Typography variant="subtitle2" gutterBottom>
                                                    Failed Products:
                                                </Typography>
                                                <List dense>
                                                    {importResults.total.errors.slice(0, 10).map((error: any index: any) => (
                                                        <ListItem key={index}></
                                                            <ListItemText primary={error.sku} 
                                                                secondary={error.error} 
                                                            /></ListItemText>
                                                    ))}
                                                </List>
                                            </Box>
                                        )}
                                    </CardContent>
                                </Card>
                            </Box>
                        ) : null}
                    </Box>
                );

            default:
                return null;
    };

    return(<Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth></
            <DialogTitle>
                CSV Product Import
            </DialogTitle>

            <DialogContent></
                <Stepper activeStep={activeStep} sx={{ display: "flex", mb: 3 } as any}>
                    {steps.map((label: any) => (
                        <Step key={label}></
                            <StepLabel>{label}</StepLabel>
                        </Step>
                    ))}
                </Stepper>

                {renderStepContent()}
            </DialogContent>

            <DialogActions></
                <Button onClick={handleClose} disabled={importing}>
                    {importResults ? 'Close' : 'Cancel'}
                </Button>

                {activeStep ===1 && (
                    <Button onClick={handleValidation} 
                        variant="outlined"
                        disabled={csvData.length ===0}>
                        Validate Data
                    </Button>
                )}

                {activeStep ===2 && validationResult.isValid && (
                    <Button onClick={handleImport} 
                        variant="outlined"
                )}
            </DialogActions></Button>
    );
};

