import React, { useState, useCallback, useRef } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Paper,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  LinearProgress,
  Alert,
  Chip,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tooltip,
  Switch,
  FormControlLabel,
  Slider,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  Tab,
  Badge,
  Divider
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Description as CSVIcon,
  Image as ImageIcon,
  CheckCircle as SuccessIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Close as CloseIcon,
  Visibility as PreviewIcon,
  Settings as SettingsIcon,
  Transform as ProcessIcon,
  PhotoSizeSelectActual as ResizeIcon,
  Speed as OptimizeIcon,
  ExpandMore as ExpandIcon,
  GetApp as DownloadIcon,
  Refresh as RefreshIcon,
  Info as InfoIcon,
  Assignment as RefIcon
} from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { toast } from 'react-toastify';
import calligraphMediaUploadService from '../../services/calligraphMediaUploadService';

/**
 * Calligraph Bulk Upload Dialog
 * Specialized for Calligraph CSV structure with REF-based image matching
 */
const CalligraphBulkUploadDialog = ({ open, onClose, onComplete }) => {
  // ===== STATE MANAGEMENT =====
  const [activeStep, setActiveStep] = useState(0);
  const [activeTab, setActiveTab] = useState(0);

  // File states
  const [csvFile, setCsvFile] = useState(null);
  const [csvData, setCsvData] = useState(null);
  const [imageFiles, setImageFiles] = useState([]);
  const [validationResults, setValidationResults] = useState(null);

  // Processing states
  const [matchingResults, setMatchingResults] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(null);
  const [uploadResults, setUploadResults] = useState(null);
  const [processingStats, setProcessingStats] = useState(null);
  const [loading, setLoading] = useState(false);

  // Settings
  const [settings, setSettings] = useState({
    processImages: true,
    imageQuality: 90,
    targetSize: 1200,
    batchSize: 3,
    delayBetweenBatches: 2000,
    autoResize: true,
    preserveAspectRatio: true,
    backgroundColor: '#FFFFFF'
  });

  const fileInputRef = useRef(null);

  const steps = [
    'Upload Calligraph CSV',
    'Upload Raw Images',
    'Review REF Matching',
    'Process & Upload'
  ];

  // ===== CSV UPLOAD HANDLER =====
  const onCSVDrop = useCallback(async (acceptedFiles) => {
    const file = acceptedFiles[0];
    if (!file) return;

    setLoading(true);
    try {
      const data = await calligraphMediaUploadService.parseCalligraphCSV(file);
      setCsvFile(file);
      setCsvData(data);
      toast.success(`Calligraph CSV parsed: ${data.totalRows} products found`);
      setActiveStep(1);
    } catch (error) {
      toast.error(error.message);
    } finally {
      setLoading(false);
    }
  }, []);

  // ===== IMAGE UPLOAD HANDLER =====
  const onImageDrop = useCallback(async (acceptedFiles) => {
    setLoading(true);

    try {
      // Validate all files
      const validation = await calligraphMediaUploadService.validateImageFiles(acceptedFiles);

      if (validation.invalid.length > 0) {
        const errorMessages = validation.invalid.map(v => `${v.file.name}: ${v.error}`);
        toast.error(`${validation.invalid.length} files rejected`);
        console.warn('Rejected files:', errorMessages);
      }

      if (validation.valid.length > 0) {
        const validFiles = validation.valid.map(v => v.file);
        setImageFiles(prev => [...prev, ...validFiles]);
        setValidationResults(validation);
        toast.success(`${validation.valid.length} raw images added`);
      }
    } catch (error) {
      toast.error(`Validation failed: ${error.message}`);
    } finally {
      setLoading(false);
    }
  }, []);

  // ===== MATCHING HANDLER =====
  const handleMatching = useCallback(() => {
    if (!csvData || imageFiles.length === 0) {
      toast.error('Please upload both Calligraph CSV and raw images');
      return;
    }

    setLoading(true);
    try {
      const results = calligraphMediaUploadService.matchImagesWithCalligraphCSV(csvData, imageFiles);
      setMatchingResults(results);
      setActiveStep(2);

      toast.success(
        `REF matching complete: ${results.stats.matched} matches for ${results.stats.uniqueProducts} products`
      );
    } catch (error) {
      toast.error(`Matching failed: ${error.message}`);
    } finally {
      setLoading(false);
    }
  }, [csvData, imageFiles]);

  // ===== UPLOAD HANDLER =====
  const handleStartUpload = async () => {
    if (!matchingResults || matchingResults.matches.length === 0) {
      toast.error('No matches to upload');
      return;
    }

    setActiveStep(3);
    setUploadProgress({ current: 0, total: matchingResults.matches.length });

    try {
      const results = await calligraphMediaUploadService.bulkUploadCalligraphImages(
        matchingResults.matches,
        (progress) => setUploadProgress(progress),
        {
          processImages: settings.processImages,
          imageQuality: settings.imageQuality / 100,
          targetSize: settings.targetSize,
          batchSize: settings.batchSize,
          delayBetweenBatches: settings.delayBetweenBatches
        }
      );

      setUploadResults(results);

      // Generate statistics
      const stats = calligraphMediaUploadService.generateProcessingStats(results);
      setProcessingStats(stats);

      const successful = results.filter(r => r.status === 'success').length;
      const failed = results.filter(r => r.status === 'error').length;

      toast.success(`Calligraph upload complete: ${successful} successful, ${failed} failed`);

      if (onComplete) {
        onComplete(results);
      }
    } catch (error) {
      toast.error(`Upload failed: ${error.message}`);
    }
  };

  // ===== UTILITY FUNCTIONS =====
  const handleReset = () => {
    setActiveStep(0);
    setActiveTab(0);
    setCsvFile(null);
    setCsvData(null);
    setImageFiles([]);
    setValidationResults(null);
    setMatchingResults(null);
    setUploadProgress(null);
    setUploadResults(null);
    setProcessingStats(null);
  };

  const removeImage = (index) => {
    setImageFiles(prev => prev.filter((_, i) => i !== index));
    setValidationResults(null);
  };

  const downloadResults = () => {
    if (!uploadResults) return;

    const data = uploadResults.map(result => ({
      SKU: result.sku,
      REF: result.ref,
      OriginalFileName: result.file.name,
      FinalFileName: result.processedFileName,
      Status: result.status,
      MatchStrategy: result.matchStrategy,
      Message: result.result.message,
      OriginalSize: `${(result.originalSize / 1024 / 1024).toFixed(2)}MB`,
      ProcessedSize: `${(result.processedSize / 1024 / 1024).toFixed(2)}MB`,
      CompressionRatio: `${result.compressionRatio}%`
    }));

    const csv = [
      Object.keys(data[0]).join(','),
      ...data.map(row => Object.values(row).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `calligraph-upload-results-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // ===== DROPZONE CONFIGURATIONS =====
  const csvDropzone = useDropzone({
    onDrop: onCSVDrop,
    accept: {
      'text/csv': ['.csv'],
      'application/vnd.ms-excel': ['.csv']
    },
    maxFiles: 1,
    disabled: loading
  });

  const imageDropzone = useDropzone({
    onDrop: onImageDrop,
    accept: {
      'image/*': ['.jpeg', '.jpg', '.png', '.gif', '.webp']
    },
    multiple: true,
    disabled: loading
  });

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="xl" 
      fullWidth
      PaperProps={{
        sx: { minHeight: '80vh', maxHeight: '90vh' }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 1,
        bgcolor: 'success.main',
        color: 'success.contrastText',
        position: 'relative'
      }}>
        <RefIcon />
        Calligraph Professional Bulk Upload
        <Chip 
          label="REF-Based Matching" 
          size="small" 
          sx={{ 
            bgcolor: 'success.dark', 
            color: 'success.contrastText',
            ml: 1
          }} 
        />
        <Box sx={{ position: 'absolute', right: 16 }}>
          <IconButton 
            onClick={onClose} 
            sx={{ color: 'inherit' }}
            size="small"
          >
            <CloseIcon />
          </IconButton>
        </Box>
      </DialogTitle>

      <DialogContent dividers sx={{ p: 0 }}>
        <Stepper activeStep={activeStep} orientation="vertical" sx={{ p: 3 }}>
          {/* Step 1: Calligraph CSV Upload */}
          <Step>
            <StepLabel>
              <Typography variant="h6">Upload Calligraph CSV</Typography>
            </StepLabel>
            <StepContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Upload the Calligraph CSV file with SKU, REF, and image name columns.
              </Typography>

              <Paper
                {...csvDropzone.getRootProps()}
                sx={{
                  p: 4,
                  border: '2px dashed',
                  borderColor: csvDropzone.isDragActive ? 'success.main' : 'grey.300',
                  bgcolor: csvDropzone.isDragActive ? 'success.light' : 'background.default',
                  cursor: 'pointer',
                  textAlign: 'center',
                  mt: 2,
                  transition: 'all 0.2s ease'
                }}
              >
                <input {...csvDropzone.getInputProps()} />
                <CSVIcon sx={{ fontSize: 64, color: 'success.main', mb: 2 }} />
                <Typography variant="h6" gutterBottom>
                  {csvDropzone.isDragActive
                    ? 'Drop Calligraph CSV here...'
                    : 'Drag & drop Calligraph CSV file here, or click to select'
                  }
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Required columns: sku, ref, image name (optional: name)
                </Typography>
              </Paper>

              {csvFile && csvData && (
                <Alert severity="success" sx={{ mt: 2 }}>
                  <Typography variant="body2">
                    <strong>{csvFile.name}</strong> - {csvData.totalRows} products loaded
                  </Typography>
                  <Typography variant="caption" display="block">
                    SKU Column: {csvData.skuColumn} | 
                    REF Column: {csvData.refColumn} |
                    {csvData.imageNameColumn && ` Image Name: ${csvData.imageNameColumn} |`}
                    {csvData.productNameColumn && ` Product Name: ${csvData.productNameColumn}`}
                  </Typography>
                </Alert>
              )}
            </StepContent>
          </Step>

          {/* Step 2: Raw Image Upload */}
          <Step>
            <StepLabel>
              <Typography variant="h6">Upload Raw Images</Typography>
            </StepLabel>
            <StepContent>
              <Typography variant="body2" color="text.secondary" gutterBottom>
                Upload raw product images with reference naming (e.g., 7203C_1.jpg, 7203C_2.jpg, 7203C.jpg).
              </Typography>

              <Paper
                {...imageDropzone.getRootProps()}
                sx={{
                  p: 4,
                  border: '2px dashed',
                  borderColor: imageDropzone.isDragActive ? 'primary.main' : 'grey.300',
                  bgcolor: imageDropzone.isDragActive ? 'primary.light' : 'background.default',
                  cursor: 'pointer',
                  textAlign: 'center',
                  mt: 2,
                  transition: 'all 0.2s ease'
                }}
              >
                <input {...imageDropzone.getInputProps()} />
                <ImageIcon sx={{ fontSize: 64, color: 'primary.main', mb: 2 }} />
                <Typography variant="h6" gutterBottom>
                  {imageDropzone.isDragActive
                    ? 'Drop raw images here...'
                    : 'Drag & drop raw images here, or click to select multiple'
                  }
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Supports: 7203C.jpg, 7203C_1.jpg, 7203C_2.jpg patterns | Max: 10MB per file
                </Typography>
              </Paper>

              {imageFiles.length > 0 && (
                <Box sx={{ mt: 3 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="subtitle1">
                      Raw Images ({imageFiles.length})
                    </Typography>
                    {validationResults && (
                      <Typography variant="body2" color="text.secondary">
                        Total Size: {(validationResults.totalSize / 1024 / 1024).toFixed(2)}MB
                      </Typography>
                    )}
                  </Box>

                  <Box sx={{ maxHeight: 200, overflow: 'auto', border: '1px solid', borderColor: 'divider', borderRadius: 1, p: 1 }}>
                    <Grid container spacing={1}>
                      {imageFiles.map((file, index) => (
                        <Grid item key={index}>
                          <Chip
                            label={file.name}
                            onDelete={() => removeImage(index)}
                            size="small"
                            color="primary"
                            variant="outlined"
                          />
                        </Grid>
                      ))}
                    </Grid>
                  </Box>

                  <Box sx={{ mt: 2, display: 'flex', gap: 2 }}>
                    <Button
                      variant="contained"
                      onClick={handleMatching}
                      disabled={!csvData || imageFiles.length === 0 || loading}
                      startIcon={loading ? <RefreshIcon className="spin" /> : <RefIcon />}
                      color="success"
                    >
                      {loading ? 'Processing...' : 'Match with REF Column'}
                    </Button>
                    <Button
                      variant="outlined"
                      onClick={() => setImageFiles([])}
                      disabled={imageFiles.length === 0}
                    >
                      Clear All Images
                    </Button>
                  </Box>
                </Box>
              )}
            </StepContent>
          </Step>

          {/* Step 3: Review REF Matching */}
          <Step>
            <StepLabel>
              <Typography variant="h6">Review REF Matching</Typography>
            </StepLabel>
            <StepContent>
              {matchingResults && (
                <Box>
                  {/* Enhanced Statistics Cards */}
                  <Grid container spacing={2} sx={{ mb: 3 }}>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center', bgcolor: 'success.light' }}>
                        <CardContent sx={{ py: 2 }}>
                          <SuccessIcon sx={{ fontSize: 32, color: 'success.main' }} />
                          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                            {matchingResults.stats.matched}
                          </Typography>
                          <Typography variant="caption">REF Matches</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center', bgcolor: 'info.light' }}>
                        <CardContent sx={{ py: 2 }}>
                          <InfoIcon sx={{ fontSize: 32, color: 'info.main' }} />
                          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                            {matchingResults.stats.uniqueProducts}
                          </Typography>
                          <Typography variant="caption">Products</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center', bgcolor: 'warning.light' }}>
                        <CardContent sx={{ py: 2 }}>
                          <WarningIcon sx={{ fontSize: 32, color: 'warning.main' }} />
                          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                            {matchingResults.stats.multipleImagesProducts}
                          </Typography>
                          <Typography variant="caption">Multi-Image</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center', bgcolor: 'secondary.light' }}>
                        <CardContent sx={{ py: 2 }}>
                          <ProcessIcon sx={{ fontSize: 32, color: 'secondary.main' }} />
                          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
                            {matchingResults.stats.averageImagesPerProduct}
                          </Typography>
                          <Typography variant="caption">Avg/Product</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  </Grid>

                  {/* Match Strategy Breakdown */}
                  <Alert severity="info" sx={{ mb: 3 }}>
                    <Typography variant="body2">
                      <strong>Match Strategies:</strong> REF Column: {matchingResults.stats.matchStrategies.ref}, 
                      Image Name: {matchingResults.stats.matchStrategies.imageName}, 
                      Fuzzy: {matchingResults.stats.matchStrategies.fuzzy}
                    </Typography>
                  </Alert>

                  {/* Tabs for detailed view */}
                  <Paper sx={{ mb: 3 }}>
                    <Tabs value={activeTab} onChange={(e, v) => setActiveTab(v)}>
                      <Tab 
                        label={
                          <Badge badgeContent={matchingResults.matches.length} color="success">
                            REF Matches
                          </Badge>
                        } 
                      />
                      <Tab label="Processing Settings" />
                      {matchingResults.stats.unmatchedCSV > 0 && (
                        <Tab 
                          label={
                            <Badge badgeContent={matchingResults.stats.unmatchedCSV} color="warning">
                              Unmatched
                            </Badge>
                          } 
                        />
                      )}
                    </Tabs>

                    <Box sx={{ p: 2 }}>
                      {/* REF Matches Tab */}
                      {activeTab === 0 && (
                        <Box sx={{ maxHeight: 300, overflow: 'auto' }}>
                          <TableContainer>
                            <Table size="small">
                              <TableHead>
                                <TableRow>
                                  <TableCell>SKU</TableCell>
                                  <TableCell>REF</TableCell>
                                  <TableCell>Raw Image</TableCell>
                                  <TableCell>Final Name</TableCell>
                                  <TableCell>Strategy</TableCell>
                                  <TableCell>Size</TableCell>
                                </TableRow>
                              </TableHead>
                              <TableBody>
                                {matchingResults.matches.slice(0, 50).map((match, index) => (
                                  <TableRow key={index}>
                                    <TableCell>{match.sku}</TableCell>
                                    <TableCell>
                                      <Chip 
                                        label={match.ref} 
                                        size="small" 
                                        color="success" 
                                        variant="outlined" 
                                      />
                                    </TableCell>
                                    <TableCell>{match.file.name}</TableCell>
                                    <TableCell>{match.finalImageName}</TableCell>
                                    <TableCell>
                                      <Chip 
                                        label={match.matchStrategy} 
                                        size="small" 
                                        color={
                                          match.matchStrategy === 'ref' ? 'success' :
                                          match.matchStrategy === 'imageName' ? 'info' : 'warning'
                                        }
                                      />
                                    </TableCell>
                                    <TableCell>{(match.file.size / 1024 / 1024).toFixed(2)}MB</TableCell>
                                  </TableRow>
                                ))}
                              </TableBody>
                            </Table>
                          </TableContainer>
                          {matchingResults.matches.length > 50 && (
                            <Typography variant="caption" sx={{ p: 2, display: 'block', textAlign: 'center' }}>
                              ... and {matchingResults.matches.length - 50} more matches
                            </Typography>
                          )}
                        </Box>
                      )}

                      {/* Processing Settings Tab */}
                      {activeTab === 1 && (
                        <Grid container spacing={3}>
                          <Grid item xs={12} md={6}>
                            <Typography variant="subtitle1" gutterBottom>
                              Image Processing
                            </Typography>
                            <FormControlLabel
                              control={
                                <Switch
                                  checked={settings.processImages}
                                  onChange={(e) => setSettings(prev => ({ ...prev, processImages: e.target.checked }))}
                                />
                              }
                              label="Enable image processing & resizing"
                            />

                            {settings.processImages && (
                              <Box sx={{ mt: 2 }}>
                                <Typography variant="body2" gutterBottom>
                                  Target Size: {settings.targetSize}x{settings.targetSize}px
                                </Typography>
                                <Slider
                                  value={settings.targetSize}
                                  onChange={(e, v) => setSettings(prev => ({ ...prev, targetSize: v }))}
                                  min={800}
                                  max={2000}
                                  step={100}
                                  marks={[
                                    { value: 800, label: '800px' },
                                    { value: 1200, label: '1200px' },
                                    { value: 1600, label: '1600px' },
                                    { value: 2000, label: '2000px' }
                                  ]}
                                />

                                <Typography variant="body2" gutterBottom sx={{ mt: 2 }}>
                                  Quality: {settings.imageQuality}%
                                </Typography>
                                <Slider
                                  value={settings.imageQuality}
                                  onChange={(e, v) => setSettings(prev => ({ ...prev, imageQuality: v }))}
                                  min={60}
                                  max={100}
                                  step={5}
                                  marks={[
                                    { value: 60, label: '60%' },
                                    { value: 80, label: '80%' },
                                    { value: 90, label: '90%' },
                                    { value: 100, label: '100%' }
                                  ]}
                                />
                              </Box>
                            )}
                          </Grid>

                          <Grid item xs={12} md={6}>
                            <Typography variant="subtitle1" gutterBottom>
                              Upload Settings
                            </Typography>
                            <Typography variant="body2" gutterBottom>
                              Batch Size: {settings.batchSize} concurrent uploads
                            </Typography>
                            <Slider
                              value={settings.batchSize}
                              onChange={(e, v) => setSettings(prev => ({ ...prev, batchSize: v }))}
                              min={1}
                              max={10}
                              step={1}
                              marks={[
                                { value: 1, label: '1' },
                                { value: 3, label: '3' },
                                { value: 5, label: '5' },
                                { value: 10, label: '10' }
                              ]}
                            />

                            <Typography variant="body2" gutterBottom sx={{ mt: 2 }}>
                              Delay: {settings.delayBetweenBatches}ms between batches
                            </Typography>
                            <Slider
                              value={settings.delayBetweenBatches}
                              onChange={(e, v) => setSettings(prev => ({ ...prev, delayBetweenBatches: v }))}
                              min={500}
                              max={5000}
                              step={500}
                              marks={[
                                { value: 500, label: '0.5s' },
                                { value: 2000, label: '2s' },
                                { value: 5000, label: '5s' }
                              ]}
                            />
                          </Grid>
                        </Grid>
                      )}

                      {/* Unmatched Tab */}
                      {activeTab === 2 && matchingResults.unmatched.csvRows.length > 0 && (
                        <Box sx={{ maxHeight: 300, overflow: 'auto' }}>
                          <Typography variant="body2" color="text.secondary" gutterBottom>
                            Products without matching images:
                          </Typography>
                          <List dense>
                            {matchingResults.unmatched.csvRows.map((row, index) => (
                              <ListItem key={index}>
                                <ListItemIcon>
                                  <WarningIcon color="warning" />
                                </ListItemIcon>
                                <ListItemText
                                  primary={`SKU: ${row.sku} - REF: ${row.ref}`}
                                  secondary={`Product: ${row.productName || 'No name'} | Expected: ${row.imageName || 'Not specified'}`}
                                />
                              </ListItem>
                            ))}
                          </List>
                        </Box>
                      )}
                    </Box>
                  </Paper>

                  <Button
                    variant="contained"
                    size="large"
                    onClick={handleStartUpload}
                    disabled={matchingResults.matches.length === 0}
                    startIcon={<UploadIcon />}
                    color="success"
                  >
                    Start Calligraph Upload ({matchingResults.matches.length} images)
                  </Button>
                </Box>
              )}
            </StepContent>
          </Step>

          {/* Step 4: Process & Upload */}
          <Step>
            <StepLabel>
              <Typography variant="h6">Process & Upload</Typography>
            </StepLabel>
            <StepContent>
              {uploadProgress && (
                <Box sx={{ mb: 3 }}>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 }}>
                    <Typography variant="body2">
                      Progress: {uploadProgress.current} of {uploadProgress.total}
                    </Typography>
                    <Typography variant="body2">
                      {((uploadProgress.current / uploadProgress.total) * 100).toFixed(1)}%
                    </Typography>
                  </Box>
                  <LinearProgress
                    variant="determinate"
                    value={(uploadProgress.current / uploadProgress.total) * 100}
                    sx={{ mb: 2, height: 8, borderRadius: 4 }}
                  />
                  {uploadProgress.sku && (
                    <Box>
                      <Typography variant="body2" color="primary">
                        Current: SKU {uploadProgress.sku} - {uploadProgress.fileName}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        Stage: {uploadProgress.stage || uploadProgress.status}
                      </Typography>
                    </Box>
                  )}
                </Box>
              )}

              {uploadResults && processingStats && (
                <Box>
                  <Alert severity="success" sx={{ mb: 3 }}>
                    <Typography variant="body1" gutterBottom>
                      Calligraph upload completed successfully!
                    </Typography>
                    <Typography variant="body2">
                      {processingStats.successful} successful, {processingStats.failed} failed
                      {processingStats.compressionRatio > 0 && (
                        <> • {processingStats.compressionRatio}% size reduction</>
                      )}
                      • Success rate: {processingStats.successRate}%
                    </Typography>
                  </Alert>

                  {/* Enhanced Results Summary */}
                  <Grid container spacing={2} sx={{ mb: 3 }}>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center' }}>
                        <CardContent sx={{ py: 2 }}>
                          <Typography variant="h4" color="success.main">
                            {processingStats.successful}
                          </Typography>
                          <Typography variant="caption">Successful</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center' }}>
                        <CardContent sx={{ py: 2 }}>
                          <Typography variant="h4" color="error.main">
                            {processingStats.failed}
                          </Typography>
                          <Typography variant="caption">Failed</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center' }}>
                        <CardContent sx={{ py: 2 }}>
                          <Typography variant="h4" color="info.main">
                            {processingStats.uniqueProducts}
                          </Typography>
                          <Typography variant="caption">Products</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ textAlign: 'center' }}>
                        <CardContent sx={{ py: 2 }}>
                          <Typography variant="h4" color="primary.main">
                            {processingStats.averageImagesPerProduct}
                          </Typography>
                          <Typography variant="caption">Avg/Product</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  </Grid>

                  <Box sx={{ display: 'flex', gap: 2, mb: 2 }}>
                    <Button
                      variant="outlined"
                      startIcon={<DownloadIcon />}
                      onClick={downloadResults}
                    >
                      Download Calligraph Results CSV
                    </Button>
                  </Box>

                  {/* Detailed Results */}
                  <Accordion>
                    <AccordionSummary expandIcon={<ExpandIcon />}>
                      <Typography>View Detailed Results</Typography>
                    </AccordionSummary>
                    <AccordionDetails>
                      <Box sx={{ maxHeight: 400, overflow: 'auto' }}>
                        <TableContainer>
                          <Table size="small">
                            <TableHead>
                              <TableRow>
                                <TableCell>Status</TableCell>
                                <TableCell>SKU</TableCell>
                                <TableCell>REF</TableCell>
                                <TableCell>Raw File</TableCell>
                                <TableCell>Final Name</TableCell>
                                <TableCell>Strategy</TableCell>
                                <TableCell>Size</TableCell>
                                <TableCell>Message</TableCell>
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {uploadResults.map((result, index) => (
                                <TableRow key={index}>
                                  <TableCell>
                                    {result.status === 'success' ? (
                                      <SuccessIcon color="success" fontSize="small" />
                                    ) : (
                                      <ErrorIcon color="error" fontSize="small" />
                                    )}
                                  </TableCell>
                                  <TableCell>{result.sku}</TableCell>
                                  <TableCell>
                                    <Chip 
                                      label={result.ref} 
                                      size="small" 
                                      color="success" 
                                      variant="outlined" 
                                    />
                                  </TableCell>
                                  <TableCell>{result.file.name}</TableCell>
                                  <TableCell>{result.processedFileName}</TableCell>
                                  <TableCell>
                                    <Chip 
                                      label={result.matchStrategy} 
                                      size="small" 
                                      color={
                                        result.matchStrategy === 'ref' ? 'success' :
                                        result.matchStrategy === 'imageName' ? 'info' : 'warning'
                                      }
                                    />
                                  </TableCell>
                                  <TableCell>
                                    {(result.originalSize / 1024 / 1024).toFixed(2)}MB
                                    {result.processedSize && result.processedSize !== result.originalSize && (
                                      <> → {(result.processedSize / 1024 / 1024).toFixed(2)}MB</>
                                    )}
                                  </TableCell>
                                  <TableCell>
                                    <Typography variant="caption">
                                      {result.result.message}
                                    </Typography>
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </TableContainer>
                      </Box>
                    </AccordionDetails>
                  </Accordion>
                </Box>
              )}
            </StepContent>
          </Step>
        </Stepper>
      </DialogContent>

      <DialogActions sx={{ p: 2, bgcolor: 'background.paper' }}>
        <Button onClick={onClose} disabled={loading}>
          {uploadResults ? 'Close' : 'Cancel'}
        </Button>
        {activeStep > 0 && !uploadResults && (
          <Button onClick={handleReset} color="secondary" disabled={loading}>
            Reset
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default CalligraphBulkUploadDialog;

import React, { useState, useCallback, useRef } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  Box,
  Typography,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Paper,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  LinearProgress,
  Alert,
  Chip,
  Grid,
  Card,
  CardContent,
  IconButton,
  Tooltip,
  Switch,
  FormControlLabel,
  Slider,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  Tab,
  Badge,
  Divider
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  Description as CSVIcon,
  Image as ImageIcon,
  CheckCircle as SuccessIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Close as CloseIcon,
  Visibility as PreviewIcon,
  Settings as SettingsIcon,
  Transform as ProcessIcon,
  PhotoSizeSelectActual as ResizeIcon,
  Speed as OptimizeIcon,
  ExpandMore as ExpandIcon,
  GetApp as DownloadIcon,
  Refresh as RefreshIcon,
  Info as InfoIcon,
  Assignment as RefIcon
} from '@mui/icons-material';
import { useDropzone } from 'react-dropzone';
import { toast } from 'react-toastify';
import calligraphMediaUploadService from '../../services/calligraphMediaUploadService';

/**
 * Calligraph Bulk Upload Dialog
 * Specialized for Calligraph CSV structure with REF-based image matching
 */
const CalligraphBulkUploadDialog: React.FC<any> = ({ open, onClose, onComplete }) => {
  // ===== STATE MANAGEMENT =====
  const [activeStep, setActiveStep] = useState(0);
  const [activeTab, setActiveTab] = useState(0);

  // File states
  const [csvFile, setCsvFile] = useState(null);
  const [csvData, setCsvData] = useState(null);
  const [imageFiles, setImageFiles] = useState([]);
  const [validationResults, setValidationResults] = useState(null);

  // Processing states
  const [matchingResults, setMatchingResults] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(null);
  const [uploadResults, setUploadResults] = useState(null);
  const [processingStats, setProcessingStats] = useState(null);
  const [loading, setLoading] = useState(false);

  // Settings
  const [settings, setSettings] = useState({
    processImages: true,
    imageQuality: 90,
    targetSize: 1200,
    batchSize: 3,
    delayBetweenBatches: 2000,
    autoResize: true,
    preserveAspectRatio: true,
    backgroundColor: '#FFFFFF'
  });

  const fileInputRef = useRef(null);

  const steps = [
    'Upload Calligraph CSV',
    'Upload Raw Images',
    'Review REF Matching',
    'Process & Upload'
  ];

  // ===== CSV UPLOAD HANDLER =====
  const onCSVDrop = useCallback(async (acceptedFiles) => {
    const file = acceptedFiles[0];
    if (!file) return;

    setLoading(true);
    try {
      const data = await calligraphMediaUploadService.parseCalligraphCSV(file);
      setCsvFile(file);
      setCsvData(data);
      toast.success(`Calligraph CSV parsed: ${data.totalRows} products found`);
      setActiveStep(1);
    } catch(error: any) {
      toast.error(error.message);
    } finally {
      setLoading(false);
  }, []);

  // ===== IMAGE UPLOAD HANDLER =====
  const onImageDrop = useCallback(async (acceptedFiles) => {
    setLoading(true);

    try {
      // Validate all files
      const validation = await calligraphMediaUploadService.validateImageFiles(acceptedFiles);

      if(validation.invalid.length > 0) {
        const errorMessages = validation.invalid.map((v: any) => `${v.file.name}: ${v.error}`);
        toast.error(`${validation.invalid.length} files rejected`);
        console.warn('Rejected files:', errorMessages);
      if(validation.valid.length > 0) {
        const validFiles = validation.valid.map((v: any) => v.file);
        setImageFiles(prev => [...prev, ...validFiles]);
        setValidationResults(validation);
        toast.success(`${validation.valid.length} raw images added`);
    } catch(error: any) {
      toast.error(`Validation failed: ${error.message}`);
    } finally {
      setLoading(false);
  }, []);

  // ===== MATCHING HANDLER =====
  const handleMatching = useCallback(() => {
    if(!csvData || imageFiles.length ===0) {
      toast.error('Please upload both Calligraph CSV and raw images');
      return;
    setLoading(true);
    try {
      const results = calligraphMediaUploadService.matchImagesWithCalligraphCSV(csvData, imageFiles);
      setMatchingResults(results);
      setActiveStep(2);

      toast.success(
        `REF matching complete: ${results.stats.matched} matches for ${results.stats.uniqueProducts} products`
      );
    } catch(error: any) {
      toast.error(`Matching failed: ${error.message}`);
    } finally {
      setLoading(false);
  }, [csvData, imageFiles]);

  // ===== UPLOAD HANDLER =====
  const handleStartUpload = async () => {
    if(!matchingResults || matchingResults.matches.length ===0) {
      toast.error('No matches to upload');
      return;
    setActiveStep(3);
    setUploadProgress({ current: 0, total: matchingResults.matches.length });

    try {
      const results = await calligraphMediaUploadService.bulkUploadCalligraphImages(matchingResults.matches,
        (progress) => setUploadProgress(progress),
        {
          processImages: settings.processImages,
          imageQuality: settings.imageQuality / 100,
          targetSize: settings.targetSize,
          batchSize: settings.batchSize,
          delayBetweenBatches: settings.delayBetweenBatches
      );

      setUploadResults(results);

      // Generate statistics
      const stats = calligraphMediaUploadService.generateProcessingStats(results);
      setProcessingStats(stats);

      const successful = results.filter((r: any) => r.status === 'success').length;
      const failed = results.filter((r: any) => r.status === 'error').length;

      toast.success(`Calligraph upload complete: ${successful} successful, ${failed} failed`);

      if(onComplete) {
        onComplete(results);
    } catch(error: any) {
      toast.error(`Upload failed: ${error.message}`);
  };

  // ===== UTILITY FUNCTIONS =====
  const handleReset = () => {
    setActiveStep(0);
    setActiveTab(0);
    setCsvFile(null);
    setCsvData(null);
    setImageFiles([]);
    setValidationResults(null);
    setMatchingResults(null);
    setUploadProgress(null);
    setUploadResults(null);
    setProcessingStats(null);
  };

  const removeImage = (index) => {
    setImageFiles(prev => prev.filter((_, i: any) => i !== index));
    setValidationResults(null);
  };

  const downloadResults = () => {
    if (!uploadResults) return;

    const data = uploadResults.map((result: any) => ({
      SKU: result.sku,
      REF: result.ref,
      OriginalFileName: result.file.name,
      FinalFileName: result.processedFileName,
      Status: result.status,
      MatchStrategy: result.matchStrategy,
      Message: result.result.message,
      OriginalSize: `${(result.originalSize / 1024 / 1024).toFixed(2)}MB`,
      ProcessedSize: `${(result.processedSize / 1024 / 1024).toFixed(2)}MB`,
      CompressionRatio: `${result.compressionRatio}%`
    }));

    const csv = [
      Object.keys(data[0]).join(','),
      ...data.map((row: any) => Object.values(row).join(','))
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `calligraph-upload-results-${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  // ===== DROPZONE CONFIGURATIONS =====
  const csvDropzone = useDropzone({
    onDrop: onCSVDrop,
    accept: {
      'text/csv': ['.csv'],
      'application/vnd.ms-excel': ['.csv']
    },
    maxFiles: 1,
    disabled: loading
  });

  const imageDropzone = useDropzone({
    onDrop: onImageDrop,
    accept: {
      'image/*': ['.jpeg', '.jpg', '.png', '.gif', '.webp']
    },
    multiple: true,
    disabled: loading
  });

  return (
    <Dialog open={open} 
      onClose={onClose} 
      maxWidth
        sx: { minHeight: '80vh', maxHeight: '90vh' }
      }}></
      <DialogTitle sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 1,
        bgcolor: 'success.main',
        color: 'success.contrastText',
        position: 'relative'
      } as any}>
        <RefIcon />
        Calligraph Professional Bulk Upload
        <Chip 
          label
            color: 'success.contrastText',
            ml: 1
          } as any} 
        /></
        <Box sx={{ display: "flex", position: 'absolute', right: 16 } as any}>
          <IconButton onClick={onClose} 
            sx={{ display: "flex", color: 'inherit' } as any}
            size="small"
      <DialogContent dividers sx={{ display: "flex", p: 0 } as any}></
        <Stepper activeStep={activeStep} orientation="vertical" sx={{ display: "flex", p: 3 } as any}>
          {/* Step 1: Calligraph CSV Upload */}
          <Step></
            <StepLabel>
              <Typography variant="h6">Upload Calligraph CSV</Typography>
            </StepLabel>
            <StepContent></
              <Typography variant="outlined" color="text.secondary" gutterBottom>
                Upload the Calligraph CSV file with SKU, REF, and image name columns.
              </Typography>

              <Paper { ...csvDropzone.getRootProps()}
                sx={{
                  borderColor: csvDropzone.isDragActive ? 'success.main' : 'grey.300',
                  bgcolor: csvDropzone.isDragActive ? 'success.light' : 'background.default',
                  cursor: 'pointer',
                  textAlign: 'center',
                  mt: 2,
                  transition: 'all 0.2s ease'
                } as any}>
                <input { ...csvDropzone.getInputProps()} />
                <CSVIcon sx={{ display: "flex", fontSize: 64, color: 'success.main', mb: 2 } as any} /></
                <Typography variant="h6" gutterBottom>
                  {csvDropzone.isDragActive
                    ? 'Drop Calligraph CSV here...'
                    : 'Drag & drop Calligraph CSV file here, or click to select'
                </Typography>
                <Typography variant="outlined" color="text.secondary">
                  Required columns: sku, ref, image name (optional: name)
                </Typography>
              </Paper>

              {csvFile && csvData && (
                <Alert severity="success" sx={{ display: "flex", mt: 2 } as any}></
                  <Typography variant="outlined">
                    <strong>{csvFile.name}</strong> - {csvData.totalRows} products loaded
                  </Typography>
                  <Typography variant="caption" display="block">
                    SKU Column: {csvData.skuColumn} | 
                    REF Column: {csvData.refColumn} |
                    {csvData.imageNameColumn && ` Image Name: ${csvData.imageNameColumn} |`}
                    {csvData.productNameColumn && ` Product Name: ${csvData.productNameColumn}`}
                  </Typography>
                </Alert>
              )}
            </StepContent>
          </Step>

          {/* Step 2: Raw Image Upload */}
          <Step></
            <StepLabel>
              <Typography variant="h6">Upload Raw Images</Typography>
            </StepLabel>
            <StepContent></
              <Typography variant="outlined" color="text.secondary" gutterBottom>
                Upload raw product images with reference naming (e.g., 7203C_1.jpg, 7203C_2.jpg, 7203C.jpg).
              </Typography>

              <Paper { ...imageDropzone.getRootProps()}
                sx={{
                  borderColor: imageDropzone.isDragActive ? 'primary.main' : 'grey.300',
                  bgcolor: imageDropzone.isDragActive ? 'primary.light' : 'background.default',
                  cursor: 'pointer',
                  textAlign: 'center',
                  mt: 2,
                  transition: 'all 0.2s ease'
                } as any}>
                <input { ...imageDropzone.getInputProps()} />
                <ImageIcon sx={{ display: "flex", fontSize: 64, color: 'primary.main', mb: 2 } as any} /></
                <Typography variant="h6" gutterBottom>
                  {imageDropzone.isDragActive
                    ? 'Drop raw images here...'
                    : 'Drag & drop raw images here, or click to select multiple'
                </Typography>
                <Typography variant="outlined" color="text.secondary">
                  Supports: 7203C.jpg, 7203C_1.jpg, 7203C_2.jpg patterns | Max: 10MB per file
                </Typography>
              </Paper>

              {imageFiles.length > 0 && (
                <Box sx={{ display: "flex", mt: 3 } as any}></
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 } as any}>
                    <Typography variant="subtitle1">
                      Raw Images ({imageFiles.length})
                    </Typography>
                    {validationResults && (
                      <Typography variant="outlined" color="text.secondary">
                        Total Size: {(validationResults?.totalSize / 1024 / 1024).toFixed(2)}MB
                      </Typography>
                    )}
                  </Box>

                  <Box sx={{ display: "flex", maxHeight: 200, overflow: 'auto', border: '1px solid', borderColor: 'divider', borderRadius: 1, p: 1 } as any}></
                    <Grid { ...{container: true}} spacing={1}>
                      {imageFiles.map((file: any index: any) => (
                        <Grid item key={index}></
                          <Chip label={file.name}
                            onDelete={() => removeImage(index)}
                            size="small"
                      ))}
                    </Grid>
                  </Box>

                  <Box sx={{ display: "flex", mt: 2, display: 'flex', gap: 2 } as any}></
                    <Button
                      variant="outlined"
                      onClick={handleMatching}
                      disabled={!csvData || imageFiles.length ===0 || loading}
                      startIcon={loading ? <RefreshIcon className="spin" /> : <RefIcon />}
                      color
                      {loading ? 'Processing...' : 'Match with REF Column'}
                    </Button>
                    <Button variant="outlined"
                      onClick={() => setImageFiles([])}
                      disabled={imageFiles.length ===0}
                    >
                      Clear All Images
                    </Button>
                  </Box>
                </Box>
              )}
            </StepContent>
          </Step>

          {/* Step 3: Review REF Matching */}
          <Step></
            <StepLabel>
              <Typography variant="h6">Review REF Matching</Typography>
            </StepLabel>
            <StepContent>
              {matchingResults && (<Box>
                  {/* Enhanced Statistics Cards */}
                  <Grid { ...{container: true}} spacing={2} sx={{ display: "flex", mb: 3 } as any}></
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ display: "flex", textAlign: 'center', bgcolor: 'success.light' } as any}></
                        <CardContent sx={{ display: "flex", py: 2 } as any}>
                          <SuccessIcon sx={{ display: "flex", fontSize: 32, color: 'success.main' } as any} /></
                          <Typography variant="h5" sx={{ display: "flex", fontWeight: 'bold' } as any}>
                            {matchingResults.stats.matched}
                          </Typography>
                          <Typography variant="caption">REF Matches</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center', bgcolor: 'info.light' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <InfoIcon sx={{ display: "flex", fontSize: 32, color: 'info.main' } as any} />
                          <Typography variant="h5" sx={{ display: "flex", fontWeight: 'bold' } as any}>
                            {matchingResults.stats.uniqueProducts}
                          </Typography>
                          <Typography variant="caption">Products</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center', bgcolor: 'warning.light' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <WarningIcon sx={{ display: "flex", fontSize: 32, color: 'warning.main' } as any} />
                          <Typography variant="h5" sx={{ display: "flex", fontWeight: 'bold' } as any}>
                            {matchingResults.stats.multipleImagesProducts}
                          </Typography>
                          <Typography variant="caption">Multi-Image</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center', bgcolor: 'secondary.light' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <ProcessIcon sx={{ display: "flex", fontSize: 32, color: 'secondary.main' } as any} />
                          <Typography variant="h5" sx={{ display: "flex", fontWeight: 'bold' } as any}>
                            {matchingResults.stats.averageImagesPerProduct}
                          </Typography>
                          <Typography variant="caption">Avg/Product</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  </Grid>

                  {/* Match Strategy Breakdown */}
                  <Alert severity="info" sx={{ display: "flex", mb: 3 } as any}></
                    <Typography variant="outlined">
                      <strong>Match Strategies:</strong> REF Column: {matchingResults.stats.matchStrategies.ref}, 
                      Image Name: {matchingResults.stats.matchStrategies.imageName}, 
                      Fuzzy: {matchingResults.stats.matchStrategies.fuzzy}
                    </Typography>
                  </Alert>

                  {/* Tabs for detailed view */}
                  <Paper sx={{ display: "flex", mb: 3 } as any}></
                    <Tabs value={activeTab} onChange={(e, v) => setActiveTab(v)}>
                      <Tab label
                          <Badge badgeContent={matchingResults.matches.length} color="success">
                            REF Matches
                          </Badge>
                      />
                      <Tab label="Processing Settings" />
                      {matchingResults.stats.unmatchedCSV > 0 && (
                        <Tab label
                            <Badge badgeContent={matchingResults.stats.unmatchedCSV} color="warning">
                              Unmatched
                            </Badge>
                        />
                      )}
                    </Tabs>

                    <Box sx={{ display: "flex", p: 2 } as any}>
                      {/* REF Matches Tab */}
                      {activeTab ===0 && (
                        <Box sx={{ display: "flex", maxHeight: 300, overflow: 'auto' } as any}></
                          <TableContainer>
                            <Table size="small"></
                              <TableHead>
                                <TableRow></
                                  <TableCell>SKU</TableCell>
                                  <TableCell>REF</TableCell>
                                  <TableCell>Raw Image</TableCell>
                                  <TableCell>Final Name</TableCell>
                                  <TableCell>Strategy</TableCell>
                                  <TableCell>Size</TableCell>
                                </TableRow>
                              </TableHead>
                              <TableBody>
                                {matchingResults.matches.slice(0, 50).map((match: any index: any) => (
                                  <TableRow key={index}></
                                    <TableCell>{match.sku}</TableCell>
                                    <TableCell></
                                      <Chip label={match.ref} 
                                        size="small"
                                    <TableCell>{match.file.name}</TableCell>
                                    <TableCell>{match.finalImageName}</TableCell>
                                    <TableCell></
                                      <Chip label={match.matchStrategy} 
                                        size="small"
                                      /></Chip>
                                    <TableCell>{(match.file.size / 1024 / 1024).toFixed(2)}MB</TableCell>
                                  </TableRow>
                                ))}
                              </TableBody>
                            </Table>
                          </TableContainer>
                          {matchingResults.matches.length > 50 && (
                            <Typography variant="caption" sx={{ display: "flex", p: 2, display: 'block', textAlign: 'center' } as any}>
                              ... and {matchingResults.matches.length - 50} more matches
                            </Typography>
                          )}
                        </Box>
                      )}

                      {/* Processing Settings Tab */}
                      {activeTab ===1 && (<Grid { ...{container: true}} spacing={3}></
                          <Grid item xs={12} md={6}>
                            <Typography variant="subtitle1" gutterBottom>
                              Image Processing
                            </Typography>
                            <FormControlLabel control
                                  checked={settings.processImages}
                                  onChange={(e) => setSettings(prev => ({ ...prev, processImages: e.target.checked }))}
                                />
                              label
                            {settings.processImages && (<Box sx={{ display: "flex", mt: 2 } as any}></
                                <Typography variant="outlined" gutterBottom>
                                  Target Size: {settings.targetSize}x{settings.targetSize}px
                                </Typography>
                                <Slider value={settings.targetSize}
                                  onChange={(e, v) => setSettings(prev => ({ ...prev, targetSize: v }))}
                                  min={800}
                                  max={2000}
                                  step={100}
                                  marks
                                    { value: 800, label: '800px' },
                                    { value: 1200, label: '1200px' },
                                    { value: 1600, label: '1600px' },
                                    { value: 2000, label: '2000px' }
                                  ]}
                                />

                                <Typography variant="outlined" gutterBottom sx={{ display: "flex", mt: 2 } as any}>
                                  Quality: {settings.imageQuality}%
                                </Typography>
                                <Slider value={settings.imageQuality}
                                  onChange={(e, v) => setSettings(prev => ({ ...prev, imageQuality: v }))}
                                  min={60}
                                  max={100}
                                  step={5}
                                  marks
                                    { value: 60, label: '60%' },
                                    { value: 80, label: '80%' },
                                    { value: 90, label: '90%' },
                                    { value: 100, label: '100%' }
                                  ]}
                                />
                              </Box>
                            )}
                          </Grid>

                          <Grid item xs={12} md={6}></
                            <Typography variant="subtitle1" gutterBottom>
                              Upload Settings
                            </Typography>
                            <Typography variant="outlined" gutterBottom>
                              Batch Size: {settings.batchSize} concurrent uploads
                            </Typography>
                            <Slider value={settings.batchSize}
                              onChange={(e, v) => setSettings(prev => ({ ...prev, batchSize: v }))}
                              min={1}
                              max={10}
                              step={1}
                              marks
                                { value: 1, label: '1' },
                                { value: 3, label: '3' },
                                { value: 5, label: '5' },
                                { value: 10, label: '10' }
                              ]}
                            />

                            <Typography variant="outlined" gutterBottom sx={{ display: "flex", mt: 2 } as any}>
                              Delay: {settings.delayBetweenBatches}ms between batches
                            </Typography>
                            <Slider value={settings.delayBetweenBatches}
                              onChange={(e, v) => setSettings(prev => ({ ...prev, delayBetweenBatches: v }))}
                              min={500}
                              max={5000}
                              step={500}
                              marks
                                { value: 500, label: '0.5s' },
                                { value: 2000, label: '2s' },
                                { value: 5000, label: '5s' }
                              ]}
                            />
                          </Grid>
                        </Grid>
                      )}

                      {/* Unmatched Tab */}
                      {activeTab ===2 && matchingResults.unmatched.csvRows.length > 0 && (
                        <Box sx={{ display: "flex", maxHeight: 300, overflow: 'auto' } as any}></
                          <Typography variant="outlined" color="text.secondary" gutterBottom>
                            Products without matching images:
                          </Typography>
                          <List dense>
                            {matchingResults.unmatched.csvRows.map((row: any index: any) => (
                              <ListItem key={index}></
                                <ListItemIcon>
                                  <WarningIcon color="warning" /></WarningIcon>
                                <ListItemText primary={`SKU: ${row.sku} - REF: ${row.ref}`}
                                  secondary={`Product: ${row.productName || 'No name'} | Expected: ${row.imageName || 'Not specified'}`}
                                /></ListItemText>
                            ))}
                          </List>
                        </Box>
                      )}
                    </Box>
                  </Paper>

                  <Button
                    variant="outlined"
                    onClick={handleStartUpload}
                    disabled={matchingResults.matches.length ===0}
                    startIcon={<UploadIcon />}
                    color
                    Start Calligraph Upload ({matchingResults.matches.length} images)
                  </Button>
                </Box>
              )}
            </StepContent>
          </Step>

          {/* Step 4: Process & Upload */}
          <Step></
            <StepLabel>
              <Typography variant="h6">Process & Upload</Typography>
            </StepLabel>
            <StepContent>
              {uploadProgress && (
                <Box sx={{ display: "flex", mb: 3 } as any}></
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 1 } as any}>
                    <Typography variant="outlined">
                      Progress: {uploadProgress.current} of {uploadProgress.total}
                    </Typography>
                    <Typography variant="outlined">
                      {((uploadProgress.current / uploadProgress.total) * 100).toFixed(1)}%
                    </Typography>
                  </Box>
                  <LinearProgress
                    variant="outlined"
                    value={(uploadProgress.current / uploadProgress.total) * 100}
                    sx={{ display: "flex", mb: 2, height: 8, borderRadius: 4 } as any}
                  />
                  {uploadProgress.sku && (
                    <Box></
                      <Typography variant="outlined" color="primary">
                        Current: SKU {uploadProgress.sku} - {uploadProgress.fileName}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        Stage: {uploadProgress.stage || uploadProgress.status}
                      </Typography>
                    </Box>
                  )}
                </Box>
              )}

              {uploadResults && processingStats && (
                <Box></
                  <Alert severity="success" sx={{ display: "flex", mb: 3 } as any}>
                    <Typography variant="body1" gutterBottom>
                      Calligraph upload completed successfully!
                    </Typography>
                    <Typography variant="outlined">
                      {processingStats.successful} successful, {processingStats.failed} failed
                      {processingStats.compressionRatio > 0 && (
                        <> • {processingStats.compressionRatio}% size reduction</>
                      )}
                      • Success rate: {processingStats.successRate}%
                    </Typography>
                  </Alert>

                  {/* Enhanced Results Summary */}
                  <Grid { ...{container: true}} spacing={2} sx={{ display: "flex", mb: 3 } as any}></
                    <Grid item xs={6} sm={3}>
                      <Card sx={{ display: "flex", textAlign: 'center' } as any}></
                        <CardContent sx={{ display: "flex", py: 2 } as any}>
                          <Typography variant="h4" color="success.main">
                            {processingStats.successful}
                          </Typography>
                          <Typography variant="caption">Successful</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <Typography variant="h4" color="error.main">
                            {processingStats.failed}
                          </Typography>
                          <Typography variant="caption">Failed</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <Typography variant="h4" color="info.main">
                            {processingStats.uniqueProducts}
                          </Typography>
                          <Typography variant="caption">Products</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                    <Grid item xs={6} sm={3}></
                      <Card sx={{ display: "flex", textAlign: 'center' } as any}>
                        <CardContent sx={{ display: "flex", py: 2 } as any}></
                          <Typography variant="h4" color="primary.main">
                            {processingStats.averageImagesPerProduct}
                          </Typography>
                          <Typography variant="caption">Avg/Product</Typography>
                        </CardContent>
                      </Card>
                    </Grid>
                  </Grid>

                  <Box sx={{ display: 'flex', gap: 2, mb: 2 } as any}></
                    <Button
                      variant="outlined"
                      startIcon={<DownloadIcon />}
                      onClick={downloadResults}
                    >
                      Download Calligraph Results CSV
                    </Button>
                  </Box>

                  {/* Detailed Results */}
                  <Accordion></
                    <AccordionSummary expandIcon={<ExpandIcon />}>
                      <Typography>View Detailed Results</Typography>
                    </AccordionSummary>
                    <AccordionDetails></
                      <Box sx={{ display: "flex", maxHeight: 400, overflow: 'auto' } as any}>
                        <TableContainer></
                          <Table size="small">
                            <TableHead></
                              <TableRow>
                                <TableCell>Status</TableCell>
                                <TableCell>SKU</TableCell>
                                <TableCell>REF</TableCell>
                                <TableCell>Raw File</TableCell>
                                <TableCell>Final Name</TableCell>
                                <TableCell>Strategy</TableCell>
                                <TableCell>Size</TableCell>
                                <TableCell>Message</TableCell>
                              </TableRow>
                            </TableHead>
                            <TableBody>
                              {uploadResults.map((result: any index: any) => (
                                <TableRow key={index}></
                                  <TableCell>
                                    {result.status === 'success' ? (
                                      <SuccessIcon color="success" fontSize="small" />
                                    ) : (
                                      <ErrorIcon color="error" fontSize="small" />
                                    )}
                                  </TableCell>
                                  <TableCell>{result.sku}</TableCell>
                                  <TableCell></
                                    <Chip label={result.ref} 
                                      size="small"
                                  <TableCell>{result.file.name}</TableCell>
                                  <TableCell>{result.processedFileName}</TableCell>
                                  <TableCell></
                                    <Chip label={result.matchStrategy} 
                                      size="small"
                                    /></Chip>
                                  <TableCell>
                                    {(result.originalSize / 1024 / 1024).toFixed(2)}MB
                                    {result.processedSize && result.processedSize !== result.originalSize && (
                                      <> → {(result.processedSize / 1024 / 1024).toFixed(2)}MB</>
                                    )}
                                  </TableCell>
                                  <TableCell></
                                    <Typography variant="caption">
                                      {result.result.message}
                                    </Typography>
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                        </TableContainer>
                      </Box>
                    </AccordionDetails>
                  </Accordion>
                </Box>
              )}
            </StepContent>
          </Step>
        </Stepper>
      </DialogContent>

      <DialogActions sx={{ display: "flex", p: 2, bgcolor: 'background.paper' } as any}></
        <Button onClick={onClose} disabled={loading}>
          {uploadResults ? 'Close' : 'Cancel'}
        </Button>
        {activeStep > 0 && !uploadResults && (
          <Button onClick={handleReset} color="secondary" disabled={loading}>
            Reset
          </Button>
        )}
      </DialogActions>
    </Dialog>
  );
};

export default CalligraphBulkUploadDialog;

import React, { useState, useCallback } from 'react';
import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    Typography,
    Alert,
    LinearProgress,
    Stepper,
    Step,
    StepLabel,
    Card,
    CardContent,
    Chip,
    List,
    ListItem,
    ListItemText,
    Divider,
    FormControlLabel,
    Switch,
    TextField,
    Grid
} from '@mui/material';
import {
    CloudUpload as UploadIcon,
    CheckCircle as CheckIcon,
    Error as ErrorIcon,
    Warning as WarningIcon,
    Info as InfoIcon,
    Download as DownloadIcon,
    Settings as BatchIcon
} from '@mui/icons-material';
import { toast } from 'react-toastify';
import { 
    processCatalogToImportCSV,
    convertProductsToCSV,
    createBatchedCSVs,
    generateImportReport
} from '../../utils/catalogProcessor';

const CatalogProcessorDialog = ({ open, onClose, onProcessComplete }) => {
    const [activeStep, setActiveStep] = useState(0);
    const [catalogFile, setCatalogFile] = useState(null);
    const [processing, setProcessing] = useState(false);
    const [processedData, setProcessedData] = useState(null);
    const [importReport, setImportReport] = useState(null);
    const [batchSize, setBatchSize] = useState(100);
    const [createBatches, setCreateBatches] = useState(true);
    const [selectedProductTypes, setSelectedProductTypes] = useState({
        simple: true,
        configurable: true
    });

    const steps = ['Upload Catalog', 'Process Data', 'Review Results', 'Generate CSV'];

    const handleFileUpload = useCallback((event) => {
        const file = event.target.files[0];
        if (!file) return;

        if (!file.name.toLowerCase().endsWith('.csv')) {
            toast.error('Please select a CSV file');
            return;
        }

        setCatalogFile(file);
        setActiveStep(1);
        toast.success(`Loaded catalog file: ${file.name} (${(file.size / 1024 / 1024).toFixed(2)} MB)`);
    }, []);

    const handleProcessCatalog = useCallback(async () => {
        if (!catalogFile) return;

        setProcessing(true);

        try {
            const reader = new FileReader();

            reader.onload = async (e) => {
                try {
                    const csvContent = e.target.result;
                    console.log('📁 Processing catalog file...');

                    const processed = await processCatalogToImportCSV(csvContent);
                    const report = generateImportReport(processed);

                    setProcessedData(processed);
                    setImportReport(report);
                    setActiveStep(2);

                    toast.success(`Successfully processed ${processed.statistics.total} products!`);
                } catch (error) {
                    console.error('Processing error:', error);
                    toast.error(`Processing failed: ${error.message}`);
                }
                setProcessing(false);
            };

            reader.onerror = () => {
                toast.error('Failed to read catalog file');
                setProcessing(false);
            };

            reader.readAsText(catalogFile);

        } catch (error) {
            toast.error(`Processing error: ${error.message}`);
            setProcessing(false);
        }
    }, [catalogFile]);

    const handleGenerateCSV = useCallback(() => {
        if (!processedData) return;

        try {
            // Filter products based on selection
            let productsToExport = [];

            if (selectedProductTypes.simple) {
                productsToExport.push(...processedData.simpleProducts);
            }

            if (selectedProductTypes.configurable) {
                productsToExport.push(...processedData.configurableProducts);
            }

            if (productsToExport.length === 0) {
                toast.warning('Please select at least one product type to export');
                return;
            }

            if (createBatches) {
                // Create batched CSV files
                const batches = createBatchedCSVs(productsToExport, batchSize);

                batches.forEach((batch, index) => {
                    const blob = new Blob([batch.csvContent], { type: 'text/csv' });
                    const url = URL.createObjectURL(blob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = `magento_import_batch_${batch.batchNumber}_products_${batch.startIndex + 1}-${batch.endIndex + 1}.csv`;
                    document.body.appendChild(link);
                    link.click();
                    document.body.removeChild(link);
                    URL.revokeObjectURL(url);
                });

                toast.success(`Generated ${batches.length} batch files with ${productsToExport.length} products total`);
            } else {
                // Create single CSV file
                const csvContent = convertProductsToCSV(productsToExport);
                const blob = new Blob([csvContent], { type: 'text/csv' });
                const url = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.download = `magento_import_all_products_${productsToExport.length}.csv`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                URL.revokeObjectURL(url);

                toast.success(`Generated CSV file with ${productsToExport.length} products`);
            }

            setActiveStep(3);

            if (onProcessComplete) {
                onProcessComplete({
                    totalProducts: productsToExport.length,
                    batches: createBatches ? Math.ceil(productsToExport.length / batchSize) : 1,
                    processedData
                });
            }

        } catch (error) {
            toast.error(`CSV generation failed: ${error.message}`);
        }
    }, [processedData, selectedProductTypes, createBatches, batchSize, onProcessComplete]);

    const handleClose = () => {
        if (!processing) {
            // Reset state
            setActiveStep(0);
            setCatalogFile(null);
            setProcessedData(null);
            setImportReport(null);
            setProcessing(false);
            onClose();
        }
    };

    const renderStepContent = () => {
        switch (activeStep) {
            case 0:
                return (
                    <Box sx={{ textAlign: 'center', py: 4 }}>
                        <input
                            accept=".csv"
                            style={{ display: 'none' }}
                            id="catalog-upload"
                            type="file"
                            onChange={handleFileUpload}
                        />
                        <label htmlFor="catalog-upload">
                            <Button
                                variant="contained"
                                component="span"
                                startIcon={<UploadIcon />}
                                size="large"
                                sx={{ mb: 2 }}
                            >
                                Select Catalog CSV
                            </Button>
                        </label>
                        <Typography variant="body2" color="text.secondary">
                            Upload the export_catalog_product.csv file (20MB) to process all products
                        </Typography>
                        {catalogFile && (
                            <Alert severity="info" sx={{ mt: 2 }}>
                                Selected: {catalogFile.name} ({(catalogFile.size / 1024 / 1024).toFixed(2)} MB)
                            </Alert>
                        )}
                    </Box>
                );

            case 1:
                return (
                    <Box sx={{ py: 2 }}>
                        <Alert severity="info" sx={{ mb: 2 }}>
                            Ready to process {catalogFile?.name} and extract all products with proper default values
                        </Alert>

                        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
                            This will:
                        </Typography>
                        <List dense>
                            <ListItem>
                                <ListItemText primary="• Parse all products from the catalog" />
                            </ListItem>
                            <ListItem>
                                <ListItemText primary="• Extract valid brands, dimensions, and categories" />
                            </ListItem>
                            <ListItem>
                                <ListItemText primary="• Apply proper default values for Magento import" />
                            </ListItem>
                            <ListItem>
                                <ListItemText primary="• Validate and normalize all product data" />
                            </ListItem>
                        </List>

                        {processing && (
                            <Box sx={{ mt: 2 }}>
                                <LinearProgress />
                                <Typography variant="body2" sx={{ mt: 1 }}>
                                    Processing catalog... This may take a few moments for large files.
                                </Typography>
                            </Box>
                        )}
                    </Box>
                );

            case 2:
                return importReport ? (
                    <Box sx={{ py: 2 }}>
                        {/* Processing Summary */}
                        <Card sx={{ mb: 2 }}>
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Processing Summary
                                </Typography>
                                <Grid container spacing={2}>
                                    <Grid item xs={6}>
                                        <Chip 
                                            icon={<CheckIcon />} 
                                            label={`${importReport.summary.totalProducts} Total Products`} 
                                            color="primary" 
                                            size="small" 
                                        />
                                    </Grid>
                                    <Grid item xs={6}>
                                        <Chip 
                                            label={`${importReport.summary.simpleProducts} Simple`} 
                                            variant="outlined" 
                                            size="small" 
                                        />
                                    </Grid>
                                    <Grid item xs={6}>
                                        <Chip 
                                            label={`${importReport.summary.configurableProducts} Configurable`} 
                                            variant="outlined" 
                                            size="small" 
                                        />
                                    </Grid>
                                    <Grid item xs={6}>
                                        <Chip 
                                            label={`${importReport.validation.totalBrands} Brands`} 
                                            variant="outlined" 
                                            size="small" 
                                        />
                                    </Grid>
                                </Grid>
                            </CardContent>
                        </Card>

                        {/* Export Options */}
                        <Card sx={{ mb: 2 }}>
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Export Options
                                </Typography>

                                <Box sx={{ mb: 2 }}>
                                    <Typography variant="subtitle2" gutterBottom>
                                        Product Types:
                                    </Typography>
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={selectedProductTypes.simple}
                                                onChange={(e) => setSelectedProductTypes(prev => ({
                                                    ...prev,
                                                    simple: e.target.checked
                                                }))}
                                            />
                                        }
                                        label={`Simple Products (${importReport.summary.simpleProducts})`}
                                    />
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={selectedProductTypes.configurable}
                                                onChange={(e) => setSelectedProductTypes(prev => ({
                                                    ...prev,
                                                    configurable: e.target.checked
                                                }))}
                                            />
                                        }
                                        label={`Configurable Products (${importReport.summary.configurableProducts})`}
                                    />
                                </Box>

                                <Box sx={{ mb: 2 }}>
                                    <FormControlLabel
                                        control={
                                            <Switch
                                                checked={createBatches}
                                                onChange={(e) => setCreateBatches(e.target.checked)}
                                            />
                                        }
                                        label="Create Batch Files"
                                    />
                                </Box>

                                {createBatches && (
                                    <TextField
                                        label="Batch Size"
                                        type="number"
                                        value={batchSize}
                                        onChange={(e) => setBatchSize(parseInt(e.target.value) || 100)}
                                        size="small"
                                        sx={{ width: 120 }}
                                        inputProps={{ min: 10, max: 500 }}
                                    />
                                )}
                            </CardContent>
                        </Card>

                        {/* Recommendations */}
                        <Card>
                            <CardContent>
                                <Typography variant="h6" gutterBottom>
                                    Import Recommendations
                                </Typography>
                                <List dense>
                                    {importReport.recommendations.map((rec, index) => (
                                        <ListItem key={index}>
                                            <InfoIcon color="info" sx={{ mr: 1 }} />
                                            <ListItemText primary={rec} />
                                        </ListItem>
                                    ))}
                                </List>
                            </CardContent>
                        </Card>
                    </Box>
                ) : null;

            case 3:
                return (
                    <Box sx={{ py: 2, textAlign: 'center' }}>
                        <CheckIcon color="success" sx={{ fontSize: 64, mb: 2 }} />
                        <Typography variant="h6" gutterBottom>
                            CSV Files Generated Successfully!
                        </Typography>
                        <Typography variant="body2" color="text.secondary">
                            Your import-ready CSV files have been downloaded. 
                            You can now import them into Magento using the admin panel or API.
                        </Typography>
                    </Box>
                );

            default:
                return null;
        }
    };

    return (
        <Dialog open={open} onClose={handleClose} maxWidth="md" fullWidth>
            <DialogTitle>
                Catalog CSV Processor
            </DialogTitle>

            <DialogContent>
                <Stepper activeStep={activeStep} sx={{ mb: 3 }}>
                    {steps.map((label) => (
                        <Step key={label}>
                            <StepLabel>{label}</StepLabel>
                        </Step>
                    ))}
                </Stepper>

                {renderStepContent()}
            </DialogContent>

            <DialogActions>
                <Button onClick={handleClose} disabled={processing}>
                    {activeStep === 3 ? 'Close' : 'Cancel'}
                </Button>

                {activeStep === 1 && (
                    <Button 
                        onClick={handleProcessCatalog} 
                        variant="contained"
                        disabled={!catalogFile || processing}
                        startIcon={processing ? null : <BatchIcon />}
                    >
                        {processing ? 'Processing...' : 'Process Catalog'}
                    </Button>
                )}

                {activeStep === 2 && importReport && (
                    <Button 
                        onClick={handleGenerateCSV} 
                        variant="contained"
                        color="primary"
                        startIcon={<DownloadIcon />}
                    >
                        Generate CSV Files
                    </Button>
                )}
            </DialogActions>
        </Dialog>
    );
};

