    <div hidden={value !== index} style={{ paddingTop: 16 }}>
      {value === index && children}
    </div>
  );

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="lg" 
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: 2,
          boxShadow: '0 8px 32px rgba(0, 0, 0, 0.1)',
          minHeight: '70vh'
        }
      }}
    >
      <DialogTitle sx={{ 
        display: 'flex', 
        alignItems: 'center', 
        gap: 1,
        bgcolor: 'primary.main',
        color: 'primary.contrastText'
      }}>
        <ProductIcon />
        {product?.sku ? `Edit Product: ${product.sku}` : 'Add New Product'}
      </DialogTitle>

      <DialogContent dividers>
        <Tabs
          value={activeTab}
          onChange={(e, newValue) => setActiveTab(newValue)}
          sx={{ borderBottom: 1, borderColor: 'divider', mb: 2 }}
        >
          <Tab icon={<ProductIcon />} label="Basic Info" />
          <Tab icon={<CategoryIcon />} label="Categories" />
          <Tab icon={<BrandingIcon />} label="Attributes" />
          <Tab icon={<ImageIcon />} label="Images" />
          <Tab icon={<SettingsIcon />} label="SEO & Meta" />
        </Tabs>

        {/* Basic Information Tab */}
        <TabPanel value={activeTab} index={0}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="SKU"
                name="sku"
                value={formData.sku}
                onChange={handleBasicChange}
                required
                disabled={!!product?.sku} // Don't allow SKU changes for existing products
              />
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Techno Reference"
                name="techno_ref"
                value={additionalAttributes.techno_ref}
                onChange={handleAttributeChange}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Product Name"
                name="name"
                value={formData.name}
                onChange={handleBasicChange}
                required
                multiline
                rows={2}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Price (DA)"
                name="price"
                type="number"
                value={formData.price}
                onChange={handleBasicChange}
                InputProps={{ inputProps: { min: 0, step: 0.01 } }}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Weight (g)"
                name="weight"
                type="number"
                value={formData.weight}
                onChange={handleBasicChange}
                InputProps={{ inputProps: { min: 0 } }}
              />
            </Grid>

            <Grid item xs={12} sm={4}>
              <FormControl fullWidth>
                <InputLabel>Status</InputLabel>
                <Select
                  name="status"
                  value={formData.status}
                  onChange={handleBasicChange}
                  label="Status"
                >
                  <MenuItem value={1}>Enabled</MenuItem>
                  <MenuItem value={2}>Disabled</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Short Description"
                name="short_description"
                value={additionalAttributes.short_description}
                onChange={handleAttributeChange}
                multiline
                rows={2}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                name="description"
                value={additionalAttributes.description}
                onChange={handleAttributeChange}
                multiline
                rows={4}
              />
            </Grid>
          </Grid>
        </TabPanel>

        {/* Categories Tab */}
        <TabPanel value={activeTab} index={1}>
          <Alert severity="info" sx={{ mb: 2 }}>
            Select categories for this product. You can choose multiple categories.
          </Alert>

          <Autocomplete
            multiple
            options={categories}
            getOptionLabel={(option) => option.label}
            value={categories.filter(cat => selectedCategories.includes(cat.id.toString()))}
            onChange={(event, newValue) => {
              setSelectedCategories(newValue.map(cat => cat.id.toString()));
            }}
            renderInput={(params) => (
              <TextField
                {...params}
                label="Product Categories"
                placeholder="Select categories..."
              />
            )}
            renderTags={(value, getTagProps) =>
              value.map((option, index) => (
                <Chip
                  variant="outlined"
                  label={option.name}
                  {...getTagProps({ index })}
                  key={option.id}
                />
              ))
            }
          />

          {selectedCategories.length > 0 && (
            <Box sx={{ mt: 2 }}>
              <Typography variant="subtitle2" gutterBottom>
                Selected Categories ({selectedCategories.length}):
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                {selectedCategories.map(catId => {
                  const category = categories.find(cat => cat.id.toString() === catId);
                  return category ? (
                    <Chip
                      key={catId}
                      label={category.name}
                      size="small"
                      color="primary"
                      variant="outlined"
                    />
                  ) : null;
                })}
              </Box>
            </Box>
          )}
        </TabPanel>

        {/* Attributes Tab */}
        <TabPanel value={activeTab} index={2}>
          <Grid container spacing={2}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Brand</InputLabel>
                <Select
                  name="mgs_brand"
                  value={additionalAttributes.mgs_brand}
                  onChange={handleAttributeChange}
                  label="Brand"
                >
                  <MenuItem value="">
                    <em>No Brand</em>
                  </MenuItem>
                  {brands.map(brand => (
                    <MenuItem key={brand.value || brand.id} value={brand.value || brand.id}>
                      {brand.label || brand.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Country of Manufacture"
                name="country_of_manufacture"
                value={additionalAttributes.country_of_manufacture}
                onChange={handleAttributeChange}
                placeholder="e.g., FR, CN, DE"
              />
            </Grid>

            <Grid item xs={12}>
              <Typography variant="subtitle1" gutterBottom>
                Product Flags
              </Typography>
              <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={additionalAttributes.trending}
                      onChange={handleAttributeChange}
                      name="trending"
                      color="success"
                    />
                  }
                  label="Trending"
                />

                <FormControlLabel
                  control={
                    <Switch
                      checked={additionalAttributes.best_seller}
                      onChange={handleAttributeChange}
                      name="best_seller"
                      color="warning"
                    />
                  }
                  label="Best Seller"
                />

                <FormControlLabel
                  control={
                    <Switch
                      checked={additionalAttributes.a_la_une}
                      onChange={handleAttributeChange}
                      name="a_la_une"
                      color="secondary"
                    />
                  }
                  label="À la Une"
                />
              </Box>
            </Grid>
          </Grid>
        </TabPanel>

        {/* Images Tab */}
        <TabPanel value={activeTab} index={3}>
          <Alert severity="info" sx={{ mb: 2 }}>
            Upload and manage product images. The first image will be used as the main product image.
          </Alert>

          <ProductMediaUpload
            sku={formData.sku}
            existingImages={productImages}
            onImagesChange={setProductImages}
          />
        </TabPanel>

        {/* SEO & Meta Tab */}
        <TabPanel value={activeTab} index={4}>
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Meta Title"
                name="meta_title"
                value={additionalAttributes.meta_title}
                onChange={handleAttributeChange}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Meta Keywords"
                name="meta_keywords"
                value={additionalAttributes.meta_keywords}
                onChange={handleAttributeChange}
                multiline
                rows={2}
                placeholder="keyword1, keyword2, keyword3"
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Meta Description"
                name="meta_description"
                value={additionalAttributes.meta_description}
                onChange={handleAttributeChange}
                multiline
                rows={3}
              />
            </Grid>
          </Grid>
        </TabPanel>
      </DialogContent>

      <DialogActions sx={{ 
        justifyContent: 'space-between',
        bgcolor: 'background.default',
        p: 2
      }}>
        <Button 
          onClick={onClose}
          startIcon={<CancelIcon />}
          color="inherit"
        >
          Cancel
        </Button>

        <Button 
          onClick={handleSave}
          variant="contained"
          color="primary"
          startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SaveIcon />}
          disabled={loading || !formData.sku.trim() || !formData.name.trim()}
        >
          Save Product
        </Button>
      </DialogActions>
    </Dialog>
  );
};

