                      </Typography>
                      <Typography variant="body2">
                        {item.location}
                      </Typography>
                    </Stack>
                  </Stack>

                  {/* Stock Level */}
                  <Box>
                    <Stack direction="row" justifyContent="space-between" sx={{ mb: 1 }}>
