                  </Box>

                  {/* Stock Thresholds */}
                  <Stack spacing={1}>
                    <Stack direction="row" justifyContent="space-between">
                      <Typography variant="caption" color="text.secondary">
                        {t('Min Stock')}
                      </Typography>
                      <Typography variant="caption">
                        {item.minStock}
                      </Typography>
                    </Stack>
                    <Stack direction="row" justifyContent="space-between">
                      <Typography variant="caption" color="text.secondary">
                        {t('Reorder Point')}
                      </Typography>
                      <Typography variant="caption">
                        {item.reorderPoint}
                      </Typography>
                    </Stack>
                    <Stack direction="row" justifyContent="space-between">
                      <Typography variant="caption" color="text.secondary">
                        {t('Last Restocked')}
                      </Typography>
                      <Typography variant="caption">
                        {item.lastRestocked}
                      </Typography>
                    </Stack>
                  </Stack>

                  {/* Actions */}
                  <Stack direction="row" spacing={1} sx={{ pt: 1 }}>
                    <Button
                      size="small"
                      variant="outlined"
                      onClick={() => handleRestock(item.id)}
                      disabled={item.currentStock >= item.maxStock}
                    >
                      {t('Restock')}
                    </Button>
                    <Tooltip title={t('Edit Item')}>
                      <IconButton size="small" onClick={() => handleEditInventory(item.id)}>
                        <EditIcon />
                      </IconButton>
                    </Tooltip>
                  </Stack>
                </Stack>
              </CardContent>
            </Card>
          );
        })}
      </Box>

      {/* Empty State */}
      {filteredInventory.length === 0 && (
        <Box sx={{ textAlign: 'center', py: 4 }}>
          <WarehouseIcon sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
          <Typography variant="h6" color="text.secondary">
            {searchQuery ? t('No inventory items found') : t('No inventory items yet')}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {searchQuery ? t('Try adjusting your search') : t('Add inventory items to track stock levels')}
          </Typography>
        </Box>
      )}
    </Box>
  );
};

