    exportOptions: {
      excel: {
        enabled: true,
        label: 'Export to Excel',
        icon: ExportIcon,
        handler: () => onExport?.('excel')
      },
      csv: {
        enabled: true,
        label: 'Export to CSV',
        icon: ExportIcon,
        handler: () => onExport?.('csv')
      },
      json: {
        enabled: true,
        label: 'Export to JSON',
