      showSnackbar('Failed to load voting features', 'error');
    } finally {
      setLoading(false);
    }
  }, [paginationModel, sortModel, filterModel]);

  /**
   * Load voting categories
   */
  const loadCategories = useCallback(async () => {
    try {
      const response = await votingApiService.getCategories();
      if (response.success) {
        setCategories(response.data);
      }
    } catch (error) {
      console.error('Error loading categories:', error);
    }
  }, []);

  /**
   * Load user votes for current features
   */
  const loadUserVotes = useCallback(async () => {
    try {
      const featureIds = features.map(f => f.id);
      if (featureIds.length === 0) return;

      const response = await votingApiService.getUserVotes(userId, featureIds);
      if (response.success) {
        const votesMap = {};
        response.data.forEach(vote => {
          votesMap[vote.feature_id] = vote.vote_type;
        });
        setUserVotes(votesMap);
      }
    } catch (error) {
      console.error('Error loading user votes:', error);
    }
  }, [features, userId]);

  /**
   * Handle voting for a feature
   */
  const handleVote = async (featureId, voteType) => {
    try {
      const userInfo = votingApiService.getCurrentUserInfo();
      const currentVote = userVotes[featureId];

      if (currentVote === voteType) {
        // Remove vote if clicking same vote type
        await votingApiService.removeVote(featureId, userInfo);
        setUserVotes(prev => {
          const updated = { ...prev };
          delete updated[featureId];
          return updated;
        });
        showSnackbar('Vote removed', 'info');
      } else {
        // Add or change vote
        await votingApiService.voteForFeature(featureId, voteType, userInfo);
        setUserVotes(prev => ({ ...prev, [featureId]: voteType }));
        showSnackbar(`${voteType === 'upvote' ? 'Upvoted' : 'Downvoted'} successfully`, 'success');
      }

      // Refresh the features to get updated vote counts
      await loadFeatures();

    } catch (error) {
      console.error('Error voting:', error);
      showSnackbar('Failed to record vote', 'error');
    }
  };

  /**
   * Show snackbar message
   */
  const showSnackbar = (message, severity = 'info') => {
    setSnackbar({ open: true, message, severity });
  };

  /**
   * Handle refresh
   */
  const handleRefresh = async () => {
    setRefreshing(true);
    await loadFeatures();
    await loadUserVotes();
    setRefreshing(false);
    showSnackbar('Data refreshed', 'success');
  };

  /**
   * DataGrid columns configuration
   */
  const columns = useMemo(() => [
    {
      field: 'title',
      headerName: 'Feature Title',
      flex: 2,
      minWidth: 250,
      renderCell: (params) => (
        <Box sx={{ py: 1 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 600, mb: 0.5 }}>
            {params.value}
          </Typography>
          <Typography variant="caption" color="text.secondary" sx={{ 
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden'
          }}>
            {params.row.description}
          </Typography>
        </Box>
      )
    },
    {
      field: 'category_name',
      headerName: 'Category',
      width: 140,
      renderCell: (params) => {
        const IconComponent = CATEGORY_ICONS[params.value] || Lightbulb;
        return (
          <Chip
            icon={<IconComponent />}
            label={params.value}
            size="small"
            sx={{
              backgroundColor: alpha(params.row.category_color || '#2196F3', 0.1),
              color: params.row.category_color || '#2196F3',
              border: `1px solid ${alpha(params.row.category_color || '#2196F3', 0.3)}`
            }}
          />
        );
      }
    },
    {
      field: 'priority',
      headerName: 'Priority',
      width: 100,
      renderCell: (params) => (
        <Chip
          label={params.value}
          size="small"
          sx={{
            backgroundColor: alpha(PRIORITY_COLORS[params.value] || '#2196F3', 0.1),
            color: PRIORITY_COLORS[params.value] || '#2196F3',
            fontWeight: 600
          }}
        />
      )
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 130,
      renderCell: (params) => (
        <Chip
          label={params.value}
          size="small"
          sx={{
            backgroundColor: alpha(STATUS_COLORS[params.value] || '#2196F3', 0.1),
            color: STATUS_COLORS[params.value] || '#2196F3',
            fontWeight: 500
          }}
        />
      )
    },
    {
      field: 'vote_count',
      headerName: 'Votes',
      width: 80,
      align: 'center',
      renderCell: (params) => (
        <Badge
          badgeContent={params.value}
          color="primary"
          sx={{
            '& .MuiBadge-badge': {
              fontSize: '0.75rem',
              fontWeight: 600
            }
          }}
        >
          <TrendingUp color="action" />
        </Badge>
      )
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 120,
      sortable: false,
      renderCell: (params) => {
        const featureId = params.row.id;
        const userVote = userVotes[featureId];

        return (
          <Stack direction="row" spacing={0.5}>
            <Tooltip title="Upvote">
              <IconButton
                size="small"
                onClick={() => handleVote(featureId, 'upvote')}
                sx={{
                  color: userVote === 'upvote' ? theme.palette.success.main : 'inherit',
                  backgroundColor: userVote === 'upvote' ? alpha(theme.palette.success.main, 0.1) : 'transparent'
                }}
              >
                <ThumbUp fontSize="small" />
              </IconButton>
            </Tooltip>
            <Tooltip title="Downvote">
              <IconButton
                size="small"
                onClick={() => handleVote(featureId, 'downvote')}
                sx={{
                  color: userVote === 'downvote' ? theme.palette.error.main : 'inherit',
                  backgroundColor: userVote === 'downvote' ? alpha(theme.palette.error.main, 0.1) : 'transparent'
                }}
              >
                <ThumbDown fontSize="small" />
              </IconButton>
            </Tooltip>
            <Tooltip title="Comments">
              <IconButton
                size="small"
                onClick={() => setSelectedFeature(params.row)}
              >
                <Comment fontSize="small" />
              </IconButton>
            </Tooltip>
          </Stack>
        );
      }
    }
  ], [userVotes, theme, handleVote]);

  // Load data on component mount and when dependencies change
  useEffect(() => {
    loadCategories();
  }, [loadCategories]);

  useEffect(() => {
    loadFeatures();
  }, [loadFeatures]);

  useEffect(() => {
    if (features.length > 0) {
      loadUserVotes();
    }
  }, [loadUserVotes]);

  return (
    <Box sx={{ height: '100%', width: '100%' }}>
      {/* Header with filters and actions */}
      <Paper sx={{ p: 2, mb: 2 }}>
        <Grid container spacing={2} alignItems="center">
          <Grid item xs={12} md={3}>
            <TextField
              fullWidth
              size="small"
              placeholder="Search features..."
              value={filterModel.search}
              onChange={(e) => setFilterModel(prev => ({ ...prev, search: e.target.value }))}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Search />
                  </InputAdornment>
                )
              }}
            />
          </Grid>

          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Category</InputLabel>
              <Select
                value={filterModel.category}
                label="Category"
                onChange={(e) => setFilterModel(prev => ({ ...prev, category: e.target.value }))}
              >
                <MenuItem value="">All Categories</MenuItem>
                {categories.map(cat => (
                  <MenuItem key={cat.id} value={cat.id}>{cat.name}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Status</InputLabel>
              <Select
                value={filterModel.status}
                label="Status"
                onChange={(e) => setFilterModel(prev => ({ ...prev, status: e.target.value }))}
              >
                <MenuItem value="">All Statuses</MenuItem>
                {Object.keys(STATUS_COLORS).map(status => (
                  <MenuItem key={status} value={status}>{status}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={2}>
            <FormControl fullWidth size="small">
              <InputLabel>Priority</InputLabel>
              <Select
                value={filterModel.priority}
                label="Priority"
                onChange={(e) => setFilterModel(prev => ({ ...prev, priority: e.target.value }))}
              >
                <MenuItem value="">All Priorities</MenuItem>
                {Object.keys(PRIORITY_COLORS).map(priority => (
                  <MenuItem key={priority} value={priority}>{priority}</MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={3}>
            <Stack direction="row" spacing={1}>
              <Button
                variant="outlined"
                startIcon={<Refresh />}
                onClick={handleRefresh}
                disabled={refreshing}
                size="small"
              >
                Refresh
              </Button>
              <Button
                variant="contained"
                startIcon={<Add />}
                onClick={() => setCreateDialogOpen(true)}
                size="small"
              >
                New Feature
              </Button>
              <Button
                variant="outlined"
                startIcon={<Settings />}
                onClick={() => setSettingsDialogOpen(true)}
                size="small"
              >
                Settings
              </Button>
            </Stack>
          </Grid>
        </Grid>
      </Paper>

      {/* Error Alert */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {/* Loading Progress */}
      {loading && <LinearProgress sx={{ mb: 2 }} />}

      {/* Data Grid */}
      <Paper sx={{ height: 600, width: '100%' }}>
        <DataGrid
          rows={features}
          columns={columns}
          paginationModel={paginationModel}
          onPaginationModelChange={setPaginationModel}
          sortModel={sortModel}
          onSortModelChange={setSortModel}
          rowCount={totalCount}
          loading={loading}
          paginationMode="server"
          sortingMode="server"
          pageSizeOptions={[10, 25, 50, 100]}
          disableRowSelectionOnClick
          getRowHeight={() => 80}
          sx={{
            border: 'none',
            '& .MuiDataGrid-cell': {
              borderBottom: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
            },
            '& .MuiDataGrid-row:hover': {
              backgroundColor: alpha(theme.palette.primary.main, 0.04),
            }
          }}
        />
      </Paper>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
          severity={snackbar.severity}
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>

      {/* Grid Settings Dialog */}
      <GridSettings
        open={settingsDialogOpen}
        onClose={() => setSettingsDialogOpen(false)}
        onSave={saveSettings}
        gridId="voting-grid"
        columns={columns}
        currentSettings={gridSettings}
        onReset={() => {
          saveSettings({});
          showSnackbar('Settings reset to defaults', 'info');
        }}
      />
    </Box>
  );
};

