          },
          {
            id: 'feature-2',
            title: 'Mobile App Development',
            description: 'Native mobile application for iOS and Android platforms.',
            priority: 'medium',
            vote_count: 32,
            estimated_completion: '2024-Q3',
            progress: 25,
            tags: ['mobile', 'app', 'cross-platform']
          }
        ],
        approved: [
          {
            id: 'feature-3',
            title: 'Advanced Search Filters',
            description: 'Enhanced search functionality with advanced filtering options.',
            priority: 'medium',
            vote_count: 28,
            estimated_completion: '2024-Q4',
            progress: 0,
            tags: ['search', 'filters', 'ux']
          },
          {
            id: 'feature-4',
            title: 'API Rate Limiting',
            description: 'Implement rate limiting for API endpoints to improve performance.',
            priority: 'high',
            vote_count: 22,
            estimated_completion: '2024-Q2',
            progress: 0,
            tags: ['api', 'performance', 'security']
          }
        ],
        completed: [
          {
            id: 'feature-5',
            title: 'Bug Bounty Program',
            description: 'Community-driven bug reporting and reward system.',
            priority: 'high',
            vote_count: 67,
            estimated_completion: '2024-Q1',
            progress: 100,
            tags: ['quality', 'community', 'testing']
          },
          {
            id: 'feature-6',
            title: 'Dark Mode Theme',
            description: 'Dark theme option for better user experience.',
            priority: 'low',
            vote_count: 89,
            estimated_completion: '2024-Q1',
            progress: 100,
            tags: ['ui', 'theme', 'accessibility']
          }
        ],
        rejected: [
          {
            id: 'feature-7',
            title: 'Cryptocurrency Integration',
            description: 'Accept cryptocurrency payments for premium features.',
            priority: 'low',
            vote_count: 12,
            estimated_completion: null,
            progress: 0,
            tags: ['payments', 'crypto']
          }
        ],
        on_hold: [
          {
            id: 'feature-8',
            title: 'AI-Powered Recommendations',
            description: 'Machine learning based product recommendations.',
            priority: 'medium',
            vote_count: 34,
            estimated_completion: '2025-Q1',
            progress: 10,
            tags: ['ai', 'ml', 'recommendations']
          }
        ]
      };

      setRoadmapData(fallbackData);

      // Only show error if it's a critical failure
      if (err.message && !err.message.includes('404') && !err.message.includes('fetch')) {
        setError(`Unable to load live roadmap data. Showing cached version. (${err.message})`);
      }
    } finally {
      setLoading(false);
    }
  };

  /**
   * Toggle section expansion
   */
  const toggleSection = (status) => {
    setExpandedSections(prev => {
      const newSet = new Set(prev);
      if (newSet.has(status)) {
        newSet.delete(status);
      } else {
        newSet.add(status);
      }
      return newSet;
    });
  };

  /**
   * Calculate progress statistics
   */
  const progressStats = useMemo(() => {
    if (!roadmapData) return null;

    const total = roadmapData.totalFeatures;
    const completed = roadmapData.byStatus.completed?.length || 0;
    const inProgress = roadmapData.byStatus.in_progress?.length || 0;
    const approved = roadmapData.byStatus.approved?.length || 0;

    return {
      total,
      completed,
      inProgress,
      approved,
      completionRate: total > 0 ? (completed / total) * 100 : 0,
      activeWork: inProgress + approved
    };
  }, [roadmapData]);

  // Load data on component mount
  useEffect(() => {
    loadRoadmap();
  }, []);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight={400}>
        <Typography>Loading roadmap...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ m: 2 }}>
        {error}
      </Alert>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h4" gutterBottom>
          Development Roadmap
        </Typography>
        <Typography variant="body1" color="text.secondary" mb={3}>
          Track the progress of features from idea to implementation
        </Typography>

        {/* Progress Overview */}
        {progressStats && (
          <Grid container spacing={3}>
            <Grid item xs={12} md={3}>
              <Card sx={{ textAlign: 'center', p: 2 }}>
                <Typography variant="h3" color="primary">
                  {progressStats.total}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Total Features
                </Typography>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ textAlign: 'center', p: 2 }}>
                <Typography variant="h3" color="success.main">
                  {progressStats.completed}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Completed
                </Typography>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ textAlign: 'center', p: 2 }}>
                <Typography variant="h3" color="warning.main">
                  {progressStats.activeWork}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  In Development
                </Typography>
              </Card>
            </Grid>
            <Grid item xs={12} md={3}>
              <Card sx={{ textAlign: 'center', p: 2 }}>
                <Typography variant="h3" color="info.main">
                  {Math.round(progressStats.completionRate)}%
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  Completion Rate
                </Typography>
                <LinearProgress 
                  variant="determinate" 
                  value={progressStats.completionRate} 
                  sx={{ mt: 1 }}
                />
              </Card>
            </Grid>
          </Grid>
        )}
      </Paper>

      {/* Roadmap Timeline */}
      <Grid container spacing={3}>
        {/* Timeline View */}
        <Grid item xs={12} lg={8}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Development Timeline
            </Typography>

            <Timeline>
              {Object.entries(STATUS_CONFIG).map(([status, config], index) => {
                const features = roadmapData?.byStatus[status] || [];
                const StatusIcon = config.icon;
                const isLast = index === Object.keys(STATUS_CONFIG).length - 1;

                return (
                  <TimelineItem key={status}>
                    <TimelineSeparator>
                      <TimelineDot color={config.color}>
                        <StatusIcon />
                      </TimelineDot>
                      {!isLast && <TimelineConnector />}
                    </TimelineSeparator>
                    <TimelineContent>
                      <Accordion 
                        expanded={expandedSections.has(status)}
                        onChange={() => toggleSection(status)}
                        sx={{ mb: 2 }}
                      >
                        <AccordionSummary expandIcon={<ExpandMore />}>
                          <Stack direction="row" alignItems="center" spacing={2} width="100%">
                            <Typography variant="h6">
                              {config.label}
                            </Typography>
                            <Badge badgeContent={features.length} color={config.color}>
                              <Typography variant="body2" color="text.secondary">
                                features
                              </Typography>
                            </Badge>
                          </Stack>
                        </AccordionSummary>
                        <AccordionDetails>
                          <Typography variant="body2" color="text.secondary" mb={2}>
                            {config.description}
                          </Typography>

                          {features.length > 0 ? (
                            <Stack spacing={2}>
                              {features.map((feature) => {
                                const CategoryIcon = CATEGORY_ICONS[feature.category] || Lightbulb;

                                return (
                                  <motion.div
                                    key={feature.id}
                                    initial={{ opacity: 0, x: -20 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ duration: 0.3 }}
                                  >
                                    <Card variant="outlined" sx={{ p: 2 }}>
                                      <Stack direction="row" spacing={2} alignItems="flex-start">
                                        <CategoryIcon color="action" />
                                        <Box flexGrow={1}>
                                          <Typography variant="subtitle1" gutterBottom>
                                            {feature.title}
                                          </Typography>
                                          <Typography variant="body2" color="text.secondary" mb={1}>
                                            {feature.description}
                                          </Typography>
                                          <Stack direction="row" spacing={1} alignItems="center">
                                            <Chip 
                                              label={feature.category} 
                                              size="small" 
                                              variant="outlined"
                                            />
                                            <Chip 
                                              label={feature.priority} 
                                              size="small" 
                                              color={feature.priority === 'high' ? 'error' : 
                                                     feature.priority === 'medium' ? 'warning' : 'success'}
                                            />
                                            {feature.vote_count > 0 && (
                                              <Tooltip title="Community votes">
                                                <Chip 
                                                  label={`${feature.vote_count} votes`} 
                                                  size="small" 
                                                  color="primary"
                                                  variant="outlined"
                                                />
                                              </Tooltip>
                                            )}
                                            {feature.target_release && (
                                              <Chip 
                                                label={`v${feature.target_release}`} 
                                                size="small" 
                                                color="info"
                                                variant="outlined"
                                              />
                                            )}
                                          </Stack>
                                        </Box>
                                      </Stack>
                                    </Card>
                                  </motion.div>
                                );
                              })}
                            </Stack>
                          ) : (
                            <Typography variant="body2" color="text.secondary" fontStyle="italic">
                              No features in this stage
                            </Typography>
                          )}
                        </AccordionDetails>
                      </Accordion>
                    </TimelineContent>
                  </TimelineItem>
                );
              })}
            </Timeline>
          </Paper>
        </Grid>

        {/* Category Breakdown */}
        <Grid item xs={12} lg={4}>
          <Paper sx={{ p: 3 }}>
            <Typography variant="h5" gutterBottom>
              Features by Category
            </Typography>

            {roadmapData?.byCategory && (
              <Stack spacing={2}>
                {Object.entries(roadmapData.byCategory).map(([category, features]) => {
                  const CategoryIcon = CATEGORY_ICONS[category] || Lightbulb;

                  return (
                    <Card key={category} variant="outlined" sx={{ p: 2 }}>
                      <Stack direction="row" alignItems="center" spacing={2}>
                        <CategoryIcon color="primary" />
                        <Box flexGrow={1}>
                          <Typography variant="subtitle1" textTransform="capitalize">
                            {category.replace('-', ' ')}
                          </Typography>
                          <Typography variant="body2" color="text.secondary">
                            {features.length} feature{features.length !== 1 ? 's' : ''}
                          </Typography>
                        </Box>
                        <Typography variant="h6" color="primary">
                          {features.length}
                        </Typography>
                      </Stack>
                    </Card>
                  );
                })}
              </Stack>
            )}
          </Paper>

          {/* Recent Activity */}
          <Paper sx={{ p: 3, mt: 3 }}>
            <Typography variant="h5" gutterBottom>
              Recent Updates
            </Typography>

            {roadmapData?.recentActivity && roadmapData.recentActivity.length > 0 ? (
              <Stack spacing={2}>
                {roadmapData.recentActivity.slice(0, 5).map((activity, index) => (
                  <Box key={index} sx={{ pb: 1, borderBottom: index < 4 ? 1 : 0, borderColor: 'divider' }}>
                    <Typography variant="body2" gutterBottom>
                      {activity.title}
                    </Typography>
                    <Stack direction="row" justifyContent="space-between" alignItems="center">
                      <Chip 
                        label={STATUS_CONFIG[activity.status]?.label || activity.status} 
                        size="small" 
                        color={STATUS_CONFIG[activity.status]?.color || 'default'}
                      />
                      <Typography variant="caption" color="text.secondary">
                        {new Date(activity.updated_date).toLocaleDateString()}
                      </Typography>
                    </Stack>
                  </Box>
                ))}
              </Stack>
            ) : (
              <Typography variant="body2" color="text.secondary" fontStyle="italic">
                No recent activity
              </Typography>
            )}
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default RoadmapGrid;

/**
 * VotingGrid Component - Interactive grid for feature voting and roadmap
 */
import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Chip,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Tooltip,
  Alert,
  Snackbar,
  Grid,
  Paper,
  Divider,
  Stack,
  Badge
} from '@mui/material';
import {
  ThumbUp,
  ThumbUpOutlined,
  Add,
  TrendingUp,
  Schedule,
  CheckCircle,
  Cancel,
  Pause,
  FilterList,
  Sort
} from '@mui/icons-material';
import { useTranslation } from 'react-i18next';
import { motion, AnimatePresence } from 'framer-motion';
import votingService from '../../services/votingService';

/**
 * Status configuration for features
 */
const STATUS_CONFIG = {
  proposed: {
    color: 'default',
    icon: Schedule,
    label: 'Proposed'
  },
  approved: {
    color: 'info',
    icon: TrendingUp,
    label: 'Approved'
  },
  in_progress: {
    color: 'warning',
    icon: Schedule,
    label: 'In Progress'
  },
  completed: {
    color: 'success',
    icon: CheckCircle,
    label: 'Completed'
  },
  rejected: {
    color: 'error',
    icon: Cancel,
    label: 'Rejected'
  },
  on_hold: {
    color: 'default',
    icon: Pause,
    label: 'On Hold'
  }
};

/**
 * Priority configuration
 */
const PRIORITY_CONFIG = {
  low: { color: 'success', label: 'Low' },
  medium: { color: 'warning', label: 'Medium' },
  high: { color: 'error', label: 'High' },
  critical: { color: 'error', label: 'Critical' }
};

/**
 * VotingGrid Component
 */
const VotingGrid = ({ userId = 'current_user' }) => {
  const { t } = useTranslation();
  const [features, setFeatures] = useState([]);
  const [userVotes, setUserVotes] = useState(new Set());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // Dialog states
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [filterDialogOpen, setFilterDialogOpen] = useState(false);

  // Filter and sort states
  const [filters, setFilters] = useState({
    status: '',
    category: '',
    priority: ''
  });
  const [sortBy, setSortBy] = useState('vote_count');
  const [sortOrder, setSortOrder] = useState('desc');

  // New feature form state
  const [newFeature, setNewFeature] = useState({
    title: '',
    description: '',
    category: 'general',
    priority: 'medium'
  });

  /**
   * Load features and user votes
   */
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const [featuresData, votesData] = await Promise.all([
        votingService.getFeatures(filters),
        votingService.getUserVotes(userId)
      ]);

      setFeatures(featuresData);
      setUserVotes(new Set(votesData.map(vote => vote.feature_id)));
    } catch (err) {
      setError(err.message);
      showSnackbar('Failed to load data', 'error');
    } finally {
      setLoading(false);
    }
  }, [filters, userId]);

  /**
   * Handle voting for a feature
   */
  const handleVote = async (featureId) => {
    try {
      const hasVoted = userVotes.has(featureId);

      if (hasVoted) {
        await votingService.removeVote(featureId, userId);
        setUserVotes(prev => {
          const newSet = new Set(prev);
          newSet.delete(featureId);
          return newSet;
        });
        showSnackbar('Vote removed', 'info');
      } else {
        await votingService.voteForFeature(featureId, userId);
        setUserVotes(prev => new Set([...prev, featureId]));
        showSnackbar('Vote added', 'success');
      }

      // Update vote count in features
      setFeatures(prev => prev.map(feature => {
        if (feature.id === featureId) {
          return {
            ...feature,
            vote_count: hasVoted ? feature.vote_count - 1 : feature.vote_count + 1
          };
        }
        return feature;
      }));
    } catch (err) {
      showSnackbar('Failed to update vote', 'error');
    }
  };

  /**
   * Handle creating a new feature
   */
  const handleCreateFeature = async () => {
    try {
      const createdFeature = await votingService.createFeature({
        ...newFeature,
        created_by: userId
      });

      setFeatures(prev => [createdFeature, ...prev]);
      setCreateDialogOpen(false);
      setNewFeature({ title: '', description: '', category: 'general', priority: 'medium' });
      showSnackbar('Feature created successfully', 'success');
    } catch (err) {
      showSnackbar('Failed to create feature', 'error');
    }
  };

  /**
   * Show snackbar message
   */
  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({ open: true, message, severity });
  };

  /**
   * Sort and filter features
   */
  const sortedAndFilteredFeatures = useMemo(() => {
    let filtered = [...features];

    // Apply filters
    if (filters.status) {
      filtered = filtered.filter(f => f.status === filters.status);
    }
    if (filters.category) {
      filtered = filtered.filter(f => f.category === filters.category);
    }
    if (filters.priority) {
      filtered = filtered.filter(f => f.priority === filters.priority);
    }

    // Apply sorting
    filtered.sort((a, b) => {
      let aVal = a[sortBy];
      let bVal = b[sortBy];

      if (sortBy === 'vote_count') {
        aVal = parseInt(aVal) || 0;
        bVal = parseInt(bVal) || 0;
      }

      if (sortOrder === 'asc') {
        return aVal > bVal ? 1 : -1;
      } else {
        return aVal < bVal ? 1 : -1;
      }
    });

    return filtered;
  }, [features, filters, sortBy, sortOrder]);

  // Load data on component mount
  useEffect(() => {
    loadData();
  }, [loadData]);

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight={400}>
        <Typography>Loading features...</Typography>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ m: 2 }}>
        {error}
      </Alert>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={2}>

          <Stack direction="row" spacing={1}>
            <Button
              variant="outlined"
              startIcon={<FilterList />}
              onClick={() => setFilterDialogOpen(true)}
            >
              Filter
            </Button>
            <Button
              variant="outlined"
              startIcon={<Sort />}
              onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
            >
              Sort {sortOrder === 'asc' ? '↑' : '↓'}
            </Button>
            <Button
              variant="contained"
              startIcon={<Add />}
              onClick={() => setCreateDialogOpen(true)}
            >
              Suggest Feature
            </Button>
          </Stack>
        </Stack>
      </Paper>

      {/* Features Grid */}
      <Grid container spacing={3}>
        <AnimatePresence>
          {sortedAndFilteredFeatures.map((feature) => {
            const statusConfig = STATUS_CONFIG[feature.status] || STATUS_CONFIG.proposed;
            const priorityConfig = PRIORITY_CONFIG[feature.priority] || PRIORITY_CONFIG.medium;
            const hasVoted = userVotes.has(feature.id);
            const StatusIcon = statusConfig.icon;

            return (
              <Grid item xs={12} md={6} lg={4} key={feature.id}>
                <motion.div
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -20 }}
                  transition={{ duration: 0.3 }}
                >
                  <Card 
                    sx={{ 
                      height: '100%',
                      display: 'flex',
                      flexDirection: 'column',
                      transition: 'transform 0.2s, box-shadow 0.2s',
                      '&:hover': {
                        transform: 'translateY(-4px)',
                        boxShadow: 4
                      }
                    }}
                  >
                    <CardContent sx={{ flexGrow: 1 }}>
                      {/* Header with status and priority */}
                      <Stack direction="row" justifyContent="space-between" alignItems="flex-start" mb={2}>
                        <Chip
                          icon={<StatusIcon />}
                          label={statusConfig.label}
                          color={statusConfig.color}
                          size="small"
                        />
                        <Chip
                          label={priorityConfig.label}
                          color={priorityConfig.color}
                          size="small"
                          variant="outlined"
                        />
                      </Stack>

                      {/* Title and description */}
                      <Typography variant="h6" gutterBottom>
                        {feature.title}
                      </Typography>
                      <Typography 
                        variant="body2" 
                        color="text.secondary" 
                        sx={{ mb: 2, minHeight: 60 }}
                      >
                        {feature.description}
                      </Typography>

                      {/* Category */}
                      <Chip
                        label={feature.category}
                        size="small"
                        variant="outlined"
                        sx={{ mb: 2 }}
                      />

                      <Divider sx={{ my: 2 }} />

                      {/* Vote section */}
                      <Stack direction="row" justifyContent="space-between" alignItems="center">
                        <Stack direction="row" alignItems="center" spacing={1}>
                          <Tooltip title={hasVoted ? 'Remove vote' : 'Vote for this feature'}>
                            <IconButton
                              onClick={() => handleVote(feature.id)}
                              color={hasVoted ? 'primary' : 'default'}
                              sx={{
                                transition: 'all 0.2s',
                                '&:hover': {
                                  transform: 'scale(1.1)'
                                }
                              }}
                            >
                              {hasVoted ? <ThumbUp /> : <ThumbUpOutlined />}
                            </IconButton>
                          </Tooltip>
                          <Badge badgeContent={feature.vote_count || 0} color="primary">
                            <Typography variant="body2" color="text.secondary">
                              votes
                            </Typography>
                          </Badge>
                        </Stack>

                        <Typography variant="caption" color="text.secondary">
                          {new Date(feature.created_date).toLocaleDateString()}
                        </Typography>
                      </Stack>
                    </CardContent>
                  </Card>
                </motion.div>
              </Grid>
            );
          })}
        </AnimatePresence>
      </Grid>

      {/* Empty state */}
      {sortedAndFilteredFeatures.length === 0 && (
        <Paper sx={{ p: 6, textAlign: 'center', mt: 3 }}>
          <Typography variant="h6" color="text.secondary" gutterBottom>
            No features found
          </Typography>
          <Typography variant="body2" color="text.secondary" mb={3}>
            Try adjusting your filters or be the first to suggest a new feature!
          </Typography>
          <Button
            variant="contained"
            startIcon={<Add />}
            onClick={() => setCreateDialogOpen(true)}
          >
            Suggest Feature
          </Button>
        </Paper>
      )}

      {/* Create Feature Dialog */}
      <Dialog 
        open={createDialogOpen} 
        onClose={() => setCreateDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Suggest New Feature</DialogTitle>
        <DialogContent>
          <Stack spacing={3} sx={{ mt: 1 }}>
            <TextField
              label="Feature Title"
              value={newFeature.title}
              onChange={(e) => setNewFeature(prev => ({ ...prev, title: e.target.value }))}
              fullWidth
              required
            />
            <TextField
              label="Description"
              value={newFeature.description}
              onChange={(e) => setNewFeature(prev => ({ ...prev, description: e.target.value }))}
              multiline
              rows={4}
              fullWidth
              required
            />
            <FormControl fullWidth>
              <InputLabel>Category</InputLabel>
              <Select
                value={newFeature.category}
                onChange={(e) => setNewFeature(prev => ({ ...prev, category: e.target.value }))}
                label="Category"
              >
                <MenuItem value="general">General</MenuItem>
                <MenuItem value="ui-ux">UI/UX</MenuItem>
                <MenuItem value="performance">Performance</MenuItem>
                <MenuItem value="features">Features</MenuItem>
                <MenuItem value="security">Security</MenuItem>
                <MenuItem value="integration">Integration</MenuItem>
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Priority</InputLabel>
              <Select
                value={newFeature.priority}
                onChange={(e) => setNewFeature(prev => ({ ...prev, priority: e.target.value }))}
                label="Priority"
              >
                <MenuItem value="low">Low</MenuItem>
                <MenuItem value="medium">Medium</MenuItem>
                <MenuItem value="high">High</MenuItem>
              </Select>
            </FormControl>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setCreateDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleCreateFeature}
            variant="contained"
            disabled={!newFeature.title || !newFeature.description}
          >
            Create Feature
          </Button>
        </DialogActions>
      </Dialog>

      {/* Filter Dialog */}
      <Dialog 
        open={filterDialogOpen} 
        onClose={() => setFilterDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Filter Features</DialogTitle>
        <DialogContent>
          <Stack spacing={3} sx={{ mt: 1 }}>
            <FormControl fullWidth>
              <InputLabel>Status</InputLabel>
              <Select
                value={filters.status}
                onChange={(e) => setFilters(prev => ({ ...prev, status: e.target.value }))}
                label="Status"
              >
                <MenuItem value="">All</MenuItem>
                {Object.entries(STATUS_CONFIG).map(([key, config]) => (
                  <MenuItem key={key} value={key}>{config.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Priority</InputLabel>
              <Select
                value={filters.priority}
                onChange={(e) => setFilters(prev => ({ ...prev, priority: e.target.value }))}
                label="Priority"
              >
                <MenuItem value="">All</MenuItem>
                {Object.entries(PRIORITY_CONFIG).map(([key, config]) => (
                  <MenuItem key={key} value={key}>{config.label}</MenuItem>
                ))}
              </Select>
            </FormControl>
            <FormControl fullWidth>
              <InputLabel>Sort By</InputLabel>
              <Select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                label="Sort By"
              >
                <MenuItem value="vote_count">Vote Count</MenuItem>
                <MenuItem value="created_date">Date Created</MenuItem>
                <MenuItem value="title">Title</MenuItem>
                <MenuItem value="priority">Priority</MenuItem>
              </Select>
            </FormControl>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => {
            setFilters({ status: '', category: '', priority: '' });
            setSortBy('vote_count');
            setSortOrder('desc');
          }}>
            Reset
          </Button>
          <Button onClick={() => setFilterDialogOpen(false)} variant="contained">
            Apply
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={() => setSnackbar(prev => ({ ...prev, open: false }))}
      >
        <Alert 
          onClose={() => setSnackbar(prev => ({ ...prev, open: false }))} 
          severity={snackbar.severity}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default VotingGrid;

/**
 * GridStatsCards - Professional Stats Cards Component
 * Displays statistics cards for grids with proper positioning
 * 
 * @author Mounir Abderrahmani
 * @email mounir.ab@techno-dz.com
 */

import React from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Grid,
  Skeleton,
  useTheme,
  alpha
} from '@mui/material';
import {
  TrendingUp as TrendingUpIcon,
  TrendingDown as TrendingDownIcon,
  Remove as RemoveIcon
} from '@mui/icons-material';

import { useCustomTheme } from '../../../contexts/ThemeContext';
import { useLanguage } from '../../../contexts/LanguageContext';

const GridStatsCards = ({
  cards = [],
  loading = false,
  gridName = 'Grid',
  variant = 'default', // 'default' | 'compact' | 'detailed'
  showTrends = false,
  ...props
}) => {
  const theme = useTheme();
  const { density, colorPreset } = useCustomTheme();
  const { translate } = useLanguage();

  if (!cards || cards.length === 0) {
    return null;
  }

  const getCardColor = (color) => {
    const colors = {
      primary: theme.palette.primary.main,
      secondary: theme.palette.secondary.main,
      success: theme.palette.success.main,
      warning: theme.palette.warning.main,
      error: theme.palette.error.main,
      info: theme.palette.info.main
    };
    return colors[color] || theme.palette.primary.main;
  };

  const getTrendIcon = (trend) => {
    if (!trend || trend === 0) return <RemoveIcon />;
    return trend > 0 ? <TrendingUpIcon /> : <TrendingDownIcon />;
  };

  const getTrendColor = (trend) => {
    if (!trend || trend === 0) return 'text.secondary';
    return trend > 0 ? 'success.main' : 'error.main';
  };

  const formatValue = (value) => {
    if (typeof value === 'number') {
      return value.toLocaleString();
    }
    return value;
  };

  const cardHeight = density === 'compact' ? 80 : variant === 'detailed' ? 140 : 100;

  return (
    <Box
      sx={{
        width: '100%',
        mb: 1,
        flexShrink: 0
      }}
      {...props}
    >
      <Grid container spacing={density === 'compact' ? 1 : 2}>
        {cards.map((card, index) => {
          const cardColor = getCardColor(card.color);

          return (
            <Grid item xs={12} sm={6} md={3} key={index}>
              <Card
                sx={{
                  height: cardHeight,
                  display: 'flex',
                  flexDirection: 'column',
                  position: 'relative',
                  overflow: 'hidden',
                  borderRadius: density === 'compact' ? 1 : 2,
                  border: `1px solid ${alpha(cardColor, 0.2)}`,
                  '&:hover': {
                    boxShadow: theme.shadows[4],
                    transform: 'translateY(-2px)',
                    transition: 'all 0.2s ease-in-out'
                  }
                }}
              >
                {/* Color accent bar */}
                <Box
                  sx={{
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    right: 0,
                    height: 4,
                    backgroundColor: cardColor
                  }}
                />

                <CardContent
                  sx={{
                    flexGrow: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    justifyContent: 'center',
                    p: density === 'compact' ? 1 : 2,
                    '&:last-child': {
                      pb: density === 'compact' ? 1 : 2
                    }
                  }}
                >
                  {loading ? (
                    <>
                      <Skeleton variant="text" width="60%" height={20} />
                      <Skeleton variant="text" width="40%" height={32} />
                      {variant === 'detailed' && (
                        <Skeleton variant="text" width="80%" height={16} />
                      )}
                    </>
                  ) : (
                    <>
                      {/* Header */}
                      <Box
                        sx={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          mb: variant === 'compact' ? 0.5 : 1
                        }}
                      >
                        <Typography
                          variant={density === 'compact' ? 'caption' : 'body2'}
                          color="text.secondary"
                          sx={{
                            fontWeight: 500,
                            textTransform: 'uppercase',
                            letterSpacing: 0.5
                          }}
                        >
                          {translate(card.title) || card.title}
                        </Typography>

                        {card.icon && (
                          <Box
                            sx={{
                              color: cardColor,
                              display: 'flex',
                              alignItems: 'center'
                            }}
                          >
                            {React.createElement(card.icon, {
                              fontSize: density === 'compact' ? 'small' : 'medium'
                            })}
                          </Box>
                        )}
                      </Box>

                      {/* Value */}
                      <Typography
                        variant={density === 'compact' ? 'h6' : 'h5'}
                        component="div"
                        sx={{
                          fontWeight: 'bold',
                          color: 'text.primary',
                          lineHeight: 1.2
                        }}
                      >
                        {formatValue(card.value)}
                      </Typography>

                      {/* Trend and Description */}
                      {(showTrends || variant === 'detailed') && (
                        <Box
                          sx={{
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'space-between',
                            mt: 0.5
                          }}
                        >
                          {card.trend !== undefined && (
                            <Box
                              sx={{
                                display: 'flex',
                                alignItems: 'center',
                                color: getTrendColor(card.trend)
                              }}
                            >
                              {getTrendIcon(card.trend)}
                              <Typography
                                variant="caption"
                                sx={{ ml: 0.5 }}
                              >
                                {Math.abs(card.trend)}%
                              </Typography>
                            </Box>
                          )}

                          {card.description && variant === 'detailed' && (
                            <Typography
                              variant="caption"
                              color="text.secondary"
                              sx={{
                                textAlign: 'right',
                                maxWidth: '60%',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                                whiteSpace: 'nowrap'
                              }}
                            >
                              {translate(card.description) || card.description}
                            </Typography>
                          )}
                        </Box>
                      )}

                      {/* Additional info for detailed variant */}
                      {variant === 'detailed' && card.additionalInfo && (
                        <Typography
                          variant="caption"
                          color="text.secondary"
                          sx={{ mt: 1 }}
                        >
                          {translate(card.additionalInfo) || card.additionalInfo}
                        </Typography>
                      )}
                    </>
                  )}
                </CardContent>
              </Card>
            </Grid>
          );
        })}
      </Grid>
    </Box>
  );
};

export default GridStatsCards;

/**
 * GridToolbar - Professional Grid Toolbar Component
 * Unified toolbar system for all grids
 * 
 * @author Mounir Abderrahmani
 * @email mounir.ab@techno-dz.com
 */

import React, { useState, useCallback } from 'react';
import {
  Box,
  Toolbar,
  Typography,
  Button,
  IconButton,
  TextField,
  InputAdornment,
  Chip,
  Menu,
  MenuItem,
  Divider,
  Tooltip,
  Badge,
  CircularProgress
} from '@mui/material';
import {
  Search as SearchIcon,
  Refresh as RefreshIcon,
  FilterList as FilterIcon,
  ViewColumn as ColumnsIcon,
  Download as ExportIcon,
  Upload as ImportIcon,
  Add as AddIcon,
  Delete as DeleteIcon,
  Edit as EditIcon,
  MoreVert as MoreIcon
} from '@mui/icons-material';

import { useLanguage } from '../../../contexts/LanguageContext';
import { useCustomTheme } from '../../../contexts/ThemeContext';

const GridToolbar = ({
  gridName,
  config = {},
  customActions = [],
  contextMenuActions = [],
  selectedRows = [],
  onRefresh,
  loading = false,
  onSearch,
  onFilter,
  onExport,
  onImport,
  onAdd,
  onEdit,
  onDelete,
  ...props
}) => {
  const { translate } = useLanguage();
  const { density } = useCustomTheme();

  // State
  const [searchValue, setSearchValue] = useState('');
  const [anchorEl, setAnchorEl] = useState(null);
  const [filterAnchorEl, setFilterAnchorEl] = useState(null);

  // Default configuration
  const defaultConfig = {
    showSearch: true,
    showRefresh: true,
    showFilter: true,
    showColumns: true,
    showExport: true,
    showImport: false,
    showAdd: true,
    showEdit: true,
    showDelete: true,
    title: gridName
  };

  const finalConfig = { ...defaultConfig, ...config };

  // Event handlers
  const handleSearch = useCallback((value) => {
    setSearchValue(value);
    onSearch?.(value);
  }, [onSearch]);

  const handleRefresh = useCallback(() => {
    onRefresh?.();
  }, [onRefresh]);

  const handleMenuOpen = useCallback((event) => {
    setAnchorEl(event.currentTarget);
  }, []);

  const handleMenuClose = useCallback(() => {
    setAnchorEl(null);
  }, []);

  const handleFilterOpen = useCallback((event) => {
    setFilterAnchorEl(event.currentTarget);
  }, []);

  const handleFilterClose = useCallback(() => {
    setFilterAnchorEl(null);
  }, []);

  // Action handlers
  const handleAdd = useCallback(() => {
    onAdd?.();
  }, [onAdd]);

  const handleEdit = useCallback(() => {
    if (selectedRows.length === 1) {
      onEdit?.(selectedRows[0]);
    }
  }, [onEdit, selectedRows]);

  const handleDelete = useCallback(() => {
    if (selectedRows.length > 0) {
      onDelete?.(selectedRows);
    }
  }, [onDelete, selectedRows]);

  const handleExport = useCallback(() => {
    onExport?.();
  }, [onExport]);

  const handleImport = useCallback(() => {
    onImport?.();
  }, [onImport]);

  return (
    <Box
      sx={{
        borderBottom: 1,
        borderColor: 'divider',
        backgroundColor: 'background.paper'
      }}
    >
      <Toolbar
        variant={density === 'compact' ? 'dense' : 'regular'}
        sx={{
          gap: 1,
          minHeight: density === 'compact' ? 48 : 64
        }}
      >
        {/* Title */}
        <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
          {translate(finalConfig.title) || finalConfig.title}
          {selectedRows.length > 0 && (
            <Chip
              label={`${selectedRows.length} selected`}
              size="small"
              color="primary"
              sx={{ ml: 1 }}
            />
          )}
        </Typography>

        {/* Search */}
        {finalConfig.showSearch && (
          <TextField
            size="small"
            placeholder={translate('common.search') || 'Search...'}
            value={searchValue}
            onChange={(e) => handleSearch(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon />
                </InputAdornment>
              )
            }}
            sx={{ minWidth: 200 }}
          />
        )}

        {/* Primary Actions */}
        <Box sx={{ display: 'flex', gap: 1 }}>
          {/* Refresh */}
          {finalConfig.showRefresh && (
            <Tooltip title={translate('common.refresh') || 'Refresh'}>
              <IconButton
                onClick={handleRefresh}
                disabled={loading}
                size={density === 'compact' ? 'small' : 'medium'}
              >
                {loading ? (
                  <CircularProgress size={20} />
                ) : (
                  <RefreshIcon />
                )}
              </IconButton>
            </Tooltip>
          )}

          {/* Filter */}
          {finalConfig.showFilter && (
            <Tooltip title={translate('common.filter') || 'Filter'}>
              <IconButton
                onClick={handleFilterOpen}
                size={density === 'compact' ? 'small' : 'medium'}
              >
                <FilterIcon />
              </IconButton>
            </Tooltip>
          )}

          {/* Add */}
          {finalConfig.showAdd && (
            <Tooltip title={translate('common.add') || 'Add'}>
              <Button
                variant="contained"
                startIcon={<AddIcon />}
                onClick={handleAdd}
                size={density === 'compact' ? 'small' : 'medium'}
              >
                {translate('common.add') || 'Add'}
              </Button>
            </Tooltip>
          )}

          {/* Edit */}
          {finalConfig.showEdit && (
            <Tooltip title={translate('common.edit') || 'Edit'}>
              <IconButton
                onClick={handleEdit}
                disabled={selectedRows.length !== 1}
                size={density === 'compact' ? 'small' : 'medium'}
              >
                <EditIcon />
              </IconButton>
            </Tooltip>
          )}

          {/* Delete */}
          {finalConfig.showDelete && (
            <Tooltip title={translate('common.delete') || 'Delete'}>
              <IconButton
                onClick={handleDelete}
                disabled={selectedRows.length === 0}
                color="error"
                size={density === 'compact' ? 'small' : 'medium'}
              >
                <Badge badgeContent={selectedRows.length} color="error">
                  <DeleteIcon />
                </Badge>
              </IconButton>
            </Tooltip>
          )}
        </Box>

        {/* Secondary Actions Menu */}
        <Box>
          <Tooltip title={translate('common.moreActions') || 'More Actions'}>
            <IconButton
              onClick={handleMenuOpen}
              size={density === 'compact' ? 'small' : 'medium'}
            >
              <MoreIcon />
            </IconButton>
          </Tooltip>

          <Menu
            anchorEl={anchorEl}
            open={Boolean(anchorEl)}
            onClose={handleMenuClose}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
          >
            {/* Export */}
            {finalConfig.showExport && (
              <MenuItem onClick={() => { handleExport(); handleMenuClose(); }}>
                <ExportIcon sx={{ mr: 1 }} />
                {translate('common.export') || 'Export'}
              </MenuItem>
            )}

            {/* Import */}
            {finalConfig.showImport && (
              <MenuItem onClick={() => { handleImport(); handleMenuClose(); }}>
                <ImportIcon sx={{ mr: 1 }} />
                {translate('common.import') || 'Import'}
              </MenuItem>
            )}

            {/* Columns */}
            {finalConfig.showColumns && (
              <MenuItem onClick={handleMenuClose}>
                <ColumnsIcon sx={{ mr: 1 }} />
                {translate('common.columns') || 'Columns'}
              </MenuItem>
            )}

            {/* Custom Actions */}
            {customActions.length > 0 && (
              <>
                <Divider />
                {customActions.map((action, index) => (
                  <MenuItem
                    key={index}
                    onClick={() => {
                      action.onClick?.(selectedRows);
                      handleMenuClose();
                    }}
                    disabled={action.disabled}
                  >
                    {action.icon && <Box sx={{ mr: 1 }}>{action.icon}</Box>}
                    {action.label}
                  </MenuItem>
                ))}
              </>
            )}
          </Menu>
        </Box>
      </Toolbar>

      {/* Filter Menu */}
      <Menu
        anchorEl={filterAnchorEl}
        open={Boolean(filterAnchorEl)}
        onClose={handleFilterClose}
        transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }}
      >
        <MenuItem onClick={handleFilterClose}>
          <Typography variant="body2">
            {translate('common.filterOptions') || 'Filter options will be implemented here'}
          </Typography>
        </MenuItem>
      </Menu>
    </Box>
  );
};

export default GridToolbar;

import React, { useState, useCallback, useMemo, useEffect } from 'react';
import { Box } from '@mui/material';
import UnifiedGrid from '../../common/UnifiedGrid';
import categoryService from '../../../services/categoryService';
import { toast } from 'react-toastify';
import CategoryIcon from '@mui/icons-material/Category';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';
import KeyboardArrowDownIcon from '@mui/icons-material/KeyboardArrowDown';
import KeyboardArrowRightIcon from '@mui/icons-material/KeyboardArrowRight';
import { generateColumns, mergeColumns } from '../../../utils/gridUtils';
import { ColumnFactory } from '../../../utils/ColumnFactory';
import CategoryEditDialog from '../../dialogs/CategoryEditDialog';

/**
 * CategoryGrid Component
 * Displays category data in a tree-like grid format.
 */
const CategoryGrid = ({ productId }) => {
    // State management
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState([]);
    const [filters, setFilters] = useState({});
    const [expandedRows, setExpandedRows] = useState(new Set());
    const [stats, setStats] = useState({ total: 0, active: 0, inactive: 0 });

    // Edit dialog state
    const [editDialogOpen, setEditDialogOpen] = useState(false);
    const [selectedCategory, setSelectedCategory] = useState(null);

    // Memoize constant props
    const defaultPageSize = useMemo(() => 10, []);
    const pageSizeOptions = useMemo(() => [10, 25, 50, 100], []);

    // Toggle row expansion
    const handleRowExpand = useCallback((id) => {
        setExpandedRows(prev => {
            const newSet = new Set(prev);
            if (newSet.has(id)) {
                newSet.delete(id);
            } else {
                newSet.add(id);
            }
            return newSet;
        });
    }, []);

    // Update visible data when expansion state changes
    useEffect(() => {
        const visibleCategories = categoryService.getVisibleCategories(expandedRows);
        setData(visibleCategories);
    }, [expandedRows]);

    // Create tree column with expand/collapse functionality
    const createTreeColumn = useMemo(() => ({
        field: 'name',
        headerName: 'Category Name',
        flex: 1,
        sortable: true,
        renderCell: (params) => {
            const { row } = params;
            const isExpanded = expandedRows.has(row.id);
            const hasChildren = row.has_children;
            const level = row.level || 0;

            return (
                <Box sx={{ display: 'flex', alignItems: 'center', pl: level * 3, py: 0.5, width: '100%' }}>
                    {hasChildren ? (
                        <Box
                            component="span"
                            onClick={(e) => {
                                e.stopPropagation();
                                handleRowExpand(row.id);
                            }}
                            sx={{
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                cursor: 'pointer',
                                mr: 1,
                                width: 20,
                                height: 20,
                                borderRadius: '4px',
                                '&:hover': { backgroundColor: 'action.hover', color: 'primary.main' }
                            }}
                        >
                            {isExpanded ? <KeyboardArrowDownIcon fontSize="small" /> : <KeyboardArrowRightIcon fontSize="small" />}
                        </Box>
                    ) : (
                        <Box sx={{ width: 20, mr: 1 }} />
                    )}
                    <CategoryIcon fontSize="small" sx={{ mr: 1, color: level === 0 ? 'primary.main' : 'action.active', opacity: level === 0 ? 1 : 0.7 }} />
                    <Box component="span" sx={{ fontWeight: level === 0 ? 600 : 400, color: level === 0 ? 'primary.main' : 'text.primary', fontSize: level === 0 ? '0.95rem' : '0.875rem' }}>
                        {params.value || `Category ${row.originalId}`}
                    </Box>
                    {process.env.NODE_ENV === 'development' && (
                        <Box component="span" sx={{ ml: 1, px: 0.5, py: 0.25, backgroundColor: 'action.hover', borderRadius: '4px', fontSize: '0.75rem', color: 'text.secondary' }}>
                            L{level}
                        </Box>
                    )}
                </Box>
            );
        }
    }), [expandedRows, handleRowExpand]);

    // Grid columns configuration
    const visibleColumns = useMemo(() => [
        createTreeColumn,
        ColumnFactory.number('product_count', { headerName: 'Products', width: 120 }),
        ColumnFactory.number('position', { headerName: 'Position', width: 100 }),
        ColumnFactory.boolean('is_active', { headerName: 'Status', width: 120 })
    ], [createTreeColumn]);

    // Data fetching handler
    const handleRefresh = useCallback(async (params = {}) => {
        try {
            setLoading(true);
            const { filter = {} } = params;

            // Fetch, filter, and search categories via service
            const { categories, stats } = await categoryService.fetchAndProcessCategories({ ...filter, expandedRows });

            setData(categories);
            setStats(stats);

            // Dynamically expand root categories on initial load
            if (expandedRows.size === 0) {
                const rootCategoryIds = categoryService.getRootCategories().map(c => c.id);
                setExpandedRows(new Set(rootCategoryIds));
            }
        } catch (error) {
            toast.error(error.message || 'Failed to load categories');
        } finally {
            setLoading(false);
        }
    }, [expandedRows]);

    // Grid cards for stats display
    const gridCards = useMemo(() => [
        { key: 'total', title: 'Total Categories', value: stats.total, icon: CategoryIcon, color: 'primary' },
        { key: 'active', title: 'Active', value: stats.active, icon: VisibilityIcon, color: 'success' },
        { key: 'inactive', title: 'Inactive', value: stats.inactive, icon: VisibilityOffIcon, color: 'error' }
    ], [stats]);

    return (
        <Box>
            <UnifiedGrid
                gridName="CategoryGrid"
                columns={visibleColumns}
                data={data}
                loading={loading}
                enableCache
                enableI18n
                enableSelection
                enableSorting
                enableFiltering
                showStatsCards
                gridCards={gridCards}
                defaultPageSize={defaultPageSize}
                pageSizeOptions={pageSizeOptions}
                toolbarConfig={{
                    showRefresh: true,
                    showAdd: true,
                    showEdit: true,
                    showDelete: true,
                    showExport: true,
                    showSearch: true,
                    showFilters: true,
                    showSettings: true
                }}
                contextMenuActions={{
                    edit: {
                        enabled: true,
                        onClick: (rowData) => {
                            const category = categoryService.findCategoryById(rowData.id);
                            setSelectedCategory(category);
                            setEditDialogOpen(true);
                        }
                    },
                    delete: {
                        enabled: (rowData) => rowData.level > 1,
                        onClick: (rowData) => toast.info(`Deleting category: ${rowData.name} (Not implemented yet)`)
                    },
                    view: {
                        enabled: true,
                        onClick: (rowData) => {
                            const category = categoryService.findCategoryById(rowData.id);
                            setSelectedCategory(category);
                            setEditDialogOpen(true);
                        }
                    }
                }}
                enableFloatingActions={false}
                onRefresh={handleRefresh}
                onAdd={() => toast.info('Add category functionality coming soon')}
                onEdit={(rowData) => {
                    const category = categoryService.findCategoryById(rowData.id);
                    setSelectedCategory(category);
                    setEditDialogOpen(true);
                }}
                onDelete={(selectedRows) => toast.info(`Deleting ${selectedRows.length} categories`)}
                onExport={(selectedRows) => {
                    const exportData = selectedRows.length > 0 ? selectedRows : data;
                    toast.success(`Exported ${exportData.length} categories`);
                }}
                currentFilter={filters}
                onFilterChange={setFilters}
