  const [viewDialogOpen, setViewDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);

  // ===== 2. DATA FETCHING =====
  const fetchCustomers = useCallback(async (filterParams = {}) => {
    setLoading(true);
    try {
      // Get settings-aware API parameters
      const apiParams = getApiParams({
        pageSize: paginationModel.pageSize,
        currentPage: paginationModel.page + 1,
        ...filterParams
      });

      // Use settings-aware API method
      const response = await magentoApi.getCustomersWithSettings('magentoCustomers', apiParams);
      // Handle {data: {items: []}} response structure
      const customersData = response?.data || response;
      const customers = customersData?.items || [];
      setData(customers);

      // Calculate stats
      const totalCustomers = customers.length;
      const activeCustomers = customers.filter(c => c.is_active === 1).length;
      const inactiveCustomers = totalCustomers - activeCustomers;
      const totalOrders = customers.reduce((sum, c) => sum + (c.orders_count || 0), 0);

      setStats({
        totalCustomers,
        activeCustomers,
        inactiveCustomers,
        totalOrders
      });
    } catch (error) {
      // Use settings-aware error handling
      handleError(error, 'Load Customers');
      setData([]);
    } finally {
      setLoading(false);
    }
  }, [paginationModel, getApiParams, handleError]);

  // ===== 3. EVENT HANDLERS =====
  const handleView = useCallback((records) => {
    if (records.length === 1) {
      const customer = data.find(c => c.id === records[0]);
      setSelectedCustomer(customer);
      setViewDialogOpen(true);
    } else {
      toast.warning('Please select exactly one customer to view');
    }
  }, [data]);

  const handleEdit = useCallback((records) => {
    if (records.length === 1) {
      const customer = data.find(c => c.id === records[0]);
      setSelectedCustomer(customer);
      setEditDialogOpen(true);
