    },
    {
      label: 'Sync Customers',
      onClick: handleSync,
      icon: SyncIcon,
      color: 'secondary',
      variant: 'outlined'
    }
  ];

  // ===== 6. CONTEXT MENU ACTIONS =====
  const contextMenuActions = useMemo(() => ({
    view: {
      enabled: true,
