import { formatDateTime } from '../../../utils/formatters';

const EnhancedCmsPagesGrid = () => {
    // ===== SETTINGS INTEGRATION =====
    const { settings } = useSettings();
    const {
        paginationSettings,
        getApiParams,
        handleError
    } = useMagentoGridSettings('magentoCmsPages', {});
    
    // Apply user settings to API service
    useEffect(() => {
        import('../../../services/magentoApi').then(({ setMagentoApiSettings }) => {
            setMagentoApiSettings(settings);
        });
    }, [settings]);

    // Content type selection (Pages or Blocks)
    const [contentType, setContentType] = useState('pages'); // 'pages' or 'blocks'
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [openDialog, setOpenDialog] = useState(false);
    const [selectedItem, setSelectedItem] = useState(null);
    const [error, setError] = useState(null);
    const [activeTab, setActiveTab] = useState(0);
    const [previewMode, setPreviewMode] = useState(false);
    const [fullscreenEditor, setFullscreenEditor] = useState(false);
    const [paginationModel, setPaginationModel] = useState({ 
        page: 0, 
        pageSize: paginationSettings.defaultPageSize 
    });
    
    // Professional filtering system
    const [filters, setFilters] = useState({
        status: 'all', // all, active, inactive
        search: '',
        dateRange: 'all', // all, today, week, month, custom
        sortBy: 'creation_time',
        sortOrder: 'desc'
    });
    
    // Enhanced form data with SEO and scheduling
    const [formData, setFormData] = useState({
        title: '',
        identifier: '',
        content: '',
        is_active: true,
        meta_title: '',
        meta_description: '',
        meta_keywords: '',
        url_key: '',
        sort_order: 0,
        store_id: [0] // All store views by default
    });

    // Professional stats for cards
    const [stats, setStats] = useState({
        total: 0,
        active: 0,
        inactive: 0,
        recentlyModified: 0,
        totalViews: 0
    });

    // Enhanced data fetching with proper filtering to fix endpoint errors
    const fetchData = useCallback(async () => {
        setLoading(true);
        setError(null);

        try {
            console.log(`🔍 EnhancedCmsPagesGrid: Fetching CMS ${contentType}...`);
            
            // Get settings-aware API parameters
            const baseParams = getApiParams({
                pageSize: paginationModel.pageSize,
                currentPage: paginationModel.page + 1,
                sortOrders: [{ 
                    field: filters.sortBy, 
                    direction: filters.sortOrder.toUpperCase() 
                }]
            });

            // Build search criteria with proper field names to fix "%fieldName" error
            const searchCriteria = {
                ...baseParams,
                filterGroups: []
            };

            // Add status filter with proper field name
            if (filters.status !== 'all') {
                searchCriteria.filterGroups.push({
                    filters: [{
                        field: 'is_active',
                        value: filters.status === 'active' ? '1' : '0',
                        conditionType: 'eq'
                    }]
                });
            }

            // Add search filter with proper field names to prevent endpoint errors
            if (filters.search.trim()) {
                searchCriteria.filterGroups.push({
                    filters: [
                        {
                            field: 'title',
                            value: `%${filters.search}%`,
                            conditionType: 'like'
                        },
                        {
                            field: 'identifier', 
                            value: `%${filters.search}%`,
                            conditionType: 'like'
                        }
                    ]
                });
            }

            // Fetch data based on content type with settings-aware API calls
            let response;
            if (contentType === 'pages') {
                // Use settings-aware API method for CMS pages
                response = await magentoApi.getCmsPagesWithSettings('magentoCmsPages', searchCriteria);
            } else {
                // Use settings-aware API method for CMS blocks
                response = await magentoApi.callWithSettings('get', '/cmsBlock/search', 'magentoCmsPages', searchCriteria);
            }

            console.log(`📦 EnhancedCmsPagesGrid: ${contentType} response:`, response);

            // Handle response structure properly
            const cmsData = response?.data || response;
            const items = cmsData?.items || [];

            if (items.length > 0) {
                setData(items);
                
                // Update professional stats
                const activeCount = items.filter(item => item.is_active).length;
                setStats({
                    total: items.length,
                    active: activeCount,
                    inactive: items.length - activeCount,
                    recentlyModified: items.filter(item => {
                        const updateTime = new Date(item.update_time);
                        const dayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
                        return updateTime > dayAgo;
                    }).length,
                    totalViews: cmsData?.total_count || items.length
                });
                
                console.log(`✅ EnhancedCmsPagesGrid: Loaded ${items.length} ${contentType}`);
            } else {
                console.warn(`⚠️ No CMS ${contentType} found`);
                setData([]);
                setStats({ total: 0, active: 0, inactive: 0, recentlyModified: 0, totalViews: 0 });
            }
        } catch (error) {
            console.error(`❌ EnhancedCmsPagesGrid: Error fetching ${contentType}:`, error);
            setError(error.message || `Failed to fetch CMS ${contentType}`);
            setData([]);
            setStats({ total: 0, active: 0, inactive: 0, recentlyModified: 0, totalViews: 0 });
            // Use settings-aware error handling
            handleError(error, `Load CMS ${contentType}`);
        } finally {
            setLoading(false);
        }
    }, [contentType, filters, paginationModel, getApiParams, handleError]);

    // Filter handlers
    const handleFilterChange = useCallback((key, value) => {
        setFilters(prev => ({ ...prev, [key]: value }));
    }, []);

    const handleClearFilters = useCallback(() => {
        setFilters({
            status: 'all',
            search: '',
            dateRange: 'all',
            sortBy: 'creation_time',
            sortOrder: 'desc'
        });
    }, []);

    // Content type handler
    const handleContentTypeChange = useCallback((newType) => {
        setContentType(newType);
        setData([]);
        setStats({ total: 0, active: 0, inactive: 0, recentlyModified: 0, totalViews: 0 });
    }, []);

    // Enhanced Quill editor configuration for Magento-friendly HTML
    const quillModules = useMemo(() => ({
        toolbar: {
            container: [
                [{ 'header': [1, 2, 3, 4, 5, 6, false] }],
                ['bold', 'italic', 'underline', 'strike'],
                [{ 'color': [] }, { 'background': [] }],
                [{ 'font': [] }],
                [{ 'align': [] }],
                [{ 'list': 'ordered'}, { 'list': 'bullet' }],
                [{ 'indent': '-1'}, { 'indent': '+1' }],
                ['blockquote', 'code-block'],
                ['link', 'image', 'video'],
                ['clean'],
                ['fullscreen']
            ],
            handlers: {
                'fullscreen': () => setFullscreenEditor(!fullscreenEditor)
            }
        },
        clipboard: {
            matchVisual: false,
        }
    }), [fullscreenEditor]);

    const quillFormats = [
        'header', 'font', 'size',
        'bold', 'italic', 'underline', 'strike', 'blockquote',
        'list', 'bullet', 'indent',
        'link', 'image', 'video',
        'color', 'background', 'align'
    ];

    // Professional stats cards configuration
    const statsCards = useMemo(() => [
        {
            title: `Total ${contentType === 'pages' ? 'Pages' : 'Blocks'}`,
            value: stats.total,
            icon: contentType === 'pages' ? <Article /> : <ViewModule />,
            color: 'primary',
            trend: stats.total > 0 ? '+' : ''
        },
        {
            title: 'Active',
            value: stats.active,
            icon: <Visibility />,
            color: 'success',
            percentage: stats.total > 0 ? Math.round((stats.active / stats.total) * 100) : 0
        },
        {
            title: 'Inactive',
            value: stats.inactive,
            icon: <Article />,
            color: 'warning',
            percentage: stats.total > 0 ? Math.round((stats.inactive / stats.total) * 100) : 0
        },
        {
            title: 'Recently Modified',
            value: stats.recentlyModified,
            icon: <Schedule />,
            color: 'info',
            subtitle: 'Last 24 hours'
        }
    ], [contentType, stats]);

    // Professional columns configuration
    const columns = useMemo(() => [
        {
            field: 'id',
            headerName: 'ID',
            width: 80,
            type: 'number'
        },
        {
            field: 'title',
            headerName: 'Title',
            width: 250,
            flex: 1,
            renderCell: (params) => (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Typography variant="body2" sx={{ fontWeight: 500 }}>
                        {params.value}
                    </Typography>
                </Box>
            )
        },
        {
            field: 'identifier',
            headerName: 'Identifier',
            width: 200,
            renderCell: (params) => (
                <Chip 
                    label={params.value} 
                    size="small" 
                    variant="outlined" 
                    color="primary"
                />
            )
        },
        {
            field: 'is_active',
            headerName: 'Status',
            width: 120,
            renderCell: (params) => (
                <Chip
                    label={params.value ? 'Active' : 'Inactive'}
                    color={params.value ? 'success' : 'default'}
                    size="small"
                    icon={params.value ? <Visibility /> : <Article />}
                />
            )
        },
        {
            field: 'creation_time',
            headerName: 'Created',
            width: 150,
            renderCell: (params) => (
                <Typography variant="body2">
                    {formatDateTime(params.value)}
                </Typography>
            )
        },
        {
            field: 'update_time',
            headerName: 'Modified',
            width: 150,
            renderCell: (params) => (
                <Typography variant="body2">
                    {formatDateTime(params.value)}
                </Typography>
            )
        },
        {
            field: 'actions',
            headerName: 'Actions',
            width: 120,
            sortable: false,
            renderCell: (params) => (
                <Box sx={{ display: 'flex', gap: 0.5 }}>
                    <Tooltip title="Edit">
                        <IconButton size="small" onClick={() => handleOpenDialog(params.row)}>
                            <Edit fontSize="small" />
                        </IconButton>
                    </Tooltip>
                    <Tooltip title="Preview">
                        <IconButton size="small" onClick={() => handlePreview(params.row)}>
                            <Preview fontSize="small" />
                        </IconButton>
                    </Tooltip>
                </Box>
            )
        }
    ], []);

    // Dialog handlers
    const handleOpenDialog = useCallback((item = null) => {
        setSelectedItem(item);
        setFormData(item ? {
            title: item.title || '',
            identifier: item.identifier || '',
            content: item.content || '',
            is_active: item.is_active || true,
            meta_title: item.meta_title || '',
            meta_description: item.meta_description || '',
            meta_keywords: item.meta_keywords || '',
            url_key: item.url_key || '',
            sort_order: item.sort_order || 0,
            store_id: item.store_id || [0]
        } : {
            title: '',
            identifier: '',
            content: '',
            is_active: true,
            meta_title: '',
            meta_description: '',
            meta_keywords: '',
            url_key: '',
            sort_order: 0,
            store_id: [0]
        });
        setOpenDialog(true);
        setActiveTab(0);
    }, []);

    const handleCloseDialog = useCallback(() => {
        setOpenDialog(false);
        setSelectedItem(null);
        setActiveTab(0);
        setPreviewMode(false);
        setFullscreenEditor(false);
    }, []);

    const handlePreview = useCallback((item) => {
        setSelectedItem(item);
        setPreviewMode(true);
        setOpenDialog(true);
    }, []);

    // Enhanced save functionality for POST and PUT operations
    const handleSave = useCallback(async () => {
        try {
            if (!formData.title || !formData.identifier) {
                toast.error('Title and Identifier are required');
                return;
            }

            const payload = {
                title: formData.title,
                identifier: formData.identifier,
                content: formData.content,
                is_active: formData.is_active,
                meta_title: formData.meta_title,
                meta_description: formData.meta_description,
                meta_keywords: formData.meta_keywords,
                url_key: formData.url_key,
                sort_order: formData.sort_order,
                store_id: formData.store_id
            };

            if (selectedItem) {
                // UPDATE existing item
                if (contentType === 'pages') {
                    await magentoApi.put(`/cmsPage/${selectedItem.id}`, { page: payload });
                    toast.success('CMS Page updated successfully');
                } else {
                    await magentoApi.put(`/cmsBlock/${selectedItem.id}`, { block: payload });
                    toast.success('CMS Block updated successfully');
                }
            } else {
                // CREATE new item (always POST to Magento API)
                if (contentType === 'pages') {
                    await magentoApi.post('/cmsPage', { page: payload });
                    toast.success('CMS Page created successfully');
                } else {
                    await magentoApi.post('/cmsBlock', { block: payload });
                    toast.success('CMS Block created successfully');
                }
            }

            handleCloseDialog();
            fetchData(); // Refresh the grid
        } catch (error) {
            console.error('Save error:', error);
            toast.error(`Failed to save CMS ${contentType.slice(0, -1)}: ${error.message}`);
        }
    }, [formData, selectedItem, contentType, handleCloseDialog, fetchData]);

    // Enhanced delete functionality
    const handleDelete = useCallback(async (id) => {
        if (!window.confirm(`Are you sure you want to delete this ${contentType.slice(0, -1)}?`)) {
            return;
        }

        try {
            if (contentType === 'pages') {
                await magentoApi.delete(`/cmsPage/${id}`);
                toast.success('CMS Page deleted successfully');
            } else {
                await magentoApi.delete(`/cmsBlock/${id}`);
                toast.success('CMS Block deleted successfully');
            }
            fetchData(); // Refresh the grid
        } catch (error) {
            console.error('Delete error:', error);
            toast.error(`Failed to delete CMS ${contentType.slice(0, -1)}: ${error.message}`);
        }
    }, [contentType, fetchData]);

    // Form change handler
    const handleFormChange = useCallback((field, value) => {
        setFormData(prev => ({ ...prev, [field]: value }));
    }, []);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    // ===== RENDER =====
    return (
        <Box sx={{ p: 3, height: '100%', display: 'flex', flexDirection: 'column' }}>
            {/* Professional Header with Content Type Toggle */}
            <Box sx={{ mb: 3 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                    <Typography variant="h4" sx={{ fontWeight: 600 }}>
                        CMS {contentType === 'pages' ? 'Pages' : 'Blocks'} Management
                    </Typography>

                    {/* Content Type Toggle */}
                    <ButtonGroup variant="outlined" size="large">
                        <Button
                            variant={contentType === 'pages' ? 'contained' : 'outlined'}
                            onClick={() => handleContentTypeChange('pages')}
                            startIcon={<Article />}
                        >
                            Pages
                        </Button>
                        <Button
                            variant={contentType === 'blocks' ? 'contained' : 'outlined'}
                            onClick={() => handleContentTypeChange('blocks')}
                            startIcon={<ViewModule />}
                        >
                            Blocks
                        </Button>
                    </ButtonGroup>
                </Box>

                {/* Professional Stats Cards */}
                <Grid container spacing={2} sx={{ mb: 3 }}>
                    {statsCards.map((card, index) => (
                        <Grid item xs={12} sm={6} md={3} key={index}>
                            <Card sx={{
                                background: `linear-gradient(135deg, ${card.color === 'primary' ? '#1976d2' :
                                    card.color === 'success' ? '#2e7d32' :
                                    card.color === 'warning' ? '#ed6c02' : '#0288d1'} 0%, ${
                                    card.color === 'primary' ? '#42a5f5' :
                                    card.color === 'success' ? '#66bb6a' :
                                    card.color === 'warning' ? '#ffb74d' : '#29b6f6'} 100%)`,
                                color: 'white',
                                height: 120
                            }}>
                                {/* Fix validateDOMNesting: Replace nested Typography <p> with <span> or <div> */}
                                {/* CardContent area */}
                                <CardContent sx={{ p: 2 }}>
                                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                        <Box>
                                            <Typography variant="h4" sx={{ fontWeight: 700, mb: 0.5 }} component="div">
                                                {card.value}
                                            </Typography>
                                            <Typography variant="body2" sx={{ opacity: 0.9 }} component="div">
                                                {card.title}
                                            </Typography>
                                            {card.subtitle && (
                                                <Typography variant="caption" sx={{ opacity: 0.8 }} component="div">
                                                    {card.subtitle}
                                                </Typography>
                                            )}
                                        </Box>
                                        <Box sx={{ opacity: 0.8 }}>
                                            {card.icon}
                                        </Box>
                                    </Box>
                                    {card.percentage !== undefined && (
                                        <Typography variant="caption" sx={{ opacity: 0.9 }} component="div">
                                            {card.percentage}% of total
                                        </Typography>
                                    )}
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>
            </Box>

            {error && (
                <Alert severity="error" sx={{ mb: 2 }}>
                    {error}
                </Alert>
            )}

            {/* Enhanced UnifiedGrid */}
            <UnifiedGrid
                {...getStandardGridProps(contentType === 'pages' ? 'cmsPages' : 'cmsBlocks', {
                    // Data
                    data,
                    columns,
                    loading,

                    // Grid identification
                    gridName: `Cms${contentType === 'pages' ? 'Pages' : 'Blocks'}Grid`,

                    // Configuration
                    toolbarConfig: getStandardToolbarConfig(contentType === 'pages' ? 'cmsPages' : 'cmsBlocks'),

                    // Event handlers
                    onRowDoubleClick: (params) => handleOpenDialog(params.row),
                    onRefresh: fetchData,
                    onAdd: () => handleOpenDialog(),
                    onEdit: (items) => items.length === 1 && handleOpenDialog(data.find(item => item.id === items[0])),
                    onDelete: (items) => items.forEach(id => handleDelete(id)),

                    // Grid styling
                    sx: {
                        flexGrow: 1,
                        '& .MuiDataGrid-cell': {
                            borderBottom: '1px solid #e0e0e0'
                        },
                        '& .MuiDataGrid-row:hover': {
                            backgroundColor: 'rgba(25, 118, 210, 0.04)'
                        }
                    }
                })}
            />

            {/* Dialog for Editing CMS Page/Block */}
            <Dialog open={openDialog} onClose={handleCloseDialog} maxWidth="md" fullWidth>
                <DialogTitle>{selectedItem ? `Edit ${contentType === 'pages' ? 'Page' : 'Block'}` : `Add ${contentType === 'pages' ? 'Page' : 'Block'}`}</DialogTitle>
                <DialogContent>
                    <Tabs value={activeTab} onChange={(_, v) => setActiveTab(v)} sx={{ mb: 2 }}>
                        <Tab label="General" />
                        <Tab label="Content" />
                        <Tab label="SEO" />
                        <Tab label="Advanced" />
                    </Tabs>
                    {activeTab === 0 && (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                            <TextField label="Title" value={formData.title} onChange={e => handleFormChange('title', e.target.value)} fullWidth required />
                            <TextField label="Identifier" value={formData.identifier} onChange={e => handleFormChange('identifier', e.target.value)} fullWidth required />
                            <FormControlLabel control={<Switch checked={formData.is_active} onChange={e => handleFormChange('is_active', e.target.checked)} />} label="Active" />
                        </Box>
                    )}
                    {activeTab === 1 && (
                        <Box sx={{ mt: 2 }}>
                            <ReactQuill theme="snow" value={formData.content} onChange={v => handleFormChange('content', v)} modules={quillModules} formats={quillFormats} style={{ minHeight: 200 }} />
                        </Box>
                    )}
                    {activeTab === 2 && (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                            <TextField label="Meta Title" value={formData.meta_title} onChange={e => handleFormChange('meta_title', e.target.value)} fullWidth />
                            <TextField label="Meta Description" value={formData.meta_description} onChange={e => handleFormChange('meta_description', e.target.value)} fullWidth />
                            <TextField label="Meta Keywords" value={formData.meta_keywords} onChange={e => handleFormChange('meta_keywords', e.target.value)} fullWidth />
                        </Box>
                    )}
                    {activeTab === 3 && (
                        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2, mt: 2 }}>
                            <TextField label="URL Key" value={formData.url_key} onChange={e => handleFormChange('url_key', e.target.value)} fullWidth />
                            <TextField label="Sort Order" type="number" value={formData.sort_order} onChange={e => handleFormChange('sort_order', Number(e.target.value))} fullWidth />
                            <TextField label="Store IDs (comma separated)" value={formData.store_id ? formData.store_id.join(',') : ''} onChange={e => handleFormChange('store_id', e.target.value.split(',').map(v => v.trim()).filter(Boolean))} fullWidth />
                        </Box>
                    )}
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleCloseDialog}>Cancel</Button>
                    <Button onClick={handleSave} variant="contained">Save</Button>
                </DialogActions>
            </Dialog>

            {/* Fix findDOMNode warning: ensure refs are attached directly to DOM elements, not React components */}
            {/* Fix validateDOMNesting warning: avoid <p> inside <p> in Typography */}
            {/* 1. Replace all <Typography component="p"> or default <Typography> (which renders <p>) inside another <Typography> or <p> with <span> or <div>. */}
            {/* 2. Check all refs passed to ReactQuill, UnifiedGrid, or other components and ensure they are attached to DOM elements, not React components. */}
        </Box>
    );
};

export default EnhancedCmsPagesGrid;

import { useState, useCallback, useMemo, useEffect } from 'react';
import { Box } from '@mui/material';
import { toast } from 'react-toastify';
import { useSettings } from '../../../contexts/SettingsContext';
import { useMagentoGridSettings } from '../../../hooks/useMagentoGridSettings';

// Icons
import ReceiptIcon from '@mui/icons-material/Receipt';
import PaidIcon from '@mui/icons-material/Paid';
import PendingIcon from '@mui/icons-material/Pending';

// Unified Grid System
import UnifiedGrid from '../../common/UnifiedGrid';
import { getStandardGridProps, getStandardToolbarConfig, getStandardContextMenuActions } from '../../../config/gridConfig';
import { ColumnFactory } from '../../../utils/ColumnFactory.jsx';

// Services and Utils
import magentoApi from '../../../services/magentoApi';
import { formatCurrency, formatDateTime } from '../../../utils/formatters';
import { generateColumns } from '../../../utils/gridUtils';

/**
 * InvoiceGrid Component
 * Displays invoice data in a grid format with status cards
 * Enhanced with settings-aware configuration and API calls
 */
const InvoicesGrid = ({ orderId }) => {
    // ===== SETTINGS INTEGRATION =====
    const { settings } = useSettings();
    const {
        paginationSettings,
        getApiParams,
        handleError
    } = useMagentoGridSettings('magentoInvoices', {});
    
    // Apply user settings to API service
    useEffect(() => {
        import('../../../services/magentoApi').then(({ setMagentoApiSettings }) => {
            setMagentoApiSettings(settings);
        });
    }, [settings]);

    // State management
    const [loading, setLoading] = useState(false);
    const [data, setData] = useState([]);
    const [filters, setFilters] = useState({});
    const [stats, setStats] = useState({
        total: 0,
        paid: 0,
        pending: 0
    });
    const [paginationModel, setPaginationModel] = useState({ 
        page: 0, 
        pageSize: paginationSettings.defaultPageSize 
    });

    // Grid columns configuration
    const columns = useMemo(() => [
        ColumnFactory.text('increment_id', {
            headerName: 'Invoice #',
            width: 130
        }),
        ColumnFactory.text('order_id', {
            headerName: 'Order #',
            width: 130
        }),
        ColumnFactory.currency('grand_total', {
            headerName: 'Total',
            width: 130,
            currency: 'USD'
        }),
        ColumnFactory.status('state', {
            headerName: 'Status',
            width: 130,
            valueOptions: ['paid', 'pending', 'canceled'],
            statusColors: {
                paid: 'success',
                pending: 'warning',
                canceled: 'error'
            }
        }),
        ColumnFactory.dateTime('created_at', {
            headerName: 'Invoice Date',
            width: 180
        })
    ], []);

    // Data fetching handler with settings integration
    const handleRefresh = useCallback(async ({ page, pageSize, filter }) => {
        try {
            setLoading(true);
            
            // Get settings-aware API parameters
            const baseParams = getApiParams({
                pageSize: pageSize || paginationModel.pageSize,
                currentPage: (page || paginationModel.page) + 1
            });

            const searchCriteria = {
                ...baseParams,
                filterGroups: []
            };

            if (orderId) {
                searchCriteria.filterGroups.push({
                    filters: [{
                        field: 'order_id',
                        value: orderId,
                        condition_type: 'eq'
                    }]
                });
            }

            if (filter?.state) {
                searchCriteria.filterGroups.push({
                    filters: [{
                        field: 'state',
                        value: filter.state,
                        condition_type: 'eq'
                    }]
                });
            }

            // Use settings-aware API method
            const response = await magentoApi.getInvoicesWithSettings('magentoInvoices', searchCriteria);
            // Handle {data: {items: []}} response structure
            const invoicesData = response?.data || response;
            const items = invoicesData?.items || [];
            setData(items);
            updateStats(items);
        } catch (error) {
            // Use settings-aware error handling
            handleError(error, 'Load Invoices');
            throw error;
        } finally {
            setLoading(false);
        }
    }, [orderId, paginationModel, getApiParams, handleError]);

    // Update invoice statistics
    const updateStats = useCallback((invoices) => {
        const newStats = invoices.reduce((acc, invoice) => ({
            total: acc.total + 1,
            paid: acc.paid + (invoice.state === 'paid' ? 1 : 0),
            pending: acc.pending + (invoice.state === 'pending' ? 1 : 0)
        }), {
            total: 0,
            paid: 0,
            pending: 0
        });
        setStats(newStats);
    }, []);

    return (
         <UnifiedGrid
                {...getStandardGridProps('magentoOrders', {
                    gridName: "InvoicesGrid",
                    columns,
                    data,
                    loading,

                    // Event handlers
                    onRowDoubleClick: (params) => {
                        console.log('Invoice double-clicked:', params.row);
                    },

                    // Configuration
                    toolbarConfig: getStandardToolbarConfig('magentoOrders'),

                    // Stats
                    showStatsCards: true,
                    gridCards: [
                        {
                            title: 'Total Invoices',
                            value: stats.total,
                            icon: ReceiptIcon,
                            color: 'primary'
                        },
                        {
                            title: 'Paid',
                            value: stats.paid,
                            icon: PaidIcon,
                            color: 'success'
                        },
                        {
                            title: 'Pending',
                            value: stats.pending,
                            icon: PendingIcon,
                            color: 'warning'
                        }
                    ],

                    // Configuration
                    contextMenuActions: getStandardContextMenuActions('magentoOrders', {
                        view: {
                            enabled: true,
                            onClick: (rowData) => {
                                console.log('Viewing invoice:', rowData);
                                toast.info(`Viewing invoice: ${rowData.increment_id}`);
                            }
                        }
                    }),

                    // Event handlers
                    onRefresh: () => {
                        console.log('Refreshing invoices...');
                        toast.info('Refreshing invoices...');
                    },
                    onExport: (selectedRows) => {
                        const exportData = selectedRows.length > 0
                            ? data.filter(invoice => selectedRows.includes(invoice.increment_id))
                            : data;
                        console.log('Exporting invoices:', exportData);
                        toast.success(`Exported ${exportData.length} invoices`);
                    },

                    // Floating actions
                    enableFloatingActions: false,
                    floatingActions: {
                        export: {
