// Modern Base Components
import BaseGrid from '../../base/BaseGrid';
import BaseDialog from '../../base/BaseDialog';
import ErrorBoundary from '../../common/ErrorBoundary';
import { SuspenseWrapper } from '../../common/SuspenseWrapper';

// Other Components
import ProductAttributesGrid from './ProductAttributesGrid';
import ProductCategoriesGrid from './ProductCategoriesGrid';
import BrandManagementDialog from '../../dialogs/BrandManagementDialog';
import TooltipWrapper from '../../common/TooltipWrapper';
import { ColumnFactory } from '../../../utils/ColumnFactory.jsx';

// Services
import magentoApi from '../../../services/magentoApi';

/**
 * ProductManagementGrid - Modern React 18 Product Management
 * 
 * Features:
 * - BaseGrid integration with React 18 patterns
 * - Enhanced state management with useTransition
 * - Comprehensive product, attributes, and categories management
 * - Modern error boundaries and suspense handling
 * - Optimized performance with memoization
 * 
 * @author Techno-ETL Team
 * @version 2.0.0
 */
const ProductManagementGrid = memo(({ initialProductIds = [] }) => {
  // ===== REACT 18 HOOKS =====
  const gridId = useId();
  const [isPending, startTransition] = useTransition();
  const [currentTab, setCurrentTab] = useState(0);
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState([]);
  const [selectedProducts, setSelectedProducts] = useState(initialProductIds);
  const [productDetailOpen, setProductDetailOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [brandManagementOpen, setBrandManagementOpen] = useState(false);
  const [stats, setStats] = useState({
    total: 0,
    active: 0,
    inactive: 0,
    withCategories: 0
  });

  // ===== FILTER STATE =====
  const [filters, setFilters] = useState({
    brand: '',
    status: '',
    type: '',
    priceRange: { min: '', max: '' }
  });

  // ===== FLOATING WINDOWS STATE =====
  const [floatingWindows, setFloatingWindows] = useState({
    quickActions: { open: false, anchorEl: null },
    bulkOperations: { open: false, anchorEl: null },
    dataManagement: { open: false, anchorEl: null },
    settings: { open: false, anchorEl: null }
  });

  // ===== MANUAL REFRESH STATE =====
  const [refreshing, setRefreshing] = useState({
    attributes: false,
    categories: false,
    brands: false
  });

  // ===== FLOATING WINDOW HANDLERS =====
  const openFloatingWindow = useCallback((windowType, event) => {
    setFloatingWindows(prev => ({
      ...prev,
      [windowType]: { open: true, anchorEl: event.currentTarget }
    }));
  }, []);

  const closeFloatingWindow = useCallback((windowType) => {
    setFloatingWindows(prev => ({
      ...prev,
      [windowType]: { open: false, anchorEl: null }
    }));
  }, []);

  const closeAllFloatingWindows = useCallback(() => {
    setFloatingWindows({
      quickActions: { open: false, anchorEl: null },
      bulkOperations: { open: false, anchorEl: null },
      dataManagement: { open: false, anchorEl: null },
      settings: { open: false, anchorEl: null }
    });
  }, []);

  // ===== MANUAL REFRESH HANDLERS =====
  const handleManualRefresh = useCallback(async (type) => {
    setRefreshing(prev => ({ ...prev, [type]: true }));

    try {
      switch (type) {
        case 'attributes':
          await magentoApi.getProductAttributes();
          toast.success('Attributes refreshed successfully');
          break;
        case 'categories':
          await magentoApi.getCategories();
          toast.success('Categories refreshed successfully');
          break;
        case 'brands':
          await magentoApi.getBrands();
          toast.success('Brands refreshed successfully');
          break;
        default:
          break;
      }
    } catch (error) {
      console.error(`Error refreshing ${type}:`, error);
      toast.error(`Failed to refresh ${type}`);
    } finally {
      setRefreshing(prev => ({ ...prev, [type]: false }));
    }
  }, []);
  const [brands, setBrands] = useState([]);
  const [brandsLoading, setBrandsLoading] = useState(false);

  // ===== TAB CONFIGURATION =====
  const tabs = [
    {
      label: 'Products Overview',
      icon: <ProductIcon />,
      component: 'products'
    },
    {
      label: 'Product Attributes',
      icon: <AttributeIcon />,
      component: 'attributes'
    },
    {
      label: 'Category Assignment',
      icon: <CategoryIcon />,
      component: 'categories'
    }
  ];

  // ===== PRODUCT COLUMNS =====
  const productColumns = useMemo(() => [
    ColumnFactory.text('id', { 
      headerName: 'ID', 
      width: 100,
      renderCell: (params) => (
        <Typography variant="body2" fontFamily="monospace" color="primary">
          {params.value}
        </Typography>
      )
    }),
    ColumnFactory.text('sku', { 
      headerName: 'SKU', 
      width: 150,
      renderCell: (params) => (
        <Typography variant="body2" fontWeight="medium">
          {params.value}
        </Typography>
      )
    }),
    ColumnFactory.text('name', { 
      headerName: 'Product Name', 
      flex: 1
    }),
    ColumnFactory.currency('price', {
      headerName: 'Price',
      width: 120
    }),
    {
      field: 'brand',
      headerName: 'Brand',
      width: 120,
      renderCell: (params) => (
        <Chip
          label={params.value || 'Unknown'}
          color={params.value && params.value !== 'Unknown' ? 'primary' : 'default'}
          size="small"
          variant="outlined"
          icon={<BrandIcon />}
        />
      )
    },
    {
      field: 'status',
      headerName: 'Status',
      width: 100,
      renderCell: (params) => (
        <Chip
          label={params.value === 1 ? 'Active' : 'Inactive'}
          color={params.value === 1 ? 'success' : 'default'}
          size="small"
        />
      )
    },
    {
      field: 'type_id',
      headerName: 'Type',
      width: 120,
      renderCell: (params) => (
        <Chip
          label={params.value || 'Simple'}
          color="info"
          size="small"
          variant="outlined"
        />
      )
    },
    {
      field: 'actions',
      headerName: 'Actions',
      width: 150,
      sortable: false,
      filterable: false,
      renderCell: (params) => (
        <Box sx={{ display: 'flex', gap: 0.5 }}>
          <TooltipWrapper title="View Details">
            <IconButton
              size="small"
              onClick={() => handleViewProduct(params.row)}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </TooltipWrapper>
          <TooltipWrapper title="Edit Product">
            <IconButton
              size="small"
              onClick={() => handleEditProduct(params.row)}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </TooltipWrapper>
          <TooltipWrapper title="Manage Categories">
            <IconButton
              size="small"
              onClick={() => handleManageCategories(params.row)}
            >
              <AssignmentIcon fontSize="small" />
            </IconButton>
          </TooltipWrapper>
        </Box>
      )
    }
  ], []);

  // ===== BRANDS FETCHING =====
  const fetchBrands = useCallback(async () => {
    try {
      setBrandsLoading(true);
      console.log('🔄 Fetching brands for filters...');

      const response = await magentoApi.getBrands();
      const brandsData = response?.items || [];

      // Sort brands alphabetically
      const sortedBrands = brandsData.sort((a, b) => a.label.localeCompare(b.label));
      setBrands(sortedBrands);

      console.log('✅ Brands loaded for filters:', sortedBrands.length);
    } catch (error) {
      console.error('❌ Error fetching brands:', error);
      toast.error('Failed to load brands');
    } finally {
      setBrandsLoading(false);
    }
  }, []);

  // ===== DATA FETCHING =====
  const fetchProducts = useCallback(async (params = {}) => {
    try {
      setLoading(true);
      console.log('🔄 Fetching products...', params, 'Filters:', filters);

      let productsData = [];

      if (selectedProducts.length > 0) {
        // Fetch specific products
        console.log('📦 Fetching specific products:', selectedProducts);
        productsData = await Promise.all(
          selectedProducts.map(async (id) => {
            try {
              const product = await magentoApi.getProduct(id);
              // Get additional attributes including brand
              const additionalAttrs = await magentoApi.getAdditionalAttributes(id);

              return {
                ...product,
                additional_attributes: additionalAttrs?.additional_attributes || [],
                brand: additionalAttrs?.additional_attributes?.find(attr => attr.attribute_code === 'mgs_brand')?.label || 'Unknown'
              } || {
                id,
                sku: `PRODUCT-${id}`,
                name: `Product ${id}`,
                price: 0,
                status: 1,
                type_id: 'simple',
                brand: 'Unknown',
                additional_attributes: []
              };
            } catch (error) {
              console.warn(`Failed to fetch product ${id}:`, error);
              return {
                id,
                sku: `PRODUCT-${id}`,
                name: `Product ${id}`,
                price: 0,
                status: 1,
                type_id: 'simple',
                brand: 'Unknown',
                additional_attributes: []
              };
            }
          })
        );
      } else {
        // Fetch all products
        const response = await magentoApi.getProducts(params);
        productsData = response?.items || [];

        // Enhance with additional attributes
        productsData = await Promise.all(
          productsData.map(async (product) => {
            try {
              const additionalAttrs = await magentoApi.getAdditionalAttributes(product.id);
              return {
                ...product,
                additional_attributes: additionalAttrs?.additional_attributes || [],
                brand: additionalAttrs?.additional_attributes?.find(attr => attr.attribute_code === 'mgs_brand')?.label || 'Unknown'
              };
            } catch (error) {
              return {
                ...product,
                brand: 'Unknown',
                additional_attributes: []
              };
            }
          })
        );
      }

      // Apply filters
      const filteredProducts = applyFilters(productsData);
      setProducts(filteredProducts);
      updateStats(filteredProducts);

    } catch (error) {
      console.error('❌ Error fetching products:', error);
      toast.error('Failed to load products');
    } finally {
      setLoading(false);
    }
  }, [selectedProducts, filters]);

  // ===== FILTERING LOGIC =====
  const applyFilters = useCallback((productsData) => {
    return productsData.filter(product => {
      // Brand filter
      if (filters.brand && product.brand !== filters.brand) {
        return false;
      }

      // Status filter
      if (filters.status !== '' && product.status.toString() !== filters.status) {
        return false;
      }

      // Type filter
      if (filters.type && product.type_id !== filters.type) {
        return false;
      }

      // Price range filter
      if (filters.priceRange.min && product.price < parseFloat(filters.priceRange.min)) {
        return false;
      }
      if (filters.priceRange.max && product.price > parseFloat(filters.priceRange.max)) {
        return false;
      }

      return true;
    });
  }, [filters]);

  // ===== STATISTICS UPDATE =====
  const updateStats = useCallback((productsData) => {
    const newStats = productsData.reduce((acc, product) => ({
      total: acc.total + 1,
      active: acc.active + (product.status === 1 ? 1 : 0),
      inactive: acc.inactive + (product.status !== 1 ? 1 : 0),
      withCategories: acc.withCategories + (product.categories?.length > 0 ? 1 : 0)
    }), {
      total: 0,
      active: 0,
      inactive: 0,
      withCategories: 0
    });
    setStats(newStats);
  }, []);

  // ===== ENHANCED EVENT HANDLERS FOR BASEGRID =====
  const handleAddProduct = useCallback(async (data) => {
    try {
      console.log('🆕 Adding new product:', data);
      const newProduct = await magentoApi.createProduct(data);
      toast.success('Product created successfully');
      fetchProducts(); // Refresh the grid
      return newProduct;
    } catch (error) {
      console.error('❌ Error creating product:', error);
      toast.error('Failed to create product');
      throw error;
    }
  }, [fetchProducts]);

  const handleEditProduct = useCallback(async (data) => {
    try {
      console.log('✏️ Editing product:', data);
      const updatedProduct = await magentoApi.updateProduct(data.id, data);
      toast.success('Product updated successfully');
      fetchProducts(); // Refresh the grid
      return updatedProduct;
    } catch (error) {
      console.error('❌ Error updating product:', error);
      toast.error('Failed to update product');
      throw error;
    }
  }, [fetchProducts]);

  const handleDeleteProducts = useCallback(async (productIds) => {
    try {
      console.log('🗑️ Deleting products:', productIds);
      await Promise.all(
        productIds.map(id => magentoApi.deleteProduct(id))
      );
      toast.success(`${productIds.length} product(s) deleted successfully`);
      fetchProducts(); // Refresh the grid
    } catch (error) {
      console.error('❌ Error deleting products:', error);
      toast.error('Failed to delete products');
      throw error;
    }
  }, [fetchProducts]);

  const handleSearchProducts = useCallback((query) => {
    console.log('🔍 Searching products:', query);
    // Search is handled by BaseGrid internally
  }, []);

  const handleSelectionChange = useCallback((selection) => {
    startTransition(() => {
      setSelectedProducts(selection);
    });
  }, []);

  const handleGridError = useCallback((error) => {
    console.error('🚨 Product Management Grid Error:', error);
    toast.error('Error in product management grid');
  }, []);

  // ===== ADDITIONAL EVENT HANDLERS =====
  const handleTabChange = useCallback((event, newValue) => {
    startTransition(() => {
      setCurrentTab(newValue);
    });
  }, []);

  const handleViewProduct = useCallback((product) => {
    console.log('👁️ Viewing product:', product);
    setSelectedProduct(product);
    setProductDetailOpen(true);
  }, []);

  const handleManageCategories = useCallback(() => {
    if (selectedProducts.length === 0) {
      toast.warning('Please select products first');
      return;
    }
    console.log('📂 Managing categories for products:', selectedProducts);
    setCurrentTab(2); // Switch to categories tab
  }, [selectedProducts]);

  // ===== FILTER HANDLERS =====
  const handleFilterChange = useCallback((filterType, value) => {
    setFilters(prev => ({
      ...prev,
      [filterType]: value
    }));
  }, []);

  const handlePriceRangeChange = useCallback((type, value) => {
    setFilters(prev => ({
      ...prev,
      priceRange: {
        ...prev.priceRange,
        [type]: value
      }
    }));
  }, []);

  const handleClearFilters = useCallback(() => {
    setFilters({
      brand: '',
      status: '',
      type: '',
      priceRange: { min: '', max: '' }
    });
  }, []);

  // ===== BRAND MANAGEMENT HANDLERS =====
  const handleOpenBrandManagement = useCallback(() => {
    setBrandManagementOpen(true);
  }, []);

  const handleBrandsUpdated = useCallback(() => {
    // Refresh brands list
    fetchBrands();
    // Refresh products to get updated brand data
    fetchProducts();
  }, [fetchBrands, fetchProducts]);

  // ===== EFFECTS =====
  useEffect(() => {
    fetchBrands();
    fetchProducts();
  }, [fetchBrands, fetchProducts]);

  // Re-fetch products when filters change
  useEffect(() => {
    if (brands.length > 0) { // Only fetch after brands are loaded
      fetchProducts();
    }
  }, [filters, fetchProducts, brands.length]);

  // ===== RENDER TAB CONTENT =====
  const renderTabContent = useCallback(() => {
    switch (currentTab) {
      case 0: // Products Overview
        return (
          <ErrorBoundary>
            <Suspense fallback={<Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}><CircularProgress /></Box>}>
              <BaseGrid
                gridName="ProductManagementGrid"
                columns={productColumns}
                data={products}
                loading={loading}
                
                // API Configuration
                apiService={magentoApi}
                apiEndpoint="products"
                apiParams={{}}
                
                // Feature Configuration
                enableSuspense={true}
                enableErrorBoundary={true}
                enableVirtualization={true}
                enableSelection={true}
                enableSorting={true}
                enableFiltering={true}
                enableSearch={true}
                enableStats={true}
                enableActions={true}
                
                // Toolbar Configuration
                toolbarConfig={{
                  showRefresh: true,
                  showAdd: true,
                  showEdit: true,
                  showDelete: true,
                  showExport: true,
                  showImport: true,
                  showSearch: true,
                  showFilters: true,
                  compact: false
                }}
                
                // Stats Configuration
                statsConfig={{
                  stats: [
                    {
                      key: 'total',
                      title: 'Total Products',
                      color: 'primary',
                      icon: ProductIcon
                    },
                    {
                      key: 'active',
                      title: 'Active',
                      color: 'success',
                      icon: SettingsIcon
                    },
                    {
                      key: 'inactive',
                      title: 'Inactive',
                      color: 'warning',
                      icon: SettingsIcon
                    },
                    {
                      key: 'withCategories',
                      title: 'With Categories',
                      color: 'info',
                      icon: CategoryIcon
                    }
                  ]
                }}
                
                // Dialog Configuration
                dialogConfig={{
                  add: {
                    title: 'Add New Product',
                    fields: [
                      { key: 'sku', label: 'SKU', required: true },
                      { key: 'name', label: 'Product Name', required: true },
                      { key: 'price', label: 'Price', type: 'number' },
                      { key: 'status', label: 'Status', type: 'select' }
                    ]
                  },
                  edit: {
                    title: 'Edit Product',
                    fields: [
                      { key: 'sku', label: 'SKU', disabled: true },
                      { key: 'name', label: 'Product Name', required: true },
                      { key: 'price', label: 'Price', type: 'number' },
                      { key: 'status', label: 'Status', type: 'select' }
                    ]
                  },
                  delete: {
                    title: 'Delete Products',
                    confirmMessage: 'Are you sure you want to delete the selected products?'
                  }
                }}
                
                // Event Handlers
                onRefresh={fetchProducts}
                onAdd={handleAddProduct}
                onEdit={handleEditProduct}
                onDelete={handleDeleteProducts}
                onSearch={handleSearchProducts}
                onSelectionChange={handleSelectionChange}
                onError={handleGridError}
                
                // Data Configuration
                searchFields={['name', 'sku', 'brand']}
                getRowId={(row) => row.id}
                
                // Custom Actions
                customActions={[
                  {
                    key: 'manage-categories',
                    label: 'Manage Categories',
                    icon: CategoryIcon,
                    color: 'primary',
                    requiresSelection: true,
                    onClick: handleManageCategories
                  },
                  {
                    key: 'manage-brands',
                    label: 'Manage Brands',
                    icon: BrandIcon,
                    color: 'secondary',
                    onClick: handleOpenBrandManagement
                  }
                ]}
                
                // Style
                sx={{ height: '100%' }}
              />
            </Suspense>
          </ErrorBoundary>
        );

      case 1: // Product Attributes
        return <ProductAttributesGrid />;

      case 2: // Category Assignment
        return <ProductCategoriesGrid productIds={selectedProducts} />;

      default:
        return null;
    }
  }, [currentTab, productColumns, products, loading, fetchProducts, handleAddProduct, handleEditProduct, handleDeleteProducts, handleSearchProducts, handleSelectionChange, handleGridError, selectedProducts, handleManageCategories, handleOpenBrandManagement]);

  return (
    <Box sx={{ height: '100%', display: 'flex', flexDirection: 'column' }}>
      {/* Header */}
      <Paper sx={{ mb: 2, p: 2 }}>
        <Typography variant="h5" gutterBottom>
          Product Management System
        </Typography>
        <Typography variant="body2" color="text.secondary">
          Comprehensive product, attributes, and categories management like Magento backend
        </Typography>
        
        {/* Selected Products Info */}
        {selectedProducts.length > 0 && (
          <Alert severity="info" sx={{ mt: 2 }}>
            <Typography variant="body2">
              Working with {selectedProducts.length} selected products: {selectedProducts.join(', ')}
            </Typography>
          </Alert>
        )}
      </Paper>

      {/* Built-in Filters */}
      {currentTab === 0 && (
        <Card sx={{ mb: 2 }}>
          <CardContent>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <FilterIcon color="primary" />
                <Typography variant="h6">
                  Product Filters
                </Typography>
              </Box>
              <Box sx={{ display: 'flex', gap: 1 }}>
                <Button
                  variant="outlined"
                  size="small"
                  startIcon={<BrandIcon />}
                  onClick={handleOpenBrandManagement}
                >
                  Manage Brands
                </Button>
                <Button
                  variant="outlined"
                  size="small"
                  startIcon={<ClearIcon />}
                  onClick={handleClearFilters}
                  disabled={!Object.values(filters).some(v => v !== '' && !(typeof v === 'object' && !v.min && !v.max))}
                >
                  Clear Filters
                </Button>
              </Box>
            </Box>

            <Grid container spacing={2}>
              {/* Brand Filter */}
              <Grid item xs={12} sm={6} md={3}>
                <FormControl fullWidth size="small">
                  <InputLabel>Brand</InputLabel>
                  <Select
                    value={filters.brand}
                    onChange={(e) => handleFilterChange('brand', e.target.value)}
                    label="Brand"
                    disabled={brandsLoading}
                  >
                    <MenuItem value="">All Brands</MenuItem>
                    {brands.map((brand) => (
                      <MenuItem key={brand.value} value={brand.label}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <BrandIcon fontSize="small" />
                          {brand.label}
                        </Box>
                      </MenuItem>
                    ))}
                  </Select>
                </FormControl>
              </Grid>

              {/* Status Filter */}
              <Grid item xs={12} sm={6} md={2}>
                <FormControl fullWidth size="small">
                  <InputLabel>Status</InputLabel>
                  <Select
                    value={filters.status}
                    onChange={(e) => handleFilterChange('status', e.target.value)}
                    label="Status"
                  >
                    <MenuItem value="">All Status</MenuItem>
                    <MenuItem value="1">Active</MenuItem>
                    <MenuItem value="0">Inactive</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              {/* Type Filter */}
              <Grid item xs={12} sm={6} md={2}>
                <FormControl fullWidth size="small">
                  <InputLabel>Type</InputLabel>
                  <Select
                    value={filters.type}
                    onChange={(e) => handleFilterChange('type', e.target.value)}
                    label="Type"
                  >
                    <MenuItem value="">All Types</MenuItem>
                    <MenuItem value="simple">Simple</MenuItem>
                    <MenuItem value="configurable">Configurable</MenuItem>
                    <MenuItem value="grouped">Grouped</MenuItem>
                    <MenuItem value="virtual">Virtual</MenuItem>
                    <MenuItem value="bundle">Bundle</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              {/* Price Range */}
              <Grid item xs={12} sm={6} md={2}>
                <TextField
                  label="Min Price"
                  type="number"
                  size="small"
                  fullWidth
                  value={filters.priceRange.min}
                  onChange={(e) => handlePriceRangeChange('min', e.target.value)}
                />
              </Grid>
              <Grid item xs={12} sm={6} md={2}>
                <TextField
                  label="Max Price"
                  type="number"
                  size="small"
                  fullWidth
                  value={filters.priceRange.max}
                  onChange={(e) => handlePriceRangeChange('max', e.target.value)}
                />
              </Grid>

              {/* Active Filters Display */}
              <Grid item xs={12}>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mt: 1 }}>
                  {filters.brand && (
                    <Chip
                      label={`Brand: ${filters.brand}`}
                      onDelete={() => handleFilterChange('brand', '')}
                      color="primary"
                      size="small"
                    />
                  )}
                  {filters.status !== '' && (
                    <Chip
                      label={`Status: ${filters.status === '1' ? 'Active' : 'Inactive'}`}
                      onDelete={() => handleFilterChange('status', '')}
                      color="primary"
                      size="small"
                    />
                  )}
                  {filters.type && (
                    <Chip
                      label={`Type: ${filters.type}`}
                      onDelete={() => handleFilterChange('type', '')}
                      color="primary"
                      size="small"
                    />
                  )}
                  {(filters.priceRange.min || filters.priceRange.max) && (
                    <Chip
                      label={`Price: ${filters.priceRange.min || '0'} - ${filters.priceRange.max || '∞'}`}
                      onDelete={() => handlePriceRangeChange('min', '') || handlePriceRangeChange('max', '')}
                      color="primary"
                      size="small"
                    />
                  )}
                </Box>
              </Grid>
            </Grid>
          </CardContent>
        </Card>
      )}

      {/* Tabs */}
      <Paper sx={{ mb: 2 }}>
        <Tabs
          value={currentTab}
          onChange={handleTabChange}
          variant="fullWidth"
          indicatorColor="primary"
          textColor="primary"
        >
          {tabs.map((tab, index) => (
            <Tab
              key={index}
              label={tab.label}
              icon={tab.icon}
              iconPosition="start"
            />
          ))}
        </Tabs>
      </Paper>

      {/* Tab Content */}
      <Box sx={{ flexGrow: 1, overflow: 'hidden' }}>
        {renderTabContent()}
      </Box>

      {/* Product Detail Dialog using BaseDialog */}
      <BaseDialog
        type="form"
        open={productDetailOpen}
        onClose={() => setProductDetailOpen(false)}
        title={`Product Details: ${selectedProduct?.name || ''}`}
        maxWidth="md"
        fields={[
          { key: 'id', label: 'Product ID', disabled: true },
          { key: 'sku', label: 'SKU', disabled: true },
          { key: 'name', label: 'Product Name', disabled: true },
          { key: 'price', label: 'Price', type: 'number', disabled: true },
          { key: 'status', label: 'Status', disabled: true },
          { key: 'type_id', label: 'Type', disabled: true },
          { key: 'brand', label: 'Brand', disabled: true }
        ]}
        data={selectedProduct || {}}
        config={{
          title: `Product Details: ${selectedProduct?.name || ''}`,
          submitLabel: 'Edit Product',
          submitColor: 'primary'
        }}
        onSubmit={async (data) => {
          // Handle edit action
          console.log('Edit product:', data);
          toast.info('Edit functionality to be implemented');
        }}
      />

      {/* Brand Management Dialog */}
      <BrandManagementDialog
        open={brandManagementOpen}
        onClose={() => setBrandManagementOpen(false)}
        onBrandsUpdated={handleBrandsUpdated}
      />

      {/* Floating Action Buttons */}
      <Box sx={{ position: 'fixed', bottom: 24, right: 24, zIndex: 1000 }}>
        <Stack spacing={2}>
          {/* Quick Actions FAB */}
          <TooltipWrapper title="Quick Actions" placement="left">
            <Fab
              color="primary"
              size="medium"
              onClick={(e) => openFloatingWindow('quickActions', e)}
            >
              <AddIcon />
            </Fab>
          </TooltipWrapper>

          {/* Bulk Operations FAB */}
          <TooltipWrapper 
            title="Bulk Operations" 
            placement="left"
            disabled={selectedProducts.length === 0}
          >
            <Fab
              color="secondary"
              size="medium"
              onClick={(e) => openFloatingWindow('bulkOperations', e)}
              disabled={selectedProducts.length === 0}
            >
              <SettingsIcon />
            </Fab>
          </TooltipWrapper>

          {/* Data Management FAB */}
          <TooltipWrapper title="Data Management" placement="left">
            <Fab
              color="info"
              size="medium"
              onClick={(e) => openFloatingWindow('dataManagement', e)}
            >
              <RefreshIcon />
            </Fab>
          </TooltipWrapper>
        </Stack>
      </Box>

      {/* Quick Actions Popover */}
      <Popover
        open={floatingWindows.quickActions.open}
        anchorEl={floatingWindows.quickActions.anchorEl}
        onClose={() => closeFloatingWindow('quickActions')}
        anchorOrigin={{ vertical: 'center', horizontal: 'left' }}
        transformOrigin={{ vertical: 'center', horizontal: 'right' }}
      >
        <Paper sx={{ p: 2, minWidth: 250 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
            <Typography variant="h6">Quick Actions</Typography>
            <IconButton size="small" onClick={() => closeFloatingWindow('quickActions')}>
              <CloseIcon />
            </IconButton>
          </Box>
          <List dense>
            <ListItem button onClick={() => { /* Add Product */ closeFloatingWindow('quickActions'); }}>
              <ListItemIcon><AddIcon /></ListItemIcon>
              <ListItemText primary="Add Product" />
            </ListItem>
            <ListItem button onClick={() => { /* Import CSV */ closeFloatingWindow('quickActions'); }}>
              <ListItemIcon><UploadIcon /></ListItemIcon>
              <ListItemText primary="Import CSV" />
            </ListItem>
            <ListItem button onClick={() => { /* Export Data */ closeFloatingWindow('quickActions'); }}>
              <ListItemIcon><DownloadIcon /></ListItemIcon>
              <ListItemText primary="Export Data" />
            </ListItem>
            <ListItem button onClick={() => { /* Sync All */ closeFloatingWindow('quickActions'); }}>
              <ListItemIcon><SyncIcon /></ListItemIcon>
              <ListItemText primary="Sync All" />
            </ListItem>
          </List>
        </Paper>
      </Popover>

      {/* Bulk Operations Popover */}
      <Popover
        open={floatingWindows.bulkOperations.open}
        anchorEl={floatingWindows.bulkOperations.anchorEl}
        onClose={() => closeFloatingWindow('bulkOperations')}
        anchorOrigin={{ vertical: 'center', horizontal: 'left' }}
        transformOrigin={{ vertical: 'center', horizontal: 'right' }}
      >
        <Paper sx={{ p: 2, minWidth: 250 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
            <Typography variant="h6">Bulk Operations</Typography>
            <IconButton size="small" onClick={() => closeFloatingWindow('bulkOperations')}>
              <CloseIcon />
            </IconButton>
          </Box>
          <Alert severity="info" sx={{ mb: 2 }}>
            {selectedProducts.length} products selected
          </Alert>
          <List dense>
            <ListItem button onClick={() => { /* Bulk Activate */ closeFloatingWindow('bulkOperations'); }}>
              <ListItemIcon><ActivateIcon color="success" /></ListItemIcon>
              <ListItemText primary="Activate Selected" />
            </ListItem>
            <ListItem button onClick={() => { /* Bulk Deactivate */ closeFloatingWindow('bulkOperations'); }}>
              <ListItemIcon><DeactivateIcon color="error" /></ListItemIcon>
              <ListItemText primary="Deactivate Selected" />
            </ListItem>
            <ListItem button onClick={() => { /* Assign Categories */ closeFloatingWindow('bulkOperations'); }}>
              <ListItemIcon><CategoryIcon /></ListItemIcon>
              <ListItemText primary="Assign Categories" />
            </ListItem>
            <ListItem button onClick={() => { /* Update Attributes */ closeFloatingWindow('bulkOperations'); }}>
              <ListItemIcon><AttributeIcon /></ListItemIcon>
              <ListItemText primary="Update Attributes" />
            </ListItem>
          </List>
        </Paper>
      </Popover>

      {/* Data Management Popover */}
      <Popover
        open={floatingWindows.dataManagement.open}
        anchorEl={floatingWindows.dataManagement.anchorEl}
        onClose={() => closeFloatingWindow('dataManagement')}
        anchorOrigin={{ vertical: 'center', horizontal: 'left' }}
        transformOrigin={{ vertical: 'center', horizontal: 'right' }}
      >
        <Paper sx={{ p: 2, minWidth: 280 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
            <Typography variant="h6">Data Management</Typography>
            <IconButton size="small" onClick={() => closeFloatingWindow('dataManagement')}>
              <CloseIcon />
            </IconButton>
          </Box>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Manually refresh data from Magento
          </Typography>
          <List dense>
            <ListItem
              button
              onClick={() => { handleManualRefresh('attributes'); closeFloatingWindow('dataManagement'); }}
              disabled={refreshing.attributes}
            >
              <ListItemIcon>
                {refreshing.attributes ? <CircularProgress size={20} /> : <AttributeIcon />}
              </ListItemIcon>
              <ListItemText primary="Refresh Attributes" />
            </ListItem>
            <ListItem
              button
              onClick={() => { handleManualRefresh('categories'); closeFloatingWindow('dataManagement'); }}
              disabled={refreshing.categories}
            >
              <ListItemIcon>
                {refreshing.categories ? <CircularProgress size={20} /> : <CategoryIcon />}
              </ListItemIcon>
              <ListItemText primary="Refresh Categories" />
            </ListItem>
            <ListItem
              button
              onClick={() => { handleManualRefresh('brands'); closeFloatingWindow('dataManagement'); }}
              disabled={refreshing.brands}
            >
              <ListItemIcon>
                {refreshing.brands ? <CircularProgress size={20} /> : <BrandIcon />}
              </ListItemIcon>
              <ListItemText primary="Refresh Brands" />
            </ListItem>
          </List>
        </Paper>
      </Popover>
    </Box>
  );
});

// Set display name for debugging
ProductManagementGrid.displayName = 'ProductManagementGrid';

export default ProductManagementGrid;

/**
 * ProductsGrid - Professional Magento Products Management Grid
 *
 * Features:
 * - Local products management with sync functionality
 * - Segmented add button with multiple import options
 * - Smart sync button (enabled only when local products exist)
 * - Professional UI with proper state management
 * - Optimized performance with memoization
 *
 * @author Techno-ETL Team
 * @version 2.0.0
 */

import { useState, useCallback, useMemo, useEffect } from 'react';
import { toast } from 'react-toastify';

// Unified Grid System
import UnifiedGrid from '../../common/UnifiedGrid';
import { getStandardGridProps, getStandardToolbarConfig } from '../../../config/gridConfig';

// Settings Context
import { useSettings } from '../../../contexts/SettingsContext';
import { useMagentoGridSettings } from '../../../hooks/useMagentoGridSettings';

// Column System
import { ColumnFactory } from '../../../utils/ColumnFactory.jsx';

// Services
import magentoApi from '../../../services/magentoApi';
import ProductService from '../../../services/ProductService';
import categoryService from '../../../services/categoryService';

// Dialogs
import CSVImportDialog from '../../dialogs/CSVImportDialog';
import CatalogProcessorDialog from '../../dialogs/CatalogProcessorDialog';
import ProductInfoDialog from '../../common/ProductInfoDialog';
import ProductEditDialog from '../../dialogs/ProductEditDialog';
import BulkMediaUploadDialog from '../../dialogs/BulkMediaUploadDialog';

/**
 * Optimized Magento Products Grid Component
 * Features:
 * - Better error handling and validation
 * - Optimized data fetching
 * - Improved performance with memoization
 * - Enhanced user feedback
 * - Settings-aware configuration and API calls
 */
const ProductsGrid = () => {
  // ===== SETTINGS INTEGRATION =====
  const { settings } = useSettings();
  const {
    paginationSettings,
    getApiParams,
    handleError,
    savePreferences
  } = useMagentoGridSettings('magentoProducts', {});
  
  // Apply user settings to API service
  useEffect(() => {
    import('../../../services/magentoApi').then(({ setMagentoApiSettings }) => {
      setMagentoApiSettings(settings);
    });
  }, [settings]);
  
  // ===== STATE =====
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState({
    total: 0,
    active: 0,
    inactive: 0,
    localProducts: 0,
    syncedProducts: 0
  });
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [infoDialogOpen, setInfoDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [bulkMediaDialogOpen, setBulkMediaDialogOpen] = useState(false);
  const [csvImportOpen, setCsvImportOpen] = useState(false);
  const [catalogProcessorOpen, setCatalogProcessorOpen] = useState(false);
  const [localProducts] = useState([]);
  const [paginationModel, setPaginationModel] = useState({ 
    page: 0, 
    pageSize: paginationSettings.defaultPageSize 
  });
  const [categoryFilter, setCategoryFilter] = useState('');
  const [brandFilter, setBrandFilter] = useState('');
  const [categories, setCategories] = useState([]);
  const [brands, setBrands] = useState([]);

  // ===== OPTIMIZED COLUMNS =====
  const columns = useMemo(() => [
    // Essential Product Information
    ColumnFactory.text('sku', {
      headerName: 'SKU',
      width: 140,
      pinned: 'left'
    }),
    ColumnFactory.text('name', {
      headerName: 'Product Name',
      flex: 1,
      minWidth: 300,
      renderCell: (params) => (
        <div style={{
          whiteSpace: 'normal',
          wordWrap: 'break-word',
          lineHeight: '1.2',
          padding: '4px 0'
        }}>
          {params.value}
        </div>
      )
    }),

    // Techno Reference (from custom_attributes)
    ColumnFactory.text('techno_ref', {
      headerName: 'Techno Ref',
      width: 120,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return '-';
          const technoRef = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'techno_ref'
          );
          return technoRef?.value || '-';
        } catch (error) {
          console.warn('Error getting techno_ref:', error);
          return '-';
        }
      }
    }),

    // Status with proper mapping
    ColumnFactory.status('status', {
      headerName: 'Status',
      width: 100,
      valueGetter: (params) => params.row.status === 1 ? 'enabled' : 'disabled',
      statusColors: {
        enabled: 'success',
        disabled: 'error'
      }
    }),

    // Price
    ColumnFactory.currency('price', {
      headerName: 'Price',
      width: 100,
      valueFormatter: (params) => `${params.value || 0} DA`
    }),

    // Weight
    ColumnFactory.number('weight', {
      headerName: 'Weight (g)',
      width: 110,
      valueFormatter: (params) => params.value ? `${params.value}g` : '-'
    }),

    // Product Type
    ColumnFactory.text('type_id', {
      headerName: 'Type',
      width: 100,
      valueFormatter: (params) => params.value?.toUpperCase() || 'SIMPLE'
    }),

    // Brand (from custom_attributes)
    ColumnFactory.text('brand', {
      headerName: 'Brand',
      width: 120,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return '-';
          const brand = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'mgs_brand'
          );
          return brand?.value || '-';
        } catch (error) {
          console.warn('Error getting brand:', error);
          return '-';
        }
      }
    }),

    // Country of Manufacture
    ColumnFactory.text('country', {
      headerName: 'Country',
      width: 80,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return '-';
          const country = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'country_of_manufacture'
          );
          return country?.value || '-';
        } catch (error) {
          console.warn('Error getting country:', error);
          return '-';
        }
      }
    }),

    // Categories (Multi-select display)
    ColumnFactory.text('categories', {
      headerName: 'Categories',
      width: 200,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return [];

          const categoryIds = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'category_ids'
          )?.value || [];

          return Array.isArray(categoryIds) ? categoryIds : [];
        } catch (error) {
          console.warn('Error getting category IDs:', error);
          return [];
        }
      },
      renderCell: (params) => {
        try {
          const categoryIds = params.value || [];

          if (!Array.isArray(categoryIds) || categoryIds.length === 0) {
            return <span style={{ color: '#999', fontSize: '0.75rem' }}>No categories</span>;
          }

          const categoryNames = categoryIds.slice(0, 2).map(id => {
            try {
              const category = categories.find(cat => cat.id.toString() === id.toString());
              return category ? category.name : `ID:${id}`;
            } catch (error) {
              console.warn('Error finding category:', error);
              return `ID:${id}`;
            }
          });

          return (
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '2px' }}>
              {categoryNames.map((name, index) => (
                <span
                  key={index}
                  style={{
                    fontSize: '0.75rem',
                    backgroundColor: '#e3f2fd',
                    color: '#1976d2',
                    padding: '2px 6px',
                    borderRadius: '4px',
                    whiteSpace: 'nowrap'
                  }}
                >
                  {name}
                </span>
              ))}
              {categoryIds.length > 2 && (
                <span style={{ fontSize: '0.75rem', color: '#666' }}>
                  +{categoryIds.length - 2} more
                </span>
              )}
            </div>
          );
        } catch (error) {
          console.warn('Error rendering categories:', error);
          return <span style={{ color: '#f44336', fontSize: '0.75rem' }}>Error</span>;
        }
      }
    }),

    // Boolean Attributes with standardized renderers
    ColumnFactory.boolean('trending', {
      headerName: 'Trending',
      width: 90,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return false;
          const trending = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'trending'
          );
          return trending?.value === '1' || trending?.value === true;
        } catch (error) {
          console.warn('Error getting trending value:', error);
          return false;
        }
      },
      renderCell: (params) => (
        <span style={{
          color: params.value ? '#4caf50' : '#999',
          fontWeight: params.value ? 'bold' : 'normal',
          fontSize: '0.875rem'
        }}>
          {params.value ? '✓' : '✗'}
        </span>
      )
    }),

    ColumnFactory.boolean('best_seller', {
      headerName: 'Best Seller',
      width: 100,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return false;
          const bestSeller = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'best_seller'
          );
          return bestSeller?.value === '1' || bestSeller?.value === true;
        } catch (error) {
          console.warn('Error getting best_seller value:', error);
          return false;
        }
      },
      renderCell: (params) => (
        <span style={{
          color: params.value ? '#ff9800' : '#999',
          fontWeight: params.value ? 'bold' : 'normal',
          fontSize: '0.875rem'
        }}>
          {params.value ? '⭐' : '✗'}
        </span>
      )
    }),

    ColumnFactory.boolean('a_la_une', {
      headerName: 'À la Une',
      width: 90,
      valueGetter: (params) => {
        try {
          if (!params?.row?.custom_attributes) return false;
          const alaune = params.row.custom_attributes.find(
            attr => attr.attribute_code === 'a_la_une'
          );
          return alaune?.value === '1' || alaune?.value === true;
        } catch (error) {
          console.warn('Error getting a_la_une value:', error);
          return false;
        }
      },
      renderCell: (params) => (
        <span style={{
          color: params.value ? '#e91e63' : '#999',
          fontWeight: params.value ? 'bold' : 'normal',
          fontSize: '0.875rem'
        }}>
          {params.value ? '🔥' : '✗'}
        </span>
      )
    }),

    // Created Date
    ColumnFactory.dateTime('created_at', {
      headerName: 'Created',
      width: 140,
      valueFormatter: (params) => {
        if (!params.value) return '-';
        return new Date(params.value).toLocaleDateString('fr-FR', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric'
        });
      }
    }),

    // Updated Date
    ColumnFactory.dateTime('updated_at', {
      headerName: 'Updated',
      width: 140,
      valueFormatter: (params) => {
        if (!params.value) return '-';
        return new Date(params.value).toLocaleDateString('fr-FR', {
          day: '2-digit',
          month: '2-digit',
          year: 'numeric'
        });
      }
    }),

    // Actions
    ColumnFactory.actions('actions', {
      headerName: 'Actions',
      width: 120,
      pinned: 'right',
      getActions: (params) => [
        {
          icon: 'edit',
          label: 'Edit Product',
          onClick: () => handleEdit(params.row)
        },
        {
          icon: 'visibility',
          label: 'View Details',
          onClick: () => handleViewDetails(params.row)
        },
        {
          icon: 'category',
          label: 'Categories',
          onClick: () => handleCategoryAssignment(params.row)
        }
      ]
    })
  ], []);

  // ===== DATA FETCHING =====
  const fetchProducts = useCallback(async (params = {}) => {
    setLoading(true);
    try {
      // Get settings-aware API parameters
      const baseParams = getApiParams({
        pageSize: paginationModel.pageSize,
        currentPage: paginationModel.page + 1, // MUI uses 0-based, Magento uses 1-based
        ...params
      });

      // Use settings-aware API method
      const response = await magentoApi.getProductsWithSettings('magentoProducts', baseParams);
      const products = response.data?.items || [];
      const totalCount = response.data?.total_count || products.length;

      setData(products);
      setStats({
        total: totalCount,
        active: products.filter(p => p.status === 1).length,
        inactive: products.filter(p => p.status === 2).length,
        localProducts: localProducts.length,
        syncedProducts: products.filter(p => !p.isLocal).length
      });
    } catch (error) {
      // Use settings-aware error handling
      handleError(error, 'Load Products');
      setData([]);
      setStats({ total: 0, active: 0, inactive: 0, localProducts: 0, syncedProducts: 0 });
    } finally {
      setLoading(false);
    }
  }, [localProducts.length, paginationModel, getApiParams, handleError]);

  // ===== PAGINATION HANDLER =====
  const handlePaginationChange = useCallback((newPaginationModel) => {
    setPaginationModel(newPaginationModel);
    // Fetch new data when pagination changes
    fetchProducts();
  }, [fetchProducts]);



  // Load categories and brands for filtering
  useEffect(() => {
    const loadFiltersData = async () => {
      try {
        // Load categories
        const categoryOptions = categoryService.getCategoriesForCombo();
        setCategories(categoryOptions);
        console.log('📂 Categories loaded for filtering:', categoryOptions.length);

        // Load brands from Magento API
        try {
          const brandsResponse = await magentoApi.getBrands();
          const brandsData = brandsResponse?.items || [];
          setBrands(brandsData);
          console.log('🏷️ Brands loaded for filtering:', brandsData.length);
        } catch (brandError) {
          console.warn('⚠️ Could not load brands:', brandError.message);
          // Provide fallback brands if API fails
          setBrands([
            { value: '1659', label: 'Calligraphe' },
            { value: '1660', label: 'Maped' },
            { value: '1661', label: 'Bic' }
          ]);
        }
      } catch (error) {
        console.error('❌ Error loading filter data:', error);
      }
    };

    loadFiltersData();
  }, []);

  // Initial data fetch
  useEffect(() => {
    fetchProducts();
  }, []); // Only run on mount

  // Fetch data when pagination changes
  useEffect(() => {
    if (paginationModel.page > 0 || paginationModel.pageSize !== 25) {
      fetchProducts();
    }
  }, [paginationModel, fetchProducts]);

  // ===== EVENT HANDLERS =====
  const handleAdd = useCallback(() => {
    console.log('Add product');
    // Implement add logic
  }, []);

  const handleEdit = useCallback((selectedIds) => {
    if (Array.isArray(selectedIds)) {
      if (selectedIds.length !== 1) {
        toast.warning('Please select one product to edit');
        return;
      }
      const product = data.find(p => p.sku === selectedIds[0]);
      setSelectedProduct(product);
    } else {
      // Handle direct row click
      setSelectedProduct(selectedIds);
    }
    setEditDialogOpen(true);
  }, [data]);

  const handleViewDetails = useCallback((selectedIds) => {
    if (Array.isArray(selectedIds)) {
      if (selectedIds.length !== 1) {
        toast.warning('Please select one product to view');
        return;
      }
      const product = data.find(p => p.sku === selectedIds[0]);
      setSelectedProduct(product);
    } else {
      // Handle direct row click
      setSelectedProduct(selectedIds);
    }
    setInfoDialogOpen(true);
  }, [data]);

  const handleDelete = useCallback(async (selectedIds) => {
    if (selectedIds.length === 0) {
      toast.warning('Please select products to delete');
      return;
    }
    
    try {
      await Promise.all(selectedIds.map(sku => ProductService.deleteProduct(sku)));
      toast.success(`${selectedIds.length} product(s) deleted`);
      fetchProducts();
    } catch (error) {
      toast.error('Failed to delete products');
    }
  }, [fetchProducts]);

  const handleSync = useCallback(async () => {
    try {
      await magentoApi.syncProducts();
      toast.success('Products synchronized');
      fetchProducts();
    } catch (error) {
      console.error('Sync error:', error);
      toast.error('Sync failed');
    }
  }, [fetchProducts]);

  const handleExport = useCallback(() => {
    console.log('Export products');
    // Implement export logic
  }, []);

  const handleRowDoubleClick = useCallback((params) => {
    setSelectedProduct(params.row);
    setInfoDialogOpen(true);
  }, []);

  const handleCategoryAssignment = useCallback((product) => {
    console.log('Category assignment for product:', product.sku);
    // For now, just show a toast. Can be expanded to open a category dialog
    toast.info(`Category assignment for ${product.name || product.sku}`);
    // TODO: Implement category assignment dialog
    // setCategoryDialogOpen(true);
    // setSelectedProduct(product);
  }, []);



  // ===== CONTEXT MENU =====
  const contextMenuActions = useMemo(() => ({
    edit: {
      enabled: true,
      label: 'Edit Product',
      icon: 'edit',
      onClick: (row) => handleEdit(row)
    },
    view: {
      enabled: true,
      label: 'View Details',
      icon: 'visibility',
      onClick: (row) => handleViewDetails(row)
    },
    delete: {
      enabled: true,
      label: 'Delete Product',
      icon: 'delete',
      onClick: (row) => handleDelete([row.sku]),
      color: 'error'
    },
    duplicate: {
      enabled: true,
      label: 'Duplicate Product',
      icon: 'content_copy',
      onClick: (row) => {
        console.log('Duplicate:', row);
        toast.info(`Duplicating product: ${row.name}`);
      }
    }
  }), [handleEdit, handleDelete]);

  // ===== STATS CARDS =====
  const gridCards = useMemo(() => [
    { title: 'Total Products', value: stats.total, color: 'primary' },
    { title: 'Active', value: stats.active, color: 'success' },
    { title: 'Inactive', value: stats.inactive, color: 'warning' },
    { title: 'Local Products', value: stats.localProducts, color: 'info' }
  ], [stats]);

  // ===== COMPACT CUSTOM ACTIONS =====
  const customActions = useMemo(() => [
    {
      label: 'Sync',
      icon: 'sync',
      onClick: handleSync,
      disabled: localProducts.length === 0
    },
    {
      label: 'Import CSV',
      icon: 'upload',
      onClick: () => setCsvImportOpen(true)
    },
    {
      label: 'Bulk Media Upload',
      icon: 'image',
      onClick: () => setBulkMediaDialogOpen(true),
      color: 'info'
    },
    {
      label: 'Catalog Processor',
      icon: 'settings',
      onClick: () => setCatalogProcessorOpen(true)
    }
  ], [handleSync, localProducts.length]);

  return (
    <>
      <UnifiedGrid
        {...getStandardGridProps('magentoProducts', {
          gridName: "MagentoProductsGrid",
          columns,
          data,
          loading,
          totalCount: stats.total,

          // Pagination configuration
          paginationMode: "server",
          paginationModel,
          onPaginationModelChange: handlePaginationChange,
          defaultPageSize: 25,

          // Event handlers
          onRefresh: fetchProducts,
          onRowDoubleClick: handleRowDoubleClick,
          onAdd: handleAdd,
          onEdit: handleEdit,
          onDelete: handleDelete,
          onSync: handleSync,
          onExport: handleExport,

          // Configuration
          toolbarConfig: {
            ...getStandardToolbarConfig('magentoProducts'),
            filters: [
              {
                field: 'category',
                label: 'Category',
                type: 'select',
                options: [
                  { value: '', label: 'All Categories' },
                  ...categories.filter(cat => cat && (cat.id || cat.id === 0)).map(cat => ({
                    value: cat.id?.toString() || '',
                    label: cat.label || `Category ${cat.id}`
                  }))
                ],
                value: categoryFilter,
                onChange: (value) => {
                  setCategoryFilter(value);
                  fetchProducts({ category_id: value, brand: brandFilter });
                }
              },
              {
                field: 'brand',
                label: 'Brand',
                type: 'select',
                options: [
                  { value: '', label: 'All Brands' },
                  ...brands.map(brand => ({
                    value: brand.value || brand.id,
                    label: brand.label || brand.name
                  }))
                ],
                value: brandFilter,
                onChange: (value) => {
                  setBrandFilter(value);
                  fetchProducts({ category_id: categoryFilter, brand: value });
                }
              }
            ]
          },
          customActions,
          contextMenuActions,

          // Stats
          showStatsCards: true,
          gridCards,

          // Grid props
          getRowId: (row) => row.sku
        })}
      />

      {/* Dialogs */}
      <ProductInfoDialog
        open={infoDialogOpen}
        onClose={() => setInfoDialogOpen(false)}
        product={selectedProduct}
      />

      <ProductEditDialog
        open={editDialogOpen}
        onClose={() => {
          setEditDialogOpen(false);
          setSelectedProduct(null);
        }}
        product={selectedProduct}
        onSave={(updatedProduct) => {
          console.log('💾 Saving product:', updatedProduct);
          toast.success(`Product "${updatedProduct.name}" saved successfully`);
          fetchProducts(); // Refresh the grid
          setEditDialogOpen(false);
          setSelectedProduct(null);
        }}
      />

      <CSVImportDialog
        open={csvImportOpen}
        onClose={() => setCsvImportOpen(false)}
