import React, { createContext, useState, useContext, useEffect, useCallback } from 'react';
import { toast } from 'react-toastify';
import {


    GoogleAuthProvider,
    signInWithPopup,
    signOut,
    onAuthStateChanged
} from 'firebase/auth';
import { auth, database } from '../config/firebase';
import { ref, set, get } from 'firebase/database';
// Removed useNavigate to avoid circular dependency with Router
import magentoApi from '../services/magentoService';
import { USER_ROLES, createDefaultUserLicense, initializeFirebaseDefaults } from '../config/firebaseDefaults';
import firebaseSyncService from '../services/firebaseSyncService';
import LicenseManager from '../services/LicenseManager';
import PermissionService from '../services/PermissionService';

const AuthContext = createContext();
const MAGENTO_API_URL = import.meta.env.VITE_MAGENTO_API_URL;

export const useAuth = () => {
    return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
    const [currentUser, setCurrentUser] = useState(() => {
        const token = localStorage.getItem('adminToken');
        if (token) {
            return {
                uid: 'magento-user',
                isMagentoUser: true,
                token
            };
        }
        return null;
    });
    // Removed navigate to avoid circular dependency
    const [loading, setLoading] = useState(true);     
    const [adminToken, setMagentoToken] = useState(() => localStorage.getItem('adminToken'));
    const [isUsingLocalData, setIsUsingLocalData] = useState(false);

    // Helper functions for settings management with local cache priority
    const initializeUserSettings = useCallback(async (user) => {
        try {
            const sanitizedUserId = user.uid.replace(/[.#$\[\]]/g, '_');
            const userSettingsKey = `userSettings_${sanitizedUserId}`;
            
            // Use unified settings manager
            const { getUserSettings } = await import('../utils/unifiedSettingsManager');
            const userSettings = getUserSettings(sanitizedUserId);
            if (userSettings) {
                console.log('User settings loaded from local cache');
                
                // Minimal sync to Firebase only if cache is old (> 24 hours)
                const lastSync = new Date(userSettings.lastSync || 0);
                const now = new Date();
                const hoursSinceSync = (now - lastSync) / (1000 * 60 * 60);
                
                if (hoursSinceSync > 24) {
                    syncSettingsToFirebase(user, userSettings);
                }
            } else {
                // If no local cache, try to fetch from Firebase
                await loadSettingsFromFirebase(user);
            }
        } catch (error) {
            console.error('Error initializing user settings:', error);
        }
    }, []);
    
    // Sync settings to Firebase (minimal)
    const syncSettingsToFirebase = async (user, settings) => {
        try {
            const sanitizedUserId = user.uid.replace(/[.#$\[\]]/g, '_');
            const settingsRef = ref(database, `userSettings/${sanitizedUserId}`);
            
            const settingsData = {
                preferences: settings,
                lastSync: new Date().toISOString(),
                userId: user.uid,
                email: user.email
            };
            
            await set(settingsRef, settingsData);
            
            // Save through unified settings manager
            const { saveUserSettings } = await import('../utils/unifiedSettingsManager');
            saveUserSettings(sanitizedUserId, settingsData);
            
            console.log('Settings synced to Firebase');
        } catch (error) {
            console.error('Error syncing settings to Firebase:', error);
        }
    };
    
    // Load settings from Firebase
    const loadSettingsFromFirebase = async (user) => {
        try {
            const sanitizedUserId = user.uid.replace(/[.#$\[\]]/g, '_');
            const settingsRef = ref(database, `userSettings/${sanitizedUserId}`);
            const snapshot = await get(settingsRef);
            
            if (snapshot.exists()) {
                const firebaseSettings = snapshot.val();
                const userSettingsKey = `userSettings_${sanitizedUserId}`;
                
                // Save through unified settings manager
                const { saveUserSettings } = await import('../utils/unifiedSettingsManager');
                saveUserSettings(sanitizedUserId, firebaseSettings);
                
                console.log('Settings loaded from Firebase');
            }
        } catch (error) {
            console.error('Error loading settings from Firebase:', error);
        }
    };
    
    // Save settings (always local first, sync later)
    const saveUserSettings = useCallback((settings) => {
        try {
            if (!currentUser) return;
            
            const sanitizedUserId = currentUser.uid.replace(/[.#$\[\]]/g, '_');
            const userSettingsKey = `userSettings_${sanitizedUserId}`;
            
            const settingsData = {
                preferences: settings,
                lastSync: new Date().toISOString(),
                userId: currentUser.uid,
                email: currentUser.email
            };
            
            // Always save to local cache first
            localStorage.setItem(userSettingsKey, JSON.stringify(settingsData));
            localStorage.setItem('techno-etl-settings', JSON.stringify(settings));
            
            // Async sync to Firebase (non-blocking)
            setTimeout(() => {
                syncSettingsToFirebase(currentUser, settings);
            }, 1000);
            
            console.log('Settings saved locally');
        } catch (error) {
            console.error('Error saving user settings:', error);
        }
    }, [currentUser]);

    const clearUserSettings = useCallback(() => {
        try {
            // Clear unified settings when user logs out
            localStorage.removeItem('techno-etl-settings');
            console.log('User settings cleared on logout');
        } catch (error) {
            console.error('Error clearing user settings:', error);
        }
    }, []);

    // Register user in database and initialize license
    const registerUserInDatabase = async (user) => {
        try {
            const sanitizedUserId = user.uid.replace(/[.#$\[\]]/g, '_');
            const userRef = ref(database, `users/${sanitizedUserId}`);
            const licenseRef = ref(database, `licenses/${sanitizedUserId}`);
            
            // Check if user already exists
            const [userSnapshot, licenseSnapshot] = await Promise.all([
                get(userRef),
                get(licenseRef)
            ]);
            
            if (!userSnapshot.exists()) {
                // Check if this is the first user (super_admin)
                const usersRef = ref(database, 'users');
                const usersSnapshot = await get(usersRef);
                const isFirstUser = !usersSnapshot.exists() || Object.keys(usersSnapshot.val() || {}).length === 0;
                const role = isFirstUser ? USER_ROLES.SUPER_ADMIN : USER_ROLES.USER;
                
                // Create user record
                await set(userRef, {
                    email: user.email,
                    displayName: user.displayName,
                    role: role,
                    createdAt: new Date().toISOString(),
                    lastLogin: new Date().toISOString(),
                    isMagentoUser: user.isMagentoUser || false
                });
                
                console.log(`User ${user.email} registered in database with role: ${isFirstUser ? 'super_admin' : 'user'}`);
            } else {
                // Update last login
                const userData = userSnapshot.val();
                await set(userRef, {
                    ...userData,
                    lastLogin: new Date().toISOString()
                });
            }

            // Initialize license if it doesn't exist
            if (!licenseSnapshot.exists()) {
                const defaultLicense = createDefaultUserLicense(user.uid, 'FREE');
                await set(licenseRef, defaultLicense);
                console.log(`Default license created for user ${user.email}`);
            }

            // Initialize permission service for this user
            await PermissionService.initialize(user);
            
        } catch (error) {
            console.error('Error registering user in database:', error);
        }
    };

    // Monitor Firebase auth state
    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, (user) => {
            if (user && !currentUser?.isMagentoUser) {
                setCurrentUser({
                    ...user,
                    isMagentoUser: false
                });
                toast.success('Welcome back, ' + user.displayName);
                
                // Register user in database and initialize settings
                registerUserInDatabase(user);
                initializeUserSettings(user);
                
                // Sync with Firebase
                firebaseSyncService.syncUserOnLogin(user);
            } else if (!user && !currentUser?.isMagentoUser) {
                setCurrentUser(null);
                // Clear settings on logout
                clearUserSettings();
            }
            setLoading(false);
        });

        return unsubscribe;
    }, [currentUser?.isMagentoUser, initializeUserSettings, clearUserSettings]);

    const validateMagentoToken = async (token) => {
        if (!token) {
            toast.error('No authentication token found');
            return false;
        }

        try {
            const response = await magentoApi.get('/store/storeConfigs');

            if (!response.ok) {
                if (response.status === 401) {
                    toast.warning('Session expired. Using local cached data.', {
                        autoClose: 5000,
                        style: { backgroundColor: '#FFA500', color: '#FFFFFF' }
                    });
                    setIsUsingLocalData(true);
                    setMagentoToken(null);
                    localStorage.removeItem('adminToken');
                    return true; // Allow using local data
                }
                toast.warning('Connection issues. Using cached session.');
                return true;
            }

            // Reset local data flag if token is valid
            setIsUsingLocalData(false);
            return true;
        } catch (error) {
            toast.error('Network error. Please check your connection.');
            console.error('Token validation error:', error);
            setIsUsingLocalData(true);
            return true;
        }
    };

    const signInWithGoogle = async () => {
        try {
            const provider = new GoogleAuthProvider();
            provider.setCustomParameters({
                prompt: 'select_account'
            });
            const result = await signInWithPopup(auth, provider);

            // User data will be set by the auth state observer
            toast.success('Successfully logged in with Google!');
            // Navigation will be handled by the component using this context
            return result;
        } catch (error) {
            console.error('Google sign-in error:', error);
            toast.error('Failed to sign in with Google');
            throw error;
        }
    };

    const signInWithMagento = async (username, password) => {
        try {
            const response = await magentoApi.login(username, password);

            const magentoUser = {
                uid: username,
                email: username,
                displayName: username,
                isMagentoUser: true,
                token: response
            };

            setCurrentUser(magentoUser);
            
            // Register Magento user and initialize settings
            registerUserInDatabase(magentoUser);
            initializeUserSettings(magentoUser);
            
            // Sync with Firebase
            firebaseSyncService.syncUserOnLogin(magentoUser);
 
            toast.success('Successfully logged in!');

            return magentoUser;
        } catch (error) {
            console.error('Magento login error:', error);
            toast.error(error.message || 'Failed to login. Please check your credentials.');
            throw error;
        }
    };

    const logout = async () => {
        try {
            if (currentUser?.isMagentoUser) {
                // Clear Magento token
                setMagentoToken(null);
                localStorage.removeItem('adminToken');
            } else {
                // Sign out from Firebase
                await signOut(auth);
            }
            setCurrentUser(null);
            toast.success('Successfully logged out');
            window.location.href = '/login';  // Force a full page reload to clear all states
        } catch (error) {
            console.error('Logout error:', error);
            toast.error('Failed to logout');
            throw error;
        }
    };

    // Check Magento token validity
    useEffect(() => {
        let mounted = true;

        const initializeAuth = async () => {
            try {
                if (adminToken) {
                    const isValid = await validateMagentoToken(adminToken);
                
                    if (!isValid && mounted) {
                        setMagentoToken(null);
                        setCurrentUser(null);
                        localStorage.removeItem('adminToken');
                    }
                }
            } catch (error) {
                console.error('Auth initialization error:', error);
            } finally {
                if (mounted) {
                    setLoading(false);
                }
            }
        };

        initializeAuth();

        return () => {
            mounted = false;
        };
    }, [adminToken]);

    // Get user permissions and license status
    const getUserPermissions = useCallback(async () => {
        if (!currentUser?.uid) return [];
        try {
            return await PermissionService.getPermissions();
        } catch (error) {
            console.error('Error getting user permissions:', error);
            return [];
        }
    }, [currentUser?.uid]);

    const getUserLicenseStatus = useCallback(async () => {
        if (!currentUser?.uid) return null;
        try {
            return await LicenseManager.checkUserLicense(currentUser.uid);
        } catch (error) {
            console.error('Error getting user license status:', error);
            return null;
        }
    }, [currentUser?.uid]);

    const hasPermission = useCallback((action, resource = '*') => {
        return PermissionService.hasPermission(action, resource);
    }, []);

    const checkFeatureAccess = useCallback(async (feature) => {
        if (!currentUser?.uid) return false;
        try {
            return await LicenseManager.validateFeatureAccess(feature, currentUser.uid);
        } catch (error) {
            console.error('Error checking feature access:', error);
            return false;
        }
    }, [currentUser?.uid]);

    const value = {
        currentUser,
        loading,
        signInWithGoogle,
        signInWithMagento,
        logout,
        adminToken,
        isUsingLocalData,
        validateMagentoToken,
        saveUserSettings,
        // Permission and license functions
        getUserPermissions,
        getUserLicenseStatus,
        hasPermission,
        checkFeatureAccess
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
};

/**
 * Optimized App Context
 * Performance-optimized context provider with selectors
 */

import React, { createContext, useContext, useReducer, useMemo, useCallback } from 'react';

// Initial state
const initialState = {
    user: null,
    theme: 'light',
    language: 'en',
    loading: false,
    error: null,
    notifications: [],
    settings: {},
    performance: {
        renderCount: 0,
        lastRender: null
    }
};

// Action types
const ActionTypes = {
    SET_USER: 'SET_USER',
    SET_THEME: 'SET_THEME',
    SET_LANGUAGE: 'SET_LANGUAGE',
    SET_LOADING: 'SET_LOADING',
    SET_ERROR: 'SET_ERROR',
    ADD_NOTIFICATION: 'ADD_NOTIFICATION',
    REMOVE_NOTIFICATION: 'REMOVE_NOTIFICATION',
    UPDATE_SETTINGS: 'UPDATE_SETTINGS',
    TRACK_RENDER: 'TRACK_RENDER',
    RESET_STATE: 'RESET_STATE'
};

// Optimized reducer
const appReducer = (state, action) => {
    switch (action.type) {
        case ActionTypes.SET_USER:
            return { ...state, user: action.payload };

        case ActionTypes.SET_THEME:
            return { ...state, theme: action.payload };

        case ActionTypes.SET_LANGUAGE:
            return { ...state, language: action.payload };

        case ActionTypes.SET_LOADING:
            return { ...state, loading: action.payload };

        case ActionTypes.SET_ERROR:
            return { ...state, error: action.payload };

        case ActionTypes.ADD_NOTIFICATION:
            return {
                ...state,
                notifications: [...state.notifications, {
                    id: Date.now().toString(),
                    timestamp: Date.now(),
                    ...action.payload
                }]
            };

        case ActionTypes.REMOVE_NOTIFICATION:
            return {
                ...state,
                notifications: state.notifications.filter(n => n.id !== action.payload)
            };

        case ActionTypes.UPDATE_SETTINGS:
            return {
                ...state,
                settings: { ...state.settings, ...action.payload }
            };

        case ActionTypes.TRACK_RENDER:
            return {
                ...state,
                performance: {
                    renderCount: state.performance.renderCount + 1,
                    lastRender: Date.now()
                }
            };

        case ActionTypes.RESET_STATE:
            return { ...initialState };

        default:
            return state;
    }
};

// Create contexts with performance optimization
const AppStateContext = createContext();
const AppDispatchContext = createContext();

// Optimized provider component
export function OptimizedAppProvider({ children }) {
    const [state, dispatch] = useReducer(appReducer, initialState);

    // Track renders for performance monitoring
    React.useEffect(() => {
        dispatch({ type: ActionTypes.TRACK_RENDER });
    });

    // Memoized dispatch actions to prevent unnecessary re-renders
    const actions = useMemo(() => ({
        setUser: (user) => dispatch({ type: ActionTypes.SET_USER, payload: user }),
        setTheme: (theme) => dispatch({ type: ActionTypes.SET_THEME, payload: theme }),
        setLanguage: (language) => dispatch({ type: ActionTypes.SET_LANGUAGE, payload: language }),
        setLoading: (loading) => dispatch({ type: ActionTypes.SET_LOADING, payload: loading }),
        setError: (error) => dispatch({ type: ActionTypes.SET_ERROR, payload: error }),
        addNotification: (notification) => dispatch({ type: ActionTypes.ADD_NOTIFICATION, payload: notification }),
        removeNotification: (id) => dispatch({ type: ActionTypes.REMOVE_NOTIFICATION, payload: id }),
        updateSettings: (settings) => dispatch({ type: ActionTypes.UPDATE_SETTINGS, payload: settings }),
        resetState: () => dispatch({ type: ActionTypes.RESET_STATE })
    }), []);

    // Memoized state to prevent unnecessary re-renders
    const memoizedState = useMemo(() => state, [
        state.user,
        state.theme,
        state.language,
        state.loading,
        state.error,
        state.notifications.length,
        state.settings,
        state.performance.renderCount
    ]);

    return (
        <AppStateContext.Provider value={memoizedState}>
            <AppDispatchContext.Provider value={actions}>
                {children}
            </AppDispatchContext.Provider>
        </AppStateContext.Provider>
    );
}

// Optimized hooks with selectors to prevent unnecessary re-renders
export function useAppState(selector) {
    const context = useContext(AppStateContext);
    if (context === undefined) {
        throw new Error('useAppState must be used within an OptimizedAppProvider');
    }

    // If no selector is provided, return the full state
    if (!selector) return context;

    // Use selector to return only specific part of state
    return useMemo(() => selector(context), [selector, context]);
}

export function useAppDispatch() {
    const context = useContext(AppDispatchContext);
    if (context === undefined) {
        throw new Error('useAppDispatch must be used within an OptimizedAppProvider');
    }
    return context;
}

// Convenient hooks for specific state slices
export const useUser = () => useAppState(state => state.user);
export const useTheme = () => useAppState(state => state.theme);
export const useLanguage = () => useAppState(state => state.language);
export const useLoading = () => useAppState(state => state.loading);
export const useError = () => useAppState(state => state.error);
export const useNotifications = () => useAppState(state => state.notifications);
export const useSettings = () => useAppState(state => state.settings);
export const usePerformanceMetrics = () => useAppState(state => state.performance);

// Performance monitoring hook
export function useContextPerformance() {
    const performance = usePerformanceMetrics();
    const dispatch = useAppDispatch();

    return {
        ...performance,
        logPerformance: useCallback(() => {
            console.log('🎯 Context Performance:', {
                renders: performance.renderCount,
                lastRender: new Date(performance.lastRender).toISOString()
            });
        }, [performance])
    };
}

export default OptimizedAppProvider;

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import PermissionService from '../services/PermissionService';
import LicenseManager from '../services/LicenseManager';
import { useAuth } from './AuthContext';

const PermissionContext = createContext();

export const usePermissions = () => {
    const context = useContext(PermissionContext);
    if (!context) {
        throw new Error('usePermissions must be used within a PermissionProvider');
    }
    return context;
};

export const useLicense = () => {
    const context = useContext(PermissionContext);
    if (!context) {
        throw new Error('useLicense must be used within a PermissionProvider');
    }
    return {
        licenseStatus: context.licenseStatus,
        checkFeatureAccess: context.checkFeatureAccess,
        refreshLicense: context.refreshLicense,
        isLicenseValid: context.isLicenseValid,
        getLicenseLevel: context.getLicenseLevel
    };
};

export const PermissionProvider = ({ children }) => {
    const { currentUser } = useAuth();
    const [permissions, setPermissions] = useState([]);
    const [licenseStatus, setLicenseStatus] = useState(null);
    const [loading, setLoading] = useState(true);
    const [initialized, setInitialized] = useState(false);

    // Initialize permission service when user changes
    const initializePermissions = useCallback(async (user) => {
        try {
            setLoading(true);

            if (user?.uid) {
                // Initialize permission service
                await PermissionService.initialize(user);

                // Get current permissions and license status
                const [userPermissions, userLicenseStatus] = await Promise.all([
                    PermissionService.getPermissions(),
                    LicenseManager.checkUserLicense(user.uid)
                ]);

                setPermissions(userPermissions);
                setLicenseStatus(userLicenseStatus);
                setInitialized(true);
            } else {
                // Clear permissions when no user
                setPermissions([]);
                setLicenseStatus(null);
                setInitialized(false);
            }
        } catch (error) {
            console.error('Error initializing permissions:', error);
            setPermissions([]);
            setLicenseStatus(null);
            setInitialized(false);
        } finally {
            setLoading(false);
        }
    }, []);

    // Initialize permissions when user changes
    useEffect(() => {
        initializePermissions(currentUser);
    }, [currentUser, initializePermissions]);

    // Set up license change listener
    useEffect(() => {
        let unsubscribe = null;

        if (currentUser?.uid && initialized) {
            unsubscribe = LicenseManager.listenToLicenseChanges(
                currentUser.uid,
                async (licenseData) => {
                    try {
                        // Refresh license status when it changes
                        const updatedLicenseStatus = await LicenseManager.checkUserLicense(currentUser.uid);
                        setLicenseStatus(updatedLicenseStatus);

                        // Refresh permissions as they might have changed
                        await PermissionService.refreshPermissions();
                        const updatedPermissions = await PermissionService.getPermissions();
                        setPermissions(updatedPermissions);
                    } catch (error) {
                        console.error('Error handling license change:', error);
                    }
                }
            );
        }

        return () => {
            if (unsubscribe) {
                unsubscribe();
            }
        };
    }, [currentUser?.uid, initialized]);

    // Permission checking functions
    const hasPermission = useCallback((action, resource = '*') => {
        if (!initialized) return false;
        return PermissionService.hasPermission(action, resource);
    }, [initialized]);

    const checkFeatureAccess = useCallback(async (feature) => {
        if (!initialized || !currentUser?.uid) return false;
        return await PermissionService.checkFeatureAccess(feature);
    }, [initialized, currentUser?.uid]);

    const filterMenuItems = useCallback((menuItems) => {
        if (!initialized) return [];
        return PermissionService.filterMenuItems(menuItems);
    }, [initialized]);

    const canAccessMenuItem = useCallback((menuItem) => {
        if (!initialized) return false;
        return PermissionService.canAccessMenuItem(menuItem);
    }, [initialized]);

    // License-specific functions
    const isLicenseValid = useCallback(() => {
        return licenseStatus?.isValid || false;
    }, [licenseStatus]);

    const getLicenseLevel = useCallback(() => {
        return licenseStatus?.level || 'basic';
    }, [licenseStatus]);

    const refreshLicense = useCallback(async () => {
        if (currentUser?.uid) {
            try {
                const updatedLicenseStatus = await LicenseManager.checkUserLicense(currentUser.uid);
                setLicenseStatus(updatedLicenseStatus);
                return updatedLicenseStatus;
            } catch (error) {
                console.error('Error refreshing license:', error);
                return null;
            }
        }
        return null;
    }, [currentUser?.uid]);

    // Permission summary for debugging/admin purposes
    const getPermissionSummary = useCallback(() => {
        if (!initialized) return null;
        return PermissionService.getPermissionSummary();
    }, [initialized]);

    // Admin functions
    const isAdmin = useCallback(() => {
        if (!initialized) return false;
        return PermissionService.isAdmin();
    }, [initialized]);

    const canPerformBulkOperations = useCallback(() => {
        if (!initialized) return false;
        return PermissionService.canPerformBulkOperations();
    }, [initialized]);

    // Refresh all permissions and license data
    const refreshPermissions = useCallback(async () => {
        if (currentUser?.uid) {
            await initializePermissions(currentUser);
        }
    }, [currentUser, initializePermissions]);

    const value = {
        // State
        permissions,
        licenseStatus,
        loading,
        initialized,

        // Permission functions
        hasPermission,
        checkFeatureAccess,
        filterMenuItems,
        canAccessMenuItem,
        getPermissionSummary,

        // License functions
        isLicenseValid,
        getLicenseLevel,
        refreshLicense,

        // Admin functions
        isAdmin,
        canPerformBulkOperations,

        // Utility functions
        refreshPermissions
    };

    return (
        <PermissionContext.Provider value={value}>
            {children}
        </PermissionContext.Provider>
    );
};

export default PermissionContext;

/**
 * Enhanced Settings Context for TECHNO-ETL
 * Manages all user preferences, settings, and their persistence
 * Professional unified settings management system
 */
import React, { createContext, useContext, useState, useEffect, useCallback, useMemo } from 'react';
import { ref, set, onValue } from 'firebase/database';
import { database } from '../config/firebase';
import { useAuth } from './AuthContext';
import {
    saveUserSettings
} from '../services/userService';
import {
    getUnifiedSettings,
    saveUnifiedSettings,
    getUserSettings,
    getDefaultSettings,
    resetToSystemDefaults,
    applyLanguageSettings,
    getSystemPreferences
} from '../utils/unifiedSettingsManager';
import SettingsSyncService from '../services/SettingsSyncService';
import { toast } from 'react-toastify';

const SettingsContext = createContext();

export const useSettings = () => {
    const context = useContext(SettingsContext);
    if (!context) {
        throw new Error('useSettings must be used within a SettingsProvider');
    }
    return context;
};

export const SettingsProvider = ({ children }) => {
    const { currentUser } = useAuth();

    // Initialize settings with defaults first
    const [settings, setSettings] = useState(null);

    const [loading, setLoading] = useState(false);
    const [isDirty, setIsDirty] = useState(false);
    const [lastSyncTime, setLastSyncTime] = useState(() => {
        return localStorage.getItem('settingsLastModified') || null;
    });

    // Simple merge function for settings
    const mergeWithDefaults = (userSettings) => {
        const defaults = getDefaultSettings();
        return { ...defaults, ...userSettings };
    };

    // Initialize settings on mount with comprehensive error handling
    useEffect(() => {
        const initializeSettings = async () => {
            setLoading(true);
            try {
                let initialSettings;

                if (currentUser) {
                    // Try to get user settings with fallback
                    try {
                        initialSettings = getUserSettings(currentUser.uid);
                        if (!initialSettings || Object.keys(initialSettings).length === 0) {
                            console.warn('Empty user settings, using defaults');
                            initialSettings = getDefaultSettings();
                        }
                    } catch (userError) {
                        console.warn('Failed to load user settings, using defaults:', userError);
                        initialSettings = getDefaultSettings();
                    }
                } else {
                    // Try to get unified settings with fallback
                    try {
                        initialSettings = getUnifiedSettings();
                        if (!initialSettings || Object.keys(initialSettings).length === 0) {
                            console.warn('Empty unified settings, using defaults');
                            initialSettings = getDefaultSettings();
                        }
                    } catch (unifiedError) {
                        console.warn('Failed to load unified settings, using defaults:', unifiedError);
                        initialSettings = getDefaultSettings();
                    }
                }

                // Validate settings structure
                const validatedSettings = mergeWithDefaults(initialSettings);
                setSettings(validatedSettings);

                // Apply language settings with error handling
                if (validatedSettings.language) {
                    try {
                        applyLanguageSettings(validatedSettings.language);
                    } catch (langError) {
                        console.warn('Failed to apply language settings:', langError);
                    }
                }

                console.log('✅ Settings initialized successfully');
            } catch (error) {
                console.error('❌ Critical error initializing settings:', error);
                // Last resort fallback
                const fallbackSettings = getDefaultSettings();
                setSettings(fallbackSettings);
                toast.error('Failed to load user preferences. Using defaults.');
            } finally {
                setLoading(false);
            }
        };

        initializeSettings();
    }, [currentUser]);

    // Apply settings when they change
    useEffect(() => {
        if (settings) {
            // Apply language settings immediately
            if (settings.language) {
                applyLanguageSettings(settings.language);
            }

            // Notify other contexts about settings changes
            window.dispatchEvent(new CustomEvent('settingsChanged', {
                detail: settings
            }));
        }
    }, [settings]);



    // Enhanced settings persistence with new sync service
    const persistSettings = useCallback(async (newSettings) => {
        try {
            // Use the new SettingsSyncService for enhanced sync capabilities
            const result = await SettingsSyncService.saveSettings(
                currentUser?.uid,
                newSettings,
                { immediate: false }
            );

            if (result.success) {
                console.log('✅ Settings saved with sync service');
                return true;
            } else {
                console.error('❌ Sync service failed:', result.error);
                // Fallback to direct local save
                if (currentUser) {
                    saveUserSettings(currentUser.uid, newSettings);
                } else {
                    saveUnifiedSettings(newSettings);
                }
                return true;
            }
        } catch (error) {
            console.error('❌ Failed to persist settings:', error);
            // Fallback to direct local save
            try {
                if (currentUser) {
                    saveUserSettings(currentUser.uid, newSettings);
                } else {
                    saveUnifiedSettings(newSettings);
                }
                return true;
            } catch (fallbackError) {
                console.error('❌ Fallback save also failed:', fallbackError);
                return false;
            }
        }
    }, [currentUser]);

    // Define loadRemoteSettings first
    const loadRemoteSettings = useCallback(async () => {
        if (!currentUser) return;

        setLoading(true);
        try {
            // Try to load from Firebase/remote first
            let userSettings = null;

            try {
                // In a real app, you would fetch from your backend/Firebase
                // For now, we'll simulate remote loading with local storage
                const remoteSettings = localStorage.getItem(`userSettings_${currentUser.uid}`);
                if (remoteSettings) {
                    userSettings = JSON.parse(remoteSettings);
                }
            } catch (remoteError) {
                console.warn('Failed to load remote settings, using local:', remoteError);
            }

            // Fallback to local settings
            if (!userSettings) {
                userSettings = getUserSettings();
            }

            // Merge with defaults to ensure all properties exist
            const mergedSettings = mergeWithDefaults(userSettings);
            setSettings(mergedSettings);

            // Apply settings through unified system
            if (mergedSettings.language) {
                applyLanguageSettings(mergedSettings.language);
            }

            // Notify other contexts about user settings
            window.dispatchEvent(new CustomEvent('userSettingsLoaded', {
                detail: mergedSettings
            }));

            console.log('User settings loaded and applied successfully');
            toast.success('Welcome back! Your preferences have been restored.');

        } catch (error) {
            console.error('Error loading user settings:', error);
            toast.error('Failed to load your settings. Using defaults.');

            // Load defaults on error
            const defaults = getDefaultSettings();
            setSettings(defaults);
        } finally {
            setLoading(false);
        }
    }, [currentUser]);

    // Load settings when user logs in with enhanced sync service
    useEffect(() => {
        let realtimeSyncUnsubscribe = null;

        if (currentUser) {
            // Load settings using sync service
            const loadSettingsWithSync = async () => {
                try {
                    const result = await SettingsSyncService.loadFromCloud(currentUser.uid);
                    if (result.success) {
                        const mergedSettings = mergeWithDefaults(result.settings);
                        setSettings(mergedSettings);

                        // Apply settings immediately
                        if (mergedSettings.language) {
                            applyLanguageSettings(mergedSettings.language);
                        }

                        if (result.hadConflicts) {
                            toast.info('Settings conflicts were resolved automatically');
                        }

                        console.log(`✅ Settings loaded from ${result.source}`);
                    }
                } catch (error) {
                    console.error('❌ Error loading settings with sync service:', error);
                    // Fallback to original method
                    loadRemoteSettings();
                }
            };

            loadSettingsWithSync();

            // Set up real-time sync using the sync service
            realtimeSyncUnsubscribe = SettingsSyncService.setupRealtimeSync(currentUser.uid);

            // Listen for remote updates
            const handleRemoteUpdate = (event) => {
                if (event.detail.userId === currentUser.uid) {
                    const mergedSettings = mergeWithDefaults(event.detail.settings);
                    setSettings(mergedSettings);

                    // Apply settings immediately
                    if (mergedSettings.language) {
                        applyLanguageSettings(mergedSettings.language);
                    }
                }
            };

            SettingsSyncService.addSyncListener((eventType, data) => {
                if (eventType === 'remoteUpdate') {
                    handleRemoteUpdate({ detail: data });
                }
            });

        } else {
            // Reset to system defaults when user logs out but preserve anonymous settings
            const anonymousSettings = localStorage.getItem('techno-etl-unified-settings');
            if (anonymousSettings) {
                try {
                    const parsed = JSON.parse(anonymousSettings);
                    const defaults = mergeWithDefaults(parsed);
                    setSettings(defaults);
                } catch (error) {
                    console.warn('Failed to parse anonymous settings, using defaults');
                    const defaults = getDefaultSettings();
                    setSettings(defaults);
                }
            } else {
                const defaults = getDefaultSettings();
                setSettings(defaults);
            }
            setIsDirty(false);
        }

        return () => {
            if (realtimeSyncUnsubscribe) {
                realtimeSyncUnsubscribe();
            }
        };
    }, [currentUser, loadRemoteSettings]);

    // Auto-save to local storage when settings change
    useEffect(() => {
        if (isDirty) {
            const timeoutId = setTimeout(() => {
                if (currentUser) {
                    saveUserSettings(currentUser.uid, settings);
                } else {
                    saveUnifiedSettings(settings);
                }
                setIsDirty(false);
            }, 1000); // 1 second debounce

            return () => clearTimeout(timeoutId);
        }
    }, [settings, isDirty]);

    const updateSettings = useCallback((updates, section = null) => {
        setSettings(prevSettings => {
            let newSettings;

            if (section) {
                // Update specific section
                newSettings = {
                    ...prevSettings,
                    [section]: {
                        ...prevSettings[section],
                        ...updates
                    }
                };
            } else {
                // Merge all updates
                newSettings = mergeWithDefaults({
                    ...prevSettings,
                    ...updates
                });
            }

            // Save to unified storage - sync preferences to theme storage
            if (section === 'preferences' || newSettings.preferences) {
                const unifiedThemeSettings = {
                    theme: newSettings.preferences?.theme || 'system',
                    fontSize: newSettings.preferences?.fontSize || 'medium',
                    colorPreset: newSettings.preferences?.colorPreset || 'techno',
                    density: newSettings.preferences?.density || 'standard',
                    animations: newSettings.preferences?.animations !== false,
                    highContrast: newSettings.preferences?.highContrast === true,
                    language: newSettings.preferences?.language || 'en'
                };

                // Save to unified theme storage
                try {
                    localStorage.setItem('techno-etl-settings', JSON.stringify(unifiedThemeSettings));
                    console.log('Settings synced to unified theme storage:', unifiedThemeSettings);
                } catch (error) {
                    console.error('Error syncing to unified theme storage:', error);
                }
            }

            // Also save to legacy settings storage
            saveUnifiedSettings(newSettings);

            return newSettings;
        });

        setIsDirty(true);
    }, [saveUnifiedSettings]);

    const saveSettings = useCallback(async (forceSave = false) => {
        if (!isDirty && !forceSave) {
            return { success: true, message: 'No changes to save' };
        }

        setLoading(true);
        try {
            // Save locally first
            let localSaved;
            if (currentUser) {
                localSaved = saveUserSettings(currentUser.uid, settings);
            } else {
                localSaved = saveUnifiedSettings(settings);
            }

            if (!localSaved) {
                throw new Error('Failed to save settings locally');
            }

            // Save remotely if user is authenticated
            if (currentUser) {
                try {
                    await saveUserSettings(currentUser.uid, settings);
                    setLastSyncTime(Date.now().toString());
                } catch (remoteError) {
                    console.warn('Failed to save to remote, but local save succeeded:', remoteError);
                    toast.warning('Settings saved locally. Will sync when connection is restored.');
                }
            }

            setIsDirty(false);
            toast.success('Settings saved successfully');
            return { success: true, message: 'Settings saved successfully' };

        } catch (error) {
            console.error('Error saving settings:', error);
            toast.error('Failed to save settings');
            return { success: false, message: error.message };
        } finally {
            setLoading(false);
        }
    }, [settings, isDirty, currentUser]);

    const resetSettings = useCallback(() => {
        const defaults = resetToSystemDefaults(currentUser?.uid);
        setSettings(defaults);
        setIsDirty(true);
        toast.info('Settings reset to defaults');
    }, [currentUser]);

    const exportSettings = useCallback(() => {
        try {
            const dataStr = JSON.stringify(settings, null, 2);
            const dataBlob = new Blob([dataStr], { type: 'application/json' });
            const url = URL.createObjectURL(dataBlob);

            const link = document.createElement('a');
            link.href = url;
            link.download = `techno-etl-settings-${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            URL.revokeObjectURL(url);

            toast.success('Settings exported successfully');
        } catch (error) {
            console.error('Error exporting settings:', error);
            toast.error('Failed to export settings');
        }
    }, [settings]);

    const importSettings = useCallback((file) => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();

            reader.onload = (e) => {
                try {
                    const importedSettings = JSON.parse(e.target.result);
                    const mergedSettings = mergeWithDefaults(importedSettings);

                    setSettings(mergedSettings);
                    setIsDirty(true);

                    toast.success('Settings imported successfully');
                    resolve(mergedSettings);
                } catch (error) {
                    console.error('Error importing settings:', error);
                    toast.error('Invalid settings file');
                    reject(error);
                }
            };

            reader.onerror = () => {
                toast.error('Failed to read settings file');
                reject(new Error('File read error'));
            };

            reader.readAsText(file);
        });
    }, []);

    // Memoized context value to prevent unnecessary re-renders
    const contextValue = useMemo(() => ({
        settings,
        loading,
        isDirty,
        lastSyncTime,
        updateSettings,
        saveSettings,
        resetSettings,
        exportSettings,
        importSettings,
        loadRemoteSettings
    }), [
        settings,
        loading,
        isDirty,
        lastSyncTime,
        updateSettings,
        saveSettings,
        resetSettings,
        exportSettings,
        importSettings,
        loadRemoteSettings
    ]);

    return (
        <SettingsContext.Provider value={contextValue}>
            {children}
        </SettingsContext.Provider>
    );
};

export default SettingsContext;

