  const handlePriceSync = useCallback(async () => {
    try {
      setSyncLoading(true);
      await syncPrices();
      return {
        success: true,
        message: 'Price sync completed successfully'
      };
    } catch (error) {
      console.error('Error syncing prices:', error);
      throw error;
    } finally {
      setSyncLoading(false);
    }
  }, [syncPrices]);

  /**
   * Refresh all data when dependencies change
   */
  useEffect(() => {
    if (refreshKey > 0) {
      fetchDashboardData();
    }
  }, [startDate, endDate, refreshKey, fetchDashboardData]);

  return {
    // Data
    stats,
    chartData,
    recentOrders,
    bestSellers,
    customerData,
    countryData,
    productTypeData,
    priceData,
    stockData,

    // Loading states
    loading: loading || syncLoading,
    syncLoading,
    error,

    // Actions
    getPrices,
    syncAllStocks,
    fetchDashboardData,
    handlePriceSync,

    // Sync operations
    syncPrices: handlePriceSync,
    syncInventory: syncAllStocks
  };
};

export default useDashboardController;

import { useCallback } from 'react';
import { toast } from 'react-toastify';

/**
 * Enhanced Grid Actions Hook
 * Provides standardized action handlers for grid operations
 */
export const useGridActions = ({
  onRefresh,
  onAdd,
  onEdit,
  onDelete,
  onSync,
  onExport,
  onSearch,
  selectedRows = [],
  data = [],
  gridName,
  searchableFields = ['sku', 'name', 'Code_MDM', 'reference']
}) => {
  // Refresh handler with error handling
  const handleRefresh = useCallback(async () => {
    try {
      await onRefresh?.();
      toast.success('Data refreshed successfully');
    } catch (error) {
      console.error('Error refreshing data:', error);
      toast.error('Failed to refresh data');
    }
  }, [onRefresh]);

  // Add handler
  const handleAdd = useCallback(async () => {
    try {
      await onAdd?.();
    } catch (error) {
      console.error('Error adding record:', error);
      toast.error('Failed to add record');
    }
  }, [onAdd]);

  // Edit handler
  const handleEdit = useCallback(async () => {
    if (selectedRows.length === 0) {
      toast.warning('Please select a record to edit');
      return;
    }

    try {
      await onEdit?.(selectedRows);
    } catch (error) {
      console.error('Error editing record:', error);
      toast.error('Failed to edit record');
    }
  }, [onEdit, selectedRows]);

  // Delete handler
  const handleDelete = useCallback(async () => {
    if (selectedRows.length === 0) {
      toast.warning('Please select records to delete');
      return;
    }

    try {
      await onDelete?.(selectedRows);
      toast.success(`Deleted ${selectedRows.length} record(s)`);
    } catch (error) {
      console.error('Error deleting records:', error);
      toast.error('Failed to delete records');
    }
  }, [onDelete, selectedRows]);

  // Sync handler
  const handleSync = useCallback(async () => {
    try {
      await onSync?.();
      toast.success('Sync completed successfully');
    } catch (error) {
      console.error('Error syncing data:', error);
      toast.error('Failed to sync data');
    }
  }, [onSync]);

  // Export handler
  const handleExport = useCallback(async () => {
    try {
      const exportData = selectedRows.length > 0
        ? data.filter(item => selectedRows.includes(item.id || item.entity_id))
        : data;

      await onExport?.(exportData, selectedRows);
      toast.success(`Exported ${exportData.length} record(s)`);
    } catch (error) {
      console.error('Error exporting data:', error);
      toast.error('Failed to export data');
    }
  }, [onExport, selectedRows, data]);

  // Search handler
  const handleSearch = useCallback(async (searchValue) => {
    try {
      if (onSearch) {
        // Use custom search logic if provided
        await onSearch(searchValue);
      } else if (searchValue.trim()) {
        // Default search behavior - show info about what would be searched
        const fieldsText = searchableFields.join(', ');
        toast.info(`Searching in: ${fieldsText}`);
        console.log(`Search "${searchValue}" in fields:`, searchableFields);
      }
    } catch (error) {
      console.error('Error searching data:', error);
      toast.error('Search failed');
    }
  }, [onSearch, searchableFields]);

  return {
    handleRefresh,
    handleAdd,
    handleEdit,
    handleDelete,
    handleSync,
    handleExport,
    handleSearch
  };
};

import { useState, useCallback, useRef, useEffect, useMemo } from 'react';

/**
 * Advanced Grid Caching Hook with Enhanced Performance
 * Provides intelligent caching with memory management, cache invalidation, and compression
 */
export const useGridCache = (gridName, enableCache = true) => {
  const [cacheData, setCacheDataState] = useState(null);
  const [cacheMetadata, setCacheMetadata] = useState({});
  const cacheRef = useRef(new Map());
  const lastAccessRef = useRef(new Map());
  const compressionRef = useRef(new Map()); // For compressed cache entries

  // Memoized cache configuration for performance
  const cacheConfig = useMemo(() => ({
    CACHE_DURATION: 5 * 60 * 1000, // 5 minutes
    MAX_CACHE_SIZE: 50, // Maximum number of cached grids
    MEMORY_THRESHOLD: 100 * 1024 * 1024, // 100MB memory threshold
    COMPRESSION_THRESHOLD: 10000 // Compress data larger than 10KB
  }), []);

  const { CACHE_DURATION, MAX_CACHE_SIZE, MEMORY_THRESHOLD, COMPRESSION_THRESHOLD } = cacheConfig;

  // Memory management
  const estimateMemoryUsage = useCallback((data) => {
    return JSON.stringify(data).length * 2; // Rough estimate in bytes
  }, []);

  const cleanupOldCache = useCallback(() => {
    const now = Date.now();
    const entries = Array.from(lastAccessRef.current.entries());

    // Sort by last access time and remove oldest entries
    entries.sort((a, b) => a[1] - b[1]);

    let totalMemory = 0;
    const keysToKeep = [];

    for (const [key, lastAccess] of entries.reverse()) {
      const cacheEntry = cacheRef.current.get(key);
      if (cacheEntry && (now - lastAccess < CACHE_DURATION)) {
        const memoryUsage = estimateMemoryUsage(cacheEntry.data);
        if (totalMemory + memoryUsage < MEMORY_THRESHOLD && keysToKeep.length < MAX_CACHE_SIZE) {
          keysToKeep.push(key);
          totalMemory += memoryUsage;
        }
      }
    }

    // Remove entries not in keysToKeep
    for (const key of cacheRef.current.keys()) {
      if (!keysToKeep.includes(key)) {
        cacheRef.current.delete(key);
        lastAccessRef.current.delete(key);
      }
    }
  }, [estimateMemoryUsage, CACHE_DURATION, MAX_CACHE_SIZE, MEMORY_THRESHOLD]);

  const setCacheData = useCallback((data, metadata = {}) => {
    if (!enableCache || !gridName) return;

    const cacheKey = `${gridName}_${JSON.stringify(metadata)}`;
    const cacheEntry = {
      data,
      metadata,
      timestamp: Date.now(),
      version: metadata.version || 1
    };

    cacheRef.current.set(cacheKey, cacheEntry);
    lastAccessRef.current.set(cacheKey, Date.now());

    setCacheDataState(data);
    setCacheMetadata(metadata);

    // Cleanup old cache entries
    if (cacheRef.current.size > MAX_CACHE_SIZE) {
      cleanupOldCache();
    }
  }, [enableCache, gridName, cleanupOldCache, MAX_CACHE_SIZE]);

  const getCacheData = useCallback((metadata = {}) => {
    if (!enableCache || !gridName) return null;

    const cacheKey = `${gridName}_${JSON.stringify(metadata)}`;
    const cacheEntry = cacheRef.current.get(cacheKey);

    if (cacheEntry) {
      const now = Date.now();
      if (now - cacheEntry.timestamp < CACHE_DURATION) {
        lastAccessRef.current.set(cacheKey, now);
        return cacheEntry.data;
      } else {
        // Cache expired
        cacheRef.current.delete(cacheKey);
        lastAccessRef.current.delete(cacheKey);
      }
    }

    return null;
  }, [enableCache, gridName, CACHE_DURATION]);

  const clearCache = useCallback((specificKey = null) => {
    if (specificKey) {
      const cacheKey = `${gridName}_${JSON.stringify(specificKey)}`;
      cacheRef.current.delete(cacheKey);
      lastAccessRef.current.delete(cacheKey);
    } else {
      // Clear all cache for this grid
      for (const key of cacheRef.current.keys()) {
        if (key.startsWith(gridName)) {
          cacheRef.current.delete(key);
          lastAccessRef.current.delete(key);
        }
      }
    }
    setCacheDataState(null);
    setCacheMetadata({});
  }, [gridName]);

  const invalidateCache = useCallback((pattern = null) => {
    if (pattern) {
      for (const key of cacheRef.current.keys()) {
        if (key.includes(pattern)) {
          cacheRef.current.delete(key);
          lastAccessRef.current.delete(key);
        }
      }
    } else {
      clearCache();
    }
  }, [clearCache]);

  // Periodic cleanup
  useEffect(() => {
    const interval = setInterval(cleanupOldCache, 60000); // Cleanup every minute
    return () => clearInterval(interval);
  }, [cleanupOldCache]);

  return {
    cacheData,
    cacheMetadata,
    setCacheData,
    getCacheData,
    clearCache,
    invalidateCache,
    cacheStats: {
      size: cacheRef.current.size,
      memoryUsage: Array.from(cacheRef.current.values())
        .reduce((total, entry) => total + estimateMemoryUsage(entry.data), 0)
    }
  };
};

export default useGridCache;

import { useState, useCallback, useEffect, useRef, useMemo } from 'react';

/**
 * Performance optimization hook for large datasets
 * Provides virtualization, lazy loading, and memory management
 */
export const useGridPerformance = (options = {}) => {
  const {
    data = [],
    pageSize = 100,
    virtualizeThreshold = 1000,
    enableVirtualization = true,
    enableLazyLoading = true,
    enableMemoryOptimization = true,
    onLoadMore,
    getRowHeight = () => 52
  } = options;

  const [virtualizedData, setVirtualizedData] = useState([]);
  const [loadedPages, setLoadedPages] = useState(new Set([0]));
  const [isLoading, setIsLoading] = useState(false);
  const [visibleRange, setVisibleRange] = useState({ start: 0, end: pageSize });

  const scrollElementRef = useRef(null);
  const observerRef = useRef(null);
  const loadingRef = useRef(false);
  const memoryUsageRef = useRef(0);

  // Memory monitoring
  const estimateMemoryUsage = useCallback((dataSet) => {
    try {
      return JSON.stringify(dataSet).length * 2; // Rough estimate in bytes
    } catch {
      return dataSet.length * 1000; // Fallback estimate
    }
  }, []);

  // Virtualization calculations
  const virtualConfig = useMemo(() => {
    if (!enableVirtualization || data.length < virtualizeThreshold) {
      return {
        shouldVirtualize: false,
        itemHeight: getRowHeight(),
        containerHeight: data.length * getRowHeight(),
        visibleCount: data.length
      };
    }

    const itemHeight = getRowHeight();
    const containerHeight = window.innerHeight - 200; // Account for headers/footers
    const visibleCount = Math.ceil(containerHeight / itemHeight) + 5; // Buffer

    return {
      shouldVirtualize: true,
      itemHeight,
      containerHeight: data.length * itemHeight,
      visibleCount,
      overscan: 5
    };
  }, [data.length, enableVirtualization, virtualizeThreshold, getRowHeight]);

  // Lazy loading implementation
  const loadPage = useCallback(async (pageIndex) => {
    if (!enableLazyLoading || loadingRef.current || loadedPages.has(pageIndex)) {
      return;
    }

    loadingRef.current = true;
    setIsLoading(true);

    try {
      if (onLoadMore) {
        await onLoadMore({
          page: pageIndex,
          pageSize,
          offset: pageIndex * pageSize
        });
      }

      setLoadedPages(prev => new Set([...prev, pageIndex]));
    } catch (error) {
      console.error('Failed to load page:', pageIndex, error);
    } finally {
      loadingRef.current = false;
      setIsLoading(false);
    }
  }, [enableLazyLoading, loadedPages, onLoadMore, pageSize]);

  // Intersection observer for lazy loading
  useEffect(() => {
    if (!enableLazyLoading || !scrollElementRef.current) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const pageIndex = parseInt(entry.target.dataset.page, 10);
            if (!isNaN(pageIndex)) {
              loadPage(pageIndex);
            }
          }
        });
      },
      {
        root: scrollElementRef.current,
        rootMargin: '100px',
        threshold: 0.1
      }
    );

    observerRef.current = observer;

    return () => {
      observer.disconnect();
    };
  }, [enableLazyLoading, loadPage]);

  // Virtualized data calculation
  useEffect(() => {
    if (!virtualConfig.shouldVirtualize) {
      setVirtualizedData(data);
      return;
    }

    const { start, end } = visibleRange;
    const virtualizedSlice = data.slice(
      Math.max(0, start - virtualConfig.overscan),
      Math.min(data.length, end + virtualConfig.overscan)
    );

    setVirtualizedData(virtualizedSlice);
  }, [data, visibleRange, virtualConfig]);

  // Memory optimization
  useEffect(() => {
    if (!enableMemoryOptimization) return;

    const currentMemoryUsage = estimateMemoryUsage(virtualizedData);
    memoryUsageRef.current = currentMemoryUsage;

    // Memory threshold check (50MB)
    const MEMORY_THRESHOLD = 50 * 1024 * 1024;

    if (currentMemoryUsage > MEMORY_THRESHOLD) {
      console.warn('Grid memory usage high:', currentMemoryUsage / 1024 / 1024, 'MB');

      // Trigger garbage collection hint
      if (window.gc) {
        window.gc();
      }

      // Reduce visible range if possible
      if (virtualConfig.shouldVirtualize) {
        setVisibleRange(prev => ({
          start: prev.start,
          end: Math.min(prev.end, prev.start + Math.floor(virtualConfig.visibleCount * 0.8))
        }));
      }
    }
  }, [virtualizedData, enableMemoryOptimization, estimateMemoryUsage, virtualConfig]);

  // Scroll handler for virtualization
  const handleScroll = useCallback((event) => {
    if (!virtualConfig.shouldVirtualize) return;

    const scrollTop = event.target.scrollTop;
    const { itemHeight, visibleCount } = virtualConfig;

    const startIndex = Math.floor(scrollTop / itemHeight);
    const endIndex = Math.min(data.length, startIndex + visibleCount);

    setVisibleRange({ start: startIndex, end: endIndex });

    // Lazy loading trigger
    if (enableLazyLoading) {
      const currentPage = Math.floor(endIndex / pageSize);
      const nextPage = currentPage + 1;

      if (!loadedPages.has(nextPage) && nextPage * pageSize < data.length + pageSize) {
        loadPage(nextPage);
      }
    }
  }, [virtualConfig, data.length, enableLazyLoading, pageSize, loadedPages, loadPage]);

  // Scroll to item
  const scrollToItem = useCallback((index) => {
    if (!scrollElementRef.current || !virtualConfig.shouldVirtualize) return;

    const scrollTop = index * virtualConfig.itemHeight;
    scrollElementRef.current.scrollTop = scrollTop;
  }, [virtualConfig]);

  // Get visible items with positioning
  const getVisibleItems = useCallback(() => {
    if (!virtualConfig.shouldVirtualize) {
      return virtualizedData.map((item, index) => ({
        item,
        index,
        style: {}
      }));
    }

    const { start } = visibleRange;
    const { itemHeight } = virtualConfig;

    return virtualizedData.map((item, virtualIndex) => {
      const actualIndex = start - virtualConfig.overscan + virtualIndex;
      return {
        item,
        index: actualIndex,
        style: {
          position: 'absolute',
          top: actualIndex * itemHeight,
          height: itemHeight,
          width: '100%'
        }
      };
    });
  }, [virtualizedData, virtualConfig, visibleRange]);

  // Performance metrics
  const getPerformanceMetrics = useCallback(() => {
    return {
      totalItems: data.length,
      virtualizedItems: virtualizedData.length,
      memoryUsage: memoryUsageRef.current,
      memoryUsageMB: Math.round(memoryUsageRef.current / 1024 / 1024 * 100) / 100,
      isVirtualized: virtualConfig.shouldVirtualize,
      loadedPages: loadedPages.size,
      visibleRange,
      itemHeight: virtualConfig.itemHeight
    };
  }, [data.length, virtualizedData.length, virtualConfig, loadedPages.size, visibleRange]);

  // Cleanup
  useEffect(() => {
    return () => {
      if (observerRef.current) {
        observerRef.current.disconnect();
      }
    };
  }, []);

  return {
    // Data
    virtualizedData,
    visibleItems: getVisibleItems(),

    // Configuration
    virtualConfig,
    shouldVirtualize: virtualConfig.shouldVirtualize,

    // State
    isLoading,
    loadedPages,
    visibleRange,

    // Handlers
    handleScroll,
    scrollToItem,
    loadPage,

    // Refs
    scrollElementRef,

    // Metrics
    getPerformanceMetrics,

    // Utils
    estimateMemoryUsage
  };
};

/**
 * Hook for optimizing column rendering
 */
export const useColumnOptimization = (columns = [], visibleColumns = {}) => {
  const optimizedColumns = useMemo(() => {
    return columns.filter(col => {
      // Hide columns that are explicitly hidden
      if (visibleColumns[col.field] === false) {
        return false;
      }

      // Always show pinned columns
      if (col.pinned) {
        return true;
      }

      return true;
    }).map(col => ({
      ...col,
      // Optimize cell rendering for large datasets
      renderCell: col.renderCell ? (params) => {
        // Memoize cell content
        return React.memo(col.renderCell)(params);
      } : undefined
    }));
  }, [columns, visibleColumns]);

  return optimizedColumns;
};

/**
 * Hook for debounced search/filter operations
 */
export const useDebounceFilter = (initialValue = '', delay = 300) => {
  const [value, setValue] = useState(initialValue);
  const [debouncedValue, setDebouncedValue] = useState(initialValue);
  const timeoutRef = useRef(null);

  useEffect(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }

    timeoutRef.current = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, [value, delay]);

  const clearFilter = useCallback(() => {
    setValue('');
    setDebouncedValue('');
  }, []);

  return {
    value,
    debouncedValue,
    setValue,
    clearFilter,
    isDebouncing: value !== debouncedValue
  };
};

export default useGridPerformance;

import { useState, useCallback, useEffect, useRef, useMemo } from 'react';

/**
 * Enhanced Grid State Management Hook with Performance Optimizations
 * Manages all grid state with persistence, synchronization, and memoization
 */
export const useGridState = (gridName, options = {}) => {
  const {
    enablePersistence = true,
    serverSide = false,
    onStateChange,
    initialState = {}
  } = options;

  // Performance optimization: memoize options to prevent unnecessary re-renders
  const memoizedOptions = useMemo(() => ({
    enablePersistence,
    serverSide,
    onStateChange,
    initialState
  }), [enablePersistence, serverSide, onStateChange, initialState]);

  // Debounce timer for state persistence
  const persistenceTimerRef = useRef(null);
  const lastPersistedStateRef = useRef(null);

  // Enhanced state management with better defaults
  const [paginationModel, setPaginationModelState] = useState(
    initialState.paginationModel || { page: 0, pageSize: 25 }
  );
  const [sortModel, setSortModelState] = useState(
    initialState.sortModel || []
  );
  const [filterModel, setFilterModelState] = useState(
    initialState.filterModel || { items: [] }
  );
  const [selectedRows, setSelectedRowsState] = useState(
    initialState.selectedRows || []
  );
  const [columnVisibility, setColumnVisibilityState] = useState(
    initialState.columnVisibility || {}
  );
  const [density, setDensityState] = useState(
    initialState.density || 'standard'
  );
  const [columnOrder, setColumnOrderState] = useState(
    initialState.columnOrder || []
  );
  const [pinnedColumns, setPinnedColumnsState] = useState(
    initialState.pinnedColumns || { left: [], right: [] }
  );

  // Additional state for enhanced functionality
  const [viewMode, setViewModeState] = useState(
    initialState.viewMode || 'grid'
  );
  const [searchValue, setSearchValueState] = useState(
    initialState.searchValue || ''
  );
  const [filtersVisible, setFiltersVisibleState] = useState(
    initialState.filtersVisible || false
  );

  const stateRef = useRef({
    paginationModel,
    sortModel,
    filterModel,
    selectedRows,
    columnVisibility,
    density,
    columnOrder,
    pinnedColumns,
    viewMode,
    searchValue,
    filtersVisible
  });

  // Update ref when state changes
  useEffect(() => {
    stateRef.current = {
      paginationModel,
      sortModel,
      filterModel,
      selectedRows,
      columnVisibility,
      density,
      columnOrder,
      pinnedColumns
    };
  }, [paginationModel, sortModel, filterModel, selectedRows, columnVisibility, density, columnOrder, pinnedColumns]);

  // Persistence helpers
  const getStorageKey = useCallback((key) => `grid_${gridName}_${key}`, [gridName]);

  // Debounced save to storage for performance
  const saveToStorage = useCallback((key, value) => {
    if (!enablePersistence || !gridName) return;

    // Clear existing timer
    if (persistenceTimerRef.current) {
      clearTimeout(persistenceTimerRef.current);
    }

    // Debounce the save operation
    persistenceTimerRef.current = setTimeout(() => {
      try {
        const serializedValue = JSON.stringify(value);
        // Only save if value actually changed
        if (lastPersistedStateRef.current?.[key] !== serializedValue) {
          localStorage.setItem(getStorageKey(key), serializedValue);
          if (!lastPersistedStateRef.current) {
            lastPersistedStateRef.current = {};
          }
          lastPersistedStateRef.current[key] = serializedValue;
        }
      } catch (error) {
        console.warn(`Failed to save grid state for ${key}:`, error);
      }
    }, 300); // 300ms debounce
  }, [enablePersistence, gridName, getStorageKey]);

  const loadFromStorage = useCallback((key, defaultValue) => {
    if (!enablePersistence || !gridName) return defaultValue;
    try {
      const stored = localStorage.getItem(getStorageKey(key));
      return stored ? JSON.parse(stored) : defaultValue;
    } catch (error) {
      console.warn(`Failed to load grid state for ${key}:`, error);
      return defaultValue;
    }
  }, [enablePersistence, gridName, getStorageKey]);

  // Load initial state from storage
  useEffect(() => {
    if (!enablePersistence || !gridName) return;

    const storedPagination = loadFromStorage('pagination', paginationModel);
    const storedSort = loadFromStorage('sort', sortModel);
    const storedFilter = loadFromStorage('filter', filterModel);
    const storedColumnVisibility = loadFromStorage('columnVisibility', columnVisibility);
    const storedDensity = loadFromStorage('density', density);
    const storedColumnOrder = loadFromStorage('columnOrder', columnOrder);
    const storedPinnedColumns = loadFromStorage('pinnedColumns', pinnedColumns);

    setPaginationModelState(storedPagination);
    setSortModelState(storedSort);
    setFilterModelState(storedFilter);
    setColumnVisibilityState(storedColumnVisibility);
    setDensityState(storedDensity);
    setColumnOrderState(storedColumnOrder);
    setPinnedColumnsState(storedPinnedColumns);
  }, [gridName, enablePersistence]); // Only run on mount

  // Enhanced setters with persistence and callbacks
  const setPaginationModel = useCallback((newModel) => {
    setPaginationModelState(newModel);
    saveToStorage('pagination', newModel);
    onStateChange?.({ type: 'pagination', value: newModel, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setSortModel = useCallback((newModel) => {
    setSortModelState(newModel);
    saveToStorage('sort', newModel);
    onStateChange?.({ type: 'sort', value: newModel, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setFilterModel = useCallback((newModel) => {
    setFilterModelState(newModel);
    saveToStorage('filter', newModel);
    onStateChange?.({ type: 'filter', value: newModel, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setSelectedRows = useCallback((newSelection) => {
    setSelectedRowsState(newSelection);
    onStateChange?.({ type: 'selection', value: newSelection, state: stateRef.current });
  }, [onStateChange]);

  const setColumnVisibility = useCallback((newVisibility) => {
    setColumnVisibilityState(newVisibility);
    saveToStorage('columnVisibility', newVisibility);
    onStateChange?.({ type: 'columnVisibility', value: newVisibility, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setDensity = useCallback((newDensity) => {
    setDensityState(newDensity);
    saveToStorage('density', newDensity);
    onStateChange?.({ type: 'density', value: newDensity, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setColumnOrder = useCallback((newOrder) => {
    setColumnOrderState(newOrder);
    saveToStorage('columnOrder', newOrder);
    onStateChange?.({ type: 'columnOrder', value: newOrder, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setPinnedColumns = useCallback((newPinned) => {
    setPinnedColumnsState(newPinned);
    saveToStorage('pinnedColumns', newPinned);
    onStateChange?.({ type: 'pinnedColumns', value: newPinned, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  // Enhanced setters for new state
  const setViewMode = useCallback((newMode) => {
    setViewModeState(newMode);
    saveToStorage('viewMode', newMode);
    onStateChange?.({ type: 'viewMode', value: newMode, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  const setSearchValue = useCallback((newValue) => {
    setSearchValueState(newValue);
    // Don't persist search value as it's typically temporary
    onStateChange?.({ type: 'searchValue', value: newValue, state: stateRef.current });
  }, [onStateChange]);

  const setFiltersVisible = useCallback((newVisible) => {
    setFiltersVisibleState(newVisible);
    saveToStorage('filtersVisible', newVisible);
    onStateChange?.({ type: 'filtersVisible', value: newVisible, state: stateRef.current });
  }, [saveToStorage, onStateChange]);

  // Utility functions
  const resetState = useCallback(() => {
    const defaultState = {
      paginationModel: { page: 0, pageSize: 25 },
      sortModel: [],
      filterModel: { items: [] },
      selectedRows: [],
      columnVisibility: {},
      density: 'standard',
      columnOrder: [],
      pinnedColumns: { left: [], right: [] }
    };

    setPaginationModelState(defaultState.paginationModel);
    setSortModelState(defaultState.sortModel);
    setFilterModelState(defaultState.filterModel);
    setSelectedRowsState(defaultState.selectedRows);
    setColumnVisibilityState(defaultState.columnVisibility);
    setDensityState(defaultState.density);
    setColumnOrderState(defaultState.columnOrder);
    setPinnedColumnsState(defaultState.pinnedColumns);

    // Clear storage
    if (enablePersistence && gridName) {
      Object.keys(defaultState).forEach(key => {
        localStorage.removeItem(getStorageKey(key));
      });
    }
  }, [enablePersistence, gridName, getStorageKey]);

  const exportState = useCallback(() => {
    return {
      paginationModel,
      sortModel,
      filterModel,
      selectedRows,
      columnVisibility,
      density,
      columnOrder,
      pinnedColumns
    };
  }, [paginationModel, sortModel, filterModel, selectedRows, columnVisibility, density, columnOrder, pinnedColumns]);

  const importState = useCallback((state) => {
    if (state.paginationModel) setPaginationModel(state.paginationModel);
    if (state.sortModel) setSortModel(state.sortModel);
    if (state.filterModel) setFilterModel(state.filterModel);
    if (state.selectedRows) setSelectedRows(state.selectedRows);
    if (state.columnVisibility) setColumnVisibility(state.columnVisibility);
    if (state.density) setDensity(state.density);
    if (state.columnOrder) setColumnOrder(state.columnOrder);
    if (state.pinnedColumns) setPinnedColumns(state.pinnedColumns);
  }, [setPaginationModel, setSortModel, setFilterModel, setSelectedRows, setColumnVisibility, setDensity, setColumnOrder, setPinnedColumns]);

  return {
    // State values
    paginationModel,
    sortModel,
    filterModel,
    selectedRows,
    columnVisibility,
    density,
    columnOrder,
    pinnedColumns,
    viewMode,
    searchValue,
    filtersVisible,

    // State setters
    setPaginationModel,
    setSortModel,
    setFilterModel,
    setSelectedRows,
    setColumnVisibility,
    setDensity,
    setColumnOrder,
    setPinnedColumns,
    setViewMode,
    setSearchValue,
    setFiltersVisible,

    // Utility functions
    resetState,
    exportState,
    importState,

    // State reference for callbacks
    stateRef
  };
};

export default useGridState;

/**
 * Hash Parameters Hook for TECHNO-ETL
 * Handles hash-based routing parameters for dashboard navigation
 */
import { useState, useEffect, useCallback } from 'react';
import { useLocation } from 'react-router-dom';

/**
 * Custom hook to handle hash-based parameters
 * @returns {Object} { params, setParams, clearParams, updateParams }
 */
export const useHashParams = () => {
  const location = useLocation();
  const [params, setParams] = useState({});

  // Parse hash parameters from URL
  const parseHashParams = useCallback((hash) => {
    if (!hash || hash === '#') return {};

    try {
      // Remove the # symbol and decode
      const encodedParams = hash.substring(1);
      const decodedParams = atob(encodedParams);
      return JSON.parse(decodedParams);
    } catch (error) {
      console.warn('Failed to parse hash parameters:', error);
      return {};
    }
  }, []);

  // Encode parameters to hash
  const encodeToHash = useCallback((params) => {
    if (!params || Object.keys(params).length === 0) return '';

    try {
      const encodedParams = btoa(JSON.stringify(params));
      return '#' + encodedParams;
    } catch (error) {
      console.warn('Failed to encode hash parameters:', error);
      return '';
    }
  }, []);

  // Update URL hash without navigation
  const updateUrlHash = useCallback((newParams) => {
    const hash = encodeToHash(newParams);
    const newUrl = window.location.pathname + window.location.search + hash;
    window.history.replaceState(null, '', newUrl);
  }, [encodeToHash]);

  // Parse parameters on location change and initial load
  useEffect(() => {
    const parsedParams = parseHashParams(location.hash);
    console.log('Hash params parsed:', location.hash, parsedParams); // Debug log
    setParams(parsedParams);
  }, [location.hash, parseHashParams]);

  // Initial load - parse hash immediately
  useEffect(() => {
    const initialHash = window.location.hash;
    if (initialHash) {
      const parsedParams = parseHashParams(initialHash);
      console.log('Initial hash params:', initialHash, parsedParams); // Debug log
      setParams(parsedParams);
    }
  }, [parseHashParams]);

  // Update parameters and URL
  const updateParams = useCallback((newParams, replace = false) => {
    const updatedParams = replace ? newParams : { ...params, ...newParams };
    setParams(updatedParams);
    updateUrlHash(updatedParams);
  }, [params, updateUrlHash]);

  // Clear all parameters
  const clearParams = useCallback(() => {
    setParams({});
    updateUrlHash({});
  }, [updateUrlHash]);

  // Get specific parameter with default value
  const getParam = useCallback((key, defaultValue = null) => {
    return params[key] !== undefined ? params[key] : defaultValue;
  }, [params]);

  // Check if parameter exists
  const hasParam = useCallback((key) => {
    return params.hasOwnProperty(key);
  }, [params]);

  // Remove specific parameter
  const removeParam = useCallback((key) => {
    const newParams = { ...params };
    delete newParams[key];
    setParams(newParams);
    updateUrlHash(newParams);
  }, [params, updateUrlHash]);

  return {
    params,
    setParams: updateParams,
    clearParams,
    updateParams,
    getParam,
    hasParam,
    removeParam,
    encodeToHash,
    parseHashParams
  };
};

