import { useContext, useCallback, useMemo } from 'react';
import { usePermissions as usePermissionContext } from '../contexts/PermissionContext';

/**
 * Custom hook for permission checking
 * Provides convenient methods for checking user permissions
 */
export const usePermissions = () => {
    const context = usePermissionContext();

    if (!context) {
        throw new Error('usePermissions must be used within a PermissionProvider');
    }

    const {
        permissions,
        hasPermission,
        filterMenuItems,
        canAccessMenuItem,
        getPermissionSummary,
        isAdmin,
        canPerformBulkOperations,
        refreshPermissions,
        loading,
        initialized
    } = context;

    // Convenience methods for common permission checks
    const canView = useCallback((resource = '*') => {
        return hasPermission('view', resource);
    }, [hasPermission]);

    const canEdit = useCallback((resource = '*') => {
        return hasPermission('edit', resource);
    }, [hasPermission]);

    const canDelete = useCallback((resource = '*') => {
        return hasPermission('delete', resource);
    }, [hasPermission]);

    const canAdd = useCallback((resource = '*') => {
        return hasPermission('add', resource);
    }, [hasPermission]);

    const canManageUsers = useCallback(() => {
        return hasPermission('manage_users');
    }, [hasPermission]);

    const canAssignRoles = useCallback(() => {
        return hasPermission('assign_roles');
    }, [hasPermission]);

    // Check multiple permissions at once
    const hasAnyPermission = useCallback((permissionChecks) => {
        return permissionChecks.some(({ action, resource }) => 
            hasPermission(action, resource)
        );
    }, [hasPermission]);

    const hasAllPermissions = useCallback((permissionChecks) => {
        return permissionChecks.every(({ action, resource }) => 
            hasPermission(action, resource)
        );
    }, [hasPermission]);

    // Get CRUD permissions for a resource
    const getCrudPermissions = useCallback((resource = '*') => {
        return {
            canView: hasPermission('view', resource),
            canEdit: hasPermission('edit', resource),
            canDelete: hasPermission('delete', resource),
            canAdd: hasPermission('add', resource)
        };
    }, [hasPermission]);

    // Memoized permission summary
    const permissionSummary = useMemo(() => {
        if (!initialized) return null;
        return getPermissionSummary();
    }, [initialized, getPermissionSummary]);

    return {
        // State
        permissions,
        loading,
        initialized,
        permissionSummary,

        // Basic permission checks
        hasPermission,
        canView,
        canEdit,
        canDelete,
        canAdd,

        // Advanced permission checks
        hasAnyPermission,
        hasAllPermissions,
        getCrudPermissions,

        // Admin functions
        canManageUsers,
        canAssignRoles,
        isAdmin,
        canPerformBulkOperations,

        // Menu functions
        filterMenuItems,
        canAccessMenuItem,

        // Utility functions
        refreshPermissions
    };
};

export default usePermissions;

/**
 * Standardized Error Handling Hook
 * Provides consistent error handling across all components
 * 
 * @author Mounir Abderrahmani
 * @email mounir.ab@techno-dz.com
 * @contact mounir.webdev.tms@gmail.com
 */

import { useState, useCallback, useEffect } from 'react';
import { toast } from 'react-toastify';
import { handleError, getFallbackData } from '../utils/errorHandler.js';

/**
 * Standard error handling hook for components
 * @param {string} componentName - Name of the component using this hook
 * @param {Object} options - Configuration options
 * @returns {Object} Error handling utilities
 */
export const useStandardErrorHandling = (componentName, options = {}) => {
  const {
    showToast = true,
    fallbackDataType = null,
    maxRetries = 3,
    retryDelay = 1000,
    onError = null,
    onRetry = null
  } = options;

  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const [lastOperation, setLastOperation] = useState(null);

  /**
   * Handle error with standardized processing
   */
  const handleComponentError = useCallback((err, context = {}) => {
    const errorInfo = handleError(err, {
      componentName,
      ...context
    });

    setError(errorInfo);

    // Call custom error handler if provided
    if (onError) {
      onError(errorInfo, err);
    }

    // Don't show toast if disabled or if it's a low severity error
    if (!showToast || errorInfo.severity === 'low') {
      return errorInfo;
    }

    return errorInfo;
  }, [componentName, showToast, onError]);

  /**
   * Clear error state
   */
  const clearError = useCallback(() => {
    setError(null);
    setRetryCount(0);
  }, []);

  /**
   * Retry last operation
   */
  const retry = useCallback(async () => {
    if (!lastOperation || retryCount >= maxRetries) {
      return;
    }

    setRetryCount(prev => prev + 1);
    clearError();

    if (onRetry) {
      onRetry(retryCount + 1);
    }

    // Add delay before retry
    if (retryDelay > 0) {
      await new Promise(resolve => setTimeout(resolve, retryDelay * (retryCount + 1)));
    }

    try {
      return await lastOperation();
    } catch (err) {
      handleComponentError(err, { isRetry: true, retryCount: retryCount + 1 });
      throw err;
    }
  }, [lastOperation, retryCount, maxRetries, retryDelay, onRetry, clearError, handleComponentError]);

  /**
   * Execute async operation with error handling
   */
  const executeWithErrorHandling = useCallback(async (operation, context = {}) => {
    setLoading(true);
    setLastOperation(() => operation);
    clearError();

    try {
      const result = await operation();
      return result;
    } catch (err) {
      handleComponentError(err, context);

      // Return fallback data if specified
      if (fallbackDataType) {
        return getFallbackData(fallbackDataType);
      }

      throw err;
    } finally {
      setLoading(false);
    }
  }, [handleComponentError, clearError, fallbackDataType]);

  /**
   * Get fallback data for the component
   */
  const getFallback = useCallback(() => {
    return fallbackDataType ? getFallbackData(fallbackDataType) : null;
  }, [fallbackDataType]);

  /**
   * Check if can retry
   */
  const canRetry = retryCount < maxRetries && lastOperation !== null;

  /**
   * Get error message for display
   */
  const getErrorMessage = useCallback(() => {
    if (!error) return null;
    return error.message || 'An unexpected error occurred';
  }, [error]);

  /**
   * Check if error is critical
   */
  const isCriticalError = error?.severity === 'critical' || error?.severity === 'high';

  return {
    // State
    error,
    loading,
    retryCount,
    canRetry,
    isCriticalError,

    // Actions
    handleError: handleComponentError,
    clearError,
    retry,
    executeWithErrorHandling,
    getFallback,
    getErrorMessage,

    // Utilities
    isError: !!error,
    hasRetried: retryCount > 0,
    maxRetriesReached: retryCount >= maxRetries
  };
};

/**
 * Hook for data fetching with error handling
 */
export const useDataFetching = (componentName, options = {}) => {
  const errorHandling = useStandardErrorHandling(componentName, options);
  const [data, setData] = useState(options.initialData || null);
  const [initialized, setInitialized] = useState(false);

  /**
   * Fetch data with error handling
   */
  const fetchData = useCallback(async (fetchFunction, context = {}) => {
    try {
      const result = await errorHandling.executeWithErrorHandling(fetchFunction, context);
      setData(result);
      setInitialized(true);
      return result;
    } catch (err) {
      // Error already handled by executeWithErrorHandling
      if (options.fallbackDataType) {
        const fallback = errorHandling.getFallback();
        setData(fallback);
        setInitialized(true);
        return fallback;
      }
      throw err;
    }
  }, [errorHandling, options.fallbackDataType]);

  /**
   * Refresh data
   */
  const refresh = useCallback(async () => {
    if (errorHandling.lastOperation) {
      return await fetchData(errorHandling.lastOperation);
    }
  }, [fetchData, errorHandling.lastOperation]);

  return {
    ...errorHandling,
    data,
    setData,
    fetchData,
    refresh,
    initialized,
    isEmpty: initialized && (!data || (Array.isArray(data) && data.length === 0))
  };
};

/**
 * Hook for form handling with error handling
 */
export const useFormErrorHandling = (componentName, options = {}) => {
  const errorHandling = useStandardErrorHandling(componentName, {
    ...options,
    showToast: false // Forms usually show inline errors
  });

  const [fieldErrors, setFieldErrors] = useState({});

  /**
   * Handle form submission with error handling
   */
  const handleSubmit = useCallback(async (submitFunction, formData, context = {}) => {
    setFieldErrors({});

    try {
      return await errorHandling.executeWithErrorHandling(
        () => submitFunction(formData),
        { ...context, formData }
      );
    } catch (err) {
      // Handle validation errors
      if (err.status === 400 && err.response?.data?.errors) {
        setFieldErrors(err.response.data.errors);
      }
      throw err;
    }
  }, [errorHandling]);

  /**
   * Clear field errors
   */
  const clearFieldErrors = useCallback(() => {
    setFieldErrors({});
  }, []);

  /**
   * Set field error
   */
  const setFieldError = useCallback((field, message) => {
    setFieldErrors(prev => ({
      ...prev,
      [field]: message
    }));
  }, []);

  return {
    ...errorHandling,
    fieldErrors,
    handleSubmit,
    clearFieldErrors,
    setFieldError,
    hasFieldErrors: Object.keys(fieldErrors).length > 0
  };
};

export default useStandardErrorHandling;

/**
 * Enhanced User Settings Hook
 * Provides comprehensive user settings management with system defaults
 */

import { useCallback, useEffect, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useCustomTheme } from '../contexts/ThemeContext';
import { useLanguage } from '../contexts/LanguageContext';
import { useSettings } from '../contexts/SettingsContext';
import { toast } from 'react-toastify';
import { saveUserSettings } from '../utils/unifiedSettingsManager';

export const useUserSettings = () => {
  const { currentUser } = useAuth();
  const { mode, setThemeMode, fontSize, setFontSize, applyUserThemeSettings } = useCustomTheme();
  const { currentLanguage, setLanguage, applyUserLanguageSettings } = useLanguage();
  const { settings, updateSettings, saveSettings, loading } = useSettings();

  const [isInitialized, setIsInitialized] = useState(false);

  /**
   * Apply system defaults when no user is logged in
   */
  const applySystemDefaults = useCallback(() => {
    // Detect system theme preference
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    setThemeMode(systemPrefersDark ? 'dark' : 'light');

    // Detect browser language
    const browserLang = navigator.language.split('-')[0];
    const supportedLanguages = ['en', 'fr', 'ar'];
    const detectedLanguage = supportedLanguages.includes(browserLang) ? browserLang : 'en';
    setLanguage(detectedLanguage);

    // Set default font size
    setFontSize('medium');

    console.log('Applied system defaults:', {
      theme: systemPrefersDark ? 'dark' : 'light',
      language: detectedLanguage,
      fontSize: 'medium'
    });
  }, [setThemeMode, setLanguage, setFontSize]);

  /**
   * Apply user settings after login
   */
  const applyUserSettings = useCallback((userSettings) => {
    if (!userSettings?.preferences) return;

    const { preferences } = userSettings;

    try {
      // Apply theme settings
      if (preferences.theme) {
        if (preferences.theme === 'system') {
          const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
          setThemeMode(systemPrefersDark ? 'dark' : 'light');
        } else {
          setThemeMode(preferences.theme);
        }
      }

      // Apply language settings
      if (preferences.language) {
        setLanguage(preferences.language);
      }

      // Apply font size settings
      if (preferences.fontSize) {
        setFontSize(preferences.fontSize);
      }

      console.log('Applied user settings:', preferences);

    } catch (error) {
      console.error('Error applying user settings:', error);
      toast.error('Failed to apply some user preferences');
    }
  }, [setThemeMode, setLanguage, setFontSize]);

  /**
   * Save current preferences to user settings
   */
  const saveCurrentPreferences = useCallback(async () => {
    if (!currentUser) return;

    const currentPreferences = {
      theme: mode,
      language: currentLanguage,
      fontSize: fontSize
    };

    try {
      await updateSettings({ preferences: currentPreferences }, 'preferences');
      await saveSettings();

      // Save through unified settings manager
      saveUserSettings(currentUser.uid, { preferences: currentPreferences });

      return { success: true };
    } catch (error) {
      console.error('Error saving preferences:', error);
      return { success: false, error: error.message };
    }
  }, [currentUser, mode, currentLanguage, fontSize, updateSettings, saveSettings]);

  /**
   * Reset to system defaults
   */
  const resetToSystemDefaults = useCallback(() => {
    applySystemDefaults();

    if (currentUser) {
      // Update user settings to reflect system defaults
      const systemDefaults = {
        theme: 'system',
        language: navigator.language.split('-')[0] === 'fr' ? 'fr' : 'en',
        fontSize: 'medium'
      };

      updateSettings({ preferences: systemDefaults }, 'preferences');
    }

    toast.info('Settings reset to system defaults');
  }, [applySystemDefaults, currentUser, updateSettings]);

  /**
   * Initialize settings based on user state
   */
  useEffect(() => {
    if (!isInitialized) {
      if (currentUser) {
        // User is logged in - apply their settings
        if (settings?.preferences) {
          applyUserSettings(settings);
        }
      } else {
        // No user logged in - apply system defaults
        applySystemDefaults();
      }
      setIsInitialized(true);
    }
  }, [currentUser, settings, applyUserSettings, applySystemDefaults, isInitialized]);

  /**
   * Listen for system theme changes
   */
  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

    const handleSystemThemeChange = (e) => {
      // Only apply if user preference is set to 'system' or no user is logged in
      const shouldFollowSystem = !currentUser || settings?.preferences?.theme === 'system';

      if (shouldFollowSystem) {
        setThemeMode(e.matches ? 'dark' : 'light');
      }
    };

    mediaQuery.addEventListener('change', handleSystemThemeChange);
    return () => mediaQuery.removeEventListener('change', handleSystemThemeChange);
  }, [currentUser, settings?.preferences?.theme, setThemeMode]);

  /**
   * Auto-save preferences when they change (for logged-in users)
   */
  useEffect(() => {
    if (currentUser && isInitialized) {
      const timeoutId = setTimeout(() => {
        saveCurrentPreferences();
      }, 2000); // 2-second debounce

      return () => clearTimeout(timeoutId);
    }
  }, [currentUser, mode, currentLanguage, fontSize, isInitialized, saveCurrentPreferences]);

  return {
    // Current state
    currentUser,
    mode,
    currentLanguage,
    fontSize,
    settings,
    loading,
    isInitialized,

    // Actions
    applySystemDefaults,
    applyUserSettings,
    saveCurrentPreferences,
    resetToSystemDefaults,

    // Theme actions
    setThemeMode,
    setFontSize,

    // Language actions
    setLanguage,

    // Settings actions
    updateSettings,
    saveSettings
  };
};

/**
 * Hook for components that need to react to theme/language changes
 */
export const useAppearanceSettings = () => {
  const { mode, fontSize } = useCustomTheme();
  const { currentLanguage } = useLanguage();

  return {
    isDark: mode === 'dark',
    theme: mode,
    fontSize,
    language: currentLanguage,
    isRTL: currentLanguage === 'ar'
  };
};

/**
 * Hook for getting system preferences
 */
export const useSystemPreferences = () => {
  const [systemTheme, setSystemTheme] = useState(() => {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  });

  const [systemLanguage] = useState(() => {
    const browserLang = navigator.language.split('-')[0];
    return ['en', 'fr', 'ar'].includes(browserLang) ? browserLang : 'en';
  });

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

    const handleChange = (e) => {
      setSystemTheme(e.matches ? 'dark' : 'light');
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  return {
    systemTheme,
    systemLanguage,
    systemPrefersDark: systemTheme === 'dark'
  };
};

export default useUserSettings;

