              </IconButton>
            </Tooltip>
          </Stack>
        </Box>

        {/* Dashboard Selection */}
        <Stack direction="row" spacing={2} flexWrap="wrap">
          {Object.entries(LOOKER_DASHBOARDS).map(([key, dashboard]) => (
            <Chip
              key={key}
              icon={dashboard.icon}
              label={dashboard.title}
              variant={selectedDashboard === key ? "filled" : "outlined"}
              color={selectedDashboard === key ? "primary" : "default"}
              onClick={() => setSelectedDashboard(key)}
              sx={{ mb: 1 }}
            />
          ))}
        </Stack>
      </Paper>

      {/* Dashboard Info */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
            {currentDashboard.icon}
            <Box>
              <Typography variant="h6">{currentDashboard.title}</Typography>
              <Typography variant="body2" color="text.secondary">
                {currentDashboard.description}
              </Typography>
            </Box>
            <Chip label={currentDashboard.category} size="small" />
          </Box>
        </CardContent>
      </Card>

      {/* Dashboard Embed */}
      {dashboardVisible && (
        <ComponentErrorBoundary>
          <LookerStudioEmbed
            dashboard={currentDashboard}
            isFullscreen={false}
          />
        </ComponentErrorBoundary>
      )}

      {/* Settings Dialog */}
      <Dialog open={settingsOpen} onClose={() => setSettingsOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>Dashboard Settings</DialogTitle>
        <DialogContent>
          <Stack spacing={3} sx={{ mt: 1 }}>
            <FormControlLabel
              control={
                <Switch
                  checked={autoRefresh}
                  onChange={(e) => setAutoRefresh(e.target.checked)}
                />
              }
              label="Auto Refresh"
            />

            {autoRefresh && (
              <FormControl fullWidth>
                <InputLabel>Refresh Interval</InputLabel>
                <Select
                  value={refreshInterval}
                  label="Refresh Interval"
                  onChange={(e) => setRefreshInterval(e.target.value)}
                >
                  <MenuItem value={60}>1 minute</MenuItem>
                  <MenuItem value={300}>5 minutes</MenuItem>
                  <MenuItem value={600}>10 minutes</MenuItem>
                  <MenuItem value={1800}>30 minutes</MenuItem>
                </Select>
              </FormControl>
            )}

            <FormControl fullWidth>
              <InputLabel>Default Dashboard</InputLabel>
              <Select
                value={selectedDashboard}
                label="Default Dashboard"
                onChange={(e) => setSelectedDashboard(e.target.value)}
              >
                {Object.entries(LOOKER_DASHBOARDS).map(([key, dashboard]) => (
                  <MenuItem key={key} value={key}>
                    {dashboard.title}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setSettingsOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Container>
  );
};

