          <Tab
            icon={<RenameIcon />}
            label="Image Renaming"
            iconPosition="start"
            sx={{ gap: 1 }}
          />
          <Tab
            icon={<ResizeIcon />}
            label="Image Resizing"
            iconPosition="start"
            sx={{ gap: 1 }}
          />
          <Tab
            icon={<SettingsIcon />}
            label="Catalog Tools"
            iconPosition="start"
