            <Typography variant="h6" gutterBottom>
              Product Selection & Management
            </Typography>
          
          {/* Mode Toggle */}
          <Box sx={{ display: 'flex', gap: 2, mb: 2 }}>
            <Button
              variant={!showAllProducts ? 'contained' : 'outlined'}
              onClick={handleShowSpecificProducts}
              startIcon={<SearchIcon />}
            >
              Specific Products
            </Button>
            <Button
              variant={showAllProducts ? 'contained' : 'outlined'}
              onClick={handleShowAllProducts}
              startIcon={<ProductIcon />}
            >
              All Products
            </Button>
          </Box>

          {/* Specific Products Mode */}
          {!showAllProducts && (
            <>
              {/* Add Product ID Input */}
              <Box sx={{ display: 'flex', gap: 2, mb: 2 }}>
                <TextField
                  label="Product ID"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  onKeyPress={handleKeyPress}
                  placeholder="Enter product ID (e.g., 1140659762)"
                  size="small"
                  sx={{ minWidth: 200 }}
                />
                <Button
                  variant="contained"
                  onClick={handleAddProductId}
                  startIcon={<AddIcon />}
                  disabled={!inputValue.trim()}
                >
                  Add
                </Button>
                <Button
                  variant="outlined"
                  onClick={handleClearAll}
                  startIcon={<ClearIcon />}
                  disabled={productIds.length === 0}
                  color="warning"
                >
                  Clear All
                </Button>
                
                <Button
                  variant="outlined"
                  onClick={() => setBulkMediaDialogOpen(true)}
                  startIcon={<ImageIcon />}
