    const themeCtx = useCustomTheme();
    const theme = useMuiTheme();
    const { settings: globalSettings, updateSettings } = useSettings();
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [stats, setStats] = useState({});
    const [chartData, setChartData] = useState([]);
    const [recentOrders, setRecentOrders] = useState([]);
    const [bestSellers, setBestSellers] = useState([]);
    const [customerData, setCustomerData] = useState([]);
    const [countryData, setCountryData] = useState([]);
    const [productTypeData, setProductTypeData] = useState([]);

    useEffect(() => {
        if (!currentUser) {
            setLoading(false);
            return;
        }

        try {
            // Listen to user preferences in real-time
            const userPrefsRef = ref(database, `users/${currentUser.uid}/preferences`);
            const unsubscribe = onValue(userPrefsRef, (snapshot) => {
                const preferences = snapshot.val();
                
                if (preferences) {
                    // Apply language preference
                    if (preferences.language) {
                        setLanguage(preferences.language);
                        localStorage.setItem('userLanguage', preferences.language);
                    }
                    
                    // Apply theme preference
                    if (preferences.theme) {
                        // Only set theme if function exists and is different
                        if (typeof themeCtx.setThemeMode === 'function') {
                            themeCtx.setThemeMode(preferences.theme);
                        } else if (typeof themeCtx.setMode === 'function') {
                            themeCtx.setMode(preferences.theme);
                        } else if (typeof themeCtx.toggleTheme === 'function') {
                            if (themeCtx.mode !== preferences.theme) themeCtx.toggleTheme();
                        }
                        localStorage.setItem('theme', preferences.theme);
                    }
                } else {
                    // If no preferences found, use localStorage values or defaults
                    const localLang = localStorage.getItem('userLanguage') || 'en';
                    const localTheme = localStorage.getItem('theme') || 'light';
                    
                    setLanguage(localLang);
                    if (typeof themeCtx.setThemeMode === 'function') {
                        themeCtx.setThemeMode(localTheme);
                    } else if (typeof themeCtx.setMode === 'function') {
                        themeCtx.setMode(localTheme);
                    } else if (typeof themeCtx.toggleTheme === 'function') {
                        if (themeCtx.mode !== localTheme) themeCtx.toggleTheme();
                    }
                }
                
                setLoading(false);
            }, (error) => {
                console.error('Error loading preferences:', error);
                setError(error);
                setLoading(false);
                
                // Fallback to localStorage if Firebase fails
                const localLang = localStorage.getItem('userLanguage') || 'en';
                const localTheme = localStorage.getItem('theme') || 'light';
                
                setLanguage(localLang);
                if (typeof themeCtx.setThemeMode === 'function') {
                    themeCtx.setThemeMode(localTheme);
                } else if (typeof themeCtx.setMode === 'function') {
                    themeCtx.setMode(localTheme);
                } else if (typeof themeCtx.toggleTheme === 'function') {
                    if (themeCtx.mode !== localTheme) themeCtx.toggleTheme();
                }
            });

            return () => unsubscribe();
        } catch (err) {
            console.error('Error in dashboard controller:', err);
            setError(err);
            setLoading(false);
        }
    }, [currentUser, setLanguage, themeCtx]);
    
    // Enhanced fetch dashboard data with caching and optimization
    const fetchDashboardData = useCallback(async (forceRefresh = false) => {
        const cacheKey = `dashboard_${startDate.getTime()}_${endDate.getTime()}_${refreshKey || 'default'}`;
        
        // Check cache first if not forcing refresh
        if (!forceRefresh && dashboardCache.has(cacheKey)) {
            console.log('📋 Loading dashboard data from cache');
            const cachedData = dashboardCache.get(cacheKey);
            setStats(cachedData.stats);
            setChartData(cachedData.chartData);
            setRecentOrders(cachedData.recentOrders);
            setBestSellers(cachedData.bestSellers);
            setCustomerData(cachedData.customerData);
            setCountryData(cachedData.countryData);
            setProductTypeData(cachedData.productTypeData);
            setLoading(false);
            return cachedData;
        }

        setLoading(true);
        setError(null);
        const ordersByTime = {};
        
        try {
            console.log('🔄 Fetching fresh dashboard data...');
            const formattedStartDate = startDate.toISOString();
            const formattedEndDate = endDate.toISOString();

            // Optimized API parameters
            const ordersParams = {
                filterGroups: [{
                    filters: [{
                        field: 'created_at',
                        value: formattedStartDate,
                        conditionType: 'gteq'
                    }, {
                        field: 'created_at',
                        value: formattedEndDate,
                        conditionType: 'lteq'
                    }]
                }],
                pageSize: 150, // Increased for better data coverage
                currentPage: 1,
                sortOrders: [{
                    field: 'created_at',
                    direction: 'DESC'
                }]
            };

            // Parallel API calls with error handling
            const apiCalls = [
                magentoApi.getOrders(ordersParams).catch(error => {
                    console.warn('Orders API failed:', error);
                    return { items: [], total_count: 0 };
                }),
                magentoApi.getCustomers({ pageSize: 150 }).catch(error => {
                    console.warn('Customers API failed:', error);
                    return { items: [], total_count: 0 };
                }),
                magentoApi.getProducts({ pageSize: 150 }).catch(error => {
                    console.warn('Products API failed:', error);
                    return { items: [], total_count: 0 };
                })
            ];

            const [ordersResponse, customersResponse, productsResponse] = await Promise.all(apiCalls);

            const orders = ordersResponse?.items || [];
            const customers = customersResponse?.items || [];
            const products = productsResponse?.items || [];
            let totalRevenue = 0;

            // Optimized chart data processing
            const processChartData = () => {
                const startTimestamp = new Date(startDate).setHours(0, 0, 0, 0);
                const endTimestamp = new Date(endDate).setHours(0, 0, 0, 0);
                
                // Initialize time buckets
                let currentDate = new Date(startTimestamp);
                while (currentDate.getTime() <= endTimestamp) {
                    const timestamp = currentDate.getTime();
                    ordersByTime[timestamp] = {
                        count: 0,
                        revenue: 0,
                        key: `day-${timestamp}`
                    };
                    currentDate.setDate(currentDate.getDate() + 1);
                }

                // Process orders efficiently
                orders.forEach(order => {
                    const orderDate = new Date(order.created_at);
                    if (orderDate >= startDate && orderDate <= endDate) {
                        const timestamp = new Date(orderDate).setHours(0, 0, 0, 0);
                        if (ordersByTime[timestamp]) {
                            ordersByTime[timestamp].count++;
                            const orderTotal = parseFloat(order.grand_total || 0);
                            ordersByTime[timestamp].revenue += orderTotal;
                            totalRevenue += orderTotal;
                        }
                    }
                });

                return Object.entries(ordersByTime)
                    .map(([timestamp, data]) => ({
                        date: parseInt(timestamp),
                        orders: data.count || 0,
                        revenue: data.revenue || 0,
                        key: data.key
                    }))
                    .sort((a, b) => a.date - b.date);
            };

            const chartDataArr = processChartData();

            // Optimized stats calculation
            const calculateStats = () => {
                const newCustomers = customers.filter(c => {
                    const createdAt = new Date(c.created_at);
                    return createdAt >= startDate && createdAt <= endDate;
                }).length;

                const totalValue = products.reduce((acc, p) => {
                    const price = parseFloat(p.price || 0);
                    const qty = parseFloat(p.qty || 0);
                    return acc + (price * qty);
                }, 0);

                return {
                    totalOrders: orders.length,
                    totalCustomers: customersResponse?.total_count || 0,
                    totalProducts: productsResponse?.total_count || 0,
                    totalRevenue: totalRevenue,
                    averageOrderValue: orders.length > 0 ? totalRevenue / orders.length : 0,
                    totalValue: totalValue,
                    newCustomers: newCustomers,
                    growthRate: 0, // TODO: Calculate compared to previous period
                    conversionRate: orders.length > 0 ? (orders.length / customers.length) * 100 : 0
                };
            };

            // Optimized best sellers calculation
            const calculateBestSellers = () => {
                const productMap = new Map();
                orders.forEach(order => {
                    (order.items || []).forEach(item => {
                        const sku = item.sku;
                        if (!productMap.has(sku)) {
                            productMap.set(sku, { 
                                sku: sku, 
                                name: item.name, 
                                qty: 0,
                                revenue: 0
                            });
                        }
                        const existing = productMap.get(sku);
                        existing.qty += parseFloat(item.qty_ordered || 0);
                        existing.revenue += parseFloat(item.price || 0) * parseFloat(item.qty_ordered || 0);
                    });
                });
                return Array.from(productMap.values())
                    .sort((a, b) => b.qty - a.qty)
                    .slice(0, 10);
            };

            // Optimized country data processing
            const calculateCountryData = () => {
                const countryCount = new Map();
                products.forEach(product => {
                    if (product?.custom_attributes?.length) {
                        const countryAttr = product.custom_attributes.find(
                            attr => attr?.attribute_code === 'country_of_manufacture'
                        );
                        const country = countryAttr?.value || 'Unknown';
                        countryCount.set(country, (countryCount.get(country) || 0) + 1);
                    }
                });
                return Array.from(countryCount.entries())
                    .map(([country, count]) => ({ country_of_manufacture: country, count }))
                    .sort((a, b) => b.count - a.count)
                    .slice(0, 8); // Increased for better insights
            };

            // Optimized product type data processing
            const calculateProductTypeData = () => {
                const typeCount = new Map();
                products.forEach(product => {
                    const type = product?.type_id || 'unknown';
                    typeCount.set(type, (typeCount.get(type) || 0) + 1);
                });
                return Array.from(typeCount.entries())
                    .map(([type, count]) => ({
                        name: type.charAt(0).toUpperCase() + type.slice(1).replace('_', ' '),
                        value: count,
                        percentage: products.length > 0 ? (count / products.length) * 100 : 0
                    }))
                    .sort((a, b) => b.value - a.value);
            };

            // Calculate all metrics
            const stats = calculateStats();
            const bestSellers = calculateBestSellers();
            const recentOrders = [...orders]
                .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
                .slice(0, 15); // Increased for better overview
            const countryData = calculateCountryData();
            const productTypeData = calculateProductTypeData();

            // Update state
            setStats(stats);
            setChartData(chartDataArr);
            setRecentOrders(recentOrders);
            setBestSellers(bestSellers);
            setCustomerData(customers);
            setCountryData(countryData);
            setProductTypeData(productTypeData);

            // Cache the results with shorter TTL for dynamic data
            const cacheData = {
                stats,
                chartData: chartDataArr,
                recentOrders,
                bestSellers,
                customerData: customers,
                countryData,
                productTypeData,
                timestamp: Date.now()
            };
            
            // Cache for 3 minutes for dashboard data (more dynamic)
            dashboardCache.set(cacheKey, cacheData, 3 * 60 * 1000);
            
            console.log('✅ Dashboard data fetched and cached successfully');
            return cacheData;

        } catch (error) {
            console.error('❌ Dashboard data fetch error:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Failed to fetch dashboard data';
            setError(errorMessage);
            toast.error(`Dashboard Error: ${errorMessage}`);
            throw error;
        } finally {
            setLoading(false);
        }
    }, [startDate, endDate, refreshKey]);
    
    // Enhanced progress tracking for stock sync
    const [syncProgress, setSyncProgress] = useState({ 
        current: 0, 
        total: 0, 
        isActive: false, 
        completed: false,
        currentStep: '',
        sources: [],
        completedSources: [],
        errorSources: [],
        message: ''
    });
    
    const reportsProgress = (completed, total) => parseInt((completed / total) * 100, 10);

    // Enhanced Sync Stocks from MDM with detailed progress tracking
    const syncAllStocks = async () => {
        try {
            console.log('🔄 Starting comprehensive stock sync from MDM...');
            
            // Initialize progress tracking
            setSyncProgress({ 
                current: 0, 
                total: 4, 
                isActive: true, 
                completed: false,
                currentStep: 'Initializing sync process...',
                sources: [],
                completedSources: [],
                errorSources: [],
                message: 'Starting comprehensive stock synchronization'
            });
            
            // Step 1: Mark stocks for sync (Local MDM level)
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 0,
                currentStep: 'Marking stocks for sync',
                message: 'Preparing stock data for synchronization...'
            }));
            
            await axios.post('/api/mdm/sync-stocks');
            setSyncProgress(prev => ({ ...prev, current: 1 }));
            
            // Step 2: Get all sources
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 1,
                currentStep: 'Fetching source configurations',
                message: 'Loading source configurations from MDM...'
            }));
            
            const sourcesResponse = await axios.get('/api/mdm/sources');
            const sources = sourcesResponse.data?.data || [];
            
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 2, 
                sources: sources,
                message: `Found ${sources.length} sources to synchronize`
            }));
            
            // Step 3: Sync sources using the consolidated endpoint
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 2,
                currentStep: 'Syncing sources to Magento',
                message: `Syncing ${sources.length} sources to Magento...`
            }));
            
            // Sync sources sequentially for better progress tracking
            const completedSources = [];
            const errorSources = [];
            
            for (let i = 0; i < sources.length; i++) {
                const source = sources[i];
                try {
                    setSyncProgress(prev => ({ 
                        ...prev,
                        message: `Syncing source ${i + 1}/${sources.length}: ${source.magentoSource || source.code_source}`
                    }));
                    
                    await axios.post('/api/mdm/sync/source', source);
                    completedSources.push(source.code_source);
                    
                    setSyncProgress(prev => ({ 
                        ...prev,
                        completedSources: [...completedSources],
                        message: `Synced ${completedSources.length}/${sources.length} sources`
                    }));
                    
                } catch (error) {
                    console.error(`Error syncing source ${source.code_source}:`, error);
                    errorSources.push(source.code_source);
                    setSyncProgress(prev => ({ 
                        ...prev,
                        errorSources: [...errorSources]
                    }));
                }
            }
            
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 3,
                completedSources: completedSources,
                errorSources: errorSources,
                message: `Sync completed: ${completedSources.length} successful, ${errorSources.length} failed`
            }));
            
            // Step 4: Mark sync as successful
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 3,
                currentStep: 'Finalizing sync process',
                message: 'Marking sync as successful...'
            }));
            
            await axios.post('/api/mdm/sync/success');
            
            // Complete the sync
            setSyncProgress(prev => ({ 
                ...prev, 
                current: 4,
                completed: true,
                isActive: false,
                currentStep: 'Sync completed successfully',
                message: `Successfully synchronized ${sources.length} sources to Magento`
            }));
            
            toast.success('🎉 Stock synchronization completed successfully!', {
                position: 'top-center',
                autoClose: 3000,
                hideProgressBar: false
            });
            // Refresh dashboard data after sync
            setTimeout(() => {
                fetchDashboardData();
                setSyncProgress({ 
                    current: 0, 
                    total: 0, 
                    isActive: false, 
                    completed: false,
                    currentStep: '',
                    sources: [],
                    completedSources: [],
                    errorSources: [],
                    message: ''
                });
            }, 3000);
            
            return { 
                success: true, 
                sourcesSynced: completedSources.length,
                totalSources: sources.length,
                failedSources: errorSources.length,
                completedSources,
                errorSources
            };
            
        } catch (error) {
            console.error('❌ Stock sync error:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Unknown error';
            
            // Update progress to show error state
            setSyncProgress(prev => ({ 
                ...prev, 
                isActive: false,
                completed: false,
                currentStep: 'Sync failed',
                message: `Sync failed: ${errorMessage}`,
                errorSources: prev.sources.map(s => s.code_source)
            }));
            
            toast.error(`❌ Failed to sync stocks: ${errorMessage}`);
            
            // Reset progress after showing error
            setTimeout(() => {
                setSyncProgress({ 
                    current: 0, 
                    total: 0, 
                    isActive: false, 
                    completed: false,
                    currentStep: '',
                    sources: [],
                    completedSources: [],
                    errorSources: [],
                    message: ''
                });
            }, 5000);
            
            throw error;
        }
    };

    // Get Prices from MDM
    const getPrices = async () => {
        try {
            console.log('🔄 Starting price sync from MDM...');
            const response = await axios.get('/api/mdm/prices');

            console.log('✅ Price sync response:', response.data);
            toast.success('✅ Price sync operation completed successfully');

            return response.data;
        } catch (error) {
            console.error('❌ Price sync error:', error);
            const errorMessage = error.response?.data?.message || error.message || 'Unknown error';
            toast.error(`❌ Failed to sync prices: ${errorMessage}`);
            throw error;
        }
    };

    useEffect(() => {
        fetchDashboardData();
    }, [fetchDashboardData]);

    return {
        stats,
        chartData,
        recentOrders,
        bestSellers,
        customerData,
        countryData,
        productTypeData,
        loading,
        error,
        getPrices,
        syncAllStocks,
        fetchDashboardData,
        syncProgress
    };
};

/**
 * LicenseManager - Enhanced license management service with Firebase integration
 * Provides comprehensive license validation, feature access control, and user management
 */

import { database } from '../config/firebase';
import { ref, get, set, onValue, off } from 'firebase/database';
import { 
    LICENSE_TYPES, 
    createDefaultUserLicense, 
    USER_ROLES,
    ROLE_HIERARCHY 
} from '../config/firebaseDefaults';

/**
 * License status interface
 * @typedef {Object} LicenseStatus
 * @property {boolean} isValid - Whether the license is currently valid
 * @property {'basic'|'professional'|'enterprise'|'admin'} level - License level
 * @property {Date} expiryDate - When the license expires
 * @property {string[]} features - Available features
 * @property {Permission[]} permissions - User permissions
 */

/**
 * License interface
 * @typedef {Object} License
 * @property {string} id - License ID
 * @property {string} userId - User ID
 * @property {string} level - License level
 * @property {string[]} features - Available features
 * @property {boolean} isValid - License validity
 * @property {Date} expiryDate - Expiry date
 * @property {number} maxUsers - Maximum users allowed
 */

class LicenseManager {
    constructor() {
        this.cache = new Map();
        this.listeners = new Map();
        this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
    }

    /**
     * Sanitize user ID for Firebase key usage
     * @param {string} userId - User ID to sanitize
     * @returns {string} Sanitized user ID
     */
    sanitizeUserId(userId) {
        return userId.replace(/[.#$\[\]]/g, '_');
    }

    /**
     * Check user license status with caching
     * @param {string} userId - User ID to check
     * @returns {Promise<LicenseStatus>} License status
     */
    async checkUserLicense(userId) {
        try {
            // Check cache first
            const cacheKey = `license_${userId}`;
            const cached = this.cache.get(cacheKey);

            if (cached && (Date.now() - cached.timestamp) < this.cacheTimeout) {
                return cached.data;
            }

            const sanitizedUserId = this.sanitizeUserId(userId);
            const licenseRef = ref(database, `licenses/${sanitizedUserId}`);
            const userRef = ref(database, `users/${sanitizedUserId}`);

            const [licenseSnapshot, userSnapshot] = await Promise.all([
                get(licenseRef),
                get(userRef)
            ]);

            let licenseData = null;
            let userData = null;

            if (licenseSnapshot.exists()) {
                licenseData = licenseSnapshot.val();
            }

            if (userSnapshot.exists()) {
                userData = userSnapshot.val();
            }

            // Create default license if none exists
            if (!licenseData) {
                licenseData = createDefaultUserLicense(userId, 'FREE');
                await set(licenseRef, licenseData);
            }

            // Determine license level based on role and license type
            const userRole = userData?.role || USER_ROLES.USER;
            const licenseLevel = this.determineLicenseLevel(licenseData, userRole);

            // Check expiry
            const now = new Date();
            const expiryDate = licenseData.expiryDate ? new Date(licenseData.expiryDate) : null;
            const isExpired = expiryDate && expiryDate <= now;

            const licenseStatus = {
                isValid: licenseData.isValid && !isExpired,
                level: licenseLevel,
                expiryDate: expiryDate,
                features: licenseData.features || [],
                permissions: this.extractPermissions(licenseData, userData),
                licenseType: licenseData.licenseType || 'free',
                maxUsers: licenseData.maxUsers || 3,
                role: userRole
            };

            // Cache the result
            this.cache.set(cacheKey, {
                data: licenseStatus,
                timestamp: Date.now()
            });

            return licenseStatus;

        } catch (error) {
            console.error('Error checking user license:', error);

            // Return minimal valid license on error
            return {
                isValid: false,
                level: 'basic',
                expiryDate: null,
                features: [],
                permissions: [],
                licenseType: 'free',
                maxUsers: 1,
                role: USER_ROLES.USER
            };
        }
    }

    /**
     * Validate feature access for a user
     * @param {string} feature - Feature to check
     * @param {string} userId - User ID
     * @returns {Promise<boolean>} Whether user has access
     */
    async validateFeatureAccess(feature, userId) {
        try {
            const licenseStatus = await this.checkUserLicense(userId);

            // Admin users have access to all features
            if (licenseStatus.role === USER_ROLES.SUPER_ADMIN || 
                licenseStatus.role === USER_ROLES.ADMIN) {
                return true;
            }

            // Check if feature is in allowed features
            return licenseStatus.isValid && licenseStatus.features.includes(feature);

        } catch (error) {
            console.error('Error validating feature access:', error);
            return false;
        }
    }

    /**
     * Get license level for a user
     * @param {string} userId - User ID
     * @returns {Promise<string>} License level
     */
    async getLicenseLevel(userId) {
        try {
            const licenseStatus = await this.checkUserLicense(userId);
            return licenseStatus.level;
        } catch (error) {
            console.error('Error getting license level:', error);
            return 'basic';
        }
    }

    /**
     * Update license status for a user
     * @param {string} userId - User ID
     * @param {License} license - License data to update
     * @returns {Promise<void>}
     */
    async updateLicenseStatus(userId, license) {
        try {
            const sanitizedUserId = this.sanitizeUserId(userId);
            const licenseRef = ref(database, `licenses/${sanitizedUserId}`);

            // Get current license data
            const currentSnapshot = await get(licenseRef);
            const currentLicense = currentSnapshot.exists() ? currentSnapshot.val() : {};

            // Merge with new license data
            const updatedLicense = {
                ...currentLicense,
                ...license,
                updatedAt: new Date().toISOString(),
                updatedBy: 'system' // Could be enhanced to track who made the change
            };

            await set(licenseRef, updatedLicense);

            // Clear cache for this user
            this.cache.delete(`license_${userId}`);

            console.log(`License updated for user ${userId}`);

        } catch (error) {
            console.error('Error updating license status:', error);
            throw error;
        }
    }

    /**
     * Listen to license changes for a user
     * @param {string} userId - User ID to listen for
     * @param {Function} callback - Callback function
     * @returns {Function} Unsubscribe function
     */
    listenToLicenseChanges(userId, callback) {
        const sanitizedUserId = this.sanitizeUserId(userId);
        const licenseRef = ref(database, `licenses/${sanitizedUserId}`);

        const listener = onValue(licenseRef, (snapshot) => {
            if (snapshot.exists()) {
                const licenseData = snapshot.val();
                // Clear cache when data changes
                this.cache.delete(`license_${userId}`);
                callback(licenseData);
            }
        });

        // Store listener for cleanup
        this.listeners.set(userId, { ref: licenseRef, listener });

        // Return unsubscribe function
        return () => {
            off(licenseRef, listener);
            this.listeners.delete(userId);
        };
    }

    /**
     * Determine license level based on license data and user role
     * @param {Object} licenseData - License data
     * @param {string} userRole - User role
     * @returns {string} License level
     */
    determineLicenseLevel(licenseData, userRole) {
        // Admin roles get admin level
        if (userRole === USER_ROLES.SUPER_ADMIN || userRole === USER_ROLES.ADMIN) {
            return 'admin';
        }

        // Map license types to levels
        const licenseType = licenseData.licenseType || 'free';
        const levelMap = {
            'free': 'basic',
            'basic': 'basic',
            'professional': 'professional',
            'enterprise': 'enterprise'
        };

        return levelMap[licenseType] || 'basic';
    }

    /**
     * Extract permissions from license and user data
     * @param {Object} licenseData - License data
     * @param {Object} userData - User data
     * @returns {Array} Permissions array
     */
    extractPermissions(licenseData, userData) {
        const permissions = [];
        const userRole = userData?.role || USER_ROLES.USER;
        const roleLevel = ROLE_HIERARCHY[userRole] || 0;

        // Basic permissions based on role
        if (roleLevel >= ROLE_HIERARCHY[USER_ROLES.VIEWER]) {
            permissions.push({ resource: '*', actions: ['view'] });
        }

        if (roleLevel >= ROLE_HIERARCHY[USER_ROLES.USER]) {
            permissions.push({ resource: '*', actions: ['view', 'edit'] });
        }

        if (roleLevel >= ROLE_HIERARCHY[USER_ROLES.MANAGER]) {
            permissions.push({ resource: '*', actions: ['view', 'edit', 'delete'] });
        }

        if (roleLevel >= ROLE_HIERARCHY[USER_ROLES.ADMIN]) {
            permissions.push({ resource: '*', actions: ['view', 'edit', 'delete', 'add'] });
        }

        // Add license-specific permissions
        if (licenseData.programPermissions) {
            Object.entries(licenseData.programPermissions).forEach(([program, config]) => {
                if (config.enabled && config.permissions) {
                    Object.entries(config.permissions).forEach(([action, allowed]) => {
                        if (allowed) {
                            permissions.push({
                                resource: program,
                                actions: [action],
                                conditions: { licenseRequired: true }
                            });
                        }
                    });
                }
            });
        }

        return permissions;
    }

    /**
     * Get all users with their license status
     * @returns {Promise<Array>} Array of users with license status
     */
    async getAllUsersWithLicenses() {
        try {
            const usersRef = ref(database, 'users');
            const licensesRef = ref(database, 'licenses');

            const [usersSnapshot, licensesSnapshot] = await Promise.all([
                get(usersRef),
                get(licensesRef)
            ]);

            const users = [];
            const usersData = usersSnapshot.exists() ? usersSnapshot.val() : {};
            const licensesData = licensesSnapshot.exists() ? licensesSnapshot.val() : {};

            for (const [userId, userData] of Object.entries(usersData)) {
                const licenseData = licensesData[userId];
                const licenseStatus = await this.checkUserLicense(userId);

                users.push({
                    userId,
                    userData,
                    licenseData,
                    licenseStatus
                });
            }

            return users;

        } catch (error) {
            console.error('Error getting all users with licenses:', error);
            return [];
        }
    }

    /**
     * Cleanup resources
     */
    cleanup() {
        // Clear all listeners
        this.listeners.forEach(({ ref, listener }) => {
            off(ref, listener);
        });
        this.listeners.clear();

        // Clear cache
        this.cache.clear();
    }
}

// Export singleton instance
export default new LicenseManager();

/**
 * PermissionService - Role-based access control service
 * Provides comprehensive permission checking, menu filtering, and feature access control
 */

import LicenseManager from './LicenseManager';
import { 
    USER_ROLES, 
    ROLE_HIERARCHY, 
    getRolePermissions,
    DEFAULT_LICENSED_PROGRAMS 
} from '../config/firebaseDefaults';

/**
 * Permission interface
 * @typedef {Object} Permission
 * @property {string} resource - Resource name
 * @property {string[]} actions - Allowed actions (view, edit, delete, add)
 * @property {Object} conditions - Additional conditions
 */

/**
 * MenuItem interface
 * @typedef {Object} MenuItem
 * @property {string} id - Menu item ID
 * @property {string} label - Display label
 * @property {string} path - Route path
 * @property {string[]} permissions - Required permissions
 * @property {boolean} licenseRequired - Whether license is required
 * @property {string} roleRequired - Minimum role required
 */

class PermissionService {
    constructor() {
        this.currentUser = null;
        this.currentPermissions = [];
        this.currentLicenseStatus = null;
        this.permissionCache = new Map();
        this.cacheTimeout = 2 * 60 * 1000; // 2 minutes
    }

    /**
     * Initialize permission service with current user
     * @param {Object} user - Current user object
     * @returns {Promise<void>}
     */
    async initialize(user) {
        try {
            this.currentUser = user;

            if (user?.uid) {
                this.currentLicenseStatus = await LicenseManager.checkUserLicense(user.uid);
                this.currentPermissions = this.currentLicenseStatus.permissions || [];
            } else {
                this.currentLicenseStatus = null;
                this.currentPermissions = [];
            }

            // Clear cache when user changes
            this.permissionCache.clear();

        } catch (error) {
            console.error('Error initializing permission service:', error);
            this.currentLicenseStatus = null;
            this.currentPermissions = [];
        }
    }

    /**
     * Check if user has specific permission for a resource and action
     * @param {string} action - Action to check (view, edit, delete, add)
     * @param {string} resource - Resource to check
     * @returns {boolean} Whether user has permission
     */
    hasPermission(action, resource = '*') {
        try {
            if (!this.currentUser || !this.currentLicenseStatus) {
                return false;
            }

            // Cache key for this permission check
            const cacheKey = `${action}_${resource}`;
            const cached = this.permissionCache.get(cacheKey);

            if (cached && (Date.now() - cached.timestamp) < this.cacheTimeout) {
                return cached.result;
            }

            let hasPermission = false;

            // Super admin and admin have all permissions
            if (this.currentLicenseStatus.role === USER_ROLES.SUPER_ADMIN || 
                this.currentLicenseStatus.role === USER_ROLES.ADMIN) {
                hasPermission = true;
            } else {
                // Check role-based permissions
                const rolePermissions = getRolePermissions(this.currentLicenseStatus.role);

                switch (action) {
                    case 'view':
                    case 'read':
                        hasPermission = rolePermissions.canRead;
                        break;
                    case 'edit':
                    case 'update':
                        hasPermission = rolePermissions.canEdit;
                        break;
                    case 'delete':
                        hasPermission = rolePermissions.canDelete;
                        break;
                    case 'add':
                    case 'create':
                        hasPermission = rolePermissions.canEdit; // Edit permission includes create
                        break;
                    case 'manage_users':
                        hasPermission = rolePermissions.canManageUsers;
                        break;
                    case 'assign_roles':
                        hasPermission = rolePermissions.canAssignRoles;
                        break;
                    default:
                        hasPermission = false;
                }

                // Check specific resource permissions
                if (hasPermission && resource !== '*') {
                    hasPermission = this.checkResourcePermission(action, resource);
                }

                // Check license validity for licensed features
                if (hasPermission && this.isLicensedResource(resource)) {
                    hasPermission = this.currentLicenseStatus.isValid;
                }
            }

            // Cache the result
            this.permissionCache.set(cacheKey, {
                result: hasPermission,
                timestamp: Date.now()
            });

            return hasPermission;

        } catch (error) {
            console.error('Error checking permission:', error);
            return false;
        }
    }

    /**
     * Get all permissions for current user
     * @param {string} userId - User ID (optional, uses current user if not provided)
     * @returns {Promise<Permission[]>} Array of permissions
     */
    async getPermissions(userId = null) {
        try {
            const targetUserId = userId || this.currentUser?.uid;

            if (!targetUserId) {
                return [];
            }

            if (userId && userId !== this.currentUser?.uid) {
                // Get permissions for different user
                const licenseStatus = await LicenseManager.checkUserLicense(userId);
                return licenseStatus.permissions || [];
            }

            return this.currentPermissions;

        } catch (error) {
            console.error('Error getting permissions:', error);
            return [];
        }
    }

    /**
     * Check if user has access to a specific feature
     * @param {string} feature - Feature name
     * @returns {Promise<boolean>} Whether user has access
     */
    async checkFeatureAccess(feature) {
        try {
            if (!this.currentUser?.uid) {
                return false;
            }

            return await LicenseManager.validateFeatureAccess(feature, this.currentUser.uid);

        } catch (error) {
            console.error('Error checking feature access:', error);
            return false;
        }
    }

    /**
     * Filter menu items based on user permissions and license
     * @param {MenuItem[]} menuItems - Array of menu items
     * @returns {MenuItem[]} Filtered menu items
     */
    filterMenuItems(menuItems) {
        try {
            if (!this.currentUser || !this.currentLicenseStatus) {
                return [];
            }

            return menuItems.filter(item => this.canAccessMenuItem(item))
                           .map(item => this.filterMenuItemChildren(item));

        } catch (error) {
            console.error('Error filtering menu items:', error);
            return [];
        }
    }

    /**
     * Check if user can access a specific menu item
     * @param {MenuItem} menuItem - Menu item to check
     * @returns {boolean} Whether user can access the item
     */
    canAccessMenuItem(menuItem) {
        try {
            // Check role requirement
            if (menuItem.roleRequired) {
                const requiredLevel = ROLE_HIERARCHY[menuItem.roleRequired] || 0;
                const userLevel = ROLE_HIERARCHY[this.currentLicenseStatus.role] || 0;

                if (userLevel < requiredLevel) {
                    return false;
                }
            }

            // Check license requirement
            if (menuItem.licenseRequired && !this.currentLicenseStatus.isValid) {
                // Allow access for admin users even without valid license
                if (this.currentLicenseStatus.role !== USER_ROLES.SUPER_ADMIN && 
                    this.currentLicenseStatus.role !== USER_ROLES.ADMIN) {
                    return false;
                }
            }

            // Check specific permissions
            if (menuItem.permissions && menuItem.permissions.length > 0) {
                return menuItem.permissions.some(permission => {
                    const [action, resource] = permission.split(':');
                    return this.hasPermission(action, resource || '*');
                });
            }

            // Check feature access for licensed programs
            if (menuItem.featureId) {
                const hasFeatureAccess = this.currentLicenseStatus.features.includes(menuItem.featureId);
                if (!hasFeatureAccess && this.currentLicenseStatus.role !== USER_ROLES.SUPER_ADMIN && 
                    this.currentLicenseStatus.role !== USER_ROLES.ADMIN) {
                    return false;
                }
            }

            return true;

        } catch (error) {
            console.error('Error checking menu item access:', error);
            return false;
        }
    }

    /**
     * Filter children of a menu item
     * @param {MenuItem} menuItem - Menu item with potential children
     * @returns {MenuItem} Menu item with filtered children
     */
    filterMenuItemChildren(menuItem) {
        if (menuItem.children && menuItem.children.length > 0) {
            return {
                ...menuItem,
                children: menuItem.children
                    .filter(child => this.canAccessMenuItem(child))
                    .map(child => this.filterMenuItemChildren(child))
            };
        }
        return menuItem;
    }

    /**
     * Check resource-specific permissions
     * @param {string} action - Action to check
     * @param {string} resource - Resource to check
     * @returns {boolean} Whether user has permission for this resource
     */
    checkResourcePermission(action, resource) {
        try {
            // Check if user has specific permission for this resource
            const hasSpecificPermission = this.currentPermissions.some(permission => {
                return (permission.resource === resource || permission.resource === '*') &&
                       permission.actions.includes(action);
            });

            if (hasSpecificPermission) {
                return true;
            }

            // Check program-specific permissions
            if (DEFAULT_LICENSED_PROGRAMS[resource]) {
                const program = DEFAULT_LICENSED_PROGRAMS[resource];
                const licenseData = this.currentLicenseStatus;

                if (licenseData.programPermissions && licenseData.programPermissions[resource]) {
                    const programConfig = licenseData.programPermissions[resource];
                    return programConfig.enabled && programConfig.permissions[action];
                }
            }

            return false;

        } catch (error) {
            console.error('Error checking resource permission:', error);
            return false;
        }
    }

    /**
     * Check if a resource requires a license
     * @param {string} resource - Resource to check
     * @returns {boolean} Whether resource requires license
     */
    isLicensedResource(resource) {
        return DEFAULT_LICENSED_PROGRAMS[resource] && 
               !DEFAULT_LICENSED_PROGRAMS[resource].defaultEnabled;
    }

    /**
     * Get permission summary for current user
     * @returns {Object} Permission summary
     */
    getPermissionSummary() {
        if (!this.currentLicenseStatus) {
            return {
                role: 'none',
                licenseLevel: 'none',
                isValid: false,
                permissions: {
                    canRead: false,
                    canEdit: false,
                    canDelete: false,
                    canAdd: false,
                    canManageUsers: false,
                    canAssignRoles: false
                },
                features: [],
                expiryDate: null
            };
        }

        const rolePermissions = getRolePermissions(this.currentLicenseStatus.role);

        return {
            role: this.currentLicenseStatus.role,
            licenseLevel: this.currentLicenseStatus.level,
            isValid: this.currentLicenseStatus.isValid,
            permissions: {
                canRead: this.hasPermission('view'),
                canEdit: this.hasPermission('edit'),
                canDelete: this.hasPermission('delete'),
                canAdd: this.hasPermission('add'),
                canManageUsers: rolePermissions.canManageUsers,
                canAssignRoles: rolePermissions.canAssignRoles
            },
            features: this.currentLicenseStatus.features,
            expiryDate: this.currentLicenseStatus.expiryDate
        };
    }

    /**
     * Refresh permissions for current user
     * @returns {Promise<void>}
     */
    async refreshPermissions() {
        if (this.currentUser?.uid) {
            await this.initialize(this.currentUser);
        }
    }

    /**
     * Clear permission cache
     */
    clearCache() {
        this.permissionCache.clear();
    }

    /**
     * Get current user's license status
     * @returns {Object|null} Current license status
     */
    getCurrentLicenseStatus() {
        return this.currentLicenseStatus;
    }

    /**
     * Check if current user is admin
     * @returns {boolean} Whether user is admin
     */
    isAdmin() {
        return this.currentLicenseStatus?.role === USER_ROLES.ADMIN || 
               this.currentLicenseStatus?.role === USER_ROLES.SUPER_ADMIN;
    }

    /**
     * Check if current user can perform bulk operations
     * @returns {boolean} Whether user can perform bulk operations
     */
    canPerformBulkOperations() {
        return this.hasPermission('edit') && this.hasPermission('delete');
    }
}

// Export singleton instance
export default new PermissionService();

/**
 * Settings Synchronization Service
 * Handles cloud storage integration, immediate local saves with cloud sync queuing,
 * conflict resolution, and sync status feedback for user settings
 * 
 * Requirements: 7.1, 7.2, 7.3, 7.4, 7.5
 */

import { ref, set, get, onValue, serverTimestamp, push } from 'firebase/database';
import { database } from '../config/firebase';
import { 
    saveUnifiedSettings, 
    saveUserSettings, 
    getUserSettings, 
    getUnifiedSettings,
    getDefaultSettings 
} from '../utils/unifiedSettingsManager';
import { toast } from 'react-toastify';

class SettingsSyncService {
    constructor() {
        this.database = database;
        this.syncQueue = [];
        this.isOnline = navigator.onLine;
        this.syncInProgress = false;
        this.syncListeners = new Set();
        this.conflictResolvers = new Map();
        this.retryAttempts = 0;
        this.maxRetryAttempts = 3;
        this.retryDelay = 1000; // Start with 1 second

        // Initialize online/offline listeners
        this.initializeNetworkListeners();

        // Initialize sync status
        this.syncStatus = {
            lastSync: null,
            pendingChanges: 0,
            isOnline: this.isOnline,
            syncInProgress: false,
            lastError: null,
            conflictsDetected: 0
        };
    }

    /**
     * Initialize network status listeners
     */
    initializeNetworkListeners() {
        window.addEventListener('online', () => {
            this.isOnline = true;
            this.updateSyncStatus({ isOnline: true, lastError: null });
            this.processSyncQueue();
            this.notifyListeners('network', { online: true });
        });

        window.addEventListener('offline', () => {
            this.isOnline = false;
            this.updateSyncStatus({ isOnline: false });
            this.notifyListeners('network', { online: false });
        });
    }

    /**
     * Save settings with immediate local storage and cloud sync queuing
     * Requirement 7.1, 7.2
     */
    async saveSettings(userId, settings, options = {}) {
        const { immediate = false, skipLocal = false } = options;

        try {
            // Step 1: Immediate local storage save (Requirement 7.2)
            if (!skipLocal) {
                const localSaveResult = userId 
                    ? saveUserSettings(userId, settings)
                    : saveUnifiedSettings(settings);

                if (!localSaveResult) {
                    throw new Error('Failed to save settings locally');
                }

                console.log('✅ Settings saved locally immediately');
            }

            // Step 2: Queue for cloud sync (Requirement 7.2)
            const syncItem = {
                id: Date.now() + Math.random(),
                userId,
                settings,
                timestamp: Date.now(),
                attempts: 0,
                immediate
            };

            this.syncQueue.push(syncItem);
            this.updateSyncStatus({ pendingChanges: this.syncQueue.length });

            // Step 3: Process sync queue if online
            if (this.isOnline && !this.syncInProgress) {
                await this.processSyncQueue();
            }

            return {
                success: true,
                savedLocally: true,
                queuedForSync: true,
                syncStatus: this.syncStatus
            };

        } catch (error) {
            console.error('❌ Error saving settings:', error);
            this.updateSyncStatus({ lastError: error.message });

            return {
                success: false,
                error: error.message,
                savedLocally: false,
                queuedForSync: false
            };
        }
    }

    /**
     * Process the sync queue with retry logic
     * Requirement 7.2
     */
    async processSyncQueue() {
        if (!this.isOnline || this.syncInProgress || this.syncQueue.length === 0) {
            return;
        }

        this.syncInProgress = true;
        this.updateSyncStatus({ syncInProgress: true });
        this.notifyListeners('syncStart', { queueLength: this.syncQueue.length });

        const processedItems = [];
        const failedItems = [];

        for (const item of this.syncQueue) {
            try {
                const result = await this.syncToCloud(item);

                if (result.success) {
                    processedItems.push(item);
                    console.log(`✅ Synced settings for ${item.userId || 'anonymous'}`);
                } else {
                    item.attempts++;
                    if (item.attempts >= this.maxRetryAttempts) {
                        failedItems.push(item);
                        console.error(`❌ Failed to sync after ${this.maxRetryAttempts} attempts:`, result.error);
                    } else {
                        // Keep in queue for retry with exponential backoff
                        setTimeout(() => {
                            console.log(`🔄 Retrying sync for ${item.userId || 'anonymous'} (attempt ${item.attempts + 1})`);
                        }, this.retryDelay * Math.pow(2, item.attempts));
                    }
                }
            } catch (error) {
                console.error('❌ Sync processing error:', error);
                item.attempts++;
                if (item.attempts >= this.maxRetryAttempts) {
                    failedItems.push(item);
                }
            }
        }

        // Remove processed items from queue
        this.syncQueue = this.syncQueue.filter(item => 
            !processedItems.includes(item) && !failedItems.includes(item)
        );

        // Update sync status
        const now = Date.now();
        this.updateSyncStatus({
            lastSync: processedItems.length > 0 ? now : this.syncStatus.lastSync,
            pendingChanges: this.syncQueue.length,
            syncInProgress: false,
            lastError: failedItems.length > 0 ? `${failedItems.length} items failed to sync` : null
        });

        this.syncInProgress = false;
        this.notifyListeners('syncComplete', {
            processed: processedItems.length,
            failed: failedItems.length,
            remaining: this.syncQueue.length
        });

        // Show user feedback
        if (processedItems.length > 0) {
            toast.success(`Settings synced successfully (${processedItems.length} items)`);
        }

        if (failedItems.length > 0) {
            toast.warning(`Some settings failed to sync (${failedItems.length} items). Will retry later.`);
        }
    }

    /**
     * Sync individual item to cloud storage
     * Requirement 7.1
     */
    async syncToCloud(syncItem) {
        try {
            const { userId, timestamp } = syncItem;
            let { settings } = syncItem;
            const settingsRef = userId 
                ? ref(this.database, `users/${userId}/settings`)
                : ref(this.database, `anonymous/${this.getAnonymousId()}/settings`);

            // Check for conflicts before saving (Requirement 7.3)
            const conflictResult = await this.checkForConflicts(userId, settings, timestamp);

            if (conflictResult.hasConflict) {
                const resolution = await this.resolveConflict(conflictResult);
                if (!resolution.resolved) {
                    return {
                        success: false,
                        error: 'Conflict resolution failed',
                        conflict: conflictResult
                    };
                }
                // Use resolved settings
                settings = resolution.resolvedSettings;
            }

            // Prepare cloud data
            const cloudData = {
                ...settings,
                syncedAt: serverTimestamp(),
                lastModified: timestamp,
                deviceInfo: {
                    userAgent: navigator.userAgent,
                    platform: navigator.platform,
                    timestamp: Date.now()
                },
                version: '2.1.0'
            };

            // Save to Firebase
            await set(settingsRef, cloudData);

            return { success: true };

        } catch (error) {
            console.error('❌ Cloud sync error:', error);
            return {
                success: false,
                error: error.message
            };
        }
    }

    /**
     * Check for conflicts between local and remote settings
     * Requirement 7.3
     */
    async checkForConflicts(userId, localSettings, localTimestamp) {
        try {
            const settingsRef = userId 
                ? ref(this.database, `users/${userId}/settings`)
                : ref(this.database, `anonymous/${this.getAnonymousId()}/settings`);

            const snapshot = await get(settingsRef);

            if (!snapshot.exists()) {
                return { hasConflict: false };
            }

            const remoteSettings = snapshot.val();
            const remoteTimestamp = remoteSettings.lastModified || 0;

            // Check if remote is newer than local
            if (remoteTimestamp > localTimestamp) {
                // Find specific conflicts
                const conflicts = this.findSettingsDifferences(localSettings, remoteSettings);

                if (conflicts.length > 0) {
                    this.updateSyncStatus({ 
                        conflictsDetected: this.syncStatus.conflictsDetected + 1 
                    });

                    return {
                        hasConflict: true,
                        localSettings,
                        remoteSettings,
                        conflicts,
                        localTimestamp,
                        remoteTimestamp
                    };
                }
            }

            return { hasConflict: false };

        } catch (error) {
            console.error('❌ Error checking for conflicts:', error);
            return { hasConflict: false, error: error.message };
        }
    }

    /**
     * Find differences between local and remote settings
     */
    findSettingsDifferences(local, remote) {
        const conflicts = [];

        const compareObjects = (localObj, remoteObj, path = '') => {
            for (const key in localObj) {
                const currentPath = path ? `${path}.${key}` : key;

                if (typeof localObj[key] === 'object' && localObj[key] !== null) {
                    if (typeof remoteObj[key] === 'object' && remoteObj[key] !== null) {
                        compareObjects(localObj[key], remoteObj[key], currentPath);
                    } else {
                        conflicts.push({
                            path: currentPath,
                            localValue: localObj[key],
                            remoteValue: remoteObj[key],
                            type: 'object_mismatch'
                        });
                    }
                } else if (localObj[key] !== remoteObj[key]) {
                    conflicts.push({
                        path: currentPath,
                        localValue: localObj[key],
                        remoteValue: remoteObj[key],
                        type: 'value_mismatch'
                    });
                }
            }
        };

        compareObjects(local, remote);
        return conflicts;
    }

    /**
     * Resolve conflicts between local and remote settings
     * Requirement 7.3
     */
    async resolveConflict(conflictResult) {
        const { localSettings, remoteSettings, conflicts, localTimestamp, remoteTimestamp } = conflictResult;

        try {
            // Check if there's a custom conflict resolver
            const customResolver = this.conflictResolvers.get('settings');
            if (customResolver) {
                const resolution = await customResolver(conflictResult);
                if (resolution) {
                    return {
                        resolved: true,
                        resolvedSettings: resolution,
                        strategy: 'custom'
                    };
                }
            }

            // Default conflict resolution strategies
            const strategy = await this.getConflictResolutionStrategy(conflicts);

            let resolvedSettings;

            switch (strategy) {
                case 'use_remote':
                    resolvedSettings = remoteSettings;
                    toast.info('Using remote settings (newer version found)');
                    break;

                case 'use_local':
                    resolvedSettings = localSettings;
                    toast.info('Using local settings (keeping your changes)');
                    break;

                case 'merge':
                    resolvedSettings = this.mergeSettings(localSettings, remoteSettings, conflicts);
                    toast.info('Merged local and remote settings');
                    break;

                case 'user_choice':
                    resolvedSettings = await this.promptUserForResolution(conflictResult);
                    break;

                default:
                    // Fallback to remote if newer, otherwise local
                    resolvedSettings = remoteTimestamp > localTimestamp ? remoteSettings : localSettings;
                    break;
            }

            // Update local storage with resolved settings
            if (conflictResult.userId) {
                saveUserSettings(conflictResult.userId, resolvedSettings);
            } else {
                saveUnifiedSettings(resolvedSettings);
            }

            return {
                resolved: true,
                resolvedSettings,
                strategy
            };

        } catch (error) {
            console.error('❌ Error resolving conflict:', error);
            return {
                resolved: false,
                error: error.message
            };
        }
    }

    /**
     * Determine conflict resolution strategy based on conflict types
     */
    async getConflictResolutionStrategy(conflicts) {
        // Analyze conflicts to determine best strategy
        const criticalConflicts = conflicts.filter(c => 
            c.path.includes('apiSettings') || 
            c.path.includes('personalInfo')
        );

        const preferenceConflicts = conflicts.filter(c => 
            c.path.includes('preferences') || 
            c.path.includes('theme') || 
            c.path.includes('language')
        );

        // Critical settings require user choice
        if (criticalConflicts.length > 0) {
            return 'user_choice';
        }

        // Preference conflicts can be merged
        if (preferenceConflicts.length > 0 && criticalConflicts.length === 0) {
            return 'merge';
        }

        // Default to using remote if it's newer
        return 'use_remote';
    }

    /**
     * Merge settings intelligently
     */
    mergeSettings(localSettings, remoteSettings, conflicts) {
        const merged = { ...remoteSettings };

        // For preferences, prefer local changes
        if (localSettings.preferences && remoteSettings.preferences) {
            merged.preferences = {
                ...remoteSettings.preferences,
                ...localSettings.preferences
            };
        }

        // For API settings, prefer remote (more likely to be correct)
        if (remoteSettings.apiSettings) {
            merged.apiSettings = remoteSettings.apiSettings;
        }

        // For personal info, prefer local (user might have updated)
        if (localSettings.personalInfo) {
            merged.personalInfo = {
                ...remoteSettings.personalInfo || {},
                ...localSettings.personalInfo
            };
        }

        return merged;
    }

    /**
     * Prompt user for conflict resolution
     * Requirement 7.4
     */
    async promptUserForResolution(conflictResult) {
        return new Promise((resolve) => {
            // Create a custom event that the UI can listen to
            const conflictEvent = new CustomEvent('settingsConflict', {
                detail: {
                    conflictResult,
                    resolve: (choice) => {
                        switch (choice) {
                            case 'local':
                                resolve(conflictResult.localSettings);
                                break;
                            case 'remote':
                                resolve(conflictResult.remoteSettings);
                                break;
                            case 'merge':
                                resolve(this.mergeSettings(
                                    conflictResult.localSettings,
                                    conflictResult.remoteSettings,
                                    conflictResult.conflicts
                                ));
                                break;
                            default:
                                resolve(conflictResult.remoteSettings);
                        }
                    }
                }
            });

            window.dispatchEvent(conflictEvent);

            // Fallback timeout - use remote after 30 seconds
            setTimeout(() => {
                resolve(conflictResult.remoteSettings);
                toast.warning('Conflict resolution timed out. Using remote settings.');
            }, 30000);
        });
    }

    /**
     * Load settings from cloud with conflict detection
     * Requirement 7.1, 7.3
     */
    async loadFromCloud(userId) {
        try {
            const settingsRef = userId 
                ? ref(this.database, `users/${userId}/settings`)
                : ref(this.database, `anonymous/${this.getAnonymousId()}/settings`);

            const snapshot = await get(settingsRef);

            if (!snapshot.exists()) {
                console.log('No cloud settings found, using local/defaults');
                return {
                    success: true,
                    settings: userId ? getUserSettings(userId) : getUnifiedSettings(),
                    source: 'local'
                };
            }

            const cloudSettings = snapshot.val();
            const localSettings = userId ? getUserSettings(userId) : getUnifiedSettings();

            // Check for conflicts
            const conflictResult = await this.checkForConflicts(
                userId, 
                localSettings, 
                localSettings.lastModified || 0
            );

            if (conflictResult.hasConflict) {
                const resolution = await this.resolveConflict(conflictResult);
                return {
                    success: true,
                    settings: resolution.resolvedSettings,
                    source: 'resolved',
                    hadConflicts: true
                };
            }

            // No conflicts, use cloud settings if newer
            const useCloud = cloudSettings.lastModified > (localSettings.lastModified || 0);
            const finalSettings = useCloud ? cloudSettings : localSettings;

            // Update local storage if using cloud settings
            if (useCloud) {
                if (userId) {
                    saveUserSettings(userId, finalSettings);
                } else {
                    saveUnifiedSettings(finalSettings);
                }
            }

            return {
                success: true,
                settings: finalSettings,
                source: useCloud ? 'cloud' : 'local'
            };

        } catch (error) {
            console.error('❌ Error loading from cloud:', error);
            this.updateSyncStatus({ lastError: error.message });

            // Fallback to local settings
            const fallbackSettings = userId ? getUserSettings(userId) : getUnifiedSettings();
            return {
                success: false,
                settings: fallbackSettings,
                source: 'local_fallback',
                error: error.message
            };
        }
    }

    /**
     * Set up real-time sync listener for a user
     * Requirement 7.1
     */
    setupRealtimeSync(userId) {
        const settingsRef = userId 
            ? ref(this.database, `users/${userId}/settings`)
            : ref(this.database, `anonymous/${this.getAnonymousId()}/settings`);

        const unsubscribe = onValue(settingsRef, (snapshot) => {
            if (snapshot.exists()) {
                const remoteSettings = snapshot.val();
                const localSettings = userId ? getUserSettings(userId) : getUnifiedSettings();

                // Only apply if remote is newer
                if (remoteSettings.lastModified > (localSettings.lastModified || 0)) {
                    console.log('🔄 Applying newer remote settings');

                    if (userId) {
                        saveUserSettings(userId, remoteSettings);
                    } else {
                        saveUnifiedSettings(remoteSettings);
                    }

                    // Notify listeners
                    this.notifyListeners('remoteUpdate', {
                        userId,
                        settings: remoteSettings
                    });

                    toast.info('Settings updated from another device');
                }
            }
        }, (error) => {
            console.warn('❌ Real-time sync error:', error);
            this.updateSyncStatus({ lastError: error.message });
        });

        return unsubscribe;
    }

    /**
     * Get anonymous user ID for cloud storage
     */
    getAnonymousId() {
        let anonymousId = localStorage.getItem('techno-etl-anonymous-id');
        if (!anonymousId) {
            anonymousId = 'anon_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
            localStorage.setItem('techno-etl-anonymous-id', anonymousId);
        }
        return anonymousId;
    }

    /**
     * Update sync status and notify listeners
     * Requirement 7.4, 7.5
     */
    updateSyncStatus(updates) {
        this.syncStatus = { ...this.syncStatus, ...updates };
        this.notifyListeners('statusUpdate', this.syncStatus);
    }

    /**
     * Add sync status listener
     * Requirement 7.4, 7.5
     */
    addSyncListener(callback) {
        this.syncListeners.add(callback);

        // Return unsubscribe function
        return () => {
            this.syncListeners.delete(callback);
        };
    }

    /**
     * Notify all sync listeners
     */
    notifyListeners(event, data) {
        this.syncListeners.forEach(callback => {
            try {
                callback(event, data);
            } catch (error) {
                console.error('❌ Error in sync listener:', error);
            }
        });
    }

    /**
     * Register custom conflict resolver
     */
    registerConflictResolver(type, resolver) {
        this.conflictResolvers.set(type, resolver);
    }

    /**
     * Get current sync status
     * Requirement 7.4, 7.5
     */
    getSyncStatus() {
        return { ...this.syncStatus };
    }

    /**
     * Force sync all pending changes
     */
    async forceSyncAll() {
        if (!this.isOnline) {
            toast.error('Cannot sync while offline');
            return false;
        }

        await this.processSyncQueue();
        return this.syncQueue.length === 0;
    }

    /**
     * Clear sync queue (use with caution)
     */
    clearSyncQueue() {
        this.syncQueue = [];
        this.updateSyncStatus({ pendingChanges: 0 });
    }

    /**
     * Get sync queue status
     */
    getSyncQueueStatus() {
        return {
            queueLength: this.syncQueue.length,
            oldestItem: this.syncQueue.length > 0 ? this.syncQueue[0].timestamp : null,
            newestItem: this.syncQueue.length > 0 ? this.syncQueue[this.syncQueue.length - 1].timestamp : null
        };
    }
}

