                            'write': true,
                            'delete': false
                        }
                    }
                }
            };

            const mockUserData = {
                role: USER_ROLES.USER,
                email: mockUser.email,
                displayName: mockUser.displayName
            };

            get.mockResolvedValue({
                exists: () => true,
                val: () => mockLicenseData
            });

            // Step 1: Initialize PermissionService with user
