        this.allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'image/webp'];
        this.defaultSettings = {
          strategies: {
            exact: true,
            normalized: true,
            partial: true,
            fuzzy: true,
            ref: true
          },
          strategyWeights: {
            exact: 1.0,
