            strictFuzzyThreshold: 0.85,
            minKeyLength: 3,
            maxEditDistance: 3,
            numberedPatternBonus: 0.1,
            specialCharPenalty: 0.05,
            edgeCaseThreshold: 0.6,
            unicodeNormalizationBonus: 0.05,
            lengthDifferenceThreshold: 0.3,
