const formatResponse = (response, mockDataKey) => {
  if (process.env.NODE_ENV === 'development' && (!response || !response.items)) {
    return {
      items: mockData[mockDataKey] || [],
      total_count: mockData[mockDataKey]?.length || 0
    };
