        // Validation
        if (skuIndex === -1) {
          reject(new Error('CSV must contain a "sku" column'));
          return;
        }

        if (imageNameIndex === -1) {
          reject(new Error('CSV must contain an "image name" column'));
          return;
        }



        const data = [];
        let processedRows = 0;
        let skippedRows = 0;

        // Parse data rows
        for (let i = 1; i < lines.length; i++) {
          try {
            const values = parseCSVLine(lines[i]);

            const requiredColumns = Math.max(skuIndex + 1, imageNameIndex + 1, refIndex !== -1 ? refIndex + 1 : 0);

            if (values.length >= requiredColumns) {
              const sku = values[skuIndex] ? values[skuIndex].replace(/"/g, '"').trim() : '';
