    // Re-render with same props
    rerender(
      <TestWrapper>
        <BaseToolbar
          config={{ showRefresh: true }}
          selectedCount={0}
        />
      </TestWrapper>
    );

    // Should not cause unnecessary re-renders
    expect(screen.getByLabelText('Refresh')).toBeInTheDocument();
