  const React = require('react');
  const [data, setData] = React.useState(null);

  if (!data) {
    throw new Promise(resolve => {
      setTimeout(() => {
        setData(result);
        resolve(result);
      }, delay);
    });
  }

  return React.createElement('div', null, data);
};

