};

// Utility function to save grid settings
export const saveGridSettings = async (gridName, settings) => {
    if (!gridName || !settings) return;

    try {
        // Save to local storage
        localStorage.setItem(`grid_${gridName}_settings`, JSON.stringify(settings));

        // Save to database
        const settingsRef = ref(database, `gridSettings/${gridName}`);
        await set(settingsRef, settings);

        return true;
    } catch (error) {
        console.error('Error saving grid settings:', error);
        return false;
    }
};

// Utility function to get grid settings
export const getGridSettings = async (gridName) => {
    try {
        // First try to get from localStorage
        const localSettings = localStorage.getItem(`${gridName}-columns`);
        if (localSettings) {
            return JSON.parse(localSettings);
        }

        // If not in localStorage, try Firebase
        const settingsRef = ref(database, `gridSettings/${gridName}`);
        const snapshot = await get(settingsRef);
        if (snapshot.exists()) {
            const settings = snapshot.val();
            // Cache in localStorage for future use
            localStorage.setItem(`${gridName}-columns`, JSON.stringify(settings));
            return settings;
        }
    } catch (error) {
        console.error('Error retrieving grid settings:', error);
    }
    return null;
};

// Merging dynamic columns with user columns
export const mergeColumns = (userColumns, dynamicColumns) => {
    const columnMap = new Map();

    // Ensure userColumns and dynamicColumns are arrays
    const safeUserColumns = Array.isArray(userColumns) ? userColumns : [];
    const safeDynamicColumns = Array.isArray(dynamicColumns) ? dynamicColumns : [];

    // Add user columns to the column map
    safeUserColumns.forEach(col => {
        if (col && col.field) {
            columnMap.set(col.field, { ...col, hide: false });
        }
    });

    // Add dynamic columns if they don't exist in user columns
    safeDynamicColumns.forEach(col => {
        if (!columnMap.has(col.field)) {
            columnMap.set(col.field, { ...col, hide: true });  // Set hide: true for dynamic columns by default
        }
    });

    return Array.from(columnMap.values());
};

/**
 * Height Calculator Utility
 * Provides consistent height calculations across all tabs and components
 */

/**
 * Standard layout dimensions
 */
export const LAYOUT_DIMENSIONS = {
  HEADER_HEIGHT: 64,
  FOOTER_HEIGHT: 64,
  TAB_HEADER_HEIGHT: 48,
  TOOLBAR_HEIGHT: 56,
  STATS_CARDS_HEIGHT: 120,
  PADDING: 16,
  MARGIN: 8
};

/**
 * Calculate available height for content
 * @param {Object} options - Configuration options
 * @param {boolean} options.hasHeader - Whether header is present
 * @param {boolean} options.hasFooter - Whether footer is present
 * @param {boolean} options.hasTabHeader - Whether tab header is present
 * @param {boolean} options.hasToolbar - Whether toolbar is present
 * @param {boolean} options.hasStatsCards - Whether stats cards are present
 * @param {number} options.extraPadding - Additional padding to subtract
 * @returns {string} CSS height value
 */
export const calculateContentHeight = (options = {}) => {
  const {
    hasHeader = true,
    hasFooter = true,
    hasTabHeader = true,
    hasToolbar = false,
    hasStatsCards = false,
    extraPadding = 0
  } = options;

  let totalHeight = 0;

  if (hasHeader) totalHeight += LAYOUT_DIMENSIONS.HEADER_HEIGHT;
  if (hasFooter) totalHeight += LAYOUT_DIMENSIONS.FOOTER_HEIGHT;
  if (hasTabHeader) totalHeight += LAYOUT_DIMENSIONS.TAB_HEADER_HEIGHT;
  if (hasToolbar) totalHeight += LAYOUT_DIMENSIONS.TOOLBAR_HEIGHT;
  if (hasStatsCards) totalHeight += LAYOUT_DIMENSIONS.STATS_CARDS_HEIGHT;

  return `calc(100vh - ${totalHeight}px)`;
};

/**
 * Create flexible container styles that use remaining height
 * @param {Object} options - Configuration options
 * @returns {Object} CSS styles for flexible height container
 */
export const createFlexibleHeightStyles = (options = {}) => {
  const {
    hasStatsCards = false,
    minHeight = '400px'
  } = options;

  return {
    display: 'flex',
    flexDirection: 'column',
    height: '100%',
    minHeight,
    overflow: 'hidden',

    // Grid container takes remaining space
    '& .grid-container': {
      flex: 1,
      minHeight: 0,
      display: 'flex',
      flexDirection: 'column',
      overflow: 'hidden'
    },

    // Stats cards at bottom if present
    ...(hasStatsCards && {
      '& .stats-container': {
        flexShrink: 0,
        borderTop: '1px solid rgba(224, 224, 224, 1)',
        pt: 1,
        backgroundColor: 'background.paper'
      }
    })
  };
};

/**
 * Calculate height for dashboard components
 * @param {Object} options - Dashboard-specific options
 * @returns {string} CSS height value
 */
export const calculateDashboardHeight = (options = {}) => {
  return calculateContentHeight({
    hasHeader: true,
    hasFooter: true,
    hasTabHeader: true,
    hasToolbar: false,
    hasStatsCards: false,
    extraPadding: 20, // Extra padding for dashboard
    ...options
  });
};

/**
 * Calculate height for grid components
 * @param {Object} options - Grid-specific options
 * @returns {string} CSS height value
 */
export const calculateGridHeight = (options = {}) => {
  return calculateContentHeight({
    hasHeader: true,
    hasFooter: true,
    hasTabHeader: true,
    hasToolbar: true,
    hasStatsCards: options.hasStatsCards || false,
    extraPadding: 2,
    ...options
  });
};

/**
 * Calculate height for chart components
 * @param {Object} options - Chart-specific options
 * @returns {string} CSS height value
 */
export const calculateChartHeight = (options = {}) => {
  const {
    isCollapsed = false,
    minHeight = 300,
    maxHeight = 500
  } = options;

  if (isCollapsed) {
    return '0px';
  }

  const baseHeight = calculateContentHeight({
    hasHeader: false,
    hasFooter: false,
    hasTabHeader: false,
    hasToolbar: false,
    hasStatsCards: false,
    extraPadding: 40,
    ...options
  });

  // For charts, we want a fixed height within min/max bounds
  return `clamp(${minHeight}px, ${baseHeight}, ${maxHeight}px)`;
};

/**
 * Calculate height for tab content
 * @param {string} tabType - Type of tab (dashboard, grid, form, etc.)
 * @param {Object} options - Tab-specific options
 * @returns {string} CSS height value
 */
export const calculateTabHeight = (tabType, options = {}) => {
  switch (tabType) {
    case 'dashboard':
      return calculateDashboardHeight(options);
    case 'grid':
      return calculateGridHeight(options);
    case 'chart':
      return calculateChartHeight(options);
    case 'form':
      return calculateContentHeight({
        hasHeader: true,
        hasFooter: true,
        hasTabHeader: true,
        hasToolbar: false,
        hasStatsCards: false,
        extraPadding: 0,
        ...options
      });
    default:
      return calculateContentHeight(options);
  }
};

/**
 * Get responsive height based on screen size
 * @param {string} baseHeight - Base height calculation
 * @param {Object} breakpoints - Responsive breakpoints
 * @returns {Object} Responsive height object for sx prop
 */
export const getResponsiveHeight = (baseHeight, breakpoints = {}) => {
  return {
    height: baseHeight,
    '@media (max-width: 768px)': {
      height: breakpoints.mobile || `calc(${baseHeight} - 20px)`
    },
    '@media (max-width: 480px)': {
      height: breakpoints.small || `calc(${baseHeight} - 40px)`
    },
    ...breakpoints.custom
  };
};

/**
 * Create height styles for different components
 * @param {string} componentType - Type of component
 * @param {Object} options - Component options
 * @returns {Object} Style object for sx prop
 */
export const createHeightStyles = (componentType, options = {}) => {
  const height = calculateTabHeight(componentType, options);

  return {
    height,
    minHeight: options.minHeight || '200px',
    maxHeight: options.maxHeight || 'auto',
    overflow: options.overflow || 'hidden',
    display: 'flex',
    flexDirection: 'column'
  };
};

/**
 * Hook for dynamic height calculation
 * @param {string} componentType - Type of component
 * @param {Object} options - Component options
 * @returns {Object} Height styles and utilities
 */
export const useHeightCalculation = (componentType, options = {}) => {
  const height = calculateTabHeight(componentType, options);
  const styles = createHeightStyles(componentType, options);

  return {
    height,
    styles,
    dimensions: LAYOUT_DIMENSIONS,
    calculateHeight: (newOptions) => calculateTabHeight(componentType, { ...options, ...newOptions })
  };
};

/**
 * Predefined height configurations for common layouts
 */
export const HEIGHT_PRESETS = {
  FULL_SCREEN: calculateContentHeight({ hasHeader: false, hasFooter: false, hasTabHeader: false }),
  DASHBOARD: calculateDashboardHeight(),
  GRID_WITH_STATS: calculateGridHeight({ hasStatsCards: true }),
  GRID_WITHOUT_STATS: calculateGridHeight({ hasStatsCards: false }),
  CHART_LARGE: calculateChartHeight({ minHeight: 400, maxHeight: 600 }),
  CHART_MEDIUM: calculateChartHeight({ minHeight: 300, maxHeight: 450 }),
  CHART_SMALL: calculateChartHeight({ minHeight: 200, maxHeight: 300 }),
  FORM: calculateTabHeight('form'),
  MODAL: 'calc(100vh - 120px)',
  DRAWER: 'calc(100vh - 64px)'
};

export default {
  LAYOUT_DIMENSIONS,
  calculateContentHeight,
  calculateDashboardHeight,
  calculateGridHeight,
  calculateChartHeight,
  calculateTabHeight,
  getResponsiveHeight,
  createHeightStyles,
  useHeightCalculation,
  HEIGHT_PRESETS
};

/**
 * Optimized Grid Data Handlers
 * Prevents duplicate processing and excessive logging
 * Uses memoization and caching for better performance
 */

import { toast } from 'react-toastify';

// Cache for processed data to prevent duplicate processing
const dataCache = new Map();
const validationCache = new Map();
const errorLogCache = new Set();

/**
 * Generate cache key for data
 */
const generateCacheKey = (data, options) => {
  try {
    return JSON.stringify({ data: Array.isArray(data) ? data.length : typeof data, options });
  } catch {
    return `${typeof data}-${Date.now()}`;
  }
};

/**
 * Optimized data validator with caching
 */
export const validateGridData = (data, options = {}) => {
  const cacheKey = generateCacheKey(data, options);

  // Return cached result if available
  if (validationCache.has(cacheKey)) {
    return validationCache.get(cacheKey);
  }

  const {
    expectedType = 'array',
    allowEmpty = true,
    requiredFields = [],
    transformers = {},
    fallbackValue = null
  } = options;

  try {
    // Type validation
    if (expectedType === 'array' && !Array.isArray(data)) {
      const errorKey = `type-error-${typeof data}`;
      if (!errorLogCache.has(errorKey)) {
        console.warn('GridDataHandler: Expected array but got:', typeof data);
        errorLogCache.add(errorKey);
      }

      const result = {
        isValid: false,
        data: allowEmpty ? [] : fallbackValue,
        errors: ['Data is not an array'],
        metadata: { originalType: typeof data, expectedType }
      };

      validationCache.set(cacheKey, result);
      return result;
    }

    // Empty data validation
    if (!allowEmpty && (!data || (Array.isArray(data) && data.length === 0))) {
      const result = {
        isValid: false,
        data: fallbackValue,
        errors: ['Data is empty but empty data is not allowed'],
        metadata: { isEmpty: true }
      };

      validationCache.set(cacheKey, result);
      return result;
    }

    // Field validation for arrays
    if (Array.isArray(data) && requiredFields.length > 0) {
      const missingFields = [];
      const sampleItem = data[0] || {};

      requiredFields.forEach(field => {
        if (!(field in sampleItem)) {
          missingFields.push(field);
        }
      });

      if (missingFields.length > 0) {
        const errorKey = `missing-fields-${missingFields.join(',')}`;
        if (!errorLogCache.has(errorKey)) {
          console.warn('GridDataHandler: Missing required fields:', missingFields);
          errorLogCache.add(errorKey);
        }
      }
    }

    // Apply transformers
    let transformedData = data;
    if (Array.isArray(data) && Object.keys(transformers).length > 0) {
      transformedData = data.map(item => {
        const transformed = { ...item };
        Object.entries(transformers).forEach(([field, transformer]) => {
          if (field in transformed && typeof transformer === 'function') {
            try {
              transformed[field] = transformer(transformed[field]);
            } catch (error) {
              const errorKey = `transform-error-${field}`;
              if (!errorLogCache.has(errorKey)) {
                console.warn(`Transform error for field ${field}:`, error);
                errorLogCache.add(errorKey);
              }
            }
          }
        });
        return transformed;
      });
    }

    const result = {
      isValid: true,
      data: transformedData,
      errors: [],
      metadata: {
        itemCount: Array.isArray(transformedData) ? transformedData.length : 1,
        hasTransformers: Object.keys(transformers).length > 0
      }
    };

    // Cache successful validation
    validationCache.set(cacheKey, result);
    return result;

  } catch (error) {
    const errorKey = `validation-error-${error.message}`;
    if (!errorLogCache.has(errorKey)) {
      console.error('GridDataHandler: Validation error:', error);
      errorLogCache.add(errorKey);
    }

    const result = {
      isValid: false,
      data: fallbackValue,
      errors: [error.message],
      metadata: { hasError: true }
    };

    validationCache.set(cacheKey, result);
    return result;
  }
};

/**
 * Optimized data fetcher with caching and deduplication
 */
export const fetchGridData = async (url, options = {}) => {
  const {
    method = 'GET',
    headers = {},
    body = null,
    timeout = 10000,
    retries = 1,
    cacheTimeout = 5000 // 5 seconds cache
  } = options;

  const cacheKey = `${method}-${url}-${JSON.stringify(body)}`;

  // Check cache first
  if (dataCache.has(cacheKey)) {
    const cached = dataCache.get(cacheKey);
    if (Date.now() - cached.timestamp < cacheTimeout) {
      return cached.data;
    } else {
      dataCache.delete(cacheKey);
    }
  }

  const fetchWithTimeout = async (fetchUrl, fetchOptions, timeoutMs) => {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(fetchUrl, {
        ...fetchOptions,
        signal: controller.signal
      });
      clearTimeout(timeoutId);
      return response;
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  };

  let lastError;
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const response = await fetchWithTimeout(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          ...headers
        },
        body: body ? JSON.stringify(body) : null
      }, timeout);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      // Cache successful response
      dataCache.set(cacheKey, {
        data,
        timestamp: Date.now()
      });

      return data;

    } catch (error) {
      lastError = error;

      if (attempt < retries) {
        // Wait before retry (exponential backoff)
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 1000));
      }
    }
  }

  // Log error only once per unique error
  const errorKey = `fetch-error-${url}-${lastError.message}`;
  if (!errorLogCache.has(errorKey)) {
    console.error(`GridDataHandler: Failed to fetch data from ${url}:`, lastError);
    errorLogCache.add(errorKey);
  }

  throw lastError;
};

/**
 * Optimized grid data handlers for specific data types
 */
export const gridDataHandlers = {
  // MDM Products handler
  mdmProducts: (data) => {
    const cacheKey = `mdm-products-${Array.isArray(data) ? data.length : 0}`;

    if (validationCache.has(cacheKey)) {
      return validationCache.get(cacheKey);
    }

    const result = validateGridData(data, {
      expectedType: 'array',
      allowEmpty: true,
      requiredFields: ['Code_MDM', 'Designation'],
      transformers: {
        QteStock: (value) => parseFloat(value) || 0,
        Tarif: (value) => parseFloat(value) || 0,
        Changed: (value) => Boolean(value)
      }
    });

    validationCache.set(cacheKey, result);
    return result;
  },

  // Magento Products handler
  magentoProducts: (data) => {
    const cacheKey = `magento-products-${Array.isArray(data) ? data.length : 0}`;

    if (validationCache.has(cacheKey)) {
      return validationCache.get(cacheKey);
    }

    const result = validateGridData(data, {
      expectedType: 'array',
      allowEmpty: true,
      requiredFields: ['sku', 'name'],
      transformers: {
        price: (value) => parseFloat(value) || 0,
        status: (value) => parseInt(value) || 0,
        qty: (value) => parseInt(value) || 0
      }
    });

    validationCache.set(cacheKey, result);
    return result;
  },

  // Generic handler for other data types
  generic: (data, options = {}) => {
    return validateGridData(data, options);
  }
};

/**
 * Clear caches (useful for testing or memory management)
 */
export const clearCaches = () => {
  dataCache.clear();
  validationCache.clear();
  errorLogCache.clear();
};

/**
 * Get cache statistics
 */
export const getCacheStats = () => {
  return {
    dataCache: dataCache.size,
    validationCache: validationCache.size,
    errorLogCache: errorLogCache.size
  };
};

export default {
  validateGridData,
  fetchGridData,
  gridDataHandlers,
  clearCaches,
  getCacheStats
};

import { MENU_ITEMS } from '../components/Layout/MenuTree.js';
import { ROUTES, ROUTE_METADATA } from '../config/routes';

/**
 * Route utilities for enhanced routing with permission integration
 */

/**
 * Get menu item by route path
 */
export const getMenuItemByPath = (path) => {
    return MENU_ITEMS.find(item => item.path === path);
};

/**
 * Get menu item by ID
 */
export const getMenuItemById = (id) => {
    return MENU_ITEMS.find(item => item.id === id);
};

/**
 * Check if a route requires authentication
 */
export const requiresAuth = (path) => {
    const metadata = ROUTE_METADATA[path];
    return metadata?.requiresAuth !== false;
};

/**
 * Check if a route requires specific permissions
 */
export const getRoutePermissions = (path) => {
    const menuItem = getMenuItemByPath(path);
    return menuItem?.permissions || [];
};

/**
 * Check if a route requires a specific role
 */
export const getRouteRole = (path) => {
    const menuItem = getMenuItemByPath(path);
    return menuItem?.roleRequired || null;
};

/**
 * Check if a route requires a license
 */
export const requiresLicense = (path) => {
    const menuItem = getMenuItemByPath(path);
    return menuItem?.licenseRequired === true;
};

/**
 * Get all routes that a user can access based on permissions
 */
export const getAccessibleRoutes = (userPermissions, userRole, licenseLevel) => {
    return MENU_ITEMS.filter(item => {
        // Check license requirement
        if (item.licenseRequired && !licenseLevel) {
            return false;
        }

        // Check role requirement
        if (item.roleRequired) {
            const roleHierarchy = ['user', 'manager', 'admin', 'super_admin'];
            const userRoleIndex = roleHierarchy.indexOf(userRole);
            const requiredRoleIndex = roleHierarchy.indexOf(item.roleRequired);

            if (userRoleIndex < requiredRoleIndex) {
                return false;
            }
        }

        // Check permissions
        if (item.permissions && item.permissions.length > 0) {
            return item.permissions.some(permission => 
                userPermissions.includes(permission)
            );
        }

        return true;
    });
};

/**
 * Get route breadcrumb
 */
export const getRouteBreadcrumb = (path) => {
    const metadata = ROUTE_METADATA[path];
    const menuItem = getMenuItemByPath(path);

    return {
        title: menuItem?.label || metadata?.title || 'Unknown Page',
        path: path,
        icon: menuItem?.icon || metadata?.icon
    };
};

/**
 * Generate navigation breadcrumbs for a route
 */
export const generateBreadcrumbs = (path) => {
    const breadcrumbs = [];

    // Always start with Dashboard
    breadcrumbs.push({
        title: 'Dashboard',
        path: '/dashboard',
        icon: 'Dashboard'
    });

    // Add current page if it's not dashboard
    if (path !== '/dashboard') {
        const currentBreadcrumb = getRouteBreadcrumb(path);
        if (currentBreadcrumb.title !== 'Unknown Page') {
            breadcrumbs.push(currentBreadcrumb);
        }
    }

    return breadcrumbs;
};

/**
 * Check if a route is valid and accessible
 */
export const isValidRoute = (path, userPermissions, userRole, licenseLevel) => {
    const menuItem = getMenuItemByPath(path);

    if (!menuItem) {
        // Check if it's a system route
        const systemRoutes = ['/login', '/docs'];
        return systemRoutes.includes(path);
    }

    // Check license requirement
    if (menuItem.licenseRequired && !licenseLevel) {
        return false;
    }

    // Check role requirement
    if (menuItem.roleRequired) {
        const roleHierarchy = ['user', 'manager', 'admin', 'super_admin'];
        const userRoleIndex = roleHierarchy.indexOf(userRole);
        const requiredRoleIndex = roleHierarchy.indexOf(menuItem.roleRequired);

        if (userRoleIndex < requiredRoleIndex) {
            return false;
        }
    }

    // Check permissions
    if (menuItem.permissions && menuItem.permissions.length > 0) {
        return menuItem.permissions.some(permission => 
            userPermissions.includes(permission)
        );
    }

    return true;
};

/**
 * Get default route for a user based on their permissions
 */
export const getDefaultRoute = (userPermissions, userRole, licenseLevel) => {
    // Always try dashboard first
    if (isValidRoute('/dashboard', userPermissions, userRole, licenseLevel)) {
        return '/dashboard';
    }

    // Find the first accessible route
    const accessibleRoutes = getAccessibleRoutes(userPermissions, userRole, licenseLevel);
    if (accessibleRoutes.length > 0) {
        return accessibleRoutes[0].path;
    }

    // Fallback to dashboard (should always be accessible)
    return '/dashboard';
};

/**
 * Route validation middleware
 */
export const validateRoute = (path, userContext) => {
    const { permissions = [], role = 'user', licenseLevel = null } = userContext;

    return {
        isValid: isValidRoute(path, permissions, role, licenseLevel),
        menuItem: getMenuItemByPath(path),
        metadata: ROUTE_METADATA[path],
        breadcrumbs: generateBreadcrumbs(path),
        defaultRoute: getDefaultRoute(permissions, role, licenseLevel)
    };
};

export default {
    getMenuItemByPath,
    getMenuItemById,
    requiresAuth,
    getRoutePermissions,
    getRouteRole,
    requiresLicense,
    getAccessibleRoutes,
    getRouteBreadcrumb,
    generateBreadcrumbs,
    isValidRoute,
    getDefaultRoute,
    validateRoute
};

