    logLevel: isDev ? 'info' : 'warn',

    // Clear screen
    clearScreen: true,

    // Environment prefix
    envPrefix: ['VITE_', 'TECHNO_ETL_'],

    // Preview configuration for production builds
    preview: {
      host: '0.0.0.0',
      port: 80,
      strictPort: false,
      cors: true,
      headers: {
        'Cache-Control': 'public, max-age=31536000, immutable'
      }
    }
  };
